-- بيانات مقرر كيمياء 2-2 (المقرر 3، قيد الإعداد) — الجزء 7 من 8. نفّذ الأجزاء بالترتيب.
-- مولّد آليًا بواسطة scripts/build-chem22-seed.js — لا تعدّله يدويًا.
begin;
insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C5-L3-O14'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يبين الشكل الآتي صيغة أحد الأميدات المهمة واسمه الكيميائي الكارباميد. ما الاسم الأكثر شيوعًا له؟', null, '[{"src":"qimg/chem22/c5-l3b-urea.svg","alt":"صيغة بنائية مكثفة: مجموعة H₂N ترتبط بذرة كربون C، وترتبط ذرة الكربون من أعلى بذرة أكسجين O برابطة ثنائية ومن اليمين بمجموعة NH₂، أي H₂N–C(=O)–NH₂."}]'::jsonb, '["اليوريا","الأسيتاميد","الأسيتامينوفين","الفورمالدهيد"]'::jsonb, 'تذكر', 'استدعاء اسم', 'سهل', 'الكتاب ص 182 — اليوريا (الكارباميد)'),
('mcq', 2, 'في أيّ أعضاء الجسم تتحول الأمونيا السامة إلى يوريا؟', null, null, '["الكليتان","الكبد","المعدة","الرئتان"]'::jsonb, 'تذكر', 'استدعاء', 'سهل', 'الكتاب ص 182 — اليوريا (الكارباميد)'),
('mcq', 3, 'ما مصدر الأمونيا NH₃ التي يحوّلها الجسم إلى يوريا؟', null, null, '["تحطم الكربوهيدرات (السكريات) في الخلايا","غاز النيتروجين الداخل مع هواء التنفس","مجموعات الأمين ‎–NH₂ المنفصلة عند تحطم البروتينات","الدهون المتحللة في الأمعاء"]'::jsonb, 'فهم', 'تفسير مصدر', 'متوسط', 'الكتاب ص 182 — اليوريا (الكارباميد)'),
('mcq', 4, 'كيف يتخلص الجسم من اليوريا الموجودة في الدم؟', null, null, '["يحوّلها الكبد مرة أخرى إلى أمونيا","تخرج غازًا مع هواء الزفير","تتحول إلى بروتينات في عضلات الإنسان","تزيلها الكليتان من الدم فتخرج مع البول"]'::jsonb, 'تذكر', 'استدعاء', 'سهل', 'الكتاب ص 182 — اليوريا (الكارباميد)'),
('mcq', 5, 'صيغة اليوريا NH₂CONH₂ (الكتل المولية: H = 1.008، C = 12.01، N = 14.01، O = 16.00 g/mol). ما النسبة المئوية الكتلية للنيتروجين فيها تقريبًا؟', null, null, '["23.3%","46.7%","53.4%","87.4%"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 182 — اليوريا والأسمدة (حساب مكمّل بالكتل المولية)'),
('mcq', 6, 'لماذا تُضاف اليوريا إلى غذاء الماشية والأغنام؟', null, null, '["لأن هذه الحيوانات تستعملها لإنتاج البروتينات في أجسامها","لأنها مصدر رئيس للطاقة مثل السكريات","لأنها تحفظ العلف من التعفن مثل الفورمالدهيد","لأنها تمد الحيوانات بالكالسيوم اللازم للعظام"]'::jsonb, 'فهم', 'تفسير استعمال', 'متوسط', 'الكتاب ص 182 — اليوريا (الكارباميد)'),
('mcq', 7, 'تُعرف اليوريا أيضًا باسم «ثنائي أميد حمض الكربونيك». إذا كانت صيغة حمض الكربونيك HO–CO–OH، فما سبب هذه التسمية؟', null, null, '["لأن اليوريا تحتوي على ذرتي كربون ترتبط كل منهما بمجموعة أمين","لأن ذرة أكسجين الكربونيل في حمض الكربونيك حلت محلها مجموعتا ‎–NH₂","لأنها تحتوي على مجموعتي كربوكسيل وذرتي نيتروجين","لأن مجموعتي ‎–OH في حمض الكربونيك حلت محلهما مجموعتا ‎–NH₂"]'::jsonb, 'تحليل', 'تفسير تسمية', 'صعب', 'الكتاب ص 182 — اليوريا (الكارباميد)'),
('essay', 1, 'صف مراحل تكوّن اليوريا في جسم الإنسان والتخلص منها بدءًا من البروتينات، وبيّن لماذا يُعد هذا التحول ضروريًّا، واذكر ثلاثة سوائل في الجسم توجد فيها اليوريا.', null, null, null, 'فهم', 'وصف عملية', 'متوسط', 'الكتاب ص 182 — اليوريا (الكارباميد)'),
('essay', 2, 'احسب النسبة المئوية الكتلية للنيتروجين في كل من اليوريا NH₂CONH₂ ونترات الأمونيوم NH₄NO₃ (الكتل المولية: H = 1.008، C = 12.01، N = 14.01، O = 16.00 g/mol)، ثم احسب كتلة النيتروجين في كيس كتلته 50.0 kg من كل منهما، وحدد أيّ السمادين يزوّد التربة بكتلة أكبر من النيتروجين.', null, null, null, 'تطبيق', 'حساب وتفسير', 'صعب', 'الكتاب ص 182 — اليوريا والأسمدة (حساب مكمّل بالكتل المولية)'),
('essay', 3, 'يبين الشكل الآتي صيغة اليوريا. (أ) حدد المجموعة الوظيفية فيها، وبيّن لماذا تُصنَّف من الأميدات. (ب) اكتب اسمها الكيميائي. (ج) اربط بين تركيبها وكل من استعماليها: سمادًا زراعيًّا، وغذاءً للماشية. (د) لماذا يتخلص الجسم من النيتروجين الزائد على صورة يوريا لا على صورة أمونيا؟', null, '[{"src":"qimg/chem22/c5-l3b-urea.svg","alt":"صيغة بنائية مكثفة: مجموعة H₂N ترتبط بذرة كربون C، وترتبط ذرة الكربون من أعلى بذرة أكسجين O برابطة ثنائية ومن اليمين بمجموعة NH₂، أي H₂N–C(=O)–NH₂."}]'::jsonb, null, 'تحليل', 'تحليل تركيب واستعمالات', 'صعب', 'الكتاب ص 182 — اليوريا (الكارباميد)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C5-L3-O14') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'المركب NH₂CONH₂ (الكارباميد) أحد الأميدات المهمة، واسمه الأكثر شيوعًا اليوريا، ويعرف أيضًا باسم ثنائي أميد حمض الكربونيك.', '["","الأسيتاميد هو الاسم الشائع لإيثان أميد CH₃CONH₂، وفيه مجموعة CH₃ لا مجموعتا NH₂.","الأسيتامينوفين مسكن للألم يحتوي على حلقة بنزين، وليس هذا المركب.","الفورمالدهيد هو الميثانال HCHO، وهو ألدهيد لا يحتوي على نيتروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.779Z"}'::jsonb),
('mcq', 2, 1, 'عند تحطم البروتينات تنفصل منها مجموعات الأمين ‎–NH₂ ثم تتحول إلى أمونيا NH₃ السامة للجسم، ويقوم الكبد بتحويلها إلى اليوريا غير السامة.', '["الكليتان تزيلان اليوريا من الدم وتخرجانها مع البول، لكنهما لا تحولان الأمونيا إليها.","","المعدة يبدأ فيها هضم البروتينات، لكن تحويل الأمونيا إلى يوريا يتم في الكبد.","الرئتان عضوا تبادل الغازات، ولا تحولان الأمونيا إلى يوريا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-15T02:47:48.779Z"}'::jsonb),
('mcq', 3, 2, 'اليوريا آخر نواتج هضم البروتينات في الثدييات: عند تحطم البروتينات تنتقل منها مجموعات الأمين ‎–NH₂ ثم تتحول إلى أمونيا NH₃ السامة، فيحولها الكبد إلى يوريا.', '["الكربوهيدرات لا تحتوي على النيتروجين، فلا تنتج عنها أمونيا.","لا يستعمل الجسم غاز النيتروجين الجوي لإنتاج الأمونيا.","","الدهون لا تحتوي على مجموعات أمين، فلا تنتج عنها أمونيا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-15T02:47:48.779Z"}'::jsonb),
('mcq', 4, 3, 'يتم التخلص من اليوريا في الدم بواسطة الكليتين، وتخرج من الجسم مع البول (وتوجد أيضًا في المرارة الصفراء والحليب والعرق).', '["الكبد يحول الأمونيا السامة إلى يوريا، لا العكس.","اليوريا لا تخرج مع هواء الزفير؛ بل تزيلها الكليتان.","الإنسان لا يستعمل اليوريا لبناء البروتينات؛ بل يتخلص منها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-15T02:47:48.779Z"}'::jsonb),
('mcq', 5, 1, 'الكتلة المولية لليوريا = 12.01 + 16.00 + 2(14.01) + 4(1.008) = 60.06 g/mol، وكتلة النيتروجين = 2 × 14.01 = 28.02 g؛ فالنسبة = (28.02 ÷ 60.06) × 100 ≈ 46.7%. وهذه النسبة العالية من النيتروجين سبب استعمالها سمادًا.', '["حُسبت كتلة ذرة نيتروجين واحدة (14.01) بدل ذرتين (28.02).","","حُسبت كتلة مجموعتي NH₂ كاملتين (32.05) بدل كتلة ذرتي النيتروجين فقط (28.02).","قُسمت كتلة النيتروجين على كتلة بقية الذرات (32.04) بدل الكتلة المولية الكلية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-15T02:47:48.779Z"}'::jsonb),
('mcq', 6, 0, 'تُستعمل اليوريا غذاءً للماشية والأغنام؛ إذ تستعملها هذه الحيوانات (مصدرًا للنيتروجين) لإنتاج البروتينات في أجسامها.', '["","اليوريا ليست مصدرًا للطاقة؛ بل مصدر للنيتروجين اللازم لبناء البروتينات.","الفورمالدهيد هو المادة الحافظة، أما اليوريا فتضاف غذاءً.","اليوريا NH₂CONH₂ لا تحتوي على الكالسيوم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-15T02:47:48.780Z"}'::jsonb),
('mcq', 7, 3, 'الأميد ينتج عن إحلال ذرة نيتروجين محل مجموعة ‎–OH في الحمض؛ وفي حمض الكربونيك HO–CO–OH مجموعتا ‎–OH، فإذا حلت محل كل منهما مجموعة ‎–NH₂ نتج NH₂–CO–NH₂، أي أميدان على ذرة الكربونيل نفسها؛ لذا تسمى ثنائي أميد حمض الكربونيك.', '["في اليوريا ذرة كربون واحدة فقط ترتبط بمجموعتي NH₂.","ذرة أكسجين الكربونيل باقية في اليوريا؛ والذي استُبدل هو مجموعتا ‎–OH.","لا تحتوي اليوريا على أي مجموعة كربوكسيل ‎–COOH.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-15T02:47:48.780Z"}'::jsonb),
('essay', 1, null::int, null, null, '(1) تتحطم البروتينات في أثناء الهضم فتنفصل منها مجموعات الأمين ‎–NH₂. (2) تتحول مجموعات الأمين إلى أمونيا NH₃ وهي مادة سامة للجسم. (3) يحول الكبد الأمونيا السامة إلى اليوريا NH₂CONH₂ غير السامة. (4) تنتقل اليوريا في الدم، وتزيلها الكليتان فتخرج مع البول. التحول ضروري لأن الأمونيا سامة، فتحويلها إلى يوريا غير سامة يمكّن الجسم من نقلها والتخلص منها دون ضرر. توجد اليوريا في الدم والمرارة الصفراء والحليب والعرق.', '["تحطم البروتينات وانفصال مجموعات الأمين","تحول مجموعات الأمين إلى أمونيا سامة","الكبد يحول الأمونيا إلى يوريا غير سامة","الكليتان تزيلانها مع البول","سبب الضرورة: سمية الأمونيا","ثلاثة سوائل: الدم، المرارة الصفراء، الحليب، العرق"]'::jsonb, '[]'::jsonb, '[{"element":"تحطم البروتينات وانفصال مجموعات الأمين","marks":1},{"element":"تحول مجموعات الأمين إلى أمونيا سامة","marks":1},{"element":"الكبد يحول الأمونيا إلى يوريا غير سامة","marks":1},{"element":"الكليتان تزيلانها مع البول","marks":1},{"element":"سبب الضرورة: سمية الأمونيا","marks":1},{"element":"ثلاثة سوائل: الدم، المرارة الصفراء، الحليب، العرق","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: تحطم البروتينات وانفصال مجموعات الأمين؛ تحول مجموعات الأمين إلى أمونيا سامة؛ الكبد يحول الأمونيا إلى يوريا غير سامة؛ الكليتان تزيلانها مع البول؛ سبب الضرورة: سمية الأمونيا؛ ثلاثة سوائل: الدم، المرارة الصفراء، الحليب، العرق"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الكليتين تحولان الأمونيا إلى يوريا","القول إن اليوريا تنتج من هضم الكربوهيدرات","وصف اليوريا بأنها سامة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-15T02:47:48.780Z"}'::jsonb),
('essay', 2, null::int, null, null, 'اليوريا: الكتلة المولية = 12.01 + 16.00 + 2(14.01) + 4(1.008) = 60.06 g/mol؛ كتلة N = 28.02 g؛ النسبة = 28.02 ÷ 60.06 × 100 = 46.7%. نترات الأمونيوم: الكتلة المولية = 2(14.01) + 4(1.008) + 3(16.00) = 80.05 g/mol؛ كتلة N = 28.02 g؛ النسبة = 28.02 ÷ 80.05 × 100 = 35.0%. كتلة N في 50.0 kg يوريا = 50.0 × 0.467 = 23.3 kg، وفي 50.0 kg نترات أمونيوم = 50.0 × 0.350 = 17.5 kg؛ إذن اليوريا تزوّد التربة بكتلة أكبر من النيتروجين.', '["الكتلة المولية لليوريا 60.06 g/mol","نسبة N في اليوريا 46.7%","الكتلة المولية لنترات الأمونيوم 80.05 g/mol","نسبة N في نترات الأمونيوم 35.0%","كتلتا N في الكيسين: 23.3 kg و17.5 kg، واليوريا أكبر"]'::jsonb, '["M(NH₂CONH₂) = 12.01 + 16.00 + 2 × 14.01 + 4 × 1.008 = 60.06 g/mol","%N = (2 × 14.01 ÷ 60.06) × 100 = 46.7%","M(NH₄NO₃) = 2 × 14.01 + 4 × 1.008 + 3 × 16.00 = 80.05 g/mol","%N = (2 × 14.01 ÷ 80.05) × 100 = 35.0%","m(N) = 50.0 kg × 0.467 = 23.3 kg (يوريا)؛ 50.0 kg × 0.350 = 17.5 kg (نترات الأمونيوم)"]'::jsonb, '[{"element":"الكتلة المولية لليوريا 60.06 g/mol","marks":1},{"element":"نسبة N في اليوريا 46.7%","marks":1},{"element":"الكتلة المولية لنترات الأمونيوم 80.05 g/mol","marks":1},{"element":"نسبة N في نترات الأمونيوم 35.0%","marks":1},{"element":"كتلتا N في الكيسين: 23.3 kg و17.5 kg، واليوريا أكبر","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: الكتلة المولية لليوريا 60.06 g/mol؛ نسبة N في اليوريا 46.7%؛ الكتلة المولية لنترات الأمونيوم 80.05 g/mol؛ نسبة N في نترات الأمونيوم 35.0%؛ التفسير: نسبة نيتروجين عالية وسهولة تحولها إلى أمونيا في التربة"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب ذرة نيتروجين واحدة في اليوريا","نسيان ذرة النيتروجين في أيون النترات","ضرب كتلة الكيس في النسبة دون القسمة على 100"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-15T02:47:48.780Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) المجموعة الوظيفية: الأميد؛ لأن ذرة نيتروجين (مجموعة ‎–NH₂) ترتبط بذرة كربون الكربونيل C=O، وفيها مجموعتا أميد على ذرة الكربونيل نفسها. (ب) الكارباميد (ويعرف أيضًا بثنائي أميد حمض الكربونيك). (ج) تحتوي على ذرتي نيتروجين في جزيء صغير فنسبة النيتروجين فيها عالية، وتتحول بسهولة إلى أمونيا في التربة فتصلح سمادًا؛ وتستعمل الماشية والأغنام نيتروجينها لإنتاج البروتينات في أجسامها. (د) لأن الأمونيا مادة سامة للجسم، أما اليوريا فغير سامة، فيحول الكبد الأمونيا إلى يوريا ثم تزيلها الكليتان مع البول.', '["(أ) الأميد: NH₂ مرتبطة بكربون الكربونيل","(ب) الكارباميد","(ج) نسبة نيتروجين عالية وتحولها إلى أمونيا في التربة (سماد)","(ج) تستعملها الماشية لإنتاج البروتينات","(د) الأمونيا سامة واليوريا غير سامة"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الأميد: NH₂ مرتبطة بكربون الكربونيل","marks":1},{"element":"(ب) الكارباميد","marks":1},{"element":"(ج) نسبة نيتروجين عالية وتحولها إلى أمونيا في التربة (سماد)","marks":1},{"element":"(ج) تستعملها الماشية لإنتاج البروتينات","marks":1},{"element":"(د) الأمونيا سامة واليوريا غير سامة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) الأميد: NH₂ مرتبطة بكربون الكربونيل؛ (ب) الكارباميد؛ (ج) نسبة نيتروجين عالية وتحولها إلى أمونيا في التربة (سماد)؛ (ج) تستعملها الماشية لإنتاج البروتينات؛ (د) الأمونيا سامة واليوريا غير سامة"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف اليوريا أمينًا لاحتوائها على NH₂","القول إن الماشية تستعمل اليوريا مصدرًا للطاقة","القول إن الأمونيا أقل سمية من اليوريا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.780Z"}'::jsonb)
