from (values
('mcq', 1, 0, 'ارتبطت ذرتا الهيدروجين في جزيء H₂ بذرتي الكربون المكونتين للرابطة الثنائية فتحولت إلى رابطة أحادية، ولم ينتج جزيء صغير آخر؛ فالتفاعل إضافة (هدرجة) يتحول فيه الألكين إلى ألكان.', '["","في الحذف تُنزع ذرتان من ذرتي كربون متجاورتين فتتكون رابطة ثنائية، وهنا حدث العكس: اختفت الرابطة الثنائية.","في الاستبدال تحل ذرة محل أخرى ويخرج ناتج ثانٍ، أما هنا فقد اندمج المتفاعلان في ناتج واحد.","التكثف يربط جزيئين عضويين مع فقد جزيء صغير كالماء، ولا يُفقد أي جزيء في هذا التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-15T02:47:48.781Z"}'::jsonb),
('mcq', 2, 2, 'حلت ذرة كلور محل ذرة هيدروجين في الإيثان فتكوّن كلورو إيثان وخرجت ذرة الهيدروجين مع ذرة الكلور الأخرى في صورة HCl؛ فهو تفاعل استبدال (هلجنة).', '["الإيثان ألكان لا يحتوي على رابطة ثنائية أو ثلاثية تُضاف إليها الذرات.","لم تتكون رابطة ثنائية بين ذرتي كربون متجاورتين، والكلورو إيثان ما زال مشبعًا.","","لم يكتسب الإيثان أكسجينًا ولم يتحول إلى مركب أكسجيني؛ بل حلت ذرة كلور محل ذرة هيدروجين فيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-15T02:47:48.781Z"}'::jsonb),
('mcq', 3, 1, 'اتحد جزيئان عضويان صغيران (حمض كربوكسيلي وكحول) لتكوين جزيء أكبر هو الإستر، مع فقد جزيء صغير هو الماء؛ وهذا هو تفاعل التكثف.', '["الإضافة تحدث على رابطة ثنائية أو ثلاثية بين ذرتي كربون وتعطي ناتجًا واحدًا دون فقد جزيء صغير، وهنا فُقد جزيء ماء.","","الاستبدال يُحل فيه ذرة أو مجموعة محل أخرى في جزيء واحد، أما هنا فاتحد جزيئان عضويان في جزيء أكبر.","لم يكتسب أي من المتفاعلين أكسجين من عامل مؤكسد، بل اتحد الجزيئان وخرج الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-15T02:47:48.781Z"}'::jsonb),
('mcq', 4, 3, 'تكتسب ذرات الكربون في الإيثان الأكسجين وتتحول إلى CO₂، فالإيثان يتأكسد؛ وتفاعلات الاحتراق من أكثر تفاعلات الأكسدة والاختزال انتشارًا.', '["لم تتكون رابطة ثنائية بين ذرتي كربون، بل تفكك الجزيء كله إلى CO₂ وH₂O.","الإيثان مشبع لا يحتوي على رابطة ثنائية أو ثلاثية تُضاف إليها الذرات.","التكثف يربط جزيئين عضويين في جزيء عضوي أكبر، ونواتج الاحتراق جزيئات غير عضوية صغيرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-15T02:47:48.781Z"}'::jsonb),
('mcq', 5, 1, 'في التفاعل CH₃CH₂Br → CH₂=CH₂ + HBr نُزعت ذرة هيدروجين وذرة بروم من ذرتي كربون متجاورتين فتكونت رابطة ثنائية وخرج جزيء HBr المستقر؛ وهذا تفاعل حذف.', '["هذا عكس الحذف: أُضيف HBr إلى الرابطة الثنائية فتحولت إلى أحادية، فهو تفاعل إضافة.","","حلت مجموعة OH محل ذرة البروم في هاليد الألكيل، فهو تفاعل استبدال يكوّن كحولًا.","حلت ذرة بروم محل ذرة هيدروجين في الإيثان، فهو تفاعل استبدال (هلجنة)، مع أن HBr يظهر في النواتج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-15T02:47:48.781Z"}'::jsonb),
('mcq', 6, 2, 'حلت مجموعة الأمين NH₂ محل ذرة البروم المرتبطة بذرة الكربون، ولم تتكون رابطة ثنائية في الناتج؛ فهو تفاعل استبدال لتكوين أمين (R–X + NH₃ → R–NH₂ + HX).', '["لو كان حذفًا لتكونت رابطة ثنائية بين ذرتي كربون، والناتج CH₃CH₂CH₂NH₂ ليس فيه رابطة ثنائية.","خروج HBr لا يكفي للتصنيف تكثفًا؛ فلم يتحد جزيئان عضويان لتكوين جزيء عضوي أكبر، بل حلت مجموعة محل ذرة.","","هاليد الألكيل مشبع لا يحتوي على رابطة ثنائية أو ثلاثية تُضاف إليها ذرات، وقد نتج مركبان لا مركب واحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.781Z"}'::jsonb),
('mcq', 7, 3, '(1) نُزع الماء من الكحول وتكونت رابطة ثنائية: حذف. (2) أُضيف الماء إلى الرابطة الثنائية: إضافة. (3) حلت OH محل Cl: استبدال. (4) تحول الكحول الثانوي إلى كيتون بفقد الهيدروجين: أكسدة واختزال.', '["التفاعل (2) لا يُحل فيه شيء محل شيء، بل يُضاف الماء إلى الرابطة الثنائية فهو إضافة، والتفاعل (3) هو الاستبدال.","التفاعل (1) ينتج رابطة ثنائية فهو حذف لا إضافة، والتفاعل (4) تحول كحول إلى كيتون وهو أكسدة لا تكثف.","التفاعل (3) لا تتكون فيه رابطة ثنائية؛ بل حلت مجموعة OH محل ذرة الكلور فهو استبدال.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-15T02:47:48.781Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) إضافة (هدرجة): أُضيف جزيء H₂ إلى ذرتي الكربون في الرابطة الثنائية فتحول الألكين إلى ألكان. (b) استبدال (هلجنة): حلت ذرة فلور محل ذرة هيدروجين في البروبان وخرج HF. (c) حذف (حذف الماء): نُزعت مجموعة OH وذرة H من ذرتي كربون متجاورتين فتكونت رابطة ثنائية وخرج الماء. (d) إضافة (إضافة الماء): أُضيفت H وOH من جزيء الماء إلى ذرتي الرابطة الثنائية فتكوّن كحول.', '["(a) إضافة مع السبب","(b) استبدال مع السبب","(c) حذف مع السبب","(d) إضافة مع السبب"]'::jsonb, '[]'::jsonb, '[{"element":"(a) إضافة وسببه","marks":1},{"element":"(b) استبدال وسببه","marks":1},{"element":"(c) حذف وسببه","marks":1},{"element":"(d) إضافة وسببه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف التفاعلات الأربعة تصنيفًا صحيحًا مع تعليل كل منها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا: عنصران أو ثلاثة من عناصر الإجابة صحيحة"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف (b) حذفًا لأن HF يظهر في النواتج","تصنيف (d) تكثفًا لأن الماء يشارك في التفاعل","الخلط بين حذف الماء في (c) وإضافة الماء في (d)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-15T02:47:48.781Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) في الإضافة ترتبط ذرات بذرتي الكربون المكونتين للرابطة الثنائية أو الثلاثية فتتكسر إحدى روابطها (تتحول الثنائية إلى أحادية)، أما في الحذف فتُنزع ذرتان أو مجموعة ذرات من ذرتي كربون متجاورتين فتتكون رابطة ثنائية بينهما. (2) المتفاعل في الإضافة مركب غير مشبع (ألكين أو ألكاين) وناتجه مركب واحد أكثر تشبعًا (ألكان أو كحول أو هاليد ألكيل)، أما في الحذف فالمتفاعل مركب مشبع (ألكان أو كحول أو هاليد ألكيل) وناتجه ألكين وجزيء صغير مستقر مثل H₂ أو H₂O أو HX. (3) الإضافة عكس الحذف. مثال الإضافة: CH₂=CH₂ + H₂ → CH₃–CH₃. مثال الحذف: CH₃–CH₂–OH → CH₂=CH₂ + H₂O.', '["الإضافة تكسر رابطة ثنائية/ثلاثية والحذف يكوّن رابطة ثنائية","المتفاعل والناتج في كل منهما","الإضافة عكس الحذف","معادلة صحيحة موزونة لكل نوع"]'::jsonb, '[]'::jsonb, '[{"element":"التغير في الروابط","marks":1},{"element":"المتفاعل والناتج","marks":1},{"element":"العلاقة العكسية","marks":1},{"element":"المعادلتان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة في النقاط الثلاث مع معادلتين صحيحتين موزونتين"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا: عنصران أو ثلاثة من عناصر الإجابة صحيحة"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الحذف يكسر الرابطة الثنائية والإضافة تكوّنها","نسيان الجزيء الصغير الناتج في معادلة الحذف","اختيار معادلة استبدال مثالًا على الإضافة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-15T02:47:48.782Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) RCOOH + R′OH → RCOOR′ + H₂O، وهو تفاعل تكثف؛ يُعد تكثفًا لأن جزيئين عضويين صغيرين اتحدا لتكوين جزيء أكبر وأكثر تعقيدًا مع فقد جزيء صغير هو الماء، ويُعد حذفًا لأن جزيء الماء نُزع من المتفاعلين وتكونت رابطة بين ذرتين (ذرة الكربون في الحمض وذرة الأكسجين في الكحول) لم تكونا مرتبطتين سابقًا. (b) CH₄ + (O) → CH₃OH، وهو تفاعل أكسدة واختزال؛ يُعد أكسدة لأن الميثان اكتسب أكسجين، والمادة تتأكسد عندما تكسب الأكسجين أو تفقد الهيدروجين، ويرافق كل أكسدة اختزال (العامل المؤكسد). (c) التصنيف يسهّل توقع نواتج التفاعلات: إذا عُرف نوع التفاعل أمكن استعمال معادلته العامة لكتابة نواتج أي مركب من النوع نفسه.', '["المعادلة العامة للإستر","تعليل التكثف","تعليل الحذف (رابطة جديدة وفقد الماء)","معادلة الميثان → ميثانول","تعليل الأكسدة باكتساب الأكسجين","فائدة التصنيف: توقع النواتج"]'::jsonb, '[]'::jsonb, '[{"element":"المعادلة العامة للإستر","marks":1},{"element":"تعليل التكثف والحذف","marks":2},{"element":"معادلة الميثانول وتعليل الأكسدة","marks":2},{"element":"فائدة التصنيف","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"معادلتان صحيحتان، وتعليل كامل للتكثف والحذف والأكسدة، وذكر فائدة التصنيف"},{"level":"4–5 درجات","description":"نقص في أحد التعليلات أو خطأ في إحدى المعادلتين"},{"level":"2–3 درجات","description":"معادلة واحدة صحيحة مع تعليل جزئي"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة H₂ بدل H₂O ناتجًا في تكوين الإستر","تعليل الأكسدة بفقد الأكسجين","القول إن التكثف لا يرتبط بالحذف إطلاقًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.782Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
