from (values
('mcq', 1, 3, 'المركب 2-بروبانول كحول تتصل فيه مجموعة OH بذرة كربون مرتبطة بذرتي كربون أخريين، فعند أكسدته تفقد ذرة الكربون هذه ذرة H وتفقد OH ذرة H فتتكون مجموعة كربونيل وسط السلسلة: CH₃CH(OH)CH₃ + (O) → CH₃COCH₃ + H₂O، والناتج كيتون هو 2-بروبانون.', '["البروبانال ألدهيد ينتج من أكسدة 1-بروبانول الذي تكون فيه OH على ذرة كربون طرفية.","الحمض الكربوكسيلي ينتج من أكسدة ألدهيد، و2-بروبانول لا يعطي ألدهيدًا؛ والكيتون الناتج لا يتأكسد بسهولة إلى حمض.","البروبين ناتج حذف الماء من الكحول، لا ناتج أكسدته بالأكسجين (O).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-15T02:47:48.788Z"}'::jsonb),
('mcq', 2, 0, '1-بروبانول كحول تتصل فيه OH بذرة كربون طرفية، فيتأكسد أولًا إلى ألدهيد (بروبانال CH₃CH₂CHO)، ثم يستمر تأكسد الألدهيد بسهولة إلى حمض كربوكسيلي (حمض البروبانويك CH₃CH₂COOH).', '["","2-بروبانون كيتون ينتج من أكسدة 2-بروبانول لا 1-بروبانول، ولا يتأكسد الكيتون بسهولة إلى حمض.","الترتيب معكوس: الألدهيد يتكون أولًا ثم يتأكسد إلى الحمض، لا العكس.","الألدهيد لا يتأكسد إلى كيتون؛ بل يتأكسد إلى حمض كربوكسيلي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-15T02:47:48.788Z"}'::jsonb),
('mcq', 3, 2, 'أكسدة 2-هكسانول تنتج 2-هكسانون CH₃COCH₂CH₂CH₂CH₃؛ وفي الكيتون ترتبط ذرة كربون الكربونيل بذرتي كربون ولا ترتبط بذرة هيدروجين، فلا يتأكسد بسهولة إلى حمض، بخلاف الألدهيد (هكسانال) الناتج من 1-هكسانول الذي يتأكسد بسهولة إلى حمض الهكسانويك.', '["ذرة الكربون المرتبطة بـ OH في 2-هكسانول مرتبطة بذرة هيدروجين واحدة، وهو يتأكسد فعلًا إلى 2-هكسانون.","حذف الماء تفاعل مختلف لا يحتاج إلى عامل مؤكسد؛ أما الأكسدة فتنتج الكيتون.","","2-هكسانول لا يعطي ألدهيدًا عند أكسدته، والإستر ينتج من تكثف حمض مع كحول لا من الأكسدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-15T02:47:48.788Z"}'::jsonb),
('mcq', 4, 1, 'في 2-بنتانول CH₃CH(OH)CH₂CH₂CH₃ تتصل مجموعة OH بذرة كربون مرتبطة بذرتي كربون، فتصبح بعد الأكسدة ذرة كربون كربونيل وسط السلسلة، أي كيتون: 2-بنتانون CH₃COCH₂CH₂CH₃.', '["في 1-بنتانول تتصل OH بذرة كربون طرفية، فيتأكسد إلى ألدهيد (بنتانال) ثم إلى حمض البنتانويك.","","الإيثانول تتصل فيه OH بذرة كربون طرفية فيتأكسد إلى إيثانال ثم إلى حمض الإيثانويك.","الميثانول يتأكسد إلى ميثانال ثم إلى حمض الميثانويك ثم ثاني أكسيد الكربون، ولا ينتج كيتونًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.788Z"}'::jsonb),
('mcq', 5, 0, 'يتأكسد الميثانول CH₃OH إلى ميثانال HCHO، ثم إلى حمض الميثانويك HCOOH، ثم يتأكسد الحمض إلى ثاني أكسيد الكربون O=C=O، وهو آخر مركب في السلسلة.', '["","الميثانال ناتج الخطوة الأولى، ويتأكسد بعدها إلى حمض الميثانويك.","حمض الميثانويك ناتج الخطوة الثانية، ويمكن أن يتأكسد بعدها إلى CO₂.","الميثان أقل أكسدة من الميثانول؛ فتحوله إلى ميثانول هو أكسدة، وتحول الميثانول إلى ميثان اختزال لا أكسدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-15T02:47:48.788Z"}'::jsonb),
('mcq', 6, 3, 'صيغة الميثانول CH₄O وصيغة الميثانال CH₂O؛ أي فقد الجزيء ذرتي هيدروجين (حذف هيدروجين) مع بقاء عدد ذرات الأكسجين، والمادة تتأكسد عندما تفقد الهيدروجين.', '["اكتساب الأكسجين يحدث في الخطوة التالية (الميثانال → حمض الميثانويك)، وعدد ذرات O لم يتغير هنا.","الميثانول فيه ذرة كربون واحدة فلا يمكن أن يتكون منه ألكين، والناتج ألدهيد.","اكتساب الهيدروجين اختزال لا أكسدة، والميثانال فيه ذرات هيدروجين أقل من الميثانول.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-15T02:47:48.788Z"}'::jsonb),
('mcq', 7, 1, 'في المركب (1) تتصل OH بذرة كربون طرفية فيتأكسد أولًا إلى ألدهيد هو بيوتانال CH₃CH₂CH₂CHO، وفي المركب (2) تتصل OH بذرة كربون مرتبطة بذرتي كربون فيتأكسد إلى كيتون هو 2-بيوتانون CH₃CH₂COCH₃.', '["الترتيب معكوس: الكيتون ينتج من الكحول الذي تتصل فيه OH بذرة كربون داخلية، أي المركب (2).","","المركب (2) يعطي كيتونًا لا حمضًا؛ والحمض ناتج أكسدة الألدهيد المشتق من المركب (1).","الحمض لا يتكون في الخطوة الأولى، والمركب (2) لا يعطي ألدهيدًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-15T02:47:48.788Z"}'::jsonb),
('essay', 1, null::int, null, null, '1-بروبانول: CH₃CH₂CH₂OH + (O) → CH₃CH₂CHO + H₂O (بروبانال، ألدهيد)، ثم CH₃CH₂CHO + (O) → CH₃CH₂COOH (حمض البروبانويك). 2-بروبانول: CH₃CH(OH)CH₃ + (O) → CH₃COCH₃ + H₂O (2-بروبانون، كيتون)، والكيتون لا يتأكسد بسهولة إلى حمض كربوكسيلي. سبب الاختلاف موقع مجموعة OH: في 1-بروبانول تتصل بذرة كربون طرفية فتصبح مجموعة الكربونيل في طرف السلسلة (ألدهيد) ويتأكسد الألدهيد بسهولة إلى حمض، وفي 2-بروبانول تتصل بذرة كربون وسطى فتصبح مجموعة الكربونيل وسط السلسلة (كيتون).', '["معادلة 1-بروبانول → بروبانال","معادلة بروبانال → حمض البروبانويك","معادلة 2-بروبانول → 2-بروبانون","الكيتون لا يتأكسد بسهولة","التفسير بموقع OH"]'::jsonb, '[]'::jsonb, '[{"element":"أكسدة 1-بروبانول (خطوتان)","marks":2},{"element":"أكسدة 2-بروبانول","marks":1},{"element":"الكيتون لا يتأكسد بسهولة","marks":1},{"element":"التفسير بموقع OH","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"المعادلات الثلاث صحيحة مع الأسماء والتفسير الكامل"},{"level":"3–4 درجات","description":"معادلتان صحيحتان مع تفسير جزئي"},{"level":"1–2 درجة","description":"معادلة واحدة صحيحة أو أسماء النواتج فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة 2-بروبانون ناتجًا لأكسدة 1-بروبانول","القول إن 2-بروبانون يتأكسد بسهولة إلى حمض البروبانويك","عدم موازنة المعادلات بالماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-15T02:47:48.788Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الخطوة الأولى: CH₃CH₂OH + (O) → CH₃CHO + H₂O، والناتج إيثانال (ألدهيد)؛ تُعد أكسدة لأن الإيثانول (C₂H₆O) فقد ذرتي هيدروجين فأصبح C₂H₄O. الخطوة الثانية: CH₃CHO + (O) → CH₃COOH، والناتج حمض الإيثانويك؛ تُعد أكسدة لأن الإيثانال اكتسب ذرة أكسجين (C₂H₄O → C₂H₄O₂). فالمادة تتأكسد عندما تكسب الأكسجين أو تفقد الهيدروجين.', '["معادلة الخطوة الأولى والإيثانال","فقد الهيدروجين في الخطوة الأولى","معادلة الخطوة الثانية وحمض الإيثانويك","اكتساب الأكسجين في الخطوة الثانية"]'::jsonb, '[]'::jsonb, '[{"element":"الخطوة الأولى","marks":1},{"element":"تعليلها","marks":1},{"element":"الخطوة الثانية","marks":1},{"element":"تعليلها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"معادلتان صحيحتان مع اسمي الناتجين وتعليل الأكسدة في كل خطوة"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا: عنصران أو ثلاثة من عناصر الإجابة صحيحة"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية الناتج الأول إيثانول أو إيثانون","تعليل الأكسدة باكتساب الهيدروجين","القفز مباشرة إلى حمض الإيثانويك دون الألدهيد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-15T02:47:48.789Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) يختار 1-بروبانول؛ لأن مجموعة OH فيه متصلة بذرة كربون طرفية، فيتأكسد إلى بروبانال ثم يتأكسد البروبانال بسهولة إلى حمض البروبانويك. أما 2-بروبانول فيتأكسد إلى 2-بروبانون (كيتون)، والكيتون لا يتأكسد بسهولة إلى حمض كربوكسيلي. (b) لأن الأكسدة قد تستمر، فيتحول الألدهيد الناتج إلى حمض كربوكسيلي، فيصعب إيقاف التفاعل عند مرحلة الألدهيد.', '["اختيار 1-بروبانول","تعليل: يعطي ألدهيدًا يتأكسد إلى الحمض","2-بروبانول يعطي كيتونًا لا يتأكسد بسهولة","صعوبة تحضير الألدهيد لاستمرار الأكسدة إلى حمض"]'::jsonb, '[]'::jsonb, '[{"element":"الاختيار","marks":1},{"element":"تعليل الاختيار","marks":1},{"element":"سبب رفض 2-بروبانول","marks":1},{"element":"(b)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"اختيار صحيح مع تعليل كامل وتفسير صعوبة تحضير الألدهيد"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا: عنصران أو ثلاثة من عناصر الإجابة صحيحة"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار 2-بروبانول بحجة أن الرقم 2 يعني أكسدة مزدوجة","القول إن الألدهيد لا يتأكسد","الخلط بين حمض البروبانويك و2-بروبانون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-15T02:47:48.789Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
