from (values
('mcq', 1, 2, 'الهكسين الحلقي ألكين والهكسان الحلقي ألكان مشبع؛ فالمطلوب تكسير الرابطة الثنائية بإضافة جزيء H₂ إلى ذرتيها، وهذا تفاعل إضافة يسمى الهدرجة (ويحتاج إلى محفز مثل البلاتين أو البلاديوم).', '["حذف الهيدروجين يحول الألكان إلى ألكين، أي عكس التحويل المطلوب.","الهلجنة تُدخل ذرة هالوجين في المركب، والهكسان الحلقي لا يحتوي على هالوجين.","","التكثف يربط جزيئين عضويين مع فقد جزيء صغير، والتحويل هنا لا يحتاج إلا إلى إضافة H₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-15T02:47:48.789Z"}'::jsonb),
('mcq', 2, 3, 'يتحد الحمض الكربوكسيلي والكحول لتكوين جزيء أكبر هو الإستر مع فقد جزيء ماء: RCOOH + R′OH → RCOOR′ + H₂O، وهذا تفاعل تكثف.', '["لا توجد رابطة ثنائية بين ذرتي كربون في المتفاعلين تُضاف إليها الذرات، ويخرج جزيء ماء.","الاستبدال يحدث في جزيء واحد تحل فيه ذرة محل أخرى، أما هنا فيتحد جزيئان عضويان في جزيء أكبر.","لا يحتاج تكوين الإستر إلى عامل مؤكسد، ولا يكتسب المتفاعل أكسجينًا من مصدر خارجي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-15T02:47:48.789Z"}'::jsonb),
('mcq', 3, 0, 'يتفاعل هاليد الألكيل مع أيون الهيدروكسيد فتحل مجموعة OH محل ذرة الهالوجين: R–X + OH⁻ → R–OH + X⁻؛ فهو تفاعل استبدال.', '["","إضافة الماء تحتاج إلى رابطة ثنائية في ألكين، وهاليد الألكيل مشبع.","حذف HX من هاليد الألكيل ينتج ألكينًا لا كحولًا.","التكثف يكوّن جزيئًا أكبر من جزيئين عضويين، أما هنا فيُستبدل الهالوجين بمجموعة OH."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-15T02:47:48.789Z"}'::jsonb),
('mcq', 4, 2, 'تُنزع ذرة الهالوجين وذرة هيدروجين من ذرتي كربون متجاورتين فتتكون رابطة ثنائية ويخرج HX: R–CH₂–CH₂–X → R–CH=CH₂ + HX؛ فهو تفاعل حذف.', '["الاستبدال يُبقي السلسلة مشبعة ويضع ذرة أو مجموعة مكان الهالوجين، فلا يتكون ألكين.","الإضافة تحول الألكين إلى هاليد ألكيل، أي عكس التحويل المطلوب.","","التحويل لا يتضمن اكتساب أكسجين أو فقد هيدروجين بعامل مؤكسد، بل نزع HX وتكوين رابطة ثنائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-15T02:47:48.789Z"}'::jsonb),
('mcq', 5, 1, 'في إضافة الماء تُضاف ذرة H من جزيء الماء إلى إحدى ذرتي الرابطة الثنائية ومجموعة OH إلى الأخرى، فيتحول الألكين إلى كحول.', '["حذف الماء يحول الكحول إلى ألكين، أي عكس المطلوب.","","الهدرجة تضيف H₂ فيتحول الألكين إلى ألكان لا كحول.","الاستبدال بمجموعة OH يحدث في هاليد الألكيل، أما الألكين فيتفاعل بالإضافة على رابطته الثنائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-15T02:47:48.790Z"}'::jsonb),
('mcq', 6, 0, 'الإيثانول C₂H₆O يتحول إلى الإيثانال C₂H₄O بفقد ذرتي هيدروجين بوجود عامل مؤكسد (O)، والمادة تتأكسد عندما تفقد الهيدروجين؛ فهذا تفاعل أكسدة واختزال يحول الكحول إلى ألدهيد.', '["","إضافة الماء تحدث على رابطة ثنائية بين ذرتي كربون، والإيثانول لا يحتوي عليها.","لم تحل ذرة أو مجموعة محل أخرى؛ بل فقد الكحول ذرتي هيدروجين وتكونت مجموعة كربونيل.","التكثف يربط جزيئين عضويين، أما هنا فيتحول جزيء واحد إلى جزيء أصغر بذرتي هيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-15T02:47:48.790Z"}'::jsonb),
('mcq', 7, 3, 'الخطوة الأولى استبدال: CH₃CH₂CH₂Br + OH⁻ → CH₃CH₂CH₂OH + Br⁻ (1-بروبانول). الخطوة الثانية أكسدة الكحول الذي تتصل فيه OH بذرة كربون طرفية إلى ألدهيد: CH₃CH₂CH₂OH + (O) → CH₃CH₂CHO + H₂O.', '["الحذف يحول هاليد الألكيل إلى بروبين، وأكسدة الألكينات للحصول على ألدهيد ليست من التفاعلات المدروسة؛ والطريق المباشر يمر بالكحول.","الاستبدال يعطي 1-بروبانول، لكن حذف الماء منه ينتج بروبين لا بروبانال.","هاليد الألكيل مشبع لا يحتوي على رابطة ثنائية أو ثلاثية تُضاف إليها الذرات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-15T02:47:48.790Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) إضافة (هدرجة): R–CH=CH₂ + H₂ → R–CH₂–CH₃. (b) استبدال: R–X + OH⁻ → R–OH + X⁻. (c) حذف (حذف هاليد الهيدروجين): R–CH₂–CH₂–X → R–CH=CH₂ + HX. (d) تكثف: يتحد الحمض والأمين في جزيء أكبر (أميد) مع فقد جزيء ماء: RCOOH + R′NH₂ → RCONHR′ + H₂O. (e) إضافة (إضافة الماء): R–CH=CH₂ + H₂O → R–CH(OH)–CH₃ أو R–CH₂–CH₂–OH.', '["(a) هدرجة","(b) استبدال","(c) حذف","(d) تكثف","(e) إضافة الماء"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":1},{"element":"(d)","marks":1},{"element":"(e)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"التحويلات الخمسة صحيحة مع معادلاتها"},{"level":"3–4 درجات","description":"ثلاثة أو أربعة تحويلات صحيحة"},{"level":"1–2 درجة","description":"تحويل أو تحويلان صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين (b) و(c) لأن المتفاعل في كليهما هاليد ألكيل","تسمية (e) حذف الماء","تصنيف (d) استبدالًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-15T02:47:48.790Z"}'::jsonb),
('essay', 2, null::int, null, null, '1) إضافة الماء إلى الإيثين لتكوين الإيثانول: CH₂=CH₂ + H₂O → CH₃CH₂OH (إضافة). 2) أكسدة جزء من الإيثانول إلى إيثانال: CH₃CH₂OH + (O) → CH₃CHO + H₂O (أكسدة واختزال). 3) استمرار أكسدة الإيثانال إلى حمض الإيثانويك: CH₃CHO + (O) → CH₃COOH (أكسدة واختزال). 4) تكثف حمض الإيثانويك مع الجزء الباقي من الإيثانول: CH₃COOH + CH₃CH₂OH → CH₃COOCH₂CH₃ + H₂O (تكثف).', '["تحضير الإيثانول بإضافة الماء","أكسدة الإيثانول إلى إيثانال ثم حمض الإيثانويك","تكثف الحمض مع الإيثانول","تحديد نوع كل خطوة","معادلات موزونة"]'::jsonb, '[]'::jsonb, '[{"element":"خطوة إضافة الماء","marks":1},{"element":"خطوتا الأكسدة","marks":2},{"element":"خطوة التكثف","marks":1},{"element":"أنواع التفاعلات","marks":1},{"element":"موازنة المعادلات","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"طريقة كاملة صحيحة بمعادلات موزونة وأنواع صحيحة"},{"level":"4–5 درجات","description":"طريقة صحيحة مع خطأ في معادلة أو نوع"},{"level":"2–3 درجات","description":"خطوتان صحيحتان فقط"},{"level":"1 درجة","description":"خطوة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["محاولة تكثف الإيثين مباشرة مع الماء لتكوين الإستر","نسيان أن الإيثانول يلزم مرتين: لتكوين الحمض وللتكثف معه","إيقاف الأكسدة عند الإيثانال واستعماله في التكثف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-15T02:47:48.790Z"}'::jsonb),
('essay', 3, null::int, null, null, 'السهم 1: حذف (حذف بروميد الهيدروجين)؛ نُزعت ذرة Br وذرة H من ذرتي كربون متجاورتين فتكونت رابطة ثنائية (بروبين) وخرج HBr. السهم 2: إضافة (هدرجة)؛ أُضيف H₂ إلى الرابطة الثنائية فتحول البروبين إلى بروبان. السهم 3: استبدال؛ حلت مجموعة OH محل ذرة البروم فتكوّن 2-بروبانول. السهم 4: أكسدة واختزال؛ تأكسد الكحول (فقد ذرتي هيدروجين بوجود (O)) فتكون الكيتون 2-بروبانون. (ويرافق هذه الأكسدة نزع ذرتي هيدروجين وخروج الماء، لكن التفاعل يُصنف أكسدة واختزال لوجود العامل المؤكسد (O)).', '["السهم 1 حذف مع التعليل","السهم 2 إضافة (هدرجة) مع التعليل","السهم 3 استبدال مع التعليل","السهم 4 أكسدة مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"السهم 1","marks":1},{"element":"السهم 2","marks":1},{"element":"السهم 3","marks":1},{"element":"السهم 4","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأسهم الأربعة مصنفة تصنيفًا صحيحًا مع التعليل"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا: عنصران أو ثلاثة من عناصر الإجابة صحيحة"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف السهم 3 إضافة لأن OH⁻ أُضيف","تصنيف السهم 4 استبدالًا أو إضافة","تصنيف السهم 1 استبدالًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-15T02:47:48.790Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
