from (values
('mcq', 1, 0, 'المونومرات هي الجزيئات العضوية الصغيرة البسيطة التي يُصنع منها البوليمر، إذ ترتبط معًا في سلسلة طويلة.', '["","هذا تعريف الوحدة البنائية للبوليمر، لا المونومر.","هذا وصف للجزيء الصغير الناتج (كالماء) في البلمرة بالتكثف، وليس المونومر.","هذا وصف للمحفّزات التي تُستعمل لتسريع التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-15T02:47:48.794Z"}'::jsonb),
('mcq', 2, 3, 'تُسمّى مجموعة الذرات المتكررة الناتجة عن ترابط المونومرات وحدة بناء البوليمر، وتتكرر n مرة في السلسلة.', '["هذا تعريف المونومر لا الوحدة البنائية.","البوليمر الكامل يتكوّن من تكرار الوحدة البنائية مرات كثيرة، فالوحدة جزء منه.","الوحدة البنائية مجموعة ذرات، وليست رابطة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-15T02:47:48.795Z"}'::jsonb),
('mcq', 3, 1, 'الوحدة البنائية –CH₂–CH(CH₃)– تحتوي على ذرات المونومر نفسها، وتنتج من كسر الرابطة الثنائية في البروبين CH₂=CH–CH₃ وارتباط المونومرات معًا.', '["البروبان مشبع لا يحتوي على رابطة ثنائية تنكسر لترتبط المونومرات معًا.","","الإيثين يعطي البولي إيثيلين، ووحدته لا تحتوي على مجموعة CH₃ المتفرعة.","البروباين يحتوي على رابطة ثلاثية، ولو تبلمر بالإضافة لبقيت في وحدته رابطة ثنائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-15T02:47:48.795Z"}'::jsonb),
('mcq', 4, 2, 'تتكرر في السلسلة المجموعة –CH₂–CHCl– (ذرة كلور على كل ذرة كربون ثانية)، فهي الوحدة البنائية المتكررة (بولي كلوريد الفينيل).', '["هذه المجموعة لا تمثل التكرار كاملًا؛ إذ تهمل ذرة الكلور الموجودة على كل ذرة كربون ثانية.","هذه صيغة المونومر؛ والوحدة البنائية لا تحتوي على رابطة ثنائية.","","ذرة الكلور ترتبط بكل ذرة كربون ثانية فقط، لا بكل ذرتي كربون متجاورتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-15T02:47:48.795Z"}'::jsonb),
('mcq', 5, 3, 'الإيثين CH₂=CH₂ هو الجزيء الصغير الذي يُصنع منه البولي إيثيلين، فهو المونومر.', '["البوليمر هو الناتج الظاهر بين القوسين مع n، لا الجزيء الصغير المتفاعل.","الوحدة البنائية هي –CH₂–CH₂– بين القوسين، وليس فيها رابطة ثنائية.","الحفّاز لا يُكتب متفاعلًا بمعامل n، والإيثين يُستهلك ويدخل في تركيب البوليمر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-15T02:47:48.796Z"}'::jsonb),
('mcq', 6, 0, 'في البلمرة بالإضافة تبقى جميع ذرات المونومر في الوحدة البنائية (C₂F₄)، لكن الرابطة الثنائية تنكسر فتصبح الرابطة بين ذرتي الكربون أحادية، وترتبط كل وحدة بالوحدتين المجاورتين.', '["","الوحدة البنائية –CF₂–CF₂– ما زالت تحتوي على ذرات الفلور الأربع.","فقد جزيء الماء يحدث في البلمرة بالتكثف، لا في البلمرة بالإضافة.","الوحدة تحتوي على عدد ذرات المونومر نفسه (2 C و4 F)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-15T02:47:48.796Z"}'::jsonb),
('mcq', 7, 1, 'يتكوّن نايلون 6,6 من مونومرين مختلفين: حمض الأديبيك HOOC–(CH₂)₄–COOH الذي يحتوي على مجموعتي كربوكسيل، و1، 6-ثنائي أمينوهكسان H₂N–(CH₂)₆–NH₂ الذي يحتوي على مجموعتي أمين.', '["الإيثين ألكين يعطي بوليمر إضافة، ولا يظهر في المعادلة؛ والمونومر الثاني مع ثنائي الأمين هو حمض الأديبيك.","","الماء ناتج جانبي في المعادلة وليس مونومرًا.","نايلون 6,6 هو البوليمر الناتج لا مونومرًا؛ والمونومر الثاني مع ثنائي الأمين هو حمض الأديبيك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-15T02:47:48.796Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المونومرات: الجزيئات الصغيرة التي يُصنع منها البوليمر. الوحدة البنائية: مجموعة الذرات المتكررة الناتجة عن ترابط المونومرات. وفي المعادلة: المونومر هو الإيثين CH₂=CH₂، والوحدة البنائية هي –CH₂–CH₂– المحصورة بين القوسين، والبوليمر هو البولي إيثيلين [–CH₂–CH₂–]n.', '["تعريف المونومر","تعريف الوحدة البنائية","المونومر: CH₂=CH₂ (الإيثين)","الوحدة البنائية: –CH₂–CH₂–","البوليمر: البولي إيثيلين [–CH₂–CH₂–]n"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف المونومر","marks":1},{"element":"تعريف الوحدة البنائية","marks":1},{"element":"تحديد المونومر","marks":1},{"element":"تحديد الوحدة البنائية","marks":1},{"element":"تحديد البوليمر","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3–4 درجات","description":"تعريفان صحيحان مع تحديد جزئي، أو تحديد صحيح مع تعريف ناقص"},{"level":"1–2 درجة","description":"تعريف واحد صحيح أو تحديد المونومر فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين المونومر والوحدة البنائية","كتابة الوحدة البنائية برابطة ثنائية","عدّ n جزءًا من الوحدة البنائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-15T02:47:48.796Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) المونومر CH₂=CCl₂ (رابطة ثنائية بين ذرتي الكربون وذرتا كلور على ذرة الكربون نفسها). (ب) يحتوي المونومر والوحدة البنائية على عدد الذرات نفسه (ذرتا C وذرتا H وذرتا Cl)؛ لأن جميع ذرات المونومر تبقى في البوليمر. أما الرابطة بين ذرتي الكربون فهي ثنائية في المونومر وأحادية في الوحدة البنائية، إذ تنكسر الرابطة الثنائية لترتبط كل وحدة بالوحدتين المجاورتين.', '["صيغة المونومر CH₂=CCl₂","عدد الذرات نفسه: 2 C و2 H و2 Cl","الرابطة ثنائية في المونومر وأحادية في الوحدة"]'::jsonb, '[]'::jsonb, '[{"element":"صيغة المونومر صحيحة","marks":2},{"element":"المقارنة من حيث عدد الذرات","marks":1},{"element":"المقارنة من حيث نوع الرابطة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2–3 درجات","description":"صيغة صحيحة للمونومر مع مقارنة ناقصة"},{"level":"1 درجة","description":"مقارنة صحيحة دون صيغة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة المونومر CHCl=CHCl بتوزيع ذرتي الكلور على ذرتي الكربون","كتابة المونومر برابطة أحادية","القول إن الوحدة البنائية فقدت ذرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-15T02:47:48.796Z"}'::jsonb),
('essay', 3, null::int, null, null, 'أولًا: السلسلتان (أ) و(ب) بوليمران متجانسان؛ لأن كلًّا منهما يتكوّن من نوع واحد من المونومرات (الأول في أ، والثاني في ب). والسلسلة (ج) بوليمر مختلط؛ لأنها تتكوّن من نوعين مختلفين من المونومرات مرتبطين معًا بتسلسل متناوب. ثانيًا: الوحدة البنائية في (ج) تتكوّن من مونومر أول مرتبط بمونومر ثانٍ، وتتكرر على طول السلسلة. ثالثًا: النايلون (نايلون 6,6 من حمض الأديبيك و1، 6-ثنائي أمينوهكسان)، أو ألياف البوليستر.', '["(أ) و(ب) متجانسان: نوع واحد من المونومر","(ج) مختلط: نوعان من المونومرات بالتناوب","الوحدة في (ج): مونومر أول + مونومر ثانٍ","مثال: النايلون أو البوليستر"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف (أ) و(ب) مع التفسير","marks":2},{"element":"تصنيف (ج) مع التفسير","marks":1},{"element":"تحديد الوحدة البنائية في (ج)","marks":1},{"element":"مثال صحيح","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3–4 درجات","description":"تصنيف صحيح للسلاسل الثلاث مع نقص في تحديد الوحدة أو المثال"},{"level":"1–2 درجة","description":"تصنيف صحيح لسلسلة واحدة أو اثنتين دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الكرة الواحدة في (ج) هي الوحدة البنائية","عدّ (أ) و(ب) بوليمرًا مختلطًا لاختلاف لونيهما","التمثيل بالبولي إيثيلين للبوليمر المختلط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-15T02:47:48.796Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
