('mcq', 4, 'تمثّل الصيغة الآتية الوحدة البنائية لبوليمر بولي فينيلدين كلوريد. فيمَ يُستعمل هذا البوليمر غالبًا؟', null, '[{"src":"qimg/chem22/c5-l5a-pvdc.svg","alt":"وحدة بنائية متكررة بين قوسين مربعين: مجموعة CH₂ مرتبطة برابطة أحادية بذرة C، وترتبط بذرة C هذه ذرة Cl إلى أعلى وذرة Cl أخرى إلى أسفل بروابط أحادية، وتعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن الحرف n."}]'::jsonb, '["تغليف الطعام والأقمشة","الأنابيب البلاستيكية وجدران المنازل","زجاجات العصير والحليب","العدسات والتحف الفنية"]'::jsonb, 'تذكر', 'تذكر استعمال', 'متوسط', 'الكتاب ص 194 — الجدول 5-14 البوليمرات الشائعة'),
('mcq', 5, 'تمثّل الصيغة الآتية الوحدة البنائية لأحد البوليمرات الشائعة. ما أبرز استعمالات هذا البوليمر؟', null, '[{"src":"qimg/chem22/c5-l5a-pan.svg","alt":"وحدة بنائية متكررة بين قوسين مربعين: مجموعة CH₂ مرتبطة برابطة أحادية بمجموعة CH، وتتدلى من CH إلى أسفل رابطة أحادية إلى ذرة C مرتبطة بذرة N برابطة ثلاثية، وتعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن الحرف n."}]'::jsonb, '["أوعية المشروبات والحبال وأدوات المطبخ","رغوة التغليف وأوعية النباتات","الأقمشة والملابس والمفروشات والسجاد","زجاجات الحليب والإطارات"]'::jsonb, 'فهم', 'ربط التركيب بالاستعمال', 'صعب', 'الكتاب ص 194 — الجدول 5-14 البوليمرات الشائعة'),
('mcq', 6, 'ما البوليمر الذي يُستعمل في صناعة ألعاب الأطفال غير القابلة للكسر لأنه مادة غير سامة؟', null, null, '["بولي كلوريد الفينيل (PVC)","بولي ستايرين (PS)","بولي إيثيلين رباعي فثالات (PETE)","البولي إيثيلين منخفض الكثافة (LDPE)"]'::jsonb, 'تذكر', 'تذكر استعمال', 'سهل', 'الكتاب ص 192 — البولي إيثيلين منخفض الكثافة (الشكل 5-18)'),
('mcq', 7, 'استُعمل النايلون على نطاق واسع في أثناء الحرب العالمية الثانية (1939–1945م). فيمَ استُعمل؟', null, null, '["صناعة أوراق النقد","صناعة المظلات والخيام","طلاء أواني الطبخ غير اللاصق","صناعة الأقراص المدمجة"]'::jsonb, 'تذكر', 'تذكر استعمال', 'سهل', 'الكتاب ص 193 — النايلون والخط الزمني (الشكل 5-19)'),
('essay', 1, 'اكتب استعمالين لكلٍّ من البوليمرات الآتية: (أ) بولي بروبلين (PP)، (ب) بولي يوريثان، (ج) الطلاء غير اللاصق (PTFE)، (د) بولي كلوريد الفينيل (PVC).', null, null, null, 'تذكر', 'تذكر استعمالات', 'متوسط', 'الكتاب ص 193، 194، 204 — الجدول 5-14 والسؤال 62'),
('essay', 2, 'يريد مصنع اختيار بوليمر مناسب لكل منتج من المنتجات الآتية: (أ) زجاج غير قابل للكسر لعدسات النظارات، (ب) زجاجات العصير والحليب، (ج) الحبال، (د) رغوة لتغليف الأجهزة وعزلها. سمِّ البوليمر المناسب لكل منتج، واذكر استعمالًا آخر له.', null, null, null, 'تطبيق', 'اختيار مادة لاستعمال', 'صعب', 'الكتاب ص 194 — الجدول 5-14 البوليمرات الشائعة'),
('essay', 3, 'يبيّن الشكل الآتي الوحدتين البنائيتين لبوليمرين (أ) و(ب). سمِّ كل بوليمر، واكتب صيغة المونومر الذي يتكوّن منه، واذكر استعمالين لكل منهما.', null, '[{"src":"qimg/chem22/c5-l5a-pp-pvc.svg","alt":"وحدتان بنائيتان. (أ): بين قوسين مربعين CH₂ مرتبطة برابطة أحادية بـ CH، وتتدلى من CH إلى أسفل مجموعة CH₃. (ب): بين قوسين مربعين CH₂ مرتبطة برابطة أحادية بـ CH، وتتدلى من CH إلى أسفل ذرة Cl. وفي كل منهما تعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن الحرف n."}]'::jsonb, null, 'فهم', 'ربط التركيب بالاسم والاستعمال', 'صعب', 'الكتاب ص 194 — الجدول 5-14 البوليمرات الشائعة')
