('mcq', 1, 2, 'يُستعمل بولي كلوريد الفينيل (PVC) في صناعة الأنابيب البلاستيكية، وخراطيم المياه، وتغطية اللحوم والمفروشات، وملابس المطر، وجدران المنازل.', '["رغوة التغليف والعزل من استعمالات بولي ستايرين (PS).","العدسات والزجاج غير القابل للكسر من استعمالات بولي ميثيل ميثاكريلات.","","وسائد النوم والطلاء المقاوم للماء من استعمالات بولي يوريثان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-15T02:47:48.797Z"}'::jsonb),
('mcq', 2, 1, 'الوحدة البنائية تحتوي على حلقة بنزين مرتبطة بسلسلة –CH₂–CH–، فهي وحدة بولي ستايرين (PS)، ويُستعمل في رغوة التغليف والعزل، وأوعية النباتات، وحاويات حفظ الطعام، وعمل النماذج.', '["الحبال وأوعية المشروبات من استعمالات بولي بروبلين، ووحدته تحتوي على مجموعة CH₃ لا حلقة بنزين.","","الأقمشة والسجاد من استعمالات بولي أكريلونيتريل، ووحدته تحتوي على مجموعة C≡N.","الأثاث وأجزاء الأحذية من استعمالات بولي يوريثان، ووحدته مختلفة تمامًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-15T02:47:48.797Z"}'::jsonb),
('mcq', 3, 3, 'يُستعمل بولي يوريثان في صناعة الأثاث، ووسائد النوم، والطلاء المقاوم للماء، وبعض أجزاء الأحذية.', '["بولي بروبلين يُستعمل في أوعية المشروبات والحبال وأدوات المطبخ.","بولي فينيلدين كلوريد يُستعمل في تغليف الطعام والأقمشة.","بولي ميثيل ميثاكريلات يُستعمل زجاجًا غير قابل للكسر للنوافذ والعدسات والتحف الفنية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-15T02:47:48.797Z"}'::jsonb),
('mcq', 4, 0, 'يُستعمل بولي فينيلدين كلوريد في تغليف الطعام والأقمشة.', '["","الأنابيب وجدران المنازل من استعمالات بولي كلوريد الفينيل (PVC)، ووحدته تحتوي على ذرة كلور واحدة فقط.","زجاجات العصير والحليب من استعمالات بولي إيثيلين رباعي فثالات (PETE).","العدسات والتحف الفنية من استعمالات بولي ميثيل ميثاكريلات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-15T02:47:48.797Z"}'::jsonb),
('mcq', 5, 2, 'الوحدة البنائية تحتوي على مجموعة C≡N مرتبطة بسلسلة –CH₂–CH–، فهي وحدة بولي أكريلونيتريل، ويُستعمل في الأقمشة والملابس والمفروشات والسجاد.', '["هذه استعمالات بولي بروبلين، ووحدته تحتوي على مجموعة CH₃ لا C≡N.","هذه استعمالات بولي ستايرين، ووحدته تحتوي على حلقة بنزين.","","هذه استعمالات بولي إيثيلين رباعي فثالات (PETE)، ووحدته تحتوي على حلقة بنزين ومجموعتي إستر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-15T02:47:48.797Z"}'::jsonb),
('mcq', 6, 3, 'البولي إيثيلين منخفض الكثافة (LDPE) مادة غير سامة وغير قابلة للكسر، لذا يدخل في صناعة ألعاب الأطفال، ويُحضَّر ببلمرة الإيثين تحت ضغط عالٍ.', '["بولي كلوريد الفينيل يُستعمل في الأنابيب والخراطيم وملابس المطر.","بولي ستايرين يُستعمل في رغوة التغليف والعزل.","بولي إيثيلين رباعي فثالات يُستعمل في العبوات البلاستيكية وألياف البوليستر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-15T02:47:48.797Z"}'::jsonb),
('mcq', 7, 1, 'النايلون يمتاز بالقوة ويمكن سحبه على شكل خيوط تشبه الحرير، فاستُعمل خلال الحرب العالمية الثانية في صناعة المظلات والخيام، ثم دخل في صناعة الملابس.', '["أوراق النقد المصنوعة من البوليمرات صدرت لأول مرة عام 1988م، وليست من النايلون.","","الطلاء غير اللاصق مصنوع من بوليمر PTFE لا من النايلون.","الأقراص المدمجة مصنوعة من البولي كربونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-15T02:47:48.797Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) بولي بروبلين: أوعية المشروبات، والحبال، وأدوات المطبخ. (ب) بولي يوريثان: الأثاث، ووسائد النوم، والطلاء المقاوم للماء، وبعض أجزاء الأحذية. (ج) PTFE: طلاء تجهيزات المطبخ غير اللاصق، والخطافات والتروس. (د) PVC: الأنابيب البلاستيكية، وخراطيم المياه، وتغطية اللحوم والمفروشات، وملابس المطر، وجدران المنازل.', '["استعمالان صحيحان لبولي بروبلين","استعمالان صحيحان لبولي يوريثان","استعمالان صحيحان للطلاء غير اللاصق","استعمالان صحيحان لـ PVC"]'::jsonb, '[]'::jsonb, '[{"element":"بولي بروبلين","marks":2},{"element":"بولي يوريثان","marks":2},{"element":"الطلاء غير اللاصق PTFE","marks":2},{"element":"بولي كلوريد الفينيل","marks":2}]'::jsonb, '[{"level":"8 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"5–7 درجات","description":"استعمالات صحيحة لثلاثة بوليمرات أو استعمال واحد لكل بوليمر"},{"level":"1–4 درجات","description":"استعمالات صحيحة لبوليمر أو بوليمرين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة رغوة التغليف إلى بولي بروبلين","نسبة تغليف الطعام إلى PVC بدل بولي فينيلدين كلوريد","الخلط بين بولي يوريثان وبولي ستايرين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (8 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-15T02:47:48.797Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) بولي ميثيل ميثاكريلات؛ ويُستعمل أيضًا زجاجًا غير قابل للكسر للنوافذ وفي التحف الفنية. (ب) بولي إيثيلين رباعي فثالات (PETE)؛ ويُستعمل أيضًا في الإطارات والملابس (ألياف البوليستر) وأواني الطعام التي تستعمل مرة واحدة. (ج) بولي بروبلين (PP)؛ ويُستعمل أيضًا في أوعية المشروبات وأدوات المطبخ. (د) بولي ستايرين (PS)؛ ويُستعمل أيضًا في أوعية النباتات وحاويات حفظ الطعام وعمل النماذج.', '["(أ) بولي ميثيل ميثاكريلات + استعمال آخر","(ب) PETE + استعمال آخر","(ج) بولي بروبلين + استعمال آخر","(د) بولي ستايرين + استعمال آخر"]'::jsonb, '[]'::jsonb, '[{"element":"تسمية البوليمر (أ) واستعمال آخر","marks":2},{"element":"تسمية البوليمر (ب) واستعمال آخر","marks":2},{"element":"تسمية البوليمر (ج) واستعمال آخر","marks":2},{"element":"تسمية البوليمر (د) واستعمال آخر","marks":2}]'::jsonb, '[{"level":"8 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"5–7 درجات","description":"تسمية صحيحة لثلاثة بوليمرات أو أكثر مع نقص في الاستعمالات الأخرى"},{"level":"1–4 درجات","description":"تسمية صحيحة لبوليمر أو بوليمرين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار PVC لعدسات النظارات","اختيار بولي يوريثان لرغوة التغليف","تكرار الاستعمال المذكور في السؤال بدل استعمال آخر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (8 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-15T02:47:48.797Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) بولي بروبلين (PP)، ومونومره البروبين CH₂=CH–CH₃، ومن استعمالاته: أوعية المشروبات، والحبال، وأدوات المطبخ. (ب) بولي كلوريد الفينيل (PVC)، ومونومره CH₂=CHCl، ومن استعمالاته: الأنابيب البلاستيكية، وخراطيم المياه، وملابس المطر، وجدران المنازل، وتغطية اللحوم والمفروشات.', '["(أ) بولي بروبلين","مونومر (أ): CH₂=CH–CH₃","استعمالان لبولي بروبلين","(ب) بولي كلوريد الفينيل","مونومر (ب): CH₂=CHCl","استعمالان لـ PVC"]'::jsonb, '[]'::jsonb, '[{"element":"تسمية (أ)","marks":1},{"element":"مونومر (أ)","marks":1},{"element":"استعمالا (أ)","marks":1},{"element":"تسمية (ب)","marks":1},{"element":"مونومر (ب)","marks":1},{"element":"استعمالا (ب)","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3–5 درجات","description":"تسمية صحيحة للبوليمرين مع نقص في المونومرات أو الاستعمالات"},{"level":"1–2 درجة","description":"تسمية بوليمر واحد أو ذكر استعمالاته فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ (أ) بولي إيثيلين لإهمال مجموعة CH₃","كتابة المونومر بلا رابطة ثنائية","نسبة استعمالات PVC إلى بولي فينيلدين كلوريد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-15T02:47:48.798Z"}'::jsonb)
