select (select id from public.objectives where code = 'K22-C5-L5-O04'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما الوصف الصحيح للبلمرة بالإضافة؟', null, null, '["ترتبط فيها مونومرات تحتوي على مجموعتين وظيفيتين مع فقد جزيء ماء","تتفكك فيها جزيئات البوليمر الكبيرة إلى مونومرات صغيرة","يُضاف فيها الماء إلى الرابطة الثنائية لتكوين كحول","تبقى فيها جميع الذرات الموجودة في المونومر في تركيب البوليمر"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 193 — البلمرة بالإضافة والبلمرة بالتكثف'),
('mcq', 2, 'إلى أيّ نوع تُصنَّف البلمرة في المعادلة الآتية، وما الدليل على ذلك؟', null, '[{"src":"qimg/chem22/c5-l5a-nylon66.svg","alt":"معادلة على سطرين. السطر الأول: nHOOC–(CH₂)₄–COOH + nH₂N–(CH₂)₆–NH₂. السطر الثاني: سهم يشير إلى اليمين، ثم وحدة بنائية بين قوسين مربعين، من اليسار: ذرة C مرتبطة بذرة O إلى أعلى برابطة ثنائية، ثم (CH₂)₄، ثم ذرة C مرتبطة بذرة O إلى أعلى برابطة ثنائية، ثم NH، ثم (CH₂)₆، ثم NH، والمجموعات متصلة بروابط أحادية، وتعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن n، وبعد القوسين: + 2nH₂O."}]'::jsonb, '["بلمرة بالتكثف؛ لأنها يصاحبها تكوّن جزيئات ماء","بلمرة بالإضافة؛ لأن المونومرين يرتبطان معًا في سلسلة","بلمرة بالإضافة؛ لأن الوحدة البنائية تحتوي على ذرات المونومرين كلها","بلمرة بالتكثف؛ لأن المونومرين يحتويان على روابط ثنائية بين ذرات الكربون"]'::jsonb, 'فهم', 'تصنيف تفاعل مع تعليل', 'سهل', 'الكتاب ص 193 — البلمرة بالإضافة والبلمرة بالتكثف'),
('mcq', 3, 'ما الشرط الذي يجب أن تحققه المونومرات لكي تتحد معًا بالبلمرة بالتكثف؟', null, null, '["أن يحتوي كل منها على رابطة ثنائية بين ذرتي كربون","أن تكون هيدروكربونات مشبعة بلا مجموعات وظيفية","أن يحتوي كل منها على اثنتين على الأقل من المجموعات الوظيفية","أن تكون جميعها من النوع نفسه دون اختلاف"]'::jsonb, 'تذكر', 'تذكر شرط', 'متوسط', 'الكتاب ص 193 — البلمرة بالإضافة والبلمرة بالتكثف'),
('mcq', 4, 'عند تكوّن البولي إيثيلين من الإيثين، ما الذي يحدث للرابطة الثنائية في كل مونومر؟', null, null, '["تبقى كما هي، وترتبط المونومرات بروابط هيدروجينية","تنكسر، فترتبط ذرتا الكربون بالمونومرين المجاورين بروابط أحادية","تتحول إلى رابطة ثلاثية بفقد ذرتي هيدروجين","تنكسر مع فقد جزيء ماء من كل مونومرين متجاورين"]'::jsonb, 'فهم', 'تفسير آلية', 'سهل', 'الكتاب ص 193 — البلمرة بالإضافة والبلمرة بالتكثف'),
('mcq', 5, 'أيّ العبارات الآتية تصف نوع البلمرة المتوقع لكل من المونومرين (I) و(II) وصفًا صحيحًا؟', null, '[{"src":"qimg/chem22/c5-l5a-monomers-1-2.svg","alt":"مونومران. (I): مجموعة CH₂ مرتبطة برابطة ثنائية بمجموعة CH، وتتدلى من CH إلى أسفل رابطة أحادية إلى ذرة Cl. (II): من اليسار H₂N مرتبطة برابطة أحادية بمجموعة CH₂، ثم CH₂، ثم ذرة C ترتبط بذرة O إلى أعلى برابطة ثنائية وبمجموعة OH إلى اليمين برابطة أحادية."}]'::jsonb, '["(I) يتبلمر بالإضافة، و(II) يتبلمر بالتكثف","(I) يتبلمر بالتكثف، و(II) يتبلمر بالإضافة","كلاهما يتبلمر بالإضافة","كلاهما يتبلمر بالتكثف"]'::jsonb, 'تحليل', 'تصنيف من التركيب', 'صعب', 'الكتاب ص 193 — البلمرة بالإضافة والبلمرة بالتكثف'),
('mcq', 6, 'في أثناء تكوين بوليمر بالتكثف تكوّنت 500 رابطة أميد جديدة. كم جزيء ماء تكوّن في أثناء ذلك؟', null, null, '["250 جزيء ماء","1000 جزيء ماء","لا يتكوّن أي جزيء ماء","500 جزيء ماء"]'::jsonb, 'تطبيق', 'استنتاج كمي', 'متوسط', 'الكتاب ص 193 — البلمرة بالإضافة والبلمرة بالتكثف'),
('mcq', 7, 'صنّف تفاعل البلمرة الآتي، مع ذكر السبب.', null, '[{"src":"qimg/chem22/c5-l5a-pan-eq.svg","alt":"معادلة: n CH₂=CH (رابطة ثنائية بين ذرتي الكربون)، وتتدلى من CH إلى أسفل رابطة أحادية إلى ذرة C مرتبطة بذرة N برابطة ثلاثية؛ ثم سهم يشير إلى اليمين، ثم وحدة بنائية بين قوسين مربعين: CH₂ مرتبطة برابطة أحادية بـ CH، وتتدلى من CH المجموعة نفسها (C مرتبطة بـ N برابطة ثلاثية)، وتعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن الحرف n."}]'::jsonb, '["بالتكثف؛ لأن المونومر يحتوي على مجموعة وظيفية C≡N","بالتكثف؛ لأن عددًا كبيرًا من المونومرات يرتبط معًا","بالإضافة؛ لأن جميع ذرات المونومر تبقى في البوليمر","بالإضافة؛ لأن الرابطة الثلاثية C≡N تنكسر في أثناء البلمرة"]'::jsonb, 'فهم', 'تصنيف تفاعل مع تعليل', 'متوسط', 'الكتاب ص 193، 196 — البلمرة بالإضافة والسؤال 22'),
('essay', 1, 'اشرح الفرق بين البلمرة بالإضافة والبلمرة بالتكثف من حيث: (أ) نوع المونومرات، (ب) بقاء ذرات المونومر في البوليمر وتكوّن نواتج جانبية، (ج) مثال لكل نوع.', null, null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 193، 203 — البلمرة والسؤال 53'),
('essay', 2, 'ادرس المونومرين (a) و(b) في الشكل الآتي. حدّد نوع البلمرة المتوقع لكل منهما مع التعليل، ثم اكتب الوحدة البنائية المتكررة للبوليمر الناتج من كل منهما.', null, '[{"src":"qimg/chem22/c5-l5a-monomers-a-b.svg","alt":"مونومران. (a): مجموعة CH مرتبطة برابطة ثنائية بمجموعة CH أخرى، وتتدلى من كل منهما إلى أسفل رابطة أحادية إلى ذرة Cl. (b): من اليسار H₂N مرتبطة برابطة أحادية بـ CH₂CH₂، ثم ذرة C ترتبط بذرة O إلى أعلى برابطة ثنائية وبمجموعة OH إلى اليمين برابطة أحادية."}]'::jsonb, null, 'تطبيق', 'كتابة صيغة وتصنيف', 'صعب', 'الكتاب ص 193، 196 — البلمرة والسؤال 21'),
('essay', 3, 'ادرس معادلة تحضير نايلون 6,6 الآتية، ثم أجب: (أ) صنّف تفاعل البلمرة مع التعليل. (ب) ما المجموعتان الوظيفيتان المتفاعلتان، وما الرابطة الجديدة المتكوّنة بينهما؟ (ج) فسّر لماذا تكون الكتلة المولية للبوليمر الناتج أقل من مجموع كتل المونومرات المتفاعلة، في حين تساوي كتلة البوليمر بالإضافة مجموع كتل مونومراته.', null, '[{"src":"qimg/chem22/c5-l5a-nylon66.svg","alt":"معادلة على سطرين. السطر الأول: nHOOC–(CH₂)₄–COOH + nH₂N–(CH₂)₆–NH₂. السطر الثاني: سهم يشير إلى اليمين، ثم وحدة بنائية بين قوسين مربعين، من اليسار: ذرة C مرتبطة بذرة O إلى أعلى برابطة ثنائية، ثم (CH₂)₄، ثم ذرة C مرتبطة بذرة O إلى أعلى برابطة ثنائية، ثم NH، ثم (CH₂)₆، ثم NH، والمجموعات متصلة بروابط أحادية، وتعبر القوسين رابطتان طرفيتان، وأسفل القوس الأيمن n، وبعد القوسين: + 2nH₂O."}]'::jsonb, null, 'تحليل', 'تحليل معادلة', 'صعب', 'الكتاب ص 193 — البلمرة بالإضافة والبلمرة بالتكثف')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C5-L5-O04') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'في البلمرة بالإضافة تبقى جميع الذرات الموجودة في المونومر في تركيب البوليمر، ولا يُفقد أي جزيء صغير.', '["هذا وصف البلمرة بالتكثف.","البلمرة بناء جزيء كبير من جزيئات صغيرة، لا تفكيكه.","هذا وصف تفاعل إضافة الماء إلى الألكين، وناتجه كحول لا بوليمر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-15T02:47:48.798Z"}'::jsonb),
('mcq', 2, 0, 'المعادلة تُظهر تكوّن الماء ناتجًا جانبيًّا مع تكوّن روابط الأميد بين المونومرين، وهذا يميز البلمرة بالتكثف.', '["","ترابط المونومرات في سلسلة يحدث في نوعي البلمرة، فلا يصلح دليلًا على الإضافة.","الوحدة البنائية لا تحتوي على ذرات المونومرين كلها؛ إذ فُقدت ذرات على هيئة جزيئات ماء.","النوع صحيح لكن السبب خاطئ؛ فالمونومران لا يحتويان على روابط ثنائية بين ذرات الكربون، بل على مجموعات كربوكسيل وأمين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-15T02:47:48.798Z"}'::jsonb),
('mcq', 3, 2, 'تحدث البلمرة بالتكثف عندما تحتوي المونومرات على اثنتين على الأقل من المجموعات الوظيفية، فتتحد معًا ويصاحب ذلك فقد جزيء صغير غالبًا ما يكون الماء.', '["الرابطة الثنائية بين ذرتي الكربون شرط البلمرة بالإضافة.","الهيدروكربونات المشبعة لا تحتوي على مجموعات وظيفية تتفاعل لتكوين روابط بين المونومرات.","","قد تتكوّن بوليمرات التكثف من مونومرين مختلفين، مثل نايلون 6,6."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-15T02:47:48.798Z"}'::jsonb),
('mcq', 4, 1, 'البلمرة بالإضافة تشبه تفاعلات الإضافة؛ إذ تنكسر الرابطة غير المشبعة (الثنائية) في الإيثين، وترتبط كل ذرة كربون بذرة كربون من مونومر مجاور برابطة أحادية.', '["لو بقيت الرابطة الثنائية لظهرت في الوحدة البنائية، والوحدات في البوليمر مرتبطة بروابط تساهمية لا هيدروجينية.","","لا تُفقد ذرات هيدروجين في البلمرة بالإضافة، ولا تتكوّن روابط ثلاثية.","لا يُفقد الماء في البلمرة بالإضافة؛ فهذا يحدث في البلمرة بالتكثف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-15T02:47:48.798Z"}'::jsonb),
('mcq', 5, 0, 'المونومر (I) يحتوي على رابطة ثنائية بين ذرتي كربون، فيتبلمر بالإضافة. والمونومر (II) يحتوي على مجموعتين وظيفيتين (أمين وكربوكسيل) ولا يحتوي على رابطة C=C، فيتبلمر بالتكثف مكوّنًا روابط أميد مع فقد الماء.', '["","عكس الصواب؛ فالرابطة الثنائية بين ذرتي الكربون في (I) تؤهله للإضافة، والمجموعتان الوظيفيتان في (II) تؤهلانه للتكثف.","المونومر (II) لا يحتوي على رابطة ثنائية بين ذرتي كربون تنكسر في البلمرة بالإضافة.","المونومر (I) لا يحتوي على مجموعتين وظيفيتين تتفاعلان مع فقد جزيء صغير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-15T02:47:48.798Z"}'::jsonb),
('mcq', 6, 3, 'يتكوّن جزيء ماء واحد مقابل كل رابطة أميد جديدة تتكوّن؛ لذا يتكوّن 500 جزيء ماء.', '["افتُرض خطأً أن جزيء الماء يتكوّن مقابل كل رابطتين.","افتُرض خطأً أن كل رابطة أميد يصاحبها جزيئا ماء.","عدم تكوّن ناتج جانبي صفة البلمرة بالإضافة لا التكثف.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-15T02:47:48.798Z"}'::jsonb),
('mcq', 7, 2, 'تنكسر الرابطة الثنائية C=C في الأكريلونيتريل، وترتبط المونومرات معًا دون فقد أي جزيء، فتحتوي الوحدة البنائية على ذرات المونومر جميعها؛ وهذه بلمرة بالإضافة.', '["التكثف يتطلب مجموعتين وظيفيتين على الأقل وفقد جزيء صغير، ولا يُفقد هنا أي جزيء.","ارتباط عدد كبير من المونومرات يحدث في نوعي البلمرة، فلا يميز التكثف.","","النوع صحيح لكن السبب خاطئ؛ فالرابطة الثلاثية C≡N تبقى في الوحدة البنائية، والتي تنكسر هي الرابطة الثنائية C=C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-15T02:47:48.799Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) في البلمرة بالإضافة تحتوي المونومرات على روابط غير مشبعة (رابطة ثنائية بين ذرتي كربون) تنكسر في أثناء التفاعل، أما في البلمرة بالتكثف فيحتوي كل مونومر على اثنتين على الأقل من المجموعات الوظيفية. (ب) في الإضافة تبقى جميع ذرات المونومر في البوليمر ولا يتكوّن ناتج جانبي، أما في التكثف فيصاحب ترابط المونومرات فقد جزيء صغير غالبًا ما يكون الماء. (ج) الإضافة: تكوين البولي إيثيلين من الإيثين؛ التكثف: تكوين نايلون 6,6 من حمض الأديبيك و1، 6-ثنائي أمينوهكسان.', '["الإضافة: مونومرات غير مشبعة","التكثف: مجموعتان وظيفيتان على الأقل","الإضافة: تبقى جميع الذرات ولا ناتج جانبي","التكثف: فقد جزيء صغير كالماء","مثال الإضافة: البولي إيثيلين","مثال التكثف: نايلون 6,6"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة في نوع المونومرات","marks":2},{"element":"المقارنة في بقاء الذرات والنواتج الجانبية","marks":2},{"element":"مثالان صحيحان","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3–5 درجات","description":"مقارنة صحيحة في معيارين أو مقارنة كاملة دون أمثلة"},{"level":"1–2 درجة","description":"وصف نوع واحد من البلمرة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن البلمرة بالتكثف لا تحتاج إلى مجموعات وظيفية","التمثيل للتكثف ببولي كلوريد الفينيل","الخلط بين البلمرة بالإضافة وتفاعل إضافة الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.799Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) CHCl=CHCl يحتوي على رابطة ثنائية بين ذرتي الكربون، فيتبلمر بالإضافة: تنكسر الرابطة الثنائية وتبقى جميع الذرات، والوحدة البنائية [–CHCl–CHCl–]n. (b) H₂N–CH₂CH₂–COOH يحتوي على مجموعتين وظيفيتين (أمين وكربوكسيل)، فيتبلمر بالتكثف: تتفاعل مجموعة الأمين في مونومر مع مجموعة الكربوكسيل في مونومر آخر مكوّنة رابطة أميد مع فقد جزيء ماء، والوحدة البنائية [–NH–CH₂CH₂–C(=O)–]n، ويتكوّن الماء ناتجًا جانبيًّا.', '["(a) بالإضافة لوجود رابطة C=C","وحدة (a): –CHCl–CHCl–","(b) بالتكثف لوجود مجموعتي أمين وكربوكسيل","وحدة (b): –NH–CH₂CH₂–CO– مع فقد H₂O"]'::jsonb, '["تحديد الرابطة الثنائية في (a)","كسر الرابطة الثنائية وكتابة الوحدة بين قوسين مع n","تحديد المجموعتين الوظيفيتين في (b)","ربط NH من مجموعة الأمين بـ C=O من مجموعة الكربوكسيل بحذف OH وH على هيئة ماء","كتابة الوحدة بين قوسين مع n"]'::jsonb, '[{"element":"نوع بلمرة (a) مع التعليل","marks":1},{"element":"الوحدة البنائية لـ (a)","marks":2},{"element":"نوع بلمرة (b) مع التعليل","marks":1},{"element":"الوحدة البنائية لـ (b)","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3–5 درجات","description":"تصنيف صحيح للمونومرين مع خطأ في إحدى الوحدتين البنائيتين"},{"level":"1–2 درجة","description":"تصنيف صحيح دون كتابة الوحدات البنائية"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إبقاء الرابطة الثنائية في وحدة (a)","إبقاء ذرات الماء في وحدة (b)","تصنيف (b) بالإضافة لوجود الرابطة C=O"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-15T02:47:48.799Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) بلمرة بالتكثف؛ لأن كل مونومر يحتوي على مجموعتين وظيفيتين، ويصاحب ترابطهما فقد جزيئات ماء. (ب) مجموعة الكربوكسيل (–COOH) في حمض الأديبيك ومجموعة الأمين (–NH₂) في 1، 6-ثنائي أمينوهكسان، وتتكوّن بينهما رابطة أميد (–CO–NH–)، ويتكوّن جزيء ماء مقابل كل رابطة أميد. (ج) لأن جزءًا من ذرات المونومرات يخرج على هيئة جزيئات ماء في البلمرة بالتكثف فلا يدخل في البوليمر؛ أما في البلمرة بالإضافة فتبقى جميع ذرات المونومرات في البوليمر، فتساوي كتلته مجموع كتلها.', '["تكثف لوجود مجموعتين وظيفيتين وفقد الماء","الكربوكسيل والأمين","رابطة الأميد","خروج ذرات على هيئة ماء يقلل الكتلة","في الإضافة تبقى جميع الذرات"]'::jsonb, '[]'::jsonb, '[{"element":"التصنيف مع التعليل","marks":2},{"element":"المجموعتان الوظيفيتان والرابطة الجديدة","marks":2},{"element":"تفسير الفرق في الكتلة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3–5 درجات","description":"تصنيف صحيح وتحديد الرابطة مع تفسير ناقص للكتلة"},{"level":"1–2 درجة","description":"تصنيف صحيح دون تعليل أو تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية الرابطة الجديدة رابطة إستر","عدّ الماء مونومرًا","القول إن كتلة البوليمر بالتكثف تساوي مجموع كتل المونومرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-15T02:47:48.799Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C5-L5-O04') and x.type = v.type and x.number = v.number
