from (values
('mcq', 1, 1, 'البولي إيثيلين سلسلة طويلة من الألكان كما يظهر من وحدته البنائية (روابط أحادية C–C وC–H فقط)؛ لذلك ملمسه شمعي، ولا يذوب في الماء.', '["ملمس البولي إيثيلين شمعي لا زلق، وهو لا يذوب في الماء لأنه سلسلة ألكان غير قطبية.","","الملمس الشمعي صحيح، لكن البولي إيثيلين لا يذوب في الماء لأنه سلسلة ألكان غير قطبية.","عدم الذوبان في الماء صحيح، لكن ملمس البولي إيثيلين شمعي لا خشن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-15T02:47:48.799Z"}'::jsonb),
('mcq', 2, 2, 'البولي إيثيلين رديء التوصيل للكهرباء وغير نشط كيميائيًّا، وهذه الخواص تجعله مثاليًّا لتغليف أسلاك الكهرباء.', '["البولي إيثيلين لا يذوب في الماء.","المادة المستعملة في تغليف الأسلاك يجب أن تكون عازلة، والبولي إيثيلين رديء التوصيل.","","جميع الروابط بين ذرات الكربون في البولي إيثيلين أحادية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.799Z"}'::jsonb),
('mcq', 3, 0, 'من أسباب انتشار البوليمرات سهولة تشكيلها بأشكال مختلفة أو سحبها على شكل ألياف رقيقة، في حين يجب تسخين الفلزات والمواد الطبيعية الأخرى إلى درجات حرارة مرتفعة لتشكيلها، فتصبح ضعيفة.', '["","الفلزات هي التي تحتاج إلى تسخين إلى درجات حرارة مرتفعة لتشكيلها.","البوليمرات يسهل سحبها أليافًا رقيقة، ومنها ألياف أنعم من الحرير.","هذا ما يحدث للفلزات والمواد الطبيعية عند تسخينها لتشكيلها، لا للبوليمرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-15T02:47:48.799Z"}'::jsonb),
('mcq', 4, 3, 'الخشب البلاستيكي غير قابل للتآكل ولا يحتاج إلى إعادة طلاء، وهذا من أمثلة كون كثير من البوليمرات أكثر تحملًا من المواد الطبيعية.', '["البولي إيثيلين لا يذوب في الماء.","الخشب البلاستيكي لا يحتاج إلى إعادة طلاء.","البولي إيثيلين رديء التوصيل للكهرباء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.800Z"}'::jsonb),
('mcq', 5, 1, 'تعود خواص البوليمر إلى تركيبه الجزيئي؛ فالبوليمر (II) يحتوي على مجموعات هيدروكسيل –OH قطبية تكوّن روابط هيدروجينية مع الماء، فتكون ذوبانيته أكبر، أما (I) فسلسلة ألكان غير قطبية لا تذوب في الماء.', '["السلسلة الهيدروكربونية غير القطبية لا تذوب في الماء، فهذا سبب لقلة ذوبانية (I) لا لزيادتها.","","الكتلة المولية تعتمد على n ولا تحدد الذوبانية هنا؛ والسبب هو مجموعة OH.","صغر الوحدة البنائية لا يجعل السلسلة غير القطبية تذوب في الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-15T02:47:48.800Z"}'::jsonb),
('mcq', 6, 0, 'البوليمر (بولي بروبلين) سلسلة هيدروكربونية مشبعة تشبه الألكانات كالبولي إيثيلين؛ لذا يُتوقع ألا يذوب في الماء، وأن يكون رديء التوصيل للكهرباء وقليل النشاط الكيميائي.', '["","مجموعة CH₃ غير قطبية، فلا تزيد الذوبانية في الماء.","جميع الروابط بين ذرات الكربون في الوحدة البنائية أحادية، والبوليمر رديء التوصيل.","السلسلة مشبعة كالألكانات، فهي قليلة النشاط الكيميائي ولا تتفاعل مع الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.800Z"}'::jsonb),
('mcq', 7, 2, 'تجمع التسمية بين الحرارة (therme) والقالب أو النموذج (plastikos)، فهي تشير إلى إمكانية تشكيل هذه البوليمرات في قوالب ونماذج بالحرارة، وهذا من أسباب سهولة تشكيل البوليمرات بأشكال مختلفة.', '["التسمية تشير إلى التشكيل بالحرارة، لا إلى مقاومة أي تغير عند التسخين.","التسمية تجمع الحرارة والقالب، فتشير إلى التشكيل بالحرارة لا إلى توصيل الحرارة أو الكهرباء؛ والبولي إيثيلين مثلًا رديء التوصيل للكهرباء.","","التسمية لا علاقة لها بالذوبان، وكثير من البوليمرات لا يذوب في الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-15T02:47:48.800Z"}'::jsonb),
('essay', 1, null::int, null, null, 'من هذه الخواص: (1) سهولة تحضيرها، والمواد الأولية المستعملة في تحضيرها غير مكلفة. (2) تنوع خواصها؛ فبعضها يمكن سحبه أليافًا أنعم من الحرير، وبعضها قوي كالفولاذ. (3) غير قابلة للصدأ، وكثير منها أكثر تحملًا من المواد الطبيعية، مثل الخشب البلاستيكي الذي لا يتآكل ولا يحتاج إلى إعادة طلاء. (4) سهولة تشكيلها بأشكال مختلفة أو سحبها على شكل ألياف رقيقة دون الحاجة إلى درجات حرارة مرتفعة كالفلزات.', '["سهولة التحضير ورخص المواد الأولية","تنوع الخواص (أنعم من الحرير أو قوية كالفولاذ)","عدم الصدأ وتحمّل أكثر من المواد الطبيعية","سهولة التشكيل والسحب أليافًا"]'::jsonb, '[]'::jsonb, '[{"element":"خاصية أولى صحيحة","marks":1},{"element":"خاصية ثانية صحيحة","marks":1},{"element":"خاصية ثالثة صحيحة","marks":1},{"element":"خاصية رابعة صحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2–3 درجات","description":"ذكر خاصيتين أو ثلاث صحيحة"},{"level":"1 درجة","description":"ذكر خاصية واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر أن البوليمرات موصلة جيدة للكهرباء","ذكر أن البوليمرات تذوب في الماء","ذكر استعمالات بدل الخواص"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-15T02:47:48.800Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المزايا (أي اثنتين): سهولة تحضيرها ورخص موادها الأولية؛ سهولة تشكيلها وسحبها أليافًا؛ عدم صدئها وتحمّلها أكثر من كثير من المواد الطبيعية (لا تتآكل ولا تحتاج إلى إعادة طلاء)؛ تنوع خواصها بين نعومة الحرير وقوة الفولاذ. العيوب: المواد الأولية لمعظم البوليمرات تُشتق من الوقود الأحفوري المهدد بالنفاد؛ وإعادة تدويرها صعبة لكثرة أنواعها المختلفة في المنتجات، فلا بد من فرزها وفق مكوناتها، وقد يكون الفرز طويلًا ومكلفًا.', '["مزية أولى","مزية ثانية","عيب: الاعتماد على الوقود الأحفوري المهدد بالنفاد","عيب: صعوبة إعادة التدوير والفرز"]'::jsonb, '[]'::jsonb, '[{"element":"مزية أولى صحيحة","marks":1},{"element":"مزية ثانية صحيحة","marks":1},{"element":"العيب الأول","marks":1},{"element":"العيب الثاني","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2–3 درجات","description":"ذكر المزايا مع عيب واحد، أو العيبين مع مزية واحدة"},{"level":"1 درجة","description":"ذكر مزية أو عيب واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر أن البوليمرات تصدأ","إغفال العيوب والاكتفاء بالمزايا","القول إن إعادة تدوير البوليمرات سهلة دائمًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-15T02:47:48.800Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) البولي إيثيلين سلسلة طويلة من الألكان، جميع الروابط فيها أحادية (C–C وC–H) وهي غير قطبية. (ب) ملمسه شمعي كالألكانات الطويلة؛ لا يذوب في الماء لأن سلسلته غير قطبية ولا تكوّن روابط هيدروجينية مع الماء؛ غير نشط كيميائيًّا لأنه مشبع بروابط أحادية كالألكانات؛ رديء التوصيل للكهرباء لأنه، كالألكانات، مركب تساهمي جزيئي لا يحتوي على أيونات. (ج) أوعية حفظ الطعام، وتغليف أسلاك الكهرباء.', '["سلسلة ألكان طويلة بروابط أحادية غير قطبية","ملمس شمعي","لا يذوب في الماء: غير قطبي","غير نشط: مشبع كالألكانات","رديء التوصيل: مركب تساهمي كالألكانات لا أيونات فيه","أوعية حفظ الطعام وتغليف أسلاك الكهرباء"]'::jsonb, '[]'::jsonb, '[{"element":"وصف التركيب (أ)","marks":1},{"element":"أربع خواص مع تفسيرها (ب)","marks":4},{"element":"استعمالان مرتبطان بالخواص (ج)","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3–5 درجات","description":"ذكر الخواص صحيحة مع تفسير ناقص لبعضها"},{"level":"1–2 درجة","description":"ذكر خاصية أو خاصيتين دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن البولي إيثيلين يحتوي على روابط ثنائية","تفسير عدم الذوبان بكبر الكتلة المولية فقط","ذكر أنه موصل جيد للكهرباء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-15T02:47:48.800Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C5-L5-O05') and x.type = v.type and x.number = v.number
