('mcq', 4, 1, 'الرمز 2 (HDPE) يدل على بولي إيثيلين عالي الكثافة، والرمز 4 (LDPE) يدل على بولي إيثيلين منخفض الكثافة؛ فكلاهما بولي إيثيلين ويختلفان في الكثافة.', '["الرمز (ب) هو LDPE، أي بولي إيثيلين منخفض الكثافة وليس بولي بروبلين (PP رقم 5).","","عكس الصحيح: HDPE (رقم 2) عالي الكثافة، وLDPE (رقم 4) منخفض الكثافة.","البولي ستايرين رمزه 6 (PS)، وبولي إيثيلين رباعي فثالات رمزه 1 (PETE)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-15T02:47:48.802Z"}'::jsonb),
('mcq', 5, 3, 'الرمز رقم 7 يدل على «مواد بلاستيكية أخرى» غير البوليمرات الستة المرقمة من 1 إلى 6.', '["البولي ستايرين رمزه الرقم 6.","الرقم يدل على نوع المادة البلاستيكية لا على عدد مرات التدوير.","البولي إيثيلين منخفض الكثافة رمزه الرقم 4.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-15T02:47:48.802Z"}'::jsonb),
('mcq', 6, 0, 'قد تكون عملية فرز المواد البلاستيكية طويلة ومكلفة؛ لذلك قُدّمت رموز موحدة تشير إلى مكونات المنتجات، فتوفر وسيلة سريعة لإعادة تدوير المواد البلاستيكية وفرزها.', '["","الرموز علامات مطبوعة لا تغيّر خواص المنتج.","الرموز تسهّل التدوير ولا تمنعه.","لا بد من فرز البلاستيك وفق مكونات البوليمر قبل إعادة استعماله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-15T02:47:48.803Z"}'::jsonb),
('mcq', 7, 2, 'الوحدة البنائية [–CH₂–CHCl–]ₙ تحمل ذرة Cl على كل وحدة، فهي وحدة بولي كلوريد الفينيل (PVC) المستعمل في الأنابيب البلاستيكية، ورمزه المعطى في السؤال هو الرقم 3 والحرف V.', '["PETE بولي إيثيلين رباعي فثالات، ووحدته تحتوي على حلقة بنزين ومجموعات إستر لا على Cl.","PP بولي بروبلين، ووحدته تحمل مجموعة CH₃ لا ذرة Cl.","","PS بولي ستايرين، ووحدته تحمل حلقة بنزين لا ذرة Cl."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.803Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تحتوي المنتجات على عدد كبير من البوليمرات المختلفة، فلا بد من فرز المواد البلاستيكية وفقًا لمكونات البوليمر قبل إعادة استعمالها. وقد تكون عملية الفرز طويلة ومكلفة؛ لذلك طُبعت على المنتجات رموز موحدة (أرقام من 1 إلى 7 مع اختصار البوليمر) تحدد مكونات كل منتج، فيعرف العامل نوع البوليمر بالنظر إلى الرمز، وهذا يوفر وسيلة سريعة لفرز المواد البلاستيكية وإعادة تدويرها.', '["تنوع البوليمرات في المنتجات","ضرورة الفرز وفق مكونات البوليمر","الفرز طويل ومكلف","الرموز تحدد مكونات المنتج","الرموز وسيلة سريعة للفرز والتدوير"]'::jsonb, '[]'::jsonb, '[{"element":"سبب ضرورة الفرز","marks":2},{"element":"صعوبة الفرز دون رموز","marks":1},{"element":"دلالة الرموز ودورها في تسريع الفرز","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تفسير كامل يربط تنوع البوليمرات بالفرز ودور الرموز"},{"level":"3–4 درجات","description":"تفسير دور الرموز مع نقص في سبب الفرز"},{"level":"1–2 درجة","description":"ذكر أن الرموز تسهل التدوير دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الرمز يدل على عدد مرات التدوير","إغفال سبب الحاجة إلى الفرز","القول إن الرموز تغيّر خواص البلاستيك"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-15T02:47:48.803Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) الرمز (أ): بولي إيثيلين عالي الكثافة (HDPE)؛ الرمز (ب): الفينيل (V)؛ الرمز (ج): بولي ستايرين (PS). (2) يُستعمل البولي ستايرين في رغوة التغليف والعزل، أو أوعية النباتات، أو حاويات حفظ الطعام. (3) الرمز (أ) رقم 2 يدل على بولي إيثيلين عالي الكثافة، أما الرمز رقم 4 (LDPE) فيدل على بولي إيثيلين منخفض الكثافة؛ فكلاهما بولي إيثيلين ويختلفان في الكثافة.', '["(أ) بولي إيثيلين عالي الكثافة","(ب) فينيل","(ج) بولي ستايرين","استعمال صحيح للبولي ستايرين","الفرق: عالي الكثافة مقابل منخفض الكثافة"]'::jsonb, '[]'::jsonb, '[{"element":"أسماء الرموز الثلاثة","marks":3},{"element":"استعمال البولي ستايرين","marks":1},{"element":"المقارنة بين الرمزين 2 و4","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تسمية صحيحة للرموز الثلاثة مع الاستعمال والمقارنة"},{"level":"3–4 درجات","description":"تسمية رمزين أو ثلاثة مع نقص في الاستعمال أو المقارنة"},{"level":"1–2 درجة","description":"تسمية رمز واحد صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين HDPE وLDPE","تسمية PS بولي بروبلين","اعتبار الحرف V اختصارًا لبوليمر غير الفينيل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-15T02:47:48.803Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) زجاجة العصير في حاوية الرمز 1: بولي إيثيلين رباعي فثالات (PETE)؛ علبة الرغوة في حاوية الرمز 6: بولي ستايرين (PS)؛ لعبة الأطفال في حاوية الرمز 4: بولي إيثيلين منخفض الكثافة (LDPE)؛ الحبل في حاوية الرمز 5: بولي بروبلين (PP)؛ الغلاف في حاوية الرمز 7. (ب) لأنهما مصنوعتان من بوليمرين مختلفين (PETE وPS)، ويجب فرز المواد البلاستيكية وفقًا لمكونات البوليمر قبل إعادة استعمالها. (ج) يعني أن الغلاف مصنوع من مواد بلاستيكية أخرى غير البوليمرات المرقمة من 1 إلى 6.', '["توزيع المنتجات الخمسة حسب الرمز","تسمية البوليمرات: PETE، PS، LDPE، PP","اختلاف البوليمرين يمنع الخلط","الفرز وفق مكونات البوليمر","الرمز 7: مواد بلاستيكية أخرى"]'::jsonb, '[]'::jsonb, '[{"element":"التوزيع والتسمية (أ)","marks":4},{"element":"التفسير (ب)","marks":1},{"element":"دلالة الرمز 7 (ج)","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"توزيع وتسمية صحيحان مع تفسير ودلالة صحيحين"},{"level":"3–5 درجات","description":"توزيع صحيح مع خطأ في تسمية بوليمر أو نقص في التفسير"},{"level":"1–2 درجة","description":"توزيع صحيح لمنتجين أو ثلاثة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية LDPE بولي إيثيلين عالي الكثافة","اعتبار الرقم 7 عدد مرات التدوير","القول إن جميع البلاستيك يمكن تدويره معًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-15T02:47:48.803Z"}'::jsonb)
