insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'المونومر CH₂=CH–C≡N (الأكريلونيتريل) يحتوي على رابطة ثنائية C=C فيتبلمر بالإضافة: تنكسر الرابطة الثنائية وترتبط المونومرات معًا مع بقاء جميع ذراتها، وتبقى مجموعة C≡N مجموعة جانبية، فتكون الوحدة البنائية [–CH₂–CH(C≡N)–]ₙ، وهو بولي أكريلونيتريل.', '["","في البلمرة بالإضافة تنكسر الرابطة الثنائية C=C، فلا تبقى في الوحدة البنائية.","في البلمرة بالإضافة تبقى جميع ذرات المونومر في البوليمر، فلا تُفقد ذرات الهيدروجين.","لا يتكون ماء في البلمرة بالإضافة، ولا يحتوي المونومر أصلًا على ذرات O."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-15T02:47:48.804Z"}'::jsonb),
('mcq', 2, 3, 'المونومر (الستايرين) يحتوي على رابطة ثنائية C=C؛ فعند البلمرة بالإضافة تنكسر الرابطة الثنائية وتبقى حلقة البنزين مجموعة جانبية، فتكون الوحدة البنائية للبولي ستايرين [–CH₂–CH(C₆H₅)–]ₙ.', '["الرابطة الثنائية تنكسر في البلمرة بالإضافة ولا تبقى، كما أن هذه الصيغة فقدت ذرتي هيدروجين.","حلقة البنزين تبقى مجموعة جانبية متصلة بذرة الكربون، ولا تدخل في السلسلة الرئيسة.","البلمرة بالإضافة لا ينتج عنها ماء أو أي جزيء صغير.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-15T02:47:48.804Z"}'::jsonb),
('mcq', 3, 1, 'للحصول على المونومر من وحدة بوليمر إضافة نعيد الرابطة الثنائية بين ذرتي الكربون في السلسلة الرئيسة ونُبقي جميع المجموعات الجانبية: CH₂=C(CH₃)COOCH₃.', '["هذه صيغة مشبعة بلا رابطة ثنائية، فلا يمكن أن تتبلمر بالإضافة.","","فقدت هذه الصيغة مجموعة CH₃ المرتبطة بذرة الكربون الثانية في الوحدة البنائية.","فقدت هذه الصيغة مجموعة الإستر COOCH₃ الموجودة في الوحدة البنائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-15T02:47:48.804Z"}'::jsonb),
('mcq', 4, 2, 'روابط الإستر –CO–O– في الوحدة تنتج من تكثف مجموعة COOH مع مجموعة OH وخروج الماء؛ فالجزء –CO–C₆H₄–CO– مصدره حمض ثنائي الكربوكسيل HOOC–C₆H₄–COOH، والجزء –O–CH₂–CH₂–O– مصدره HO–CH₂–CH₂–OH.', '["الإيثين مادة أولية تُحضَّر منها مونومرات PETE، لكنه لا يحتوي على مجموعات وظيفية يتكثف بها مع الحمض ويخرج الماء، فليس هو المونومر الذي يرتبط في السلسلة.","حمض البنزويك يحتوي على مجموعة كربوكسيل واحدة، ومونومر التكثف يحتاج إلى مجموعتين وظيفيتين على الأقل.","","هذان المونومران يعطيان بوليمرًا ترتبط فيه الحلقة بذرات O لا بمجموعات C=O، وهذا عكس الوحدة المرسومة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-15T02:47:48.804Z"}'::jsonb),
('mcq', 5, 3, 'الوحدة المتكررة في السلسلة هي –CH₂–CHBr–، وبإعادة الرابطة الثنائية بين ذرتي الكربون نحصل على المونومر CH₂=CHBr.', '["هذا مركب مشبع لا يحتوي على رابطة ثنائية، فلا يتبلمر بالإضافة.","في السلسلة ذرة Br واحدة لكل ذرتي كربون، وهذه الصيغة فيها ذرتا Br.","ذرتا Br هنا على ذرة كربون واحدة، أما في السلسلة فعلى كل CH ذرة Br واحدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-15T02:47:48.804Z"}'::jsonb),
('mcq', 6, 1, 'عند التكثف تفقد مجموعة COOH مجموعة OH وتفقد مجموعة OH في المونومر الآخر ذرة H فيتكوّن H₂O، وترتبط ذرة O بذرة C=O برابطة إستر؛ فتكون الوحدة المتكررة [–O–CH₂–CH₂–CO–]ₙ.', '["أبقت هذه الصيغة جميع ذرات المونومر، وهذا لا يحدث في التكثف الذي يخرج فيه الماء.","","فقدت هذه الصيغة المجموعتين الوظيفيتين كلتيهما، وهما موضع الارتباط بين المونومرات.","هذه الوحدة تحتوي على ذرة O زائدة؛ فعند تكرارها ترتبط ذرتا O معًا، والصحيح أن تخرج OH من الكربوكسيل مع H من الهيدروكسيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-15T02:47:48.804Z"}'::jsonb),
('mcq', 7, 0, 'تتحد مجموعة الأمين NH₂ في مونومر مع مجموعة الكربوكسيل COOH في مونومر آخر، فيخرج H₂O وتتكوّن رابطة أميد –CO–NH–، فتكون الوحدة المتكررة [–NH–(CH₂)₅–CO–]ₙ.', '["","أبقت هذه الصيغة جميع ذرات المونومر، مع أن التكثف يرافقه خروج جزيء ماء.","أبقت هذه الصيغة ذرة O من مجموعة OH التي تخرج مع الماء، فلا تتكوّن رابطة أميد.","استبدلت هذه الصيغة مجموعة الكربوكسيل بمجموعة أمين، فلم يعد هناك ما يكوّن رابطة الأميد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-15T02:47:48.804Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) من (a) CH₂=CHF ينتج [–CH₂–CHF–]ₙ، ومن (b) CH₂=C(CH₃)₂ ينتج [–CH₂–C(CH₃)₂–]ₙ، حيث تبقى ذرة F في الأول ومجموعتا CH₃ في الثاني مرتبطة بذرة الكربون نفسها. (ب) ···–CH₂–CHF–CH₂–CHF–CH₂–CHF–···. (ج) تنكسر الرابطة الثنائية C=C في كل مونومر وتتحول إلى رابطة أحادية، وتُستعمل الإلكترونات لربط المونومر بالمونومرين المجاورين، وتبقى جميع ذرات المونومر في البوليمر.', '["[–CH₂–CHF–]ₙ","[–CH₂–C(CH₃)₂–]ₙ","سلسلة من ثلاث وحدات متتالية صحيحة","انكسار الرابطة الثنائية وتحولها إلى أحادية","بقاء جميع الذرات"]'::jsonb, '["حدّد الرابطة الثنائية C=C في المونومر.","حوّلها إلى رابطة أحادية وأضف رابطتين طرفيتين على ذرتي الكربون.","ضع الوحدة بين قوسين واكتب n أسفل القوس الأيمن.","كرّر الوحدة ثلاث مرات لرسم جزء من السلسلة."]'::jsonb, '[{"element":"الوحدة البنائية من (a)","marks":2},{"element":"الوحدة البنائية من (b)","marks":2},{"element":"جزء السلسلة (ب)","marks":1},{"element":"وصف ما يحدث للرابطة الثنائية (ج)","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"رسم صحيح للوحدتين والسلسلة مع وصف صحيح"},{"level":"3–5 درجات","description":"رسم وحدة صحيحة والأخرى بخطأ بسيط أو نقص في (ب) أو (ج)"},{"level":"1–2 درجة","description":"رسم وحدة واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إبقاء الرابطة الثنائية داخل القوسين","نقل ذرة F أو مجموعتي CH₃ إلى ذرة كربون أخرى","نسيان الروابط الطرفية أو الحرف n","إضافة ماء ناتج عن البلمرة بالإضافة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-15T02:47:48.804Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) (I): CH₂=CF₂. (II): H₂N–(CH₂)₆–NH₂ وHOOC–(CH₂)₈–COOH. (ب) (I) بلمرة بالإضافة؛ لأن السلسلة الرئيسة من ذرات كربون فقط والوحدة تحتوي على جميع ذرات المونومر غير المشبع بعد انكسار الرابطة الثنائية. (II) بلمرة بالتكثف؛ لأن السلسلة تحتوي على روابط أميد تكوّنت بين مونومرين لكل منهما مجموعتان وظيفيتان (أمين وكربوكسيل) مع فقد جزيء صغير. (ج) يخرج جزيء ماء H₂O مقابل كل رابطة أميد –CO–NH– تتكوّن.', '["مونومر (I): CH₂=CF₂","مونومرا (II): ثنائي أمين وحمض ثنائي الكربوكسيل","(I) إضافة مع التعليل","(II) تكثف مع التعليل","خروج الماء وتكوّن رابطة الأميد"]'::jsonb, '["(I): أعد الرابطة الثنائية بين ذرتي الكربون في الوحدة.","(II): افصل الوحدة عند رابطتي الأميد C–N.","أضف H إلى كل ذرة N لتصبح NH₂، وأضف OH إلى كل C=O لتصبح COOH."]'::jsonb, '[{"element":"مونومر (I)","marks":1},{"element":"مونومرا (II)","marks":2},{"element":"تصنيف (I) وتعليله","marks":1},{"element":"تصنيف (II) وتعليله","marks":1},{"element":"الجزيء الخارج والرابطة (ج)","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"استنتاج صحيح للمونومرات وتصنيف معلل وإجابة (ج) كاملة"},{"level":"3–5 درجات","description":"استنتاج صحيح لمونومرات أحد البوليمرين مع تصنيف صحيح للاثنين"},{"level":"1–2 درجة","description":"تصنيف صحيح فقط دون مونومرات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة مونومر (I) بلا رابطة ثنائية","كتابة مونومري (II) بصورة NH و CO دون إعادة H وOH","تصنيف (II) إضافة لعدم ملاحظة رابطة الأميد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-15T02:47:48.805Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) n HO–CH₂–CH₂–OH + n HOOC–(CH₂)₄–COOH → [–O–CH₂–CH₂–O–CO–(CH₂)₄–CO–]ₙ + 2n H₂O. (ب) رابطة إستر –CO–O– بين مجموعة الكربوكسيل ومجموعة الهيدروكسيل. (ج) يتكوّن جزيء ماء واحد مقابل كل رابطة إستر (تخرج OH من الكربوكسيل وH من الهيدروكسيل)، ولكل وحدة متكررة رابطتا إستر فيخرج 2n جزيء ماء لكل n وحدة. ويُصنَّف تكثفًا لأن كل مونومر يحتوي على مجموعتين وظيفيتين، ويرافق ارتباطهما فقد جزيء صغير هو الماء.', '["المعادلة مع الوحدة [–O–CH₂–CH₂–O–CO–(CH₂)₄–CO–]ₙ","خروج الماء في المعادلة","رابطة إستر","جزيء ماء لكل رابطة","تعليل التصنيف: مجموعتان وظيفيتان وفقد جزيء صغير"]'::jsonb, '["اكتب المونومرين بمعامل n.","أزل OH من كل COOH وH من كل OH لتكوين H₂O.","اربط ذرة O من الكحول بذرة C=O من الحمض لتكوين رابطة إستر.","ضع الوحدة المتكررة بين قوسين مع n واكتب الماء الناتج."]'::jsonb, '[{"element":"الوحدة البنائية الصحيحة","marks":2},{"element":"المعادلة كاملة مع الماء","marks":1},{"element":"اسم الرابطة","marks":1},{"element":"عدد جزيئات الماء والتعليل","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"معادلة صحيحة كاملة مع تسمية الرابطة وتعليل التصنيف"},{"level":"3–5 درجات","description":"وحدة صحيحة مع نقص في الماء أو التعليل"},{"level":"1–2 درجة","description":"تسمية الرابطة أو تصنيف التفاعل فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إبقاء مجموعات OH وCOOH كاملة داخل القوسين","إغفال الماء الناتج","تسمية الرابطة أميدًا","ربط ذرتي O معًا","كتابة n H₂O بدل 2n H₂O مع أن في كل وحدة متكررة رابطتي إستر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-15T02:47:48.805Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
