('essay', 1, null::int, null, null, '(أ) 1909م: صُنع أول بلاستيك من البوليمرات الصناعية وهو الباكالايت. (ب) 1939–1945م: استُعمل النايلون خلال الحرب العالمية الثانية في صناعة المظلات والخيام، ودخل في صناعة الملابس. (ج) 1959م: تم إنتاج الألياف اللدنة والألياف المرنة صناعيًّا. (د) 2006م: طوّر الباحثون ورقًا رقيقًا جدًّا يقاوم الإشعاع وهو بوليمر الكريستال السائل المستعمل في الدوائر الكهربائية، مما جعله مفيدًا في تطبيقات الفضاء.', '["(أ) الباكالايت أول بلاستيك صناعي","(ب) النايلون في المظلات والخيام والملابس","(ج) الألياف اللدنة والمرنة","(د) بوليمر الكريستال السائل المقاوم للإشعاع"]'::jsonb, '[]'::jsonb, '[{"element":"الحدث (أ)","marks":1},{"element":"الحدث (ب)","marks":1},{"element":"الحدث (ج)","marks":1},{"element":"الحدث (د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأحداث الأربعة صحيحة"},{"level":"2–3 درجات","description":"حدثان أو ثلاثة صحيحة"},{"level":"1 درجة","description":"حدث واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة تحضير النايلون إلى فترة الحرب بدلًا من 1931م","الخلط بين 1946م (PTFE) و1959م (الألياف)","نسبة الأوراق النقدية البوليمرية إلى 2006م"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-15T02:47:48.809Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) حُضّر النايلون أول مرة عام 1931م. (ب) أصبح مادة شعبية لأنه يمتاز بالقوة، ويمكن سحبه على شكل خيوط رفيعة تشبه الحرير. (ج) يُحضَّر نايلون 6,6 بالبلمرة بالتكثف بين حمض الأديبيك و1، 6-ثنائي أمينو هكسان، فتتكوّن روابط أميد ويخرج جزيء ماء مقابل كل رابطة أميد، ولأن في كل وحدة متكررة رابطتي أميد يخرج 2n H₂O. (د) استُعمل في أثناء الحرب العالمية الثانية (1939–1945م) في صناعة المظلات والخيام، كما دخل في صناعة الملابس.', '["1931م","القوة وإمكانية سحبه خيوطًا تشبه الحرير","البلمرة بالتكثف وخروج الماء","المظلات والخيام والملابس"]'::jsonb, '[]'::jsonb, '[{"element":"سنة التحضير","marks":1},{"element":"سبب الشعبية","marks":1},{"element":"نوع البلمرة والجزيء الناتج","marks":2},{"element":"الاستعمال في الحرب","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"فقرة تستوفي العناصر الأربعة بدقة"},{"level":"3–4 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن النايلون أول بوليمر صناعي","تصنيف بلمرة النايلون إضافة","نسبة استعمال النايلون في الحرب إلى عام 1931م"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-15T02:47:48.809Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) تحضير الباكالايت 1909م، ثم تحضير النايلون 1931م، ثم انتشار منتجات الطلاء غير اللاصق (PTFE) تجاريًّا 1946م، ثم إصدار الأوراق النقدية البوليمرية في أستراليا 1988م. (ب) ازدهرت صناعة البوليمرات بعد الحرب العالمية الثانية، على الرغم من أن أول بوليمر صُنع عام 1909م. (ج) لأن البوليمرات الصناعية أصبحت تُستعمل استعمالًا واسعًا؛ فمنذ عام 1909م طُوّرت مئات البوليمرات الصناعية الأخرى.', '["الترتيب الصحيح للأحداث الأربعة","السنوات: 1909، 1931، 1946، 1988","الازدهار بعد الحرب العالمية الثانية","الاستعمال الواسع وتطوير مئات البوليمرات"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب الصحيح","marks":2},{"element":"السنوات الأربع","marks":2},{"element":"وقت الازدهار","marks":1},{"element":"سبب التسمية","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"ترتيب وسنوات صحيحة مع إجابة (ب) و(ج)"},{"level":"3–5 درجات","description":"ترتيب صحيح مع خطأ في سنة أو نقص في (ب) أو (ج)"},{"level":"1–2 درجة","description":"ترتيب صحيح جزئيًّا دون سنوات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تقديم النايلون على الباكالايت","القول إن صناعة البوليمرات ازدهرت عام 1909م مباشرة","الخلط بين عامي 1946م و1988م"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-15T02:47:48.809Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
