insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C6-L1-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'البروتينات بوليمرات عضوية تتكوّن من وحدات بنائية مرتبطة معًا بترتيب معين. ما هذه الوحدات البنائية؟', null, null, '["السكريات الأحادية","الأحماض الأمينية","الأحماض الدهنية","النيوكليوتيدات"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 210 — تركيب البروتين (الأحماض الأمينية)'),
('mcq', 2, 'يمثّل الشكل الآتي جزءًا من سلسلة بروتين، وتمثّل كل دائرة فيه وحدة بنائية واحدة من وحدات السلسلة. ماذا تمثّل كل دائرة؟', null, '[{"src":"qimg/chem22/c6-l1a-chain.svg","alt":"سلسلة متموجة أفقية من اثنتي عشرة دائرة ملونة بألوان مختلفة (أزرق وأحمر وأخضر وبني وبنفسجي)، تتصل كل دائرة بالدائرة التي تليها بخط قصير، وفي طرفي السلسلة ثلاث نقاط تدل على أن السلسلة تستمر. لا توجد أي كتابة على الدوائر."}]'::jsonb, '["جزيء جلوكوز","حمضًا دهنيًا","حمضًا أمينيًا","نيوكليوتيدًا"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 210 — تركيب البروتين (الأحماض الأمينية)'),
('mcq', 3, 'أيّ المركبات الآتية يمكن أن يكون وحدة بنائية في سلسلة بروتين؟', null, null, '["الجلايسين","الجلوكوز","حمض البالمتيك","الجليسرول"]'::jsonb, 'فهم', 'تصنيف', 'متوسط', 'الكتاب ص 211 — الجدول 6-1 أمثلة على الأحماض الأمينية'),
('mcq', 4, 'المركب الآتي وحدة بنائية لأيّ نوع من المركبات العضوية الحيوية؟', null, '[{"src":"qimg/chem22/c6-l1a-cysteine.svg","alt":"صيغة بنائية لمركب: ذرة كربون مركزية C ترتبط من اليسار بالمجموعة H₂N، ومن الأسفل بذرة H، ومن الأعلى بالمجموعة CH₂ التي ترتبط بدورها من الأعلى بالمجموعة SH، ومن اليمين بذرة كربون C ترتبط من الأسفل بذرة O برابطة ثنائية ومن اليمين بالمجموعة OH. أي: H₂N−CH(CH₂SH)−COOH."}]'::jsonb, '["الكربوهيدرات","الليبيدات","الأحماض النووية","البروتينات"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 210 — تركيب البروتين (الأحماض الأمينية)'),
('mcq', 5, 'كم عدد الأنواع المختلفة من الوحدات البنائية التي تستطيع تكوين البروتينات؟', null, null, '["20","50","400","1000"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 212 — الببتيد وعديد الببتيد'),
('mcq', 6, 'أيّ العبارات الآتية تصف تركيب البروتين من وحداته البنائية وصفًا صحيحًا؟', null, null, '["سلسلة من وحدات بنائية مرتبة عشوائيًا، لا تنطوي ولا تلتف","سلسلة من وحدات بنائية متماثلة جميعها من نوع واحد فقط","جزيء صغير يتكوّن من وحدتين بنائيتين فقط","سلسلة من وحدات بنائية مرتبطة بترتيب معين، تنطوي في تركيب ثلاثي الأبعاد محدد"]'::jsonb, 'فهم', 'اختيار وصف صحيح', 'صعب', 'الكتاب ص 210 — تركيب البروتين (الأحماض الأمينية)'),
('mcq', 7, 'يُقدَّر متوسط الكتلة المولية للوحدة البنائية الواحدة في سلاسل البروتينات بنحو 110 g/mol. ما الكتلة المولية التقريبية لبروتين المايوسين الذي تتكوّن سلسلته من 1750 وحدة بنائية؟', null, null, '["15.9 g/mol","192,500 g/mol","1860 g/mol","192,390 g/mol"]'::jsonb, 'تطبيق', 'استنتاج', 'متوسط', 'الكتاب ص 231 — تقويم الفصل س40 (المايوسين)'),
('essay', 1, 'اذكر الوحدة البنائية للبروتينات، ثم عرّف البروتينات مستعملًا اسم هذه الوحدة، وبيّن لماذا تُصنَّف البروتينات ضمن البوليمرات.', null, null, null, 'فهم', 'تعريف وتفسير', 'سهل', 'الكتاب ص 210 — تركيب البروتين (الأحماض الأمينية)'),
('essay', 2, 'سمِّ الوحدات البنائية الأساسية التي تكوّن كلًّا من البروتينات والكربوهيدرات المركبة (عديدة التسكر)، ثم سمِّ الرابطة التي تربط الوحدات البنائية بعضها ببعض في البروتين، والجزيء الصغير الذي ينطلق عند تكوّن كل رابطة منها.', null, null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 234 — تقويم الفصل س81، وص 211'),
('essay', 3, 'إذا كان متوسط الكتلة المولية للحمض الأميني في البروتينات 110 g/mol:
(a) احسب الكتلة المولية التقريبية لهرمون الأنسولين الذي يتكوّن من 51 حمضًا أمينيًا.
(b) احسب العدد التقريبي للأحماض الأمينية في بروتين كتلته المولية 36,500 g/mol.
(c) ماذا تستنتج عن العلاقة بين عدد الوحدات البنائية في البروتين وكتلته المولية؟', null, null, null, 'تطبيق', 'حساب واستنتاج', 'صعب', 'الكتاب ص 231–232 — تقويم الفصل س40 وس42')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
