insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'البروتينات بوليمرات عضوية تتكوّن من أحماض أمينية مرتبطة معًا بترتيب معين؛ فالوحدة البنائية للبروتين هي الحمض الأميني.', '["السكريات الأحادية وحدات بناء الكربوهيدرات لا البروتينات.","","الأحماض الدهنية من مكونات الليبيدات لا البروتينات.","النيوكليوتيدات وحدات بناء الأحماض النووية لا البروتينات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.809Z"}'::jsonb),
('mcq', 2, 2, 'سلسلة البروتين بوليمر وحداته المتكررة أحماض أمينية مرتبطة معًا؛ لذا تمثل كل دائرة حمضًا أمينيًا.', '["الجلوكوز سكر أحادي يدخل في بناء الكربوهيدرات، لا في سلاسل البروتين.","الأحماض الدهنية تدخل في تكوين الليبيدات، ولا تتكرر في سلاسل البروتين.","","النيوكليوتيد وحدة بناء الأحماض النووية DNA وRNA، لا البروتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-15T02:47:48.810Z"}'::jsonb),
('mcq', 3, 0, 'الجلايسين حمض أميني (أبسط الأحماض الأمينية، سلسلته الجانبية ذرة هيدروجين)، والأحماض الأمينية هي الوحدات البنائية للبروتينات؛ لذا فالجلايسين هو الذي يمكن أن يكون وحدة في سلسلة بروتين.', '["","الجلوكوز سكر أحادي، وهو وحدة بناء الكربوهيدرات.","حمض البالمتيك حمض دهني يدخل في تكوين الليبيدات.","الجليسرول كحول يرتبط بالأحماض الدهنية في الليبيدات، وليس حمضًا أمينيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-15T02:47:48.810Z"}'::jsonb),
('mcq', 4, 3, 'في المركب ذرة كربون مركزية ترتبط بمجموعة أمين −NH₂ ومجموعة كربوكسيل −COOH وذرة هيدروجين وسلسلة جانبية؛ فهو حمض أميني، والأحماض الأمينية هي الوحدات البنائية للبروتينات.', '["وحدات الكربوهيدرات سكريات أحادية فيها مجموعات هيدروكسيل متعددة ومجموعة كربونيل، ولا تحتوي على مجموعة أمين.","الليبيدات تتكوّن أساسًا من أحماض دهنية طويلة السلاسل، وهذا المركب ليس حمضًا دهنيًا.","وحدات الأحماض النووية نيوكليوتيدات تتكوّن من مجموعة فوسفات وسكر وقاعدة نيتروجينية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-15T02:47:48.810Z"}'::jsonb),
('mcq', 5, 0, 'هناك 20 حمضًا أمينيًا فقط تستطيع تكوين البروتينات، ومع ذلك تتنوع البروتينات تنوعًا كبيرًا بسبب اختلاف عدد هذه الأحماض وترتيبها في السلسلة.', '["","50 حمضًا أمينيًا هو تقريبًا طول السلسلة التي يُطلق عليها عندها اسم بروتين، لا عدد أنواع الأحماض الأمينية.","400 هو عدد التتابعات المحتملة لثنائي الببتيد (20²)، لا عدد أنواع الأحماض الأمينية.","قد يحتوي البروتين على أكثر من 1000 حمض أميني، لكن هذا عدد الوحدات في السلسلة لا عدد أنواعها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.810Z"}'::jsonb),
('mcq', 6, 3, 'البروتينات بوليمرات من أحماض أمينية مرتبطة معًا بترتيب معين، وليست سلاسل مرتبة عشوائيًا، ويجب أن ينطوي البروتين في تركيب ثلاثي الأبعاد معين حتى يعمل بشكل صحيح.', '["البروتينات ليست مجرد سلاسل من أحماض أمينية مرتبة عشوائيًا؛ فترتيبها محدد، ويجب أن ينطوي البروتين في تركيب ثلاثي الأبعاد معين ليعمل.","تتكوّن البروتينات من عشرين نوعًا مختلفًا من الأحماض الأمينية، لا من نوع واحد يتكرر.","الجزيء المكوّن من حمضين أمينيين فقط هو ثنائي الببتيد؛ أما البروتين فسلسلة طويلة تصل إلى نحو 50 حمضًا أمينيًا أو أكثر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-15T02:47:48.810Z"}'::jsonb),
('mcq', 7, 1, 'البروتين بوليمر وحدته البنائية الحمض الأميني، فكتلته المولية التقريبية = عدد الأحماض الأمينية × متوسط كتلة الحمض الأميني = 1750 × 110 g/mol = 192,500 g/mol.', '["ناتج قسمة 1750 على 110 بدل ضربهما؛ والكتلة المولية للبوليمر تساوي عدد وحداته × كتلة الوحدة.","","ناتج جمع 1750 و110 بدل ضربهما.","ناتج ضرب 110 في 1749 (عدد الروابط بين الوحدات) بدل عدد الوحدات نفسها 1750."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-15T02:47:48.810Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الوحدة البنائية للبروتينات هي الحمض الأميني. البروتينات بوليمرات عضوية تتكوّن من أحماض أمينية مرتبطة معًا بروابط ببتيدية بترتيب معين. وتُصنَّف ضمن البوليمرات لأن البوليمر مركب كبير يتكوّن من وحدات متكررة عديدة تسمى المونومرات، والبروتين جزيء كبير يتكوّن من عدد كبير من الأحماض الأمينية المتكررة.', '["الوحدة البنائية: الحمض الأميني","تعريف البروتين: بوليمر من أحماض أمينية مرتبطة بترتيب معين","التصنيف بوليمرًا: جزيء كبير من وحدات متكررة (مونومرات) هي الأحماض الأمينية"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر الحمض الأميني وحدةً بنائية","marks":1},{"element":"تعريف البروتين تعريفًا صحيحًا","marks":1},{"element":"تفسير تصنيفه بوليمرًا","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يذكر الوحدة ويعرّف البروتين ويفسر تصنيفه بوليمرًا تفسيرًا صحيحًا"},{"level":"2 درجتان","description":"يذكر الوحدة ويعرّف البروتين دون تفسير التصنيف أو العكس"},{"level":"1 درجة","description":"يذكر الوحدة البنائية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر السكريات الأحادية أو النيوكليوتيدات وحدةً بنائية للبروتين","وصف البروتين بأنه سلسلة من أحماض أمينية مرتبة عشوائيًا","الخلط بين البوليمر والمونومر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-15T02:47:48.810Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تتكوّن البروتينات من الأحماض الأمينية، وتتكوّن الكربوهيدرات المركبة (عديدة التسكر) من السكريات الأحادية. وترتبط الأحماض الأمينية في البروتين بروابط ببتيدية، وينطلق جزيء ماء H₂O عند تكوّن كل رابطة ببتيدية (تفاعل تكثف).', '["وحدات البروتين: الأحماض الأمينية","وحدات الكربوهيدرات المركبة: السكريات الأحادية","الرابطة: الرابطة الببتيدية","ينطلق جزيء ماء مع كل رابطة"]'::jsonb, '[]'::jsonb, '[{"element":"الأحماض الأمينية للبروتينات","marks":1},{"element":"السكريات الأحادية للكربوهيدرات المركبة","marks":1},{"element":"الرابطة الببتيدية","marks":1},{"element":"جزيء الماء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يسمي الوحدتين والرابطة والجزيء الناتج تسمية صحيحة"},{"level":"2–3 درجات","description":"يسمي الوحدتين صحيحًا مع خطأ في الرابطة أو الجزيء الناتج"},{"level":"1 درجة","description":"يسمي وحدة واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل وحدات البروتينات بوحدات الكربوهيدرات","تسمية الرابطة في البروتين رابطة هيدروجينية","ذكر ثاني أكسيد الكربون بدل الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-15T02:47:48.811Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) الكتلة المولية للأنسولين ≈ 51 × 110 g/mol = 5610 g/mol.
(b) عدد الأحماض الأمينية ≈ 36,500 ÷ 110 ≈ 332 حمضًا أمينيًا.
(c) البروتين بوليمر وحدته البنائية الحمض الأميني، فكلما زاد عدد الأحماض الأمينية في السلسلة زادت الكتلة المولية للبروتين.', '["الضرب في عدد الأحماض: 51 × 110","النتيجة 5610 g/mol","القسمة على متوسط الكتلة: 36,500 ÷ 110 ≈ 332","الاستنتاج: الكتلة تزداد بزيادة عدد الأحماض الأمينية"]'::jsonb, '["الكتلة المولية للبروتين ≈ عدد الأحماض الأمينية × متوسط كتلة الحمض الأميني","الأنسولين: 51 × 110 g/mol = 5610 g/mol","عدد الأحماض الأمينية = الكتلة المولية للبروتين ÷ متوسط كتلة الحمض الأميني","36,500 g/mol ÷ 110 g/mol = 331.8 ≈ 332 حمضًا أمينيًا"]'::jsonb, '[{"element":"حساب كتلة الأنسولين 5610 g/mol","marks":1},{"element":"إعداد القسمة 36,500 ÷ 110","marks":1},{"element":"النتيجة ≈ 332 حمضًا أمينيًا","marks":1},{"element":"الاستنتاج الصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابان صحيحان بوحداتهما مع استنتاج صحيح"},{"level":"2–3 درجات","description":"حساب واحد صحيح أو خطأ حسابي بسيط مع استنتاج صحيح"},{"level":"1 درجة","description":"استنتاج صحيح دون حساب صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة 110 على 51 بدل الضرب","ضرب 36,500 في 110 بدل القسمة","إهمال الوحدة g/mol في الناتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-15T02:47:48.811Z"}'::jsonb)
