('mcq', 1, 2, 'الهيموجلوبين من بروتينات النقل؛ فهو بروتين كروي يحتوي على مجموعات هيم فيها حديد يرتبط بها الأكسجين، فينقله في الدم من الرئتين إلى سائر الجسم.', '["الكولاجين بروتين بنائي في الجلد والأوتار والأربطة والعظام، ولا ينقل الأكسجين.","الكيراتين بروتين بنائي ليفي يكوّن الشعر، ولا ينقل الأكسجين.","","الأنسولين هرمون بروتيني يحمل إشارات خلوية، ولا ينقل الأكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.811Z"}'::jsonb),
('mcq', 2, 0, 'الكولاجين بروتين بنائي يقتصر دوره على تكوين تراكيب حيوية؛ فهو جزء من الجلد والأوتار والأربطة والعظام.', '["","تسريع التفاعلات وظيفة الإنزيمات، لا البروتينات البنائية.","نقل الأكسجين وظيفة الهيموجلوبين، وهو بروتين نقل.","حمل الإشارات وظيفة الهرمونات مثل الأنسولين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-15T02:47:48.811Z"}'::jsonb),
('mcq', 3, 3, 'الأنسولين هرمون بروتيني، والهرمونات جزيئات تحمل الإشارات من جزء من الجسم إلى آخر؛ فدوره من وظيفة الإشارات الخلوية.', '["الدعم البنائي وظيفة بروتينات مثل الكولاجين والكيراتين التي تكوّن تراكيب حيوية.","نقل المواد وظيفة بروتينات مثل الهيموجلوبين الذي ينقل الأكسجين.","تسريع التفاعلات وظيفة الإنزيمات التي تعمل عوامل محفزة حيوية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-15T02:47:48.811Z"}'::jsonb),
('mcq', 4, 1, 'التسخين يسبب انفكاك طيات البروتين ولوالبه فيتشوه تركيبه الطبيعي ثلاثي الأبعاد، وتسمى هذه العملية تغيّر الخواص الطبيعية.', '["التكثف تفاعل يربط حمضين أمينيين وينطلق فيه ماء، أما التسخين هنا فيفك طيات سلسلة موجودة.","","تكوين الرابطة الببتيدية يربط الأحماض الأمينية في السلسلة، ولا يفك طياتها.","المطابقة التأثيرية تغيّر بسيط في شكل الموقع النشط للإنزيم ليحيط بالمادة الخاضعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-15T02:47:48.812Z"}'::jsonb),
('mcq', 5, 0, 'الحرارة المرتفعة وتغيّر pH تفك طيات البروتين ولوالبه فيتشوّه تركيبه الطبيعي ثلاثي الأبعاد (تغيّر الخواص الطبيعية)، ولأن البروتينات تعمل بصورة صحيحة فقط عندما تكون مطوية بشكلها الصحيح، يصبح البروتين غير فعّال عادة بعد هذا التغير.', '["","تكسير الروابط الببتيدية إلى أحماض أمينية حرة تحلل للبروتين (كالذي يسببه البابايين)، أما تغيّر الخواص الطبيعية فهو تشوه الشكل ثلاثي الأبعاد بانفكاك الطيات.","تغيّر الخواص الطبيعية لا يضيف أحماضًا أمينية إلى السلسلة.","البروتين لا يتحول إلى كربوهيدرات؛ فهو يبقى بروتينًا لكن بشكل مشوّه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-15T02:47:48.812Z"}'::jsonb),
('mcq', 6, 2, 'في الشكل الحلزوني والصحيفة المطوية تُثبَّت الأحماض الأمينية في مواقع معينة بواسطة الروابط الهيدروجينية بين أجزاء سلسلة عديد الببتيد.', '["الروابط الببتيدية تربط الأحماض الأمينية المتتالية على طول السلسلة، أما تثبيت الطيات فيتم بروابط هيدروجينية بين أجزاء السلسلة.","الروابط الأيونية ليست الروابط التي تثبت الشكل الحلزوني والصحيفة المطوية.","","الروابط الفلزية توجد في الفلزات، لا بين أجزاء السلاسل العضوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-15T02:47:48.812Z"}'::jsonb),
('mcq', 7, 3, 'الكيراتين بروتين ليفي يكوّن الشعر، والكولاجين جزء من الجلد والأوتار والأربطة والعظام؛ فكلاهما من البروتينات البنائية.', '["الهيموجلوبين بروتين نقل، والأنسولين هرمون للإشارات الخلوية.","البابايين إنزيم، والهيموجلوبين بروتين نقل.","الكيراتين بنائي، لكن الأنسولين هرمون للإشارات الخلوية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.812Z"}'::jsonb),
('essay', 1, null::int, null, null, '1) تسريع التفاعلات: تعمل بعض البروتينات إنزيمات (عوامل محفزة حيوية) تسرّع التفاعلات الكيميائية دون أن تُستهلك، مثل البابايين الذي يفكك جزيئات البروتين إلى أحماض أمينية.
2) النقل: تنقل بعض البروتينات جسيمات أصغر منها في أرجاء الجسم، مثل الهيموجلوبين الذي ينقل الأكسجين من الرئتين إلى سائر الجسم.
3) الدعم البنائي: تكوّن بعض البروتينات تراكيب حيوية، مثل الكولاجين في الجلد والأوتار والأربطة والعظام، والكيراتين في الشعر.
(ويُقبل أيضًا: الإشارات الخلوية، مثل هرمون الأنسولين الذي يحمل إشارات إلى خلايا الجسم لأخذ سكر الدم وتخزينه.)', '["وظيفة أولى مشروحة","مثال صحيح عليها","وظيفة ثانية مشروحة","مثال صحيح عليها","وظيفة ثالثة مشروحة","مثال صحيح عليها"]'::jsonb, '[]'::jsonb, '[{"element":"شرح الوظيفة الأولى","marks":1},{"element":"مثال الوظيفة الأولى","marks":1},{"element":"شرح الوظيفة الثانية","marks":1},{"element":"مثال الوظيفة الثانية","marks":1},{"element":"شرح الوظيفة الثالثة","marks":1},{"element":"مثال الوظيفة الثالثة","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"ثلاث وظائف مختلفة مشروحة مع مثال صحيح لكل منها"},{"level":"3–5 درجات","description":"وظيفتان أو ثلاث مع نقص في الشرح أو في الأمثلة"},{"level":"1–2 درجة","description":"وظيفة واحدة صحيحة مع مثالها أو دونه"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة نقل الأكسجين إلى الكولاجين","عدّ الأنسولين بروتينًا بنائيًا","ذكر الوظيفة دون شرح ما يقوم به البروتين فيها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-15T02:47:48.812Z"}'::jsonb),
('essay', 2, null::int, null, null, 'العملية هي تغيّر الخواص الطبيعية، وهي العملية التي تشوّه تركيب البروتين الطبيعي ثلاثي الأبعاد بانفكاك طياته ولوالبه. عند سلق البيضة ترتفع درجة الحرارة فتنفك طيات البروتين في الزلال ويتغير شكله، فيتصلب الزلال. ومن العوامل الأخرى المسببة لهذه العملية: تغير الرقم الهيدروجيني pH، وتغير قوة الرابطة الأيونية. ولأن البروتين يعمل بصورة صحيحة فقط عندما يكون مطويًا بشكله الصحيح، فإنه يصبح عادة غير فعال بعد تغيّر خواصه الطبيعية.', '["تسمية العملية (تغيّر الخواص الطبيعية) وتعريفها: تشوه التركيب ثلاثي الأبعاد","تفسير تصلب الزلال بانفكاك طيات البروتين بالحرارة","عاملان آخران: pH وقوة الرابطة الأيونية","الأثر: يصبح البروتين غير فعال لأن شكله ضروري لعمله"]'::jsonb, '[]'::jsonb, '[{"element":"تسمية العملية وتعريفها","marks":1},{"element":"تفسير تصلب الزلال","marks":1},{"element":"ذكر العاملين","marks":1},{"element":"بيان الأثر في الوظيفة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل مع العاملين والأثر"},{"level":"2–3 درجات","description":"تفسير صحيح مع نقص في العوامل أو الأثر"},{"level":"1 درجة","description":"تسمية العملية فقط دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير التصلب بتبخر الماء فقط","القول إن البروتين يتحول إلى أحماض أمينية حرة","ذكر التسخين عاملًا ثانيًا مع أن السؤال يطلب غير درجة الحرارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-15T02:47:48.812Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الهيموجلوبين بروتين كروي يتكوّن من أربع سلاسل عديدة الببتيد، تحتوي كل منها على مجموعة حديد تسمى هيم، ووظيفته نقل الأكسجين في الدم من الرئتين إلى سائر الجسم (بروتين نقل). أما الكيراتين فبروتين ليفي طويل يكوّن الشعر، ووظيفته الدعم البنائي. وشكل البروتين مهم لعمله؛ فالبروتين يعمل بصورة صحيحة فقط عندما يكون مطويًا بشكله الصحيح، فإذا تغيّر هذا الشكل فقد لا يستطيع أداء عمله داخل الخلية.', '["الهيموجلوبين: كروي من أربع سلاسل فيها هيم","وظيفته نقل الأكسجين","الكيراتين: ليفي طويل","وظيفته الدعم البنائي (الشعر)","الشكل ضروري لعمل البروتين"]'::jsonb, '[]'::jsonb, '[{"element":"شكل الهيموجلوبين","marks":1},{"element":"وظيفة الهيموجلوبين","marks":1},{"element":"شكل الكيراتين","marks":1},{"element":"وظيفة الكيراتين","marks":1},{"element":"تفسير أهمية الشكل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة في الشكل والوظيفة مع تفسير صحيح"},{"level":"3–4 درجات","description":"مقارنة صحيحة في أحد الجانبين مع تفسير، أو مقارنة كاملة دون تفسير"},{"level":"1–2 درجة","description":"معلومة صحيحة واحدة أو اثنتان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصف الهيموجلوبين بأنه ليفي","نسبة نقل الأكسجين إلى الكيراتين","إغفال الربط بين الشكل والوظيفة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-15T02:47:48.813Z"}'::jsonb)
