('mcq', 1, 1, 'المجموعة B صيغتها −COOH (ذرة كربون ترتبط بذرة أكسجين برابطة ثنائية وبمجموعة OH)، وهي مجموعة الكربوكسيل الحمضية.', '["مجموعة الأمين هي −NH₂ المحددة بالحرف A.","","السلسلة الجانبية المتغيرة هي R المحددة بالحرف D.","ذرة الهيدروجين هي H المحددة بالحرف C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-15T02:47:48.813Z"}'::jsonb),
('mcq', 2, 3, 'تشترك الأحماض الأمينية في ذرة الكربون المركزية ومجموعة الأمين ومجموعة الكربوكسيل وذرة الهيدروجين، وتختلف في السلسلة الجانبية المتغيرة R التي تتفاوت من ذرة هيدروجين واحدة إلى تركيب معقد ذي حلقتين.', '["مجموعة الأمين −NH₂ موجودة في كل الأحماض الأمينية.","مجموعة الكربوكسيل −COOH موجودة في كل الأحماض الأمينية.","ذرة الكربون المركزية موجودة في كل الأحماض الأمينية وتحيط بها المجموعات الأربع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-15T02:47:48.813Z"}'::jsonb),
('mcq', 3, 2, 'يوجد في كل حمض أميني ذرة كربون مركزية محاطة بأربع مجموعات: مجموعة الأمين −NH₂، ومجموعة الكربوكسيل −COOH، وذرة هيدروجين، وسلسلة جانبية متغيرة R.', '["في الحمض الأميني مجموعة أمين واحدة على الكربون المركزي، والمجموعة الرابعة ذرة هيدروجين.","الهيدروكسيل والكربونيل جزءان من مجموعة الكربوكسيل نفسها −COOH، ولا يرتبطان منفصلين بالكربون المركزي، كما أن ذرة الهيدروجين غائبة.","","يحتوي الحمض الأميني على مجموعة أمين، ولا يرتبط بالكربون المركزي مجموعتا كربوكسيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.813Z"}'::jsonb),
('mcq', 4, 0, 'ترتبط ذرة الكربون المركزية بمجموعة الأمين ومجموعة الكربوكسيل وذرتي هيدروجين؛ إحداهما ذرة الهيدروجين الثابتة في كل حمض أميني، والأخرى هي السلسلة الجانبية R. فالسلسلة الجانبية ذرة هيدروجين (وهذا هو الجلايسين).', '["","لا توجد مجموعة ميثيل في هذا المركب؛ فذرة الكربون المركزية ترتبط بذرتي هيدروجين.","مجموعة −OH الوحيدة جزء من مجموعة الكربوكسيل، لا سلسلة جانبية.","لكل حمض أميني سلسلة جانبية، وهي هنا أبسط سلسلة ممكنة: ذرة هيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-11-15T02:47:48.813Z"}'::jsonb),
('mcq', 5, 1, 'السلسلة الجانبية في هذا الحمض الأميني هي −CH₂OH، وتنتهي بالمجموعة −OH؛ أي إنها تحتوي على مجموعة الهيدروكسيل القطبية (وهذا هو السيرين).', '["مجموعة الأمين في هذا المركب مرتبطة بالكربون المركزي مباشرة، وليست في السلسلة الجانبية.","","مجموعة الكربوكسيل مرتبطة بالكربون المركزي، وليست في السلسلة الجانبية.","لا توجد مجموعة كربونيل في السلسلة الجانبية؛ فمجموعة C=O الوحيدة جزء من مجموعة الكربوكسيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-11-15T02:47:48.813Z"}'::jsonb),
('mcq', 6, 2, 'السلسلة الجانبية للحمض (3) هي −CH₂CH₂COOH، وتحتوي على مجموعة كربوكسيل −COOH، وهي مجموعة حمضية؛ لذا فسلسلته الجانبية حمضية (وهو حمض الجلوتاميك).', '["السلسلة الجانبية للحمض (1) −CH(CH₃)₂ ألكان غير قطبي، ليست حمضية.","السلسلة الجانبية للحمض (2) تنتهي بمجموعة أمين −NH₂ وهي قاعدية لا حمضية.","","السلسلة الجانبية للحمض (4) تحتوي على حلقة أروماتية (بنزين)، وليست حمضية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-15T02:47:48.814Z"}'::jsonb),
('mcq', 7, 2, 'مجموعة الأمين صيغتها −NH₂، ومجموعة الكربوكسيل الحمضية صيغتها −COOH؛ وكلتاهما ترتبطان بذرة الكربون المركزية في الحمض الأميني.', '["هذا ترتيب معكوس؛ فالمطلوب صيغة مجموعة الأمين أولًا ثم الكربوكسيل.","−OH مجموعة هيدروكسيل، ومجموعة الكربوكسيل −COOH تحتوي على C=O وOH معًا.","","−CHO مجموعة الألدهيد، لا مجموعة الكربوكسيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.814Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يتكوّن الحمض الأميني من ذرة كربون مركزية ترتبط بأربع مجموعات: مجموعة الأمين −NH₂، ومجموعة الكربوكسيل الحمضية −COOH، وذرة هيدروجين −H، وسلسلة جانبية متغيرة R. ويدل اسم «الحمض الأميني» على وجود مجموعة الأمين (أميني) ومجموعة الكربوكسيل (حمض). والجزء الذي يميز حمضًا أمينيًا من آخر هو السلسلة الجانبية R، التي تتفاوت من ذرة هيدروجين واحدة إلى تركيب معقد ذي حلقتين. ويمكن تمثيله بالصيغة: H₂N−CH(R)−COOH.', '["ذرة كربون مركزية","مجموعة الأمين −NH₂","مجموعة الكربوكسيل −COOH","ذرة هيدروجين وسلسلة جانبية R","السلسلة الجانبية R هي ما يميز الأحماض الأمينية"]'::jsonb, '[]'::jsonb, '[{"element":"ذرة الكربون المركزية","marks":1},{"element":"مجموعة الأمين وصيغتها","marks":1},{"element":"مجموعة الكربوكسيل وصيغتها","marks":1},{"element":"ذرة الهيدروجين والسلسلة الجانبية","marks":1},{"element":"تحديد السلسلة الجانبية مميزًا","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وصف كامل بالصيغ مع تحديد الجزء المميز"},{"level":"3–4 درجات","description":"وصف صحيح مع نقص صيغة أو مجموعة"},{"level":"1–2 درجة","description":"ذكر مجموعتين صحيحتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة مجموعة الكربوكسيل −OH فقط","إغفال ذرة الهيدروجين المرتبطة بالكربون المركزي","القول إن مجموعة الأمين هي التي تختلف بين الأحماض الأمينية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.814Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) مجموعة الأمين هي H₂N− المرتبطة بالكربون المركزي من اليسار، ومجموعة الكربوكسيل هي −COOH المرتبطة به من اليمين.
(b) السلسلة الجانبية −CH₂−SH، ويميزها احتواؤها على عنصر الكبريت S.
(c) لأن فيه ذرة كربون مركزية ترتبط بأربع مجموعات: مجموعة أمين، ومجموعة كربوكسيل، وذرة هيدروجين، وسلسلة جانبية؛ وهذا هو التركيب العام للحمض الأميني (والمركب هو السيستين).', '["تحديد −NH₂","تحديد −COOH","السلسلة الجانبية −CH₂SH وعنصر الكبريت","التفسير بالمجموعات الأربع حول الكربون المركزي"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد مجموعة الأمين","marks":1},{"element":"تحديد مجموعة الكربوكسيل","marks":1},{"element":"السلسلة الجانبية والكبريت","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد صحيح للأجزاء الثلاثة مع تفسير كامل"},{"level":"2–3 درجات","description":"تحديد صحيح لمعظم الأجزاء مع تفسير ناقص"},{"level":"1 درجة","description":"تحديد جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ −SH مجموعة هيدروكسيل","عدّ ذرة الهيدروجين على الكربون المركزي السلسلة الجانبية","إغفال ذرة الهيدروجين عند تعداد المجموعات الأربع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-15T02:47:48.814Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الفالين: سلسلة جانبية غير قطبية؛ لأنها ألكان (−CH(CH₃)₂) تحتوي على كربون وهيدروجين فقط.
السيرين: سلسلة جانبية قطبية؛ لأنها تحتوي على مجموعة الهيدروكسيل −OH.
فينيل الألنين: سلسلة جانبية أروماتية؛ لأنها تحتوي على حلقة بنزين.
حمض الجلوتاميك: سلسلة جانبية حمضية؛ لأنها تحتوي على مجموعة الكربوكسيل −COOH.', '["الفالين غير قطبي (ألكان)","السيرين قطبي (هيدروكسيل)","فينيل الألنين أروماتي (حلقة بنزين)","حمض الجلوتاميك حمضي (كربوكسيل)"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف الفالين مع المبرر","marks":1},{"element":"تصنيف السيرين مع المبرر","marks":1},{"element":"تصنيف فينيل الألنين مع المبرر","marks":1},{"element":"تصنيف حمض الجلوتاميك مع المبرر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف الأربعة صحيح مع المجموعة المبررة لكل منها"},{"level":"2–3 درجات","description":"تصنيف صحيح لاثنين أو ثلاثة"},{"level":"1 درجة","description":"تصنيف صحيح لواحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف السيرين حمضيًا لوجود −OH","تصنيف حمض الجلوتاميك قاعديًا","عدّ الفالين أروماتيًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-15T02:47:48.814Z"}'::jsonb)
