from (values
('mcq', 1, 'يمثّل الشكل الآتي اتحاد حمضين أمينيين. ما نوع هذا التفاعل؟', null, '[{"src":"qimg/chem22/c6-l1a-peptide-rxn.svg","alt":"معادلة على سطرين. السطر الأول: حمض أميني صيغته H₂N−C(H)(R₁)−C(=O)−OH، حيث R₁ فوق ذرة الكربون المركزية وH أسفلها، ثم إشارة +، ثم حمض أميني ثانٍ ترتبط فيه ذرة N بذرة H من اليسار وبذرة H من الأعلى وبذرة الكربون المركزية من اليمين، وفوق ذرة الكربون المركزية R₂ وأسفلها H، ثم C(=O)−OH. السطر الثاني: سهم يتجه إلى اليمين، ثم المركب H₂N−C(H)(R₁)−C(=O)−N(H)−C(H)(R₂)−C(=O)−OH، حيث ترتبط ذرة الكربون التي تحمل O بالرابطة الثنائية بذرة N تحمل ذرة H فوقها، ثم إشارة +، ثم H₂O."}]'::jsonb, '["تفاعل إضافة","تفاعل حذف","تفاعل استبدال","تفاعل تكثف"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 211 — الشكل 6-2 تكوين الرابطة الببتيدية'),
('mcq', 2, 'كم جزيء ماء ينطلق عند ارتباط 5 أحماض أمينية معًا في سلسلة ببتيد واحدة غير متفرعة؟', null, null, '["4","5","1","8"]'::jsonb, 'تطبيق', 'تذكر حقيقة', 'متوسط', 'الكتاب ص 211 — الرابطة الببتيدية، وص 231 تقويم الفصل س39'),
('mcq', 3, 'ما المجموعة الوظيفية العضوية التي تتكوّن في الرابطة الببتيدية؟', null, null, '["الإستر","الأميد","الإيثر","الأمين"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 211–212 — الرابطة الببتيدية والشكل 6-3'),
('mcq', 4, 'كم رابطة ببتيدية في الببتيد المبيَّن في الشكل الآتي؟', null, '[{"src":"qimg/chem22/c6-l1a-tetrapeptide.svg","alt":"صيغة بنائية لسلسلة ببتيد أفقية من اليسار إلى اليمين: H₂N−CH₂−C(=O)−NH−CH(CH₂OH)−C(=O)−NH−CH(CH(CH₃)₂)−C(=O)−NH−CH(CH₂SH)−C(=O)−OH. كل ذرة كربون مركزية مرسومة وتحتها ذرة H وفوقها سلسلتها الجانبية: الأولى H، والثانية CH₂ ثم OH، والثالثة CH ترتبط بمجموعتي CH₃، والرابعة CH₂ ثم SH. وكل ذرة كربون كربونيل تحتها ذرة O مرتبطة برابطة ثنائية، وكل ذرة N داخل السلسلة فوقها ذرة H."}]'::jsonb, '["2","3","4","5"]'::jsonb, 'تطبيق', 'عدّ من شكل', 'متوسط', 'الكتاب ص 232 — تقويم الفصل س41 (الشكل 6-25)'),
('mcq', 5, 'سلسلة تتكوّن من 25 حمضًا أمينيًا مرتبطة معًا بروابط ببتيدية. ما الاسم المناسب لهذه السلسلة؟', null, null, '["ثنائي الببتيد","بروتين","حمض أميني","عديد الببتيد"]'::jsonb, 'فهم', 'تمييز', 'متوسط', 'الكتاب ص 212 — الببتيد وعديد الببتيد'),
('mcq', 6, 'يبيّن الشكل الآتي ثنائيَي ببتيد (1) و(2) يتكوّن كلٌّ منهما من الجلايسين وفينيل الألنين. ما العلاقة بين المركبين؟', null, '[{"src":"qimg/chem22/c6-l1a-glyphe.svg","alt":"صيغتان بنائيتان مفصولتان بخط متقطع. المركب (1) في الأعلى: H₂N−CH₂−C(=O)−NH−CH(CH₂−C₆H₅)−C(=O)−OH، أي تبدأ السلسلة من اليسار بذرة كربون تحمل ذرتي هيدروجين، ثم مجموعة C=O، ثم N تحمل H، ثم ذرة كربون تحمل مجموعة CH₂ مرتبطة بحلقة بنزين، ثم المجموعة COOH في الطرف الأيمن. المركب (2) في الأسفل: H₂N−CH(CH₂−C₆H₅)−C(=O)−NH−CH₂−C(=O)−OH، أي تبدأ السلسلة من اليسار بذرة الكربون التي تحمل CH₂ وحلقة البنزين، ثم C=O، ثم N تحمل H، ثم ذرة كربون تحمل ذرتي هيدروجين، ثم المجموعة COOH في الطرف الأيمن."}]'::jsonb, '["مركب واحد؛ لأنهما يحتويان على الحمضين الأمينيين نفسيهما","مركبان مختلفان؛ لأن عدد الروابط الببتيدية فيهما مختلف","مركبان مختلفان؛ لأن ترتيب ارتباط الحمضين الأمينيين مختلف","مركب واحد؛ لأن لكلٍّ منهما طرفًا أمينيًا وطرفًا كربوكسيليًا"]'::jsonb, 'تحليل', 'مقارنة تراكيب', 'صعب', 'الكتاب ص 212 — الشكل 6-4 (Gly–Phe و Phe–Gly)'),
('mcq', 7, 'إذا كان كل موقع في سلسلة الببتيد يمكن أن يشغله أيّ حمض من الأحماض الأمينية العشرين، فكم تتابعًا محتملًا لببتيد ثلاثي يتكوّن من 3 أحماض أمينية؟', null, null, '["60","400","8000","3²⁰"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 212 — الببتيد وعديد الببتيد'),
('essay', 1, 'اكتب الصيغة البنائية المكثفة لثنائي الببتيد Gly–Ser المتكوّن من الجلايسين (سلسلته الجانبية −H) والسيرين (سلسلته الجانبية −CH₂OH)، بحيث يكون الجلايسين هو الطرف الذي يحمل مجموعة الأمين الحرة، ثم حدّد الرابطة الببتيدية في الصيغة، واذكر الجزيء الذي ينطلق عند تكوّنها ونوع هذا التفاعل.', null, null, null, 'تطبيق', 'كتابة صيغة', 'متوسط', 'الكتاب ص 215 — التقويم 6-1 س3، وص 211–212'),
('essay', 2, 'قارن بين الحمض الأميني، وثنائي الببتيد، وعديد الببتيد، والبروتين من حيث عدد الأحماض الأمينية في كلٍّ منها، ثم رتّبها تصاعديًا حسب الكتلة الجزيئية.', null, null, null, 'فهم', 'مقارنة وترتيب', 'سهل', 'الكتاب ص 212 — الببتيد وعديد الببتيد، وص 215 التقويم 6-1 س2'),
('essay', 3, 'ببتيد يتكوّن من 4 أحماض أمينية:
(a) كم رابطة ببتيدية فيه؟
(b) كم جزيء ماء ينطلق عند تكوينه من الأحماض الأمينية الأربعة؟
(c) احسب عدد التتابعات المحتملة لببتيد من 4 أحماض أمينية إذا كان كل موقع يمكن أن يشغله أي حمض من الأحماض الأمينية العشرين.
(d) إذا كانت الأحماض الأمينية الأربعة مختلفة ومحددة، فبكم طريقة يمكن ترتيبها في الببتيد؟', null, null, null, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 212 — عدد التتابعات المحتملة، وص 231 تقويم الفصل س38 وس39')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
