from (values
('mcq', 1, 3, 'تتحد مجموعة الكربوكسيل لأحد الحمضين مع مجموعة الأمين للحمض الآخر فيتكوّن ثنائي ببتيد وينطلق جزيء ماء؛ واتحاد جزيئين مع انطلاق جزيء صغير كالماء هو تفاعل تكثف.', '["في تفاعل الإضافة تُضاف ذرات إلى رابطة ثنائية أو ثلاثية دون انطلاق جزيء صغير، أما هنا فينطلق ماء.","تفاعل الحذف يحدث في جزيء واحد ويكوّن رابطة ثنائية، أما هنا فيتحد جزيئان.","في الاستبدال تحل ذرة أو مجموعة محل أخرى في الجزيء، أما هنا فيتحد جزيئان مع انطلاق ماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-15T02:47:48.815Z"}'::jsonb),
('mcq', 2, 0, 'في سلسلة من 5 أحماض أمينية توجد 5 − 1 = 4 روابط ببتيدية، وينطلق جزيء ماء واحد H₂O عند تكوّن كل رابطة (تفاعل تكثف)؛ فينطلق 4 جزيئات ماء.', '["","5 هو عدد الأحماض الأمينية، أما جزيئات الماء فبعدد الروابط الببتيدية، وهو أقل من عدد الأحماض بواحد.","ينطلق جزيء ماء واحد مع كل رابطة ببتيدية، لا جزيء واحد للسلسلة كلها.","ينطلق جزيء ماء واحد مع كل رابطة، لا جزيئان؛ فذرة H من الأمين ومجموعة OH من الكربوكسيل تكوّنان معًا جزيء ماء واحدًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-15T02:47:48.815Z"}'::jsonb),
('mcq', 3, 1, 'تتحد مجموعة الكربوكسيل لأحد الحمضين الأمينيين مع مجموعة الأمين للآخر لتكوين مجموعة الأميد الوظيفية −CO−NH−، وتسمى هذه الرابطة الرابطة الببتيدية.', '["الإستر يتكوّن من حمض كربوكسيلي وكحول، ويحتوي على −COO− لا على نيتروجين.","","الإيثر فيه ذرة أكسجين بين مجموعتين ألكيل، ولا يحتوي على نيتروجين.","مجموعة الأمين −NH₂ موجودة في الحمض الأميني قبل التفاعل، أما الرابطة الناتجة فتحتوي على C=O مرتبطة بـ N."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-15T02:47:48.815Z"}'::jsonb),
('mcq', 4, 1, 'تتكوّن السلسلة من 4 أحماض أمينية (لكل منها ذرة كربون مركزية)، وبين كل حمضين متتاليين رابطة ببتيدية −CO−NH−؛ فعدد الروابط = 4 − 1 = 3.', '["عدد الروابط الببتيدية (C=O مرتبطة بـ N−H) هنا ثلاث لا اثنتان؛ ربما أُغفلت إحدى الروابط في وسط السلسلة.","","4 هو عدد الأحماض الأمينية في السلسلة لا عدد الروابط بينها.","5 ينتج عن عدّ الأحماض الأمينية وإضافة رابطة؛ وعدد الروابط أقل من عدد الأحماض بواحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-15T02:47:48.815Z"}'::jsonb),
('mcq', 5, 3, 'السلسلة المكوّنة من عشرة أحماض أمينية أو أكثر مرتبطة بروابط ببتيدية تسمى عديد الببتيد، ولا تُسمى بروتينًا إلا عندما يصل طولها إلى نحو 50 حمضًا أمينيًا؛ فسلسلة من 25 حمضًا أمينيًا عديد ببتيد.', '["ثنائي الببتيد يتكوّن من حمضين أمينيين فقط.","يُطلق اسم البروتين عندما يصل طول السلسلة إلى نحو 50 حمضًا أمينيًا.","الحمض الأميني وحدة واحدة، لا سلسلة من وحدات مرتبطة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-15T02:47:48.815Z"}'::jsonb),
('mcq', 6, 2, 'في المركب (1) يحمل الجلايسين مجموعة الأمين الحرة وفينيل الألنين مجموعة الكربوكسيل الحرة (Gly–Phe)، وفي المركب (2) العكس (Phe–Gly)؛ ولأن ترتيب ارتباط الحمضين مختلف فهما مركبان مختلفان.', '["احتواؤهما على الحمضين نفسيهما لا يجعلهما مركبًا واحدًا؛ فالترتيب الذي يرتبط به الحمضان مهم.","في كلٍّ منهما رابطة ببتيدية واحدة فقط، فعدد الروابط متساوٍ.","","وجود طرف أميني وآخر كربوكسيلي صفة لكل ثنائي ببتيد، ولا يدل على أنهما المركب نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.816Z"}'::jsonb),
('mcq', 7, 2, 'عدد التتابعات المحتملة لببتيد يحتوي على n من الأحماض الأمينية = 20ⁿ، وللببتيد الثلاثي: 20³ = 8000 تتابع.', '["60 ناتج ضرب 20 × 3، والصحيح رفع 20 إلى القوة 3.","400 = 20² عدد تتابعات ثنائي الببتيد، لا الببتيد الثلاثي.","","3²⁰ ناتج عكس الأساس والأس؛ فالأساس عدد الأحماض الممكنة (20) والأس عدد المواقع (3)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-15T02:47:48.816Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الصيغة: H₂N−CH₂−CO−NH−CH(CH₂OH)−COOH.
الرابطة الببتيدية هي −CO−NH− الواصلة بين ذرة كربون الكربوكسيل للجلايسين وذرة نيتروجين الأمين للسيرين (مجموعة الأميد).
ينطلق جزيء ماء H₂O (من OH الكربوكسيل وH الأمين)، والتفاعل تفاعل تكثف.', '["الطرف الأميني H₂N−CH₂− للجلايسين","الطرف الكربوكسيلي −CH(CH₂OH)−COOH للسيرين","تحديد −CO−NH− رابطةً ببتيدية","انطلاق H₂O وتفاعل تكثف"]'::jsonb, '["الجلايسين: H₂N−CH₂−COOH، والسيرين: H₂N−CH(CH₂OH)−COOH","تُزال OH من كربوكسيل الجلايسين وH من أمين السيرين فيتكوّن H₂O","ترتبط C=O للجلايسين بـ N−H للسيرين: H₂N−CH₂−CO−NH−CH(CH₂OH)−COOH"]'::jsonb, '[{"element":"صيغة الطرف الأميني صحيحة","marks":1},{"element":"صيغة الطرف الكربوكسيلي مع السلسلة الجانبية","marks":1},{"element":"تحديد الرابطة الببتيدية","marks":1},{"element":"الماء ونوع التفاعل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"صيغة صحيحة كاملة مع تحديد الرابطة والجزيء الناتج ونوع التفاعل"},{"level":"2–3 درجات","description":"صيغة صحيحة مع نقص في التحديد أو خطأ في الترتيب"},{"level":"1 درجة","description":"ذكر الماء أو التكثف فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الترتيب معكوسًا (Ser–Gly)","إبقاء OH على الكربونيل الذي دخل في الرابطة","ربط السلسلة الجانبية −CH₂OH بذرة النيتروجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-15T02:47:48.816Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الحمض الأميني: وحدة واحدة. ثنائي الببتيد: حمضان أمينيان مرتبطان برابطة ببتيدية واحدة. عديد الببتيد: سلسلة من عشرة أحماض أمينية أو أكثر مرتبطة بروابط ببتيدية. البروتين: سلسلة يصل طولها إلى نحو 50 حمضًا أمينيًا أو أكثر (وقد يتجاوز 1000). الترتيب تصاعديًا حسب الكتلة الجزيئية: الحمض الأميني < ثنائي الببتيد < عديد الببتيد < البروتين.', '["الحمض الأميني وحدة واحدة","ثنائي الببتيد حمضان أمينيان","عديد الببتيد عشرة أحماض أمينية أو أكثر","البروتين نحو 50 حمضًا أمينيًا أو أكثر","الترتيب التصاعدي الصحيح"]'::jsonb, '[]'::jsonb, '[{"element":"الحمض الأميني","marks":1},{"element":"ثنائي الببتيد","marks":1},{"element":"عديد الببتيد","marks":1},{"element":"البروتين","marks":1},{"element":"الترتيب","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة صحيحة للأربعة مع ترتيب صحيح"},{"level":"3–4 درجات","description":"مقارنة صحيحة لثلاثة أو أكثر مع خطأ بسيط في الترتيب"},{"level":"1–2 درجة","description":"تعريف واحد أو اثنان صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ عديد الببتيد أكبر من البروتين","القول إن ثنائي الببتيد يتكوّن من رابطتين ببتيديتين","عدّ كل سلسلة من أكثر من حمضين بروتينًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.816Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) 3 روابط ببتيدية (عدد الأحماض − 1).
(b) 3 جزيئات ماء؛ جزيء مع كل رابطة ببتيدية.
(c) 20⁴ = 160,000 تتابع.
(d) 4 × 3 × 2 × 1 = 24 طريقة.', '["3 روابط","3 جزيئات ماء","20⁴ = 160,000","24 ترتيبًا"]'::jsonb, '["عدد الروابط الببتيدية = عدد الأحماض الأمينية − 1 = 4 − 1 = 3","ينطلق جزيء H₂O مع كل رابطة: 3 جزيئات","عدد التتابعات = 20ⁿ = 20⁴ = 160,000","ترتيب 4 أحماض مختلفة: الموقع الأول 4 خيارات، والثاني 3، والثالث 2، والرابع 1: 4 × 3 × 2 × 1 = 24"]'::jsonb, '[{"element":"عدد الروابط","marks":1},{"element":"عدد جزيئات الماء","marks":1},{"element":"حساب 160,000","marks":1},{"element":"حساب 24","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابات الأربع صحيحة مع الخطوات"},{"level":"2–3 درجات","description":"إجابتان أو ثلاث صحيحة"},{"level":"1 درجة","description":"إجابة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الروابط مساويًا لعدد الأحماض (4)","حساب 4²⁰ بدل 20⁴","حساب 20 × 4 = 80 تتابعًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-15T02:47:48.816Z"}'::jsonb)
