('mcq', 5, 'ماذا يحدث للإنزيم بعد انتهاء التفاعل وانطلاق النواتج؟', null, null, '["يتحول إلى نواتج مع المادة الخاضعة لفعله","يبقى مرتبطًا بالنواتج ارتباطًا دائمًا","تتغير خواصه الطبيعية فيفقد قدرته على العمل","ينطلق بشكله الأصلي ويمكنه تكرار التفاعل مرات عديدة"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 214 — الشكل 6-6'),
