from (values
('mcq', 1, 0, 'الإنزيم عامل محفز حيوي؛ يعمل على تسريع التفاعل الكيميائي دون أن يُستهلك في هذا التفاعل.', '["","الإنزيم لا يُستهلك في التفاعل، بل ينطلق بشكله الأصلي بعده.","الإنزيم ليس ناتجًا للتفاعل؛ فهو موجود قبل التفاعل وبعده دون تغيير.","الإنزيم يسرّع التفاعل الكيميائي ولا يبطئه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-15T02:47:48.817Z"}'::jsonb),
('mcq', 2, 1, 'X تجويف (جيب) في جزيء الإنزيم ترتبط به المادة الخاضعة، والنقطة التي ترتبط بها المواد الخاضعة لفعل الإنزيم تسمى الموقع النشط.', '["المادة الخاضعة لفعل الإنزيم هي الجسم الصغير الذي يرتبط بالإنزيم (Y)، لا التجويف في الإنزيم.","","مركب الإنزيم والمادة الخاضعة هو التركيب Z في المرحلة الوسطى.","النواتج هي القطعتان المنفصلتان في المرحلة الأخيرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-15T02:47:48.817Z"}'::jsonb),
('mcq', 3, 3, 'Z هو التركيب الناتج من ارتباط المادة الخاضعة بالموقع النشط للإنزيم، ويسمى مركب الإنزيم والمادة الخاضعة.', '["الموقع النشط جزء من الإنزيم فقط (X)، أما Z فيشمل الإنزيم والمادة المرتبطة به معًا.","المادة الخاضعة وحدها هي Y قبل ارتباطها، أما Z فيشمل الإنزيم أيضًا.","النواتج تنطلق في المرحلة الأخيرة بعد انفصالها عن الإنزيم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-15T02:47:48.817Z"}'::jsonb),
('mcq', 4, 2, 'يؤدي الإنزيم عادة إلى تخفيض طاقة تنشيط التفاعل عن طريق تثبيت الحالة الانتقالية، وتخفض القوى بين جزيئات الإنزيم والمادة الخاضعة طاقة التنشيط فتتكسر الروابط وتتحول المادة الخاضعة إلى نواتج.', '["الإنزيمات لا ترفع درجة حرارة الخلية؛ بل تخفض طاقة التنشيط اللازمة.","زيادة طاقة التنشيط تبطئ التفاعل ولا تسرّعه.","","الإنزيم يطلق النواتج بعد التفاعل ويعود بشكله الأصلي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-15T02:47:48.817Z"}'::jsonb),
('mcq', 5, 3, 'بعد التفاعل ينطلق الإنزيم بشكله الأصلي، ويستطيع أن يقوم بالتفاعل نفسه مرات عديدة؛ لأنه عامل محفز لا يُستهلك.', '["الإنزيم لا يُستهلك في التفاعل ولا يتحول إلى نواتج.","تنطلق النواتج من الموقع النشط فيصبح الإنزيم حرًّا.","تغيّر الخواص الطبيعية يحدث بعوامل مثل الحرارة وpH، لا بمجرد إتمام التفاعل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-15T02:47:48.817Z"}'::jsonb),
('mcq', 6, 1, 'تُعد الإنزيمات نوعًا من البروتينات؛ فهي بروتينات تعمل عوامل محفزة حيوية.', '["الكربوهيدرات تزود المخلوقات الحية بالطاقة والمواد البنائية، والإنزيمات ليست منها.","","الليبيدات تكوّن الأغشية وتخزن الطاقة، والإنزيمات ليست منها.","الأحماض النووية تخزن المعلومات الوراثية وتنقلها، والإنزيمات ليست منها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-15T02:47:48.817Z"}'::jsonb),
('mcq', 7, 0, 'يجب أن تتطابق أشكال المواد الخاضعة مع شكل الموقع النشط كما تتطابق قطع الألغاز أو القفل والمفتاح؛ لذا فالجزيء الذي يختلف شكله قليلًا لن يرتبط بصورة جيدة بالموقع النشط، وقد لا يحدث التفاعل.', '["","التغير في شكل الموقع النشط (المطابقة التأثيرية) تغير بسيط مؤقت ليحيط بالمادة الخاضعة المناسبة، ولا يجعله يناسب أي مادة بتغير دائم.","اختلاف الشكل يضعف الارتباط بالموقع النشط ولا يسرّع التفاعل.","الإنزيم عامل محفز ولا يتحول إلى مادة خاضعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.818Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الإنزيم: عامل محفز حيوي (بروتين) يسرّع التفاعل الكيميائي دون أن يُستهلك فيه. المادة الخاضعة لفعل الإنزيم: المادة المتفاعلة في تفاعل يعمل الإنزيم فيه عاملًا محفزًا. الموقع النشط: النقطة (الجيب أو الشق) في جزيء الإنزيم التي ترتبط بها المادة الخاضعة.
الخطوات: 1) ترتبط المادة الخاضعة بالموقع النشط الذي يطابق شكلها. 2) يغيّر الموقع النشط شكله قليلًا ليحيط بالمادة الخاضعة بإحكام أكبر (المطابقة التأثيرية)، فيتكوّن مركب الإنزيم والمادة الخاضعة. 3) تخفض القوى بين الإنزيم والمادة الخاضعة طاقة التنشيط، فتتكسر الروابط وتتحول المادة الخاضعة إلى نواتج. 4) تنطلق النواتج، ويعود الإنزيم إلى شكله الأصلي ليعيد التفاعل مرات عديدة.', '["تعريف الإنزيم","تعريف المادة الخاضعة","تعريف الموقع النشط","المطابقة التأثيرية وتكوّن مركب الإنزيم والمادة الخاضعة","خفض طاقة التنشيط وانطلاق النواتج وعودة الإنزيم"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الإنزيم","marks":1},{"element":"تعريف المادة الخاضعة","marks":1},{"element":"تعريف الموقع النشط","marks":1},{"element":"المطابقة التأثيرية والمركب","marks":1},{"element":"خفض طاقة التنشيط وانطلاق النواتج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تعريفات صحيحة مع وصف متسلسل كامل للخطوات"},{"level":"3–4 درجات","description":"تعريفات صحيحة مع وصف ناقص للخطوات أو العكس"},{"level":"1–2 درجة","description":"تعريف أو اثنان صحيحان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الإنزيم يُستهلك في التفاعل","الخلط بين الموقع النشط والمادة الخاضعة","القول إن الإنزيم يرفع طاقة التنشيط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.819Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) عند حرارة الجسم 37 °C؛ لأن ارتفاع الرغوة (الناتجة عن تكوّن غاز الأكسجين) كان الأكبر (3.2 cm)، أي إن التفاعل الذي يحفزه الإنزيم كان أسرع.
(b) الإنزيم بروتين، وعند 100 °C تتغير خواصه الطبيعية؛ فتنفك طياته ويتشوه تركيبه ثلاثي الأبعاد ويتغير شكل الموقع النشط، فلا ترتبط به المادة الخاضعة (H₂O₂) ارتباطًا جيدًا ويتوقف تقريبًا تحفيز التفاعل.
(c) 2H₂O₂ → 2H₂O + O₂', '["أنشط عند 37 °C","الاستدلال بأكبر ارتفاع للرغوة","تفسير الغليان بتغيّر الخواص الطبيعية وتشوه الموقع النشط","المعادلة الموزونة 2H₂O₂ → 2H₂O + O₂"]'::jsonb, '["مقارنة ارتفاعات الرغوة: 3.2 cm > 1.8 cm > 0.6 cm > 0.1 cm","أكبر ارتفاع عند 37 °C يعني أسرع تحلل","موازنة المعادلة: 2H₂O₂ → 2H₂O + O₂ (4 ذرات H و4 ذرات O في الطرفين)"]'::jsonb, '[{"element":"تحديد 37 °C","marks":1},{"element":"الاستدلال بالرغوة","marks":1},{"element":"تفسير أثر الغليان","marks":2},{"element":"المعادلة الموزونة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد واستدلال صحيحان مع تفسير كامل ومعادلة موزونة"},{"level":"3–4 درجات","description":"تحديد صحيح مع تفسير ناقص أو معادلة غير موزونة"},{"level":"1–2 درجة","description":"تحديد درجة الحرارة فقط أو المعادلة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار 100 °C لأن الحرارة تسرع التفاعلات دائمًا","كتابة المعادلة H₂O₂ → H₂O + O₂ دون موازنة","القول إن الإنزيم يُستهلك في التفاعل عند الغليان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-15T02:47:48.819Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) المادة الخاضعة: جزيئات البروتين في ألياف اللحم القاسية، والنواتج: أحماض أمينية حرة.
(b) البابايين عامل محفز حيوي؛ ترتبط جزيئات البروتين بالموقع النشط للبابايين، فيسرّع تفكيكها إلى أحماض أمينية حرة بخفض طاقة التنشيط دون أن يُستهلك، فتتكسر ألياف البروتين القاسية ويصبح اللحم أكثر طراوة.
(c) لأن البابايين بروتين، والتسخين حتى الغليان يغيّر خواصه الطبيعية فيتشوه تركيبه ثلاثي الأبعاد وشكل موقعه النشط، فلا يستطيع الارتباط بالمادة الخاضعة ويفقد فعاليته.', '["المادة الخاضعة: بروتينات اللحم","النواتج: أحماض أمينية حرة","ارتباط البروتين بالموقع النشط وتسريع تفكيكه دون استهلاك الإنزيم","تغيّر الخواص الطبيعية للبابايين بالغليان وفقده فعاليته"]'::jsonb, '[]'::jsonb, '[{"element":"المادة الخاضعة","marks":1},{"element":"النواتج","marks":1},{"element":"شرح عمل البابايين","marks":2},{"element":"تفسير أثر الغليان","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد صحيح وشرح كامل وتفسير صحيح"},{"level":"3–4 درجات","description":"تحديد صحيح مع شرح أو تفسير ناقص"},{"level":"1–2 درجة","description":"تحديد المادة الخاضعة أو النواتج فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ البابايين المادة الخاضعة","ذكر السكريات نواتجَ لتفكيك البروتين","القول إن الحرارة تزيد نشاط الإنزيم مهما ارتفعت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.819Z"}'::jsonb)
