('mcq', 1, 'ما المقصود بتغيّر الخواص الطبيعية للبروتين؟', null, null, '["تحلّل البروتين إلى أحماض أمينية حرة بتكسير روابطه الببتيدية","اتحاد الأحماض الأمينية بروابط ببتيدية لتكوين سلسلة البروتين","العملية التي تشوّه تركيب البروتين الطبيعي ثلاثي الأبعاد وتتلفه","تغيّر ترتيب الأحماض الأمينية في السلسلة بإضافة أحماض أمينية جديدة"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 213 — تغير الخواص الطبيعية'),
('mcq', 2, 'أيّ مجموعات العوامل الآتية يمكن أن يسبّب كلٌّ منها تغيّر الخواص الطبيعية للبروتين؟', null, null, '["التغيّر في درجة الحرارة، والرقم الهيدروجيني pH، وقوة الرابطة الأيونية","ارتباط المادة الخاضعة بالموقع النشط، والمطابقة التأثيرية، وانطلاق النواتج","تكوين روابط ببتيدية جديدة، وانطلاق جزيئات الماء، وزيادة طول السلسلة","إضافة أحماض أمينية إلى الطرف الكربوكسيلي، وطي السلسلة في شكل حلزوني"]'::jsonb, 'فهم', 'تعرّف عوامل', 'متوسط', 'الكتاب ص 213 — تغير الخواص الطبيعية'),
('mcq', 3, 'الإنزيمات بروتينات. يمثّل المنحنى الآتي سرعة تفاعل يحفّزه إنزيم في جسم الإنسان عند درجات حرارة مختلفة. ما التفسير الصحيح لانخفاض سرعة التفاعل في المنطقة C؟', null, '[{"src":"qimg/chem22/c6-l1b-enzyme-temp.svg","alt":"منحنى بياني: المحور الأفقي درجة الحرارة (°C) مدرّج من 0 إلى 60 كل 10 درجات، والمحور الرأسي سرعة التفاعل. يبدأ المنحنى منخفضًا عند 0 °C ثم يرتفع تدريجيًا في المنطقة المعلّمة بالحرف A حتى يبلغ قمته عند نحو 38 °C في المنطقة المعلّمة بالحرف B (ويُسقط منها خط رأسي متقطع إلى المحور الأفقي)، ثم ينخفض بسرعة في المنطقة المعلّمة بالحرف C حتى تصبح سرعة التفاعل صفرًا تقريبًا عند 60 °C."}]'::jsonb, '["يُستهلك الإنزيم في التفاعل فينفد عند درجات الحرارة المرتفعة","تقلّ التصادمات بين الإنزيم والمادة الخاضعة كلما ارتفعت درجة الحرارة","يتحول الإنزيم إلى مادة خاضعة جديدة عند درجات الحرارة المرتفعة","تتغيّر الخواص الطبيعية للإنزيم فتنفك طياته ويتشوّه شكله ثلاثي الأبعاد"]'::jsonb, 'فهم', 'تفسير منحنى', 'متوسط', 'الكتاب ص 213 — تغير الخواص الطبيعية، والجزء الأول ص 67 — الكيمياء والصحة (الشكل 1)'),
('mcq', 4, 'يؤدي طبخ اللحم إلى تغيّر الخواص الطبيعية لبروتيناته. أيّ مما يأتي يحدث لهذه البروتينات في أثناء الطبخ؟', null, null, '["تتكوّن فيها روابط ببتيدية إضافية فتزداد كتلتها المولية","تنفك طياتها ولوالبها فيتشوّه تركيبها الطبيعي ثلاثي الأبعاد","يتضاعف عدد الأحماض الأمينية في سلاسلها فيزداد طولها","تلتف سلاسلها المنبسطة لتكوّن أشكالها الطبيعية ثلاثية الأبعاد"]'::jsonb, 'فهم', 'تطبيق مفهوم على موقف حياتي', 'سهل', 'الكتاب ص 213 — تغير الخواص الطبيعية (الطبخ)'),
('mcq', 5, 'أُضيف حمض إلى محلول إنزيم مع إبقاء درجة الحرارة ثابتة عند 37 °C، فتوقف الإنزيم عن تحفيز التفاعل. ما العامل الذي سبّب تغيّر الخواص الطبيعية للإنزيم في هذه الحالة؟', null, null, '["ارتفاع درجة حرارة المحلول","زيادة عدد الأحماض الأمينية في الإنزيم","نقص كمية المادة الخاضعة في المحلول","تغيّر الرقم الهيدروجيني pH للمحلول"]'::jsonb, 'تطبيق', 'تحديد عامل في موقف', 'سهل', 'الكتاب ص 213 — تغير الخواص الطبيعية'),
('mcq', 6, 'يُنثر البابايين على اللحم فيكسّر جزيئات البروتين ويحوّلها إلى أحماض أمينية حرة، في حين يؤدي تسخين اللحم إلى تغيّر الخواص الطبيعية لبروتيناته. ما الفرق الصحيح بين العمليتين؟', null, null, '["التسخين يشوّه الشكل ثلاثي الأبعاد للسلسلة، أما البابايين فيكسّر البروتين إلى أحماض أمينية حرة","كلتا العمليتين تحوّل البروتين إلى أحماض أمينية حرة، لكن التسخين أسرع من البابايين","التسخين يكوّن روابط ببتيدية جديدة، أما البابايين فيفك الروابط الهيدروجينية فقط","البابايين يغيّر الخواص الطبيعية للبروتين، أما التسخين فيبني بروتينات جديدة في اللحم"]'::jsonb, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 213 — تغير الخواص الطبيعية، وواقع الكيمياء في الحياة: الإنزيمات (البابايين)'),
('mcq', 7, 'تحتوي بعض محاليل تنظيف العدسات اللاصقة على إنزيمات تزيل الترسبات البروتينية. أيّ طرائق التعامل الآتية مع المحلول يُتوقع أن تُفقده فاعليته؟', null, null, '["حفظه في عبوته المغلقة عند درجة حرارة الغرفة","استعماله وفق الكمية والمدة المحددتين على العبوة","تركه مدة طويلة داخل سيارة مغلقة في حر الصيف","حفظه في خزانة مظللة بعيدًا عن أشعة الشمس"]'::jsonb, 'تطبيق', 'تطبيق مفهوم على موقف حياتي', 'متوسط', 'الكتاب ص 210 — الربط مع الحياة (محلول تنظيف العدسات)، وص 213 — تغير الخواص الطبيعية'),
('essay', 1, 'عرّف تغيّر الخواص الطبيعية للبروتين، ثم بيّن أيّ المواقف الآتية يسبّب تغيّر الخواص الطبيعية للبروتين وأيّها لا يسببه، مع ذكر العامل المسبّب إن وُجد:
(1) طبخ قطعة لحم.
(2) إضافة حمض إلى محلول بروتين.
(3) إذابة كمية كبيرة من ملح أيوني في محلول بروتين، مما يغيّر قوة الرابطة الأيونية في المحلول.
(4) ارتباط المادة الخاضعة بالموقع النشط لإنزيم عند 37 °C.', null, null, null, 'فهم', 'تعريف وتصنيف مواقف', 'متوسط', 'الكتاب ص 213 — تغير الخواص الطبيعية'),
('essay', 2, 'الإنزيمات بروتينات. يمثّل المنحنى الآتي سرعة تفاعل يحفّزه إنزيم في جسم الإنسان عند درجات حرارة مختلفة.
(a) عند أيّ درجة حرارة تقريبًا يكون الإنزيم أكثر نشاطًا؟
(b) فسّر زيادة سرعة التفاعل في المنطقة A.
(c) فسّر انخفاض سرعة التفاعل في المنطقة C مستعملًا مفهوم تغيّر الخواص الطبيعية.
(d) توقّع ما يحدث لهذا التفاعل إذا وُضع الإنزيم عند 55 °C مدة طويلة ثم أُعيد إلى 37 °C، معلّلًا توقعك.', null, '[{"src":"qimg/chem22/c6-l1b-enzyme-temp.svg","alt":"منحنى بياني: المحور الأفقي درجة الحرارة (°C) مدرّج من 0 إلى 60 كل 10 درجات، والمحور الرأسي سرعة التفاعل. يبدأ المنحنى منخفضًا عند 0 °C ثم يرتفع تدريجيًا في المنطقة المعلّمة بالحرف A حتى يبلغ قمته عند نحو 38 °C في المنطقة المعلّمة بالحرف B (ويُسقط منها خط رأسي متقطع إلى المحور الأفقي)، ثم ينخفض بسرعة في المنطقة المعلّمة بالحرف C حتى تصبح سرعة التفاعل صفرًا تقريبًا عند 60 °C."}]'::jsonb, null, 'تحليل', 'تفسير منحنى وتوقع', 'صعب', 'الكتاب ص 213 — تغير الخواص الطبيعية، والجزء الأول ص 67 — الكيمياء والصحة (الشكل 1)'),
('essay', 3, 'معجون لب البطاطس يحتوي على إنزيم يحفّز تحلل فوق أكسيد الهيدروجين H₂O₂ إلى ماء وغاز الأكسجين، ويُقاس نشاط الإنزيم بارتفاع الرغوة الناتجة. صمّم تجربة لاختبار الفرضية: «تغيّر الرقم الهيدروجيني pH يسبب تغيّر الخواص الطبيعية للإنزيم»، مبيّنًا: المتغير المستقل، والمتغير التابع، متغيرين اثنين يجب ضبطهما، وخطوات مختصرة، والنتيجة المتوقعة مع تفسيرها.', null, null, null, 'إبداع', 'تصميم تجربة', 'صعب', 'الكتاب ص 229 — مختبر الكيمياء: فعل الإنزيم ودرجة الحرارة (الاستقصاء)، وص 213')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
