from (values
('mcq', 1, 2, 'تغيّر الخواص الطبيعية هو العملية التي تشوّه تركيب البروتين الطبيعي ثلاثي الأبعاد وتمزقه أو تتلفه، نتيجة انفكاك طيات البروتين ولوالبه.', '["تكسير البروتين إلى أحماض أمينية حرة تحلّل له (كالذي يحفزه البابايين)، أما تغيّر الخواص الطبيعية فيتعلق بتشوه الشكل ثلاثي الأبعاد.","هذا وصف لتكوين البروتين من الأحماض الأمينية بتفاعلات التكثف، لا لإتلاف تركيبه.","","تغيّر الخواص الطبيعية لا يضيف أحماضًا أمينية ولا يغيّر ترتيبها، بل يفك طيات السلسلة الموجودة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-15T02:47:48.820Z"}'::jsonb),
('mcq', 2, 0, 'تنتج التغيرات في درجة الحرارة وقوة الرابطة الأيونية والرقم الهيدروجيني pH انفكاك طيات البروتين ولوالبه، فتسبب تغيّر خواصه الطبيعية.', '["","هذه مراحل عمل الإنزيم الطبيعية؛ يعود بعدها الإنزيم إلى شكله الأصلي ولا يتلف تركيبه.","هذه خطوات تكوين سلسلة الببتيد بالتكثف، وهي تبني البروتين ولا تشوّه تركيبه.","إضافة الأحماض الأمينية وطي السلسلة حلزونيًا من خطوات بناء البروتين وتكوين شكله الطبيعي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-15T02:47:48.820Z"}'::jsonb),
('mcq', 3, 3, 'الإنزيم بروتين، والارتفاع الكبير في درجة الحرارة (فوق درجة الحرارة القريبة من 37 °C التي يكون عندها الإنزيم أكثر نشاطًا) يسبب تغيّر خواصه الطبيعية بانفكاك طياته وتشوه شكله ثلاثي الأبعاد، فيفقد قدرته على العمل وتنخفض سرعة التفاعل حتى تقترب من الصفر.', '["الإنزيم عامل محفز لا يُستهلك في التفاعل، بل يعود إلى شكله الأصلي بعد انطلاق النواتج.","ارتفاع درجة الحرارة يزيد التصادمات ولا يقللها، ولهذا ترتفع السرعة في المنطقة A.","الإنزيم لا يتحول إلى مادة خاضعة؛ المادة الخاضعة هي المادة المتفاعلة التي يعمل عليها الإنزيم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-15T02:47:48.820Z"}'::jsonb),
('mcq', 4, 1, 'يؤدي الطبخ (ارتفاع درجة الحرارة) عادة إلى تغيّر الخواص الطبيعية للبروتينات في الأغذية؛ أي انفكاك طيات البروتين ولوالبه وتشوه تركيبه الطبيعي ثلاثي الأبعاد.', '["تغيّر الخواص الطبيعية لا يكوّن روابط ببتيدية جديدة، فهو يغيّر الشكل لا عدد الوحدات.","","التسخين لا يضيف أحماضًا أمينية إلى السلاسل.","هذا عكس ما يحدث؛ فالطيّ يكوّن الشكل الطبيعي، أما تغيّر الخواص الطبيعية فيفكّه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-15T02:47:48.820Z"}'::jsonb),
('mcq', 5, 3, 'إضافة الحمض تغيّر الرقم الهيدروجيني pH للمحلول، والتغير في pH من العوامل التي تفك طيات البروتين وتسبب تغيّر خواصه الطبيعية، فيتوقف الإنزيم عن العمل.', '["درجة الحرارة بقيت ثابتة عند 37 °C، فليست هي العامل في هذه الحالة.","إضافة الحمض لا تضيف أحماضًا أمينية إلى سلسلة الإنزيم.","نقص المادة الخاضعة يبطئ التفاعل لكنه لا يتلف تركيب الإنزيم، ولم يُذكر أي نقص في المادة الخاضعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.820Z"}'::jsonb),
('mcq', 6, 0, 'تغيّر الخواص الطبيعية الناتج عن التسخين انفكاك طيات البروتين ولوالبه وتشوه شكله ثلاثي الأبعاد، أما البابايين فإنزيم يحفّز تفكيك جزيئات البروتين إلى أحماض أمينية حرة؛ فالأول يغيّر الشكل والثاني يفكك السلسلة نفسها.', '["","التسخين يشوّه شكل البروتين ولا يحوّله إلى أحماض أمينية حرة؛ تفكيك السلسلة إلى أحماض أمينية هو عمل البابايين.","التسخين لا يكوّن روابط ببتيدية، والبابايين يفكك البروتين إلى أحماض أمينية حرة لا مجرد فك روابط هيدروجينية.","البابايين يفكك البروتين إلى أحماض أمينية، والتسخين لا يبني بروتينات بل يتلف شكلها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-15T02:47:48.820Z"}'::jsonb),
('mcq', 7, 2, 'الإنزيمات بروتينات، والارتفاع الكبير في درجة الحرارة داخل سيارة مغلقة صيفًا يسبب تغيّر خواصها الطبيعية بانفكاك طياتها وتشوه شكلها، فيفقد المحلول قدرته على التنظيف.', '["درجة حرارة الغرفة لا تسبب ارتفاعًا كبيرًا في الحرارة يتلف تركيب الإنزيم.","الاستعمال الصحيح لا يغيّر درجة الحرارة أو pH أو قوة الرابطة الأيونية، فلا يتلف الإنزيم.","","الحفظ في مكان مظلل يحمي الإنزيم من ارتفاع الحرارة، فيحافظ على فاعليته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-15T02:47:48.821Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تغيّر الخواص الطبيعية: العملية التي تشوّه تركيب البروتين الطبيعي ثلاثي الأبعاد وتمزقه أو تتلفه، بانفكاك طياته ولوالبه.
(1) يسبّبه؛ العامل: ارتفاع درجة الحرارة.
(2) يسبّبه؛ العامل: تغيّر الرقم الهيدروجيني pH.
(3) يسبّبه؛ العامل: تغيّر قوة الرابطة الأيونية.
(4) لا يسبّبه؛ فهذه خطوة طبيعية من عمل الإنزيم، يتغير فيها شكل الموقع النشط قليلًا (المطابقة التأثيرية) ثم يعود الإنزيم إلى شكله الأصلي بعد انطلاق النواتج.', '["تعريف تغيّر الخواص الطبيعية بتشوه التركيب ثلاثي الأبعاد","(1) يسبّبه — درجة الحرارة","(2) يسبّبه — pH","(3) يسبّبه — قوة الرابطة الأيونية","(4) لا يسبّبه مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الموقف (1)","marks":1},{"element":"الموقف (2)","marks":1},{"element":"الموقف (3)","marks":1},{"element":"الموقف (4) مع التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تعريف صحيح وتصنيف المواقف الأربعة مع العوامل والتعليل"},{"level":"3–4 درجات","description":"تعريف صحيح مع خطأ أو خطأين في المواقف أو العوامل"},{"level":"1–2 درجة","description":"تعريف فقط أو تصنيف موقف أو موقفين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف تغيّر الخواص الطبيعية بأنه تحلل البروتين إلى أحماض أمينية","عدّ المطابقة التأثيرية تغيرًا في الخواص الطبيعية","عدّ إذابة الملح عملية لا تؤثر في البروتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.821Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) عند نحو 37 °C (قمة المنحنى B)، وهي قريبة من درجة حرارة الجسم الطبيعية.
(b) ارتفاع درجة الحرارة يزيد الطاقة الحركية للجزيئات فتزداد التصادمات بين الإنزيم والمادة الخاضعة، فتزداد سرعة التفاعل.
(c) الإنزيم بروتين، والارتفاع الكبير في درجة الحرارة يفك طياته ولوالبه فيتشوه تركيبه ثلاثي الأبعاد ويتغير شكل موقعه النشط (تغيّر الخواص الطبيعية)، فلا ترتبط به المادة الخاضعة جيدًا وتنخفض السرعة.
(d) يُتوقع أن تبقى سرعة التفاعل منخفضة؛ لأن تركيب الإنزيم قد تشوّه، والبروتينات التي تغيرت خواصها الطبيعية تصبح غير فعالة بصورة عامة، فلا يكفي خفض الحرارة لإعادة نشاطه.', '["تحديد درجة الحرارة التي يكون عندها الإنزيم أكثر نشاطًا: نحو 37 °C","تفسير الزيادة بزيادة التصادمات","تفسير الانخفاض بتغيّر الخواص الطبيعية وتشوه الشكل","توقع بقاء النشاط منخفضًا مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":2},{"element":"(d)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة صحيحة ومعللة للأجزاء الأربعة"},{"level":"3–4 درجات","description":"تفسير صحيح لـ (c) مع نقص في جزء آخر"},{"level":"1–2 درجة","description":"تحديد درجة الحرارة المثلى أو تفسير جزئي فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير الانخفاض بنفاد الإنزيم أو استهلاكه","القول إن الإنزيم يستعيد نشاطه تلقائيًا بمجرد التبريد","تفسير الزيادة في A بتغير شكل الإنزيم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-15T02:47:48.821Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المتغير المستقل: الرقم الهيدروجيني pH للوسط (مثلًا محاليل بقيم pH مختلفة: حمضي، ومتعادل، وقاعدي).
المتغير التابع: ارتفاع الرغوة الناتجة (cm) بعد زمن محدد.
المتغيرات المضبوطة: درجة الحرارة (مثلًا 37 °C في جميع الأنابيب)، وكمية المعجون (2.0 mL)، وحجم H₂O₂ وتركيزه (5.0 mL من 3%)، وزمن التفاعل (5 min).
الخطوات: نضع كمية متساوية من المعجون في عدة أنابيب، ونضيف إلى كل أنبوب حجمًا متساويًا من محلول له pH مختلف وننتظر بضع دقائق، ثم نضيف H₂O₂ وننتظر الزمن نفسه ونقيس ارتفاع الرغوة، مع أنبوب ضابط عند pH متعادل.
النتيجة المتوقعة: يكون ارتفاع الرغوة أكبر في الأنبوب ذي pH المناسب للإنزيم، ويقل كثيرًا في الأوساط شديدة الحموضة أو القاعدية؛ لأن تغير pH يفك طيات الإنزيم (البروتين) ويشوّه شكله ثلاثي الأبعاد وموقعه النشط، فيقل تحفيزه للتفاعل.', '["تحديد المتغير المستقل pH","تحديد المتغير التابع (ارتفاع الرغوة)","ضبط متغيرين (الحرارة، كمية المعجون، حجم H₂O₂ وتركيزه، الزمن)","خطوات واضحة مع أنبوب ضابط","نتيجة متوقعة مفسرة بتغيّر الخواص الطبيعية"]'::jsonb, '[]'::jsonb, '[{"element":"المتغير المستقل","marks":1},{"element":"المتغير التابع","marks":1},{"element":"المتغيرات المضبوطة","marks":1},{"element":"الخطوات","marks":1},{"element":"النتيجة المتوقعة وتفسيرها","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصميم كامل ومتسق مع نتيجة مفسرة"},{"level":"3–4 درجات","description":"تصميم صحيح مع نقص في الضبط أو التفسير"},{"level":"1–2 درجة","description":"تحديد المتغيرات فقط دون خطوات أو تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تغيير درجة الحرارة مع pH في الوقت نفسه","عدّ ارتفاع الرغوة متغيرًا مستقلًا","عدم استعمال أنبوب ضابط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.821Z"}'::jsonb)
