('mcq', 3, 'يبيّن الشكل الآتي جزءًا من سلسلة عديد ببتيد واحدة، وتمثّل الخطوط الزرقاء المتقطعة فيه روابط هيدروجينية. أيّ العبارات الآتية تصف هذا التركيب وصفًا صحيحًا؟', null, '[{"src":"qimg/chem22/c6-l1b-sheet.svg","alt":"ثلاثة صفوف أفقية متوازية من الذرات تمثّل ثلاثة أجزاء من سلسلة عديد ببتيد واحدة. كل صف سلسلة متعرجة تتكرر فيها الذرات N ثم C ثم C: ترتبط بذرة N ذرة H، وترتبط بإحدى ذرتي الكربون مجموعة R، وترتبط بالأخرى ذرة O برابطة ثنائية. يسير الصف العلوي من اليسار إلى اليمين، ثم تنعطف السلسلة بقوس عند الطرف الأيمن لتكوّن الصف الأوسط الذي يسير من اليمين إلى اليسار، ثم تنعطف بقوس عند الطرف الأيسر لتكوّن الصف السفلي الذي يسير من اليسار إلى اليمين وينتهي بسهم. وبين كل صفين متجاورين خطوط زرقاء متقطعة رأسية تصل ذرة H المرتبطة بذرة N في أحد الصفين بذرة O المرتبطة بذرة C في الصف المجاور."}]'::jsonb, '["صحيفة مطوية: تنثني السلسلة إلى الأمام والخلف بصورة متكررة فتتجاور أجزاؤها","شكل حلزوني: تلتف السلسلة لفّات كسلك الهاتف فوق بعضها بعضًا","ثلاث سلاسل عديد ببتيد منفصلة ترتبط معًا بروابط ببتيدية","سلسلة تغيّرت خواصها الطبيعية فانفكت طياتها وانبسطت"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 213 — تركيب البروتين الثلاثي الأبعاد والشكل 6-5'),
('mcq', 4, 'يمثّل الشكل الآتي سلسلة عديد ببتيد مطوية في تركيب ثلاثي الأبعاد، وفيه مناطق مرقّمة. أيّ الأرقام يمثّل منطقة الصحيفة المطوية؟', null, '[{"src":"qimg/chem22/c6-l1b-regions.svg","alt":"سلسلة عديد ببتيد مطوية تُقرأ من اليسار إلى اليمين: تبدأ بجزء ملتف على شكل لفّات منتظمة حمراء تشبه النابض مرقّم (1)، ثم وصلة تصعد إلى ثلاثة أشرطة عريضة على شكل أسهم متوازية متجاورة: العلوي يتجه يمينًا، والأوسط يتجه يسارًا، والسفلي يتجه يمينًا، وتتصل نهاياتها بانعطافات قصيرة، وبين الأشرطة خطوط زرقاء متقطعة قصيرة، ومجموعة الأشرطة مرقّمة (2). ثم جزء من السلسلة يتعرج ويلتف بلا نمط منتظم مرقّم (3)، وأخيرًا جزء آخر ملتف على شكل لفّات منتظمة حمراء تشبه النابض مرقّم (1)."}]'::jsonb, '["المنطقة (1)","المنطقة (3)","المنطقة (2)","المنطقتان (1) و(3)"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 213 — تركيب البروتين الثلاثي الأبعاد والشكل 6-5'),
('mcq', 5, 'ما الذي يحدّد الشكل الثلاثي الأبعاد الذي تتخذه سلسلة عديد الببتيد؟', null, null, '["التفاعلات بين الأحماض الأمينية في السلسلة","عدد الروابط الببتيدية في السلسلة وحده","المادة الخاضعة التي ترتبط بالبروتين بعد تكوّنه","مجموعة الأمين الحرة في طرف السلسلة وحدها"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 213 — تركيب البروتين الثلاثي الأبعاد والشكل 6-5'),
('mcq', 6, 'متى تبدأ السلاسل الطويلة المكوّنة من الأحماض الأمينية بالطيّ مكوّنة أشكالًا ثلاثية الأبعاد؟', null, null, '["بعد اكتمال تكوينها وانتقالها إلى الدم","عند تسخينها إلى درجة حرارة مرتفعة","عند ارتباطها بالمادة الخاضعة لفعل الإنزيم","قبل أن يكتمل تكوينها"]'::jsonb, 'تذكر', 'استرجاع', 'سهل', 'الكتاب ص 213 — تركيب البروتين الثلاثي الأبعاد والشكل 6-5'),
('mcq', 7, 'أيّ العبارات الآتية عن التركيب ثلاثي الأبعاد للبروتينات صحيحة؟', null, null, '["يحتوي كل بروتين على شكل حلزوني واحد وصحيفة مطوية واحدة فقط","قد يحتوي البروتين على عدة لوالب وصحائف ولفّات، وقد لا يحتوي على أيٍّ منها","تثبّت الروابط الببتيدية وحدها الأحماض الأمينية في مواقعها في اللولب والصحيفة","تتخذ جميع البروتينات شكلًا كرويًا غير منتظم مثل الهيموجلوبين"]'::jsonb, 'تحليل', 'تقويم عبارات', 'صعب', 'الكتاب ص 213 — تركيب البروتين الثلاثي الأبعاد، وص 214–215'),
('essay', 1, 'صف الشكلين الشائعين لطيّ سلاسل عديد الببتيد: الشكل الحلزوني والصحيفة المطوية، مبيّنًا في كلٍّ منهما: كيف تنثني السلسلة، والتشبيه المناسب له، ونوع الروابط التي تثبّت الأحماض الأمينية في مواقعها.', null, null, null, 'فهم', 'وصف ومقارنة', 'متوسط', 'الكتاب ص 213 — الشكل 6-5، وص 231 تقويم الفصل س29'),
('essay', 2, 'ادرس الشكل الآتي الذي يمثّل سلسلة عديد ببتيد واحدة مطوية في تركيب ثلاثي الأبعاد، ثم أجب:
(a) سمِّ نوع التركيب في كلٍّ من المنطقتين (1) و(2).
(b) ماذا تمثّل الخطوط المتقطعة بين أشرطة المنطقة (2)؟ وما دورها؟
(c) فسّر كيف تتكوّن المنطقة (2) من سلسلة واحدة.
(d) المنطقة (3) لا تتبع نمطًا منتظمًا. هل يتعارض وجودها مع كون هذا التركيب بروتينًا طبيعيًا؟ وضّح.', null, '[{"src":"qimg/chem22/c6-l1b-regions.svg","alt":"سلسلة عديد ببتيد مطوية تُقرأ من اليسار إلى اليمين: تبدأ بجزء ملتف على شكل لفّات منتظمة حمراء تشبه النابض مرقّم (1)، ثم وصلة تصعد إلى ثلاثة أشرطة عريضة على شكل أسهم متوازية متجاورة: العلوي يتجه يمينًا، والأوسط يتجه يسارًا، والسفلي يتجه يمينًا، وتتصل نهاياتها بانعطافات قصيرة، وبين الأشرطة خطوط زرقاء متقطعة قصيرة، ومجموعة الأشرطة مرقّمة (2). ثم جزء من السلسلة يتعرج ويلتف بلا نمط منتظم مرقّم (3)، وأخيرًا جزء آخر ملتف على شكل لفّات منتظمة حمراء تشبه النابض مرقّم (1)."}]'::jsonb, null, 'تحليل', 'تفسير شكل', 'صعب', 'الكتاب ص 213 — تركيب البروتين الثلاثي الأبعاد والشكل 6-5'),
('essay', 3, 'سلسلتا عديد ببتيد (أ) و(ب) تتكوّن كلٌّ منهما من 60 حمضًا أمينيًا، لكن ترتيب الأحماض الأمينية في (أ) يختلف عنه في (ب). هل يُتوقع أن تنطوي السلسلتان في الشكل الثلاثي الأبعاد نفسه؟ فسّر إجابتك مبيّنًا ما الذي يحدد الشكل الثلاثي الأبعاد، ثم بيّن أثر ذلك في وظيفة كلٍّ منهما.', null, null, null, 'تحليل', 'استنتاج وتفسير', 'صعب', 'الكتاب ص 211 و213 — السلاسل الجانبية وتركيب البروتين الثلاثي الأبعاد')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C6-L1-O07') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'تلتف السلسلة في الشكل لفّات متتالية تشبه لفّات سلك الهاتف، وهذا هو الشكل الحلزوني الذي تثبّت فيه الروابط الهيدروجينية الأحماض الأمينية في مواقعها.', '["في الصحيفة المطوية تنثني السلسلة إلى الأمام والخلف فتتجاور أجزاء مستقيمة متعرجة، لا لفّات لولبية.","الشكل الكروي وصف للشكل الكلي لبعض البروتينات (مثل الهيموجلوبين)، لا لنمط طيّ جزء من السلسلة.","الشكل الليفي وصف للشكل الكلي لبروتينات طويلة مثل الكيراتين الذي يتكوّن منه الشعر، لا لنمط اللفّات هذا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-15T02:47:48.822Z"}'::jsonb),
('mcq', 2, 1, 'تتكوّن بعض أجزاء عديد الببتيد في صورة شكل حلزوني يشبه لفّات سلك الهاتف.', '["الطيّات المتكررة إلى الأمام والخلف تصف الصحيفة المطوية لا الشكل الحلزوني.","","قطع الألغاز تشبيه لتطابق شكل المادة الخاضعة مع الموقع النشط للإنزيم.","الخيط المستقيم يخلو من أي طي، والشكل الحلزوني التفاف منتظم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-15T02:47:48.822Z"}'::jsonb),
('mcq', 3, 0, 'تنثني أجزاء السلسلة في الشكل إلى الأمام والخلف بصورة متكررة (تتصل الصفوف بانعطافات)، فتتجاور أجزاؤها وترتبط بروابط هيدروجينية بين N–H و C=O، وهذه هي الصحيفة المطوية.', '["","لا توجد لفّات لولبية في الشكل؛ الأجزاء متعرجة ومتجاورة جنبًا إلى جنب.","الصفوف الثلاثة تتصل بانعطافات فهي سلسلة واحدة، والخطوط المتقطعة بينها روابط هيدروجينية لا ببتيدية.","السلسلة هنا مطوية بنمط منتظم تثبته الروابط الهيدروجينية، وليست منبسطة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-15T02:47:48.822Z"}'::jsonb),
('mcq', 4, 2, 'في المنطقة (2) تنثني السلسلة إلى الأمام والخلف فتتجاور أجزاؤها جنبًا إلى جنب (الأشرطة المتوازية) وترتبط بروابط هيدروجينية، وهذه هي الصحيفة المطوية.', '["المنطقة (1) لفّات منتظمة تشبه سلك الهاتف، أي الشكل الحلزوني.","المنطقة (3) جزء يلتف بلا نمط منتظم، فليس صحيفة مطوية.","","المنطقة (1) حلزونية والمنطقة (3) لفّة غير منتظمة، ولا تمثّل أيٌّ منهما صحيفة مطوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-15T02:47:48.822Z"}'::jsonb),
('mcq', 5, 0, 'يتحدد الشكل الثلاثي الأبعاد لعديد الببتيد عن طريق التفاعلات بين الأحماض الأمينية المكوّنة له.', '["","عدد الروابط الببتيدية يحدد طول السلسلة لا طريقة طيّها.","الشكل يتكوّن قبل ارتباط أي مادة خاضعة، والمادة الخاضعة تغيّر شكل الموقع النشط قليلًا فقط.","طرف السلسلة لا يحدد وحده طيّها؛ الطيّ نتيجة تفاعلات الأحماض الأمينية على طول السلسلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-15T02:47:48.822Z"}'::jsonb),
('mcq', 6, 3, 'تبدأ السلاسل الطويلة المكوّنة من الأحماض الأمينية بالطيّ مكوّنة أشكالًا ثلاثية الأبعاد قبل أن يكتمل تكوينها.', '["الطيّ يبدأ في أثناء بناء السلسلة لا بعد اكتمالها وانتقالها.","التسخين الشديد يفك الطيات (تغيّر الخواص الطبيعية) ولا يكوّنها.","الطيّ يسبق ارتباط المادة الخاضعة؛ فالموقع النشط نفسه جزء من الشكل المطوي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-15T02:47:48.822Z"}'::jsonb),
('mcq', 7, 1, 'يمكن أن يحتوي بروتين معين على عدة لوالب وصحائف ولفّات، وقد لا يحتوي على أيٍّ منها؛ فالشكل الكلي لبعض البروتينات كروي غير منتظم ولبعضها شكل ليفي طويل.', '["لا يوجد عدد ثابت؛ فقد يحتوي البروتين على عدة لوالب وصحائف أو لا يحتوي على أيٍّ منها.","","الروابط الهيدروجينية هي التي تثبّت الأحماض الأمينية في مواقعها في اللولب والصحيفة، أما الروابط الببتيدية فتربط الأحماض الأمينية في السلسلة.","بعض البروتينات ليفية طويلة مثل الكيراتين الذي يتكوّن منه شعر الإنسان، فليست جميعها كروية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-15T02:47:48.823Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الشكل الحلزوني: يلتف جزء من سلسلة عديد الببتيد التفافًا منتظمًا في صورة لولب يشبه لفّات سلك الهاتف، وتثبّت الروابط الهيدروجينية بين اللفّات المتتالية الأحماضَ الأمينية في مواقعها.
الصحيفة المطوية: تنثني أجزاء من السلسلة إلى الأمام والخلف بصورة متكررة فتتجاور جنبًا إلى جنب مكوّنة هيئة صحيفة مطوية عدة طيات، وتثبّت الروابط الهيدروجينية بين الأجزاء المتجاورة الأحماضَ الأمينية في مواقعها.', '["الحلزوني: التفاف لولبي منتظم","الحلزوني: يشبه لفّات سلك الهاتف","الصحيفة: انثناء متكرر إلى الأمام والخلف وتجاور الأجزاء","الصحيفة: هيئة صحيفة مطوية عدة طيات","الروابط الهيدروجينية تثبّت الأحماض الأمينية في الشكلين"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الشكل الحلزوني","marks":1},{"element":"تشبيه الشكل الحلزوني","marks":1},{"element":"وصف الصحيفة المطوية","marks":1},{"element":"تشبيه/هيئة الصحيفة المطوية","marks":1},{"element":"الروابط الهيدروجينية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وصف كامل للشكلين مع التشبيه ونوع الروابط"},{"level":"3–4 درجات","description":"وصف صحيح للشكلين مع نقص في التشبيه أو الروابط"},{"level":"1–2 درجة","description":"وصف شكل واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية الروابط المثبّتة روابط ببتيدية","الخلط بين وصف الشكلين","عدّ الصحيفة المطوية سلاسل منفصلة لا أجزاء من سلسلة واحدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-15T02:47:48.823Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) المنطقة (1): الشكل الحلزوني؛ المنطقة (2): الصحيفة المطوية.
(b) روابط هيدروجينية بين الأجزاء المتجاورة من السلسلة، تثبّت الأحماض الأمينية في مواقع معينة فتحافظ على الطيّ.
(c) تنثني السلسلة إلى الأمام ثم إلى الخلف بصورة متكررة (تنثني على نفسها وتغيّر اتجاهها)، فتتجاور أجزاؤها جنبًا إلى جنب مكوّنة صحيفة مطوية عدة طيات.
(d) لا يتعارض؛ فيمكن أن يحتوي البروتين على عدة لوالب وصحائف ولفّات، وقد لا يحتوي على أيٍّ منها، وتسهم التفاعلات بين الأحماض الأمينية في تحديد شكله الثلاثي الأبعاد الخاص به.', '["(1) حلزوني و(2) صحيفة مطوية","الخطوط روابط هيدروجينية تثبّت المواقع","انثناء السلسلة إلى الأمام والخلف وتغيير اتجاهها","وجود لفّات غير منتظمة أمر طبيعي في البروتينات"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":1},{"element":"(d)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة صحيحة للأجزاء الأربعة"},{"level":"2–3 درجات","description":"إجابة صحيحة لجزأين أو ثلاثة"},{"level":"1 درجة","description":"تسمية المنطقتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ أشرطة المنطقة (2) سلاسل منفصلة","تسمية الخطوط المتقطعة روابط ببتيدية","الحكم بأن المنطقة (3) دليل على تغيّر الخواص الطبيعية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-15T02:47:48.823Z"}'::jsonb),
('essay', 3, null::int, null, null, 'لا يُتوقع ذلك. يتحدد الشكل الثلاثي الأبعاد لعديد الببتيد عن طريق التفاعلات بين الأحماض الأمينية في السلسلة، والسلاسل الجانبية المختلفة تعطي الأحماض الأمينية خواص كيميائية وفيزيائية مختلفة. فإذا اختلف ترتيب الأحماض الأمينية اختلفت التفاعلات بينها، فتختلف أماكن تكوّن اللوالب والصحائف واللفّات، ويختلف الشكل الكلي للسلسلة. ولأن شكل البروتين مهم لعمله، فإن السلسلتين يُتوقع أن تؤديا وظيفتين مختلفتين، أو أن تؤدي إحداهما وظيفة لا تؤديها الأخرى.', '["الحكم: لا يُتوقع الشكل نفسه","الشكل يحدده التفاعل بين الأحماض الأمينية (سلاسلها الجانبية)","اختلاف الترتيب يغيّر مواضع اللوالب والصحائف والشكل الكلي","الشكل يحدد الوظيفة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"ما يحدد الشكل","marks":1},{"element":"أثر اختلاف الترتيب في الطيّ","marks":1},{"element":"أثر الشكل في الوظيفة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تفسير كامل لما يحدد الشكل وأثره في الوظيفة"},{"level":"2–3 درجات","description":"حكم صحيح مع تفسير ناقص"},{"level":"1 درجة","description":"حكم صحيح دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاعتقاد أن عدد الأحماض الأمينية وحده يحدد الشكل","إغفال دور التفاعلات بين الأحماض الأمينية","إغفال العلاقة بين الشكل والوظيفة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-15T02:47:48.823Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C6-L1-O07') and x.type = v.type and x.number = v.number
