insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C6-L1-O08'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'إذا افترضنا أن كل موقع في سلسلة ببتيد يمكن أن يشغله أيّ حمض من الأحماض الأمينية العشرين، فما العلاقة التي تعطي عدد التتابعات المحتملة لببتيد يحتوي على n من الأحماض الأمينية؟', null, null, '["20ⁿ","n²⁰","20 × n","20 + n"]'::jsonb, 'فهم', 'علاقة رياضية', 'سهل', 'الكتاب ص 212 — عدد التتابعات المحتملة (20ⁿ)'),
('mcq', 2, 'كم تتابعًا محتملًا يوجد لثنائي ببتيد، إذا كان كل موقع فيه يمكن أن يشغله أيّ حمض من الأحماض الأمينية العشرين؟', null, null, '["40 تتابعًا","20 تتابعًا","400 تتابع","تتابعان اثنان"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 212 — عدد التتابعات المحتملة (20ⁿ)'),
('mcq', 3, 'كم تتابعًا محتملًا يوجد لببتيد يحتوي على عدد الأحماض الأمينية نفسه الموجود في الببتيد المبيَّن في الشكل الآتي، إذا كان كل موقع يمكن أن يشغله أيّ من الأحماض الأمينية العشرين؟', null, '[{"src":"qimg/chem22/c6-l1b-pentapeptide.svg","alt":"صيغة بنائية لسلسلة ببتيد تُقرأ من اليسار إلى اليمين: تبدأ بمجموعة H₂N مرتبطة بذرة كربون تحمل ذرة H والسلسلة الجانبية CH(CH₃)₂، ثم C=O، ثم N–H، ثم ذرة كربون تحمل ذرتي H، ثم C=O، ثم N–H، ثم ذرة كربون تحمل H والسلسلة الجانبية CH₂OH، ثم C=O، ثم N–H، ثم ذرة كربون تحمل H والسلسلة الجانبية CH₃، ثم C=O، ثم N–H، ثم ذرة كربون تحمل H والسلسلة الجانبية CH₂SH، ثم C(=O)–OH في نهاية السلسلة."}]'::jsonb, '["1.6 × 10⁵ تتابع","100 تتابع","9.5 × 10¹³ تتابع","3.2 × 10⁶ تتابع"]'::jsonb, 'تطبيق', 'حساب من شكل', 'متوسط', 'الكتاب ص 212 — عدد التتابعات المحتملة، وص 231 تقويم الفصل س39'),
('mcq', 4, 'يمثّل الشكل الآتي سلسلة ببتيد، وتمثّل كل دائرة موقعًا يمكن أن يشغله أيّ من الأحماض الأمينية العشرين. كم تتابعًا محتملًا لهذه السلسلة؟', null, '[{"src":"qimg/chem22/c6-l1b-beads6.svg","alt":"سلسلة أفقية من ست دوائر متصلة بخطوط، في كل دائرة علامة استفهام، ويتصل بطرف السلسلة الأيسر H₂N وبطرفها الأيمن COOH."}]'::jsonb, '["120 تتابعًا","6.4 × 10⁷ تتابع","3.2 × 10⁶ تتابع","3.7 × 10¹⁵ تتابع"]'::jsonb, 'تطبيق', 'حساب من شكل', 'سهل', 'الكتاب ص 212 — عدد التتابعات المحتملة (20ⁿ)'),
('mcq', 5, 'ببتيد عدد تتابعاته المحتملة 1.28 × 10⁹ تتابع، بافتراض أن كل موقع فيه يمكن أن يشغله أيّ من الأحماض الأمينية العشرين. كم حمضًا أمينيًا يحتوي عليه هذا الببتيد؟', null, null, '["9","6","7","8"]'::jsonb, 'تحليل', 'حساب عكسي', 'صعب', 'الكتاب ص 212 — عدد التتابعات المحتملة (20ⁿ)'),
('mcq', 6, 'عند إضافة حمض أميني واحد إلى ببتيد (مع افتراض أن كل موقع يمكن أن يشغله أيّ من الأحماض الأمينية العشرين)، كيف يتغير عدد التتابعات المحتملة؟', null, null, '["يزداد بمقدار 20 تتابعًا فقط","يُضرب في 20 فيصبح 20 مثلًا","يُضرب في 2 فيصبح مثلَين فقط","يبقى ثابتًا لثبات عدد الأنواع"]'::jsonb, 'تحليل', 'استدلال رياضي', 'متوسط', 'الكتاب ص 212 — عدد التتابعات المحتملة (20ⁿ)'),
('mcq', 7, 'إذا كان المتاح لبناء ببتيد ثلاثي 4 أنواع فقط من الأحماض الأمينية، ويمكن أن يشغل كلَّ موقع أيٌّ منها مع إمكان تكرار النوع نفسه، فكم تتابعًا محتملًا لهذا الببتيد؟', null, null, '["12 تتابعًا","81 تتابعًا","8000 تتابع","64 تتابعًا"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 212 — عدد التتابعات المحتملة (20ⁿ)'),
('essay', 1, 'بافتراض أن كل موقع في سلسلة الببتيد يمكن أن يشغله أيّ من الأحماض الأمينية العشرين:
(a) احسب عدد التتابعات المحتملة لببتيد يتكوّن من 8 أحماض أمينية.
(b) احسب عدد التتابعات المحتملة لعديد ببتيد يتكوّن من 10 أحماض أمينية.
(c) كم مرة يزيد عدد التتابعات في (b) على عدده في (a)؟ فسّر النتيجة.', null, null, null, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 212 — عدد التتابعات المحتملة، وص 231 تقويم الفصل س38'),
('essay', 2, 'يحتوي أصغر البروتينات على نحو 50 حمضًا أمينيًا، وتصنع خلايا الإنسان ما بين 80,000 و100,000 بروتين مختلف.
(a) احسب عدد التتابعات المحتملة لسلسلة من 50 حمضًا أمينيًا (افترض أن كل موقع يمكن أن يشغله أيّ من الأحماض الأمينية العشرين)، علمًا بأن 2⁵⁰ ≈ 1.13 × 10¹⁵.
(b) احسب النسبة بين أكبر عدد من البروتينات تصنعه خلايا الإنسان وعدد التتابعات في (a).
(c) ماذا تستنتج من النتيجة؟', null, null, null, 'تحليل', 'حساب واستنتاج', 'صعب', 'الكتاب ص 212 — عدد التتابعات المحتملة (20⁵⁰ وبروتينات الإنسان)'),
('essay', 3, 'ثلاثة أحماض أمينية محددة هي: الجلايسين (Gly) والسيرين (Ser) والفالين (Val).
(a) اكتب جميع تتابعات الببتيد الثلاثي التي يمكن تكوينها إذا استُعمل كل حمض منها مرة واحدة فقط، بالرموز الثلاثية (مثل Gly–Ser–Val)، وكم عددها؟
(b) هل الببتيد Gly–Ser–Val هو المركب Val–Ser–Gly نفسه؟ وضّح.
(c) لماذا يكون عدد التتابعات المحتملة لببتيد ثلاثي أكبر كثيرًا (20³ = 8000) عندما يمكن أن يشغل كل موقع أيٌّ من الأحماض الأمينية العشرين؟', null, null, null, 'تحليل', 'عدّ وتفسير', 'متوسط', 'الكتاب ص 212 — الشكل 6-4 وعدد التتابعات المحتملة، وص 231 تقويم الفصل س38')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
