insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'لكل موقع 20 احتمالًا، ولأن المواقع n مستقلة تُضرب الاحتمالات: 20 × 20 × … (n مرة) = 20ⁿ.', '["","هذا قلب للأس والأساس؛ الأساس هو عدد أنواع الأحماض الأمينية (20) والأس هو عدد المواقع n.","الضرب في n يفترض أن الاحتمالات تُجمع، لكنها تُضرب لكل موقع.","الجمع لا يعبّر عن تضاعف الاحتمالات مع كل موقع جديد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-15T02:47:48.824Z"}'::jsonb),
('mcq', 2, 2, 'ثنائي الببتيد يتكوّن من حمضين أمينيين، فعدد التتابعات = 20² = 400 تتابع.', '["40 ناتج 20 × 2، أي ضرب عدد الأنواع في عدد المواقع بدل رفعه إلى أس.","20 هو عدد الاحتمالات لموقع واحد فقط.","","تتابعان هما عدد ترتيبات حمضين محددين (مثل Gly–Phe و Phe–Gly)، لا عدد التتابعات من 20 حمضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-15T02:47:48.824Z"}'::jsonb),
('mcq', 3, 3, 'في الشكل خمس ذرات كربون مركزية، أي 5 أحماض أمينية (مرتبطة بأربع روابط ببتيدية). عدد التتابعات = 20⁵ = 3,200,000 = 3.2 × 10⁶ تتابع.', '["1.6 × 10⁵ = 20⁴، وهو ناتج عدّ الروابط الببتيدية (4) بدل الأحماض الأمينية (5).","100 = 20 × 5، أي ضرب بدل الرفع إلى أس.","9.5 × 10¹³ = 5²⁰، أي قلب الأساس والأس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-15T02:47:48.824Z"}'::jsonb),
('mcq', 4, 1, 'في السلسلة 6 مواقع، فعدد التتابعات = 20⁶ = 64,000,000 = 6.4 × 10⁷ تتابع.', '["120 = 20 × 6، أي ضرب بدل الرفع إلى أس.","","3.2 × 10⁶ = 20⁵، وهو ناتج عدّ الخطوط الواصلة بين الدوائر (5) بدل المواقع (6).","3.7 × 10¹⁵ = 6²⁰، أي قلب الأساس والأس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-15T02:47:48.824Z"}'::jsonb),
('mcq', 5, 2, 'نبحث عن n التي تحقق 20ⁿ = 1.28 × 10⁹: 20⁶ = 6.4 × 10⁷، و20⁷ = 1.28 × 10⁹، إذن n = 7 أحماض أمينية.', '["9 هو أس العدد 10 في الناتج، وليس عدد المرات التي ضُرب فيها 20 في نفسه.","20⁶ = 6.4 × 10⁷ فقط، وهو أصغر من العدد المعطى بعشرين مرة؛ وقد ينتج من الخلط بين عدد الروابط الببتيدية (6) وعدد الأحماض.","","20⁸ = 2.56 × 10¹⁰، وهو أكبر من العدد المعطى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-15T02:47:48.824Z"}'::jsonb),
('mcq', 6, 1, 'عدد التتابعات لـ n حمضًا 20ⁿ، وللسلسلة بعد الإضافة 20ⁿ⁺¹ = 20 × 20ⁿ، أي يُضرب عدد التتابعات في 20.', '["الموقع الجديد يضرب العدد في 20 ولا يضيف إليه 20 فقط.","","الضرب في 2 يناسب موقعًا له احتمالان فقط، والموقع الجديد له 20 احتمالًا.","عدد الأنواع ثابت، لكن زيادة المواقع ترفع الأس فيزداد عدد التتابعات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-15T02:47:48.824Z"}'::jsonb),
('mcq', 7, 3, 'لكل موقع من المواقع الثلاثة 4 احتمالات، فعدد التتابعات = 4³ = 64 تتابعًا.', '["12 = 4 × 3، أي ضرب بدل الرفع إلى أس.","81 = 3⁴، أي قلب الأساس (عدد الأنواع) والأس (عدد المواقع).","8000 = 20³، وهو يفترض توافر الأحماض الأمينية العشرين لا 4 أنواع فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-15T02:47:48.825Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) 20⁸ = 25,600,000,000 = 2.56 × 10¹⁰ تتابع.
(b) 20¹⁰ = 1.024 × 10¹³ تتابع.
(c) 20¹⁰ ÷ 20⁸ = 20² = 400 مرة؛ لأن كل حمض أميني يُضاف يضرب عدد التتابعات في 20، وأُضيف حمضان أمينيان.', '["20⁸ = 2.56 × 10¹⁰","20¹⁰ = 1.024 × 10¹³","النسبة 400","التفسير: كل حمض مضاف يضرب العدد في 20"]'::jsonb, '["عدد التتابعات = 20ⁿ","(a) n = 8: 20⁸ = 2.56 × 10¹⁰","(b) n = 10: 20¹⁰ = 1.024 × 10¹³","(c) 1.024 × 10¹³ ÷ 2.56 × 10¹⁰ = 400 = 20²"]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c) الحساب","marks":1},{"element":"(c) التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابات الثلاثة صحيحة مع التفسير"},{"level":"2–3 درجات","description":"حسابان صحيحان أو ثلاثة دون تفسير"},{"level":"1 درجة","description":"كتابة العلاقة 20ⁿ أو حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب 8²⁰ بدل 20⁸","حساب النسبة 2 (فرق عدد الأحماض) بدل 400","الخطأ في كتابة الصيغة العلمية للأعداد الكبيرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-15T02:47:48.825Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) 20⁵⁰ = (2 × 10)⁵⁰ = 2⁵⁰ × 10⁵⁰ ≈ 1.13 × 10¹⁵ × 10⁵⁰ = 1.13 × 10⁶⁵ تتابع (أكثر من 1 × 10⁶⁵).
(b) 100,000 ÷ (1.13 × 10⁶⁵) = 1 × 10⁵ ÷ 1.13 × 10⁶⁵ ≈ 8.9 × 10⁻⁶¹.
(c) البروتينات التي تصنعها خلايا الإنسان جزء صغير جدًا من مجموع البروتينات المحتملة؛ فوجود 20 حمضًا أمينيًا فقط لا يحدّ من تنوع البروتينات، لأن عدد التتابعات الممكنة هائل.', '["20⁵⁰ ≈ 1.13 × 10⁶⁵","النسبة ≈ 8.9 × 10⁻⁶¹","الاستنتاج: جزء صغير جدًا من الاحتمالات"]'::jsonb, '["عدد التتابعات = 20ⁿ = 20⁵⁰","20⁵⁰ = 2⁵⁰ × 10⁵⁰ = 1.13 × 10¹⁵ × 10⁵⁰ = 1.13 × 10⁶⁵","النسبة = 1 × 10⁵ ÷ 1.13 × 10⁶⁵ = 8.9 × 10⁻⁶¹"]'::jsonb, '[{"element":"(a) الحساب","marks":2},{"element":"(b) النسبة","marks":1},{"element":"(c) الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابان صحيحان مع استنتاج سليم"},{"level":"2–3 درجات","description":"حساب (a) صحيح مع خطأ في النسبة أو الاستنتاج"},{"level":"1 درجة","description":"كتابة 20⁵⁰ دون إكمال الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب 50²⁰ بدل 20⁵⁰","جمع الأسس خطأً عند تحويل (2 × 10)⁵⁰","قسمة عدد التتابعات على عدد البروتينات بدل العكس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-15T02:47:48.825Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) Gly–Ser–Val، Gly–Val–Ser، Ser–Gly–Val، Ser–Val–Gly، Val–Gly–Ser، Val–Ser–Gly؛ وعددها 6 تتابعات (3 × 2 × 1).
(b) لا؛ فلكل ببتيد طرف فيه مجموعة أمين حرة وطرف فيه مجموعة كربوكسيل حرة. في Gly–Ser–Val يحمل الجلايسين مجموعة الأمين الحرة والفالين مجموعة الكربوكسيل الحرة، وفي Val–Ser–Gly العكس، فهما مركبان مختلفان.
(c) لأن كل موقع له 20 احتمالًا لا احتمالات محدودة، ويمكن تكرار الحمض الأميني نفسه في أكثر من موقع، فيكون العدد 20 × 20 × 20 = 8000.', '["كتابة التتابعات الستة","العدد 6","التمييز بين الطرفين الأميني والكربوكسيلي","تفسير 20³ بعشرين احتمالًا لكل موقع مع التكرار"]'::jsonb, '["الموقع الأول: 3 اختيارات، والثاني: 2، والثالث: 1 → 3 × 2 × 1 = 6","مع الأحماض العشرين والتكرار: 20 × 20 × 20 = 20³ = 8000"]'::jsonb, '[{"element":"(a) التتابعات وعددها","marks":2},{"element":"(b)","marks":1},{"element":"(c)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التتابعات الستة صحيحة مع تفسير (b) و(c)"},{"level":"2–3 درجات","description":"التتابعات صحيحة مع نقص في أحد التفسيرين"},{"level":"1 درجة","description":"عدد التتابعات فقط أو بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ Gly–Ser–Val و Val–Ser–Gly مركبًا واحدًا","نسيان بعض التتابعات أو تكرارها","تطبيق 20³ على ثلاثة أحماض محددة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-15T02:47:48.825Z"}'::jsonb)
