from (values
('mcq', 1, 'تُصنَّف السلاسل الجانبية للأحماض الأمينية بحسب المجموعة الوظيفية فيها: السلاسل التي تشبه الألكانات غير قطبية، والتي تحتوي على مجموعة هيدروكسيل −OH أو مجموعة أميد −CONH₂ قطبية، والتي تحتوي على مجموعة كربوكسيل −COOH حمضية، والتي تحتوي على مجموعة أمين −NH₂ قاعدية. إلى أيّ فئة تُصنَّف السلسلة الجانبية للحمض الأميني المبيَّن في الشكل الآتي؟', null, '[{"src":"qimg/chem22/c6-l1b-glutamine.svg","alt":"صيغة بنائية لحمض أميني: ذرة كربون مركزية ترتبط من اليسار بمجموعة H₂N، ومن اليمين بذرة كربون ترتبط برابطة ثنائية بذرة O وبرابطة أحادية بمجموعة OH، ومن الأسفل بذرة H، ومن الأعلى بسلسلة جانبية تتكوّن من CH₂ ثم CH₂ ثم ذرة C ترتبط برابطة ثنائية بذرة O وبرابطة أحادية بمجموعة NH₂."}]'::jsonb, '["غير قطبية؛ لأنها تتكوّن من مجموعات CH₂ فقط","حمضية؛ لأنها تنتهي بمجموعة كربوكسيل","قطبية؛ لأنها تنتهي بمجموعة أميد","قاعدية؛ لأنها تنتهي بمجموعة أمين"]'::jsonb, 'تحليل', 'تصنيف من شكل', 'متوسط', 'الكتاب ص 211 — الجدول 6-1 (الجلوتامين)، وص 231 تقويم الفصل س30'),
('mcq', 2, 'أيّ الأحماض الأمينية الآتية تحتوي سلسلته الجانبية على الكبريت؟', null, null, '["السيستين","السيرين","الفالين","الجلوتامين"]'::jsonb, 'فهم', 'تصنيف', 'سهل', 'الكتاب ص 211 — الجدول 6-1 والسلاسل الجانبية'),
('mcq', 3, 'أيّ الأحماض الأمينية المرقّمة في الشكل الآتي سلسلته الجانبية قاعدية؟', null, '[{"src":"qimg/chem22/c6-l1b-aa-four.svg","alt":"أربعة أحماض أمينية مرقّمة من اليسار إلى اليمين، لكلٍّ منها التركيب العام نفسه: ذرة كربون مركزية ترتبط بمجموعة H₂N وبمجموعة كربوكسيل (C=O و OH) وبذرة H، وتختلف في السلسلة الجانبية المرتبطة بالكربون المركزي من الأعلى: (1) CH₃. (2) CH₂ ثم SH. (3) CH₂ ثم CH₂ ثم ذرة C ترتبط برابطة ثنائية بذرة O وبرابطة أحادية بمجموعة NH₂. (4) أربع مجموعات CH₂ متتالية ثم NH₂."}]'::jsonb, '["الحمض (1)","الحمض (2)","الحمض (3)","الحمض (4)"]'::jsonb, 'تحليل', 'تصنيف من شكل', 'سهل', 'الكتاب ص 211 — الجدول 6-1 والسلاسل الجانبية'),
('mcq', 4, 'يبيّن الجدول الآتي السلاسل الجانبية لأربعة أحماض أمينية W وX وY وZ. أيّ زوج منها سلسلتاه الجانبيتان غير قطبيتين؟', '{"headers":["الحمض الأميني","السلسلة الجانبية"],"rows":[["W","−CH(CH₃)₂"],["X","−CH₂OH"],["Y","−CH₃"],["Z","−CH₂COOH"]]}'::jsonb, null, '["X و Z","W و Y","W و X","Y و Z"]'::jsonb, 'تحليل', 'تصنيف من جدول', 'متوسط', 'الكتاب ص 211 — الجدول 6-1، وص 231 تقويم الفصل س33'),
('mcq', 5, 'السلسلة الجانبية لحمض الجلوتاميك −CH₂CH₂COOH، والسلسلة الجانبية للايسين −CH₂CH₂CH₂CH₂NH₂. أيّ مما يأتي يصنّف السلسلتين تصنيفًا صحيحًا؟', null, null, '["كلتاهما حمضية؛ لأن كلًّا منهما جزء من حمض أميني","سلسلة حمض الجلوتاميك قاعدية، وسلسلة اللايسين حمضية","كلتاهما غير قطبية؛ لأن كلًّا منهما تبدأ بمجموعات CH₂","سلسلة حمض الجلوتاميك حمضية، وسلسلة اللايسين قاعدية"]'::jsonb, 'تحليل', 'مقارنة وتصنيف', 'صعب', 'الكتاب ص 211 — الجدول 6-1 (حمض الجلوتاميك واللايسين)، وص 215 التقويم 6-1 س6c'),
('mcq', 6, 'أيّ الأوصاف الآتية ينطبق على السلسلة الجانبية للحمض الأميني المبيَّن في الشكل الآتي؟', null, '[{"src":"qimg/chem22/c6-l1b-tyrosine.svg","alt":"صيغة بنائية لحمض أميني: ذرة كربون مركزية ترتبط من اليسار بمجموعة H₂N، ومن اليمين بذرة كربون ترتبط برابطة ثنائية بذرة O وبرابطة أحادية بمجموعة OH، ومن الأسفل بذرة H، ومن الأعلى بسلسلة جانبية تتكوّن من CH₂ مرتبطة بحلقة بنزين سداسية فيها ثلاث روابط ثنائية متبادلة، وترتبط مجموعة OH برأس الحلقة المقابل لموضع ارتباط CH₂."}]'::jsonb, '["أليفاتية غير قطبية تشبه الألكانات","حمضية لاحتوائها على مجموعة كربوكسيل","أروماتية، وفيها مجموعة هيدروكسيل قطبية","قاعدية لاحتوائها على مجموعة أمين"]'::jsonb, 'تحليل', 'تصنيف من شكل', 'متوسط', 'الكتاب ص 211 — السلاسل الجانبية (الأروماتية والقطبية)، وص 232 الشكل 6-25'),
('mcq', 7, 'أيّ الأحماض الأمينية الآتية سلسلته الجانبية أروماتية؟', null, null, '["فينيل الألنين","اللايسين","السيرين","الفالين"]'::jsonb, 'فهم', 'تصنيف', 'سهل', 'الكتاب ص 211 — الجدول 6-1، وص 231 تقويم الفصل س32'),
('essay', 1, 'من الأحماض الأمينية الآتية وسلاسلها الجانبية:
اللايسين −(CH₂)₄NH₂، والسيستين −CH₂SH، وفينيل الألنين −CH₂−C₆H₅ (حلقة بنزين)، والفالين −CH(CH₃)₂، وحمض الجلوتاميك −CH₂CH₂COOH، والسيرين −CH₂OH.
اختر حمضًا أمينيًا لكل طرف من الأزواج الآتية، مع تعليل اختيارك بالمجموعة الوظيفية في السلسلة الجانبية:
(a) غير قطبي مقابل قطبي.
(b) أروماتي مقابل أليفاتي.
(c) حمضي مقابل قاعدي.
(d) سمِّ الحمض الأميني الذي تحتوي سلسلته الجانبية على الكبريت.', null, null, null, 'تحليل', 'تصنيف مع تعليل', 'متوسط', 'الكتاب ص 215 — التقويم 6-1 س6، وص 211 الجدول 6-1'),
('essay', 2, 'يبيّن الشكل الآتي التركيب البنائي للتريبتوفان.
(a) إلى أيّ المركبات العضوية الحيوية ينتمي التريبتوفان؟ وضّح إجابتك بالإشارة إلى المجموعات المرتبطة بذرة الكربون المركزية.
(b) صنّف سلسلته الجانبية، معلّلًا تصنيفك.
(c) ما الصفة المشتركة بين السلسلة الجانبية للتريبتوفان والسلسلة الجانبية لفينيل الألنين (−CH₂−C₆H₅) التي تجعلهما في الفئة نفسها؟ وبماذا تختلف سلسلة التريبتوفان؟', null, '[{"src":"qimg/chem22/c6-l1b-tryptophan.svg","alt":"صيغة بنائية لحمض أميني: ذرة كربون مركزية ترتبط من اليسار بمجموعة H₂N، ومن اليمين بذرة كربون ترتبط برابطة ثنائية بذرة O وبرابطة أحادية بمجموعة OH، ومن الأسفل بذرة H، ومن الأعلى بسلسلة جانبية تتكوّن من CH₂ مرتبطة بذرة كربون في حلقة خماسية فيها رابطة ثنائية بين ذرتي كربون ومجموعة NH، والحلقة الخماسية ملتحمة (تشترك في ضلع) مع حلقة بنزين سداسية فيها ثلاث روابط ثنائية متبادلة."}]'::jsonb, null, 'تحليل', 'تحليل تركيب', 'صعب', 'الكتاب ص 231 — تقويم الفصل س34 (الشكل 6-24)، وص 210–211'),
('essay', 3, 'يمثّل الشكل الآتي بروتينًا كرويًا في الوسط المائي للخلية، تتجه فيه السلاسل الجانبية من النوع X إلى داخل البروتين، والسلاسل الجانبية من النوع Y إلى سطحه الخارجي.
(a) أيّ النوعين يُتوقع أن يتكوّن من سلاسل جانبية قطبية، وأيّهما من سلاسل غير قطبية؟
(b) قوّم هذا الترتيب: هل هو منطقي من حيث طبيعة بيئة الخلية؟ وضّح.
(c) علمًا بأن السلاسل الجانبية المكوّنة من الكربون والهيدروجين فقط (ومنها السلاسل التي فيها حلقة بنزين) غير قطبية، وأن السلاسل التي تحتوي على مجموعة هيدروكسيل أو مجموعة أميد قطبية، اختر من الأحماض الأمينية الآتية حمضين يُتوقع وجود سلسلتيهما الجانبيتين في النوع X، وحمضين في النوع Y: الفالين −CH(CH₃)₂، والسيرين −CH₂OH، وفينيل الألنين −CH₂−C₆H₅، والجلوتامين −CH₂CH₂CONH₂.', null, '[{"src":"qimg/chem22/c6-l1b-globular.svg","alt":"مخطط لبروتين كروي في وسط مائي: منطقة بيضوية فاتحة تمثّل البروتين، وفيها سلسلة عديد ببتيد زرقاء تلتف قرب المحيط ثم تنثني إلى الداخل. ترتبط بأجزاء السلسلة القريبة من السطح عشر دوائر بيضاء مفرغة متجهة إلى الخارج نحو جزيئات الماء H₂O المحيطة بالبروتين، وترتبط بأجزاء السلسلة الداخلية سبع دوائر سوداء مصمتة متجهة إلى مركز البروتين بعيدًا عن الماء. وفي المفتاح: الدائرة السوداء سلسلة جانبية من النوع X، والدائرة البيضاء سلسلة جانبية من النوع Y، والخط الأزرق سلسلة عديد الببتيد."}]'::jsonb, null, 'تقويم', 'تقويم وتعليل', 'صعب', 'الكتاب ص 231 — تقويم الفصل س37، وص 211 السلاسل الجانبية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
