('mcq', 3, 3, 'تنتهي السلسلة الجانبية للحمض (4) بمجموعة أمين −NH₂ (وهو اللايسين)، والمجموعة الأمينية من المجموعات القاعدية؛ لذا سلسلته الجانبية قاعدية.', '["السلسلة الجانبية للحمض (1) هي −CH₃، وهي ألكانية غير قطبية.","السلسلة الجانبية للحمض (2) تحتوي على مجموعة SH (كبريت)، وليست مجموعة أمين قاعدية.","السلسلة الجانبية للحمض (3) تنتهي بمجموعة أميد −CONH₂، لا بمجموعة أمين مرتبطة بسلسلة ألكيل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-15T02:47:48.826Z"}'::jsonb),
('mcq', 4, 1, 'السلسلتان −CH(CH₃)₂ (W) و −CH₃ (Y) تتكوّنان من الكربون والهيدروجين فقط وتشبهان الألكانات، والألكانات غير قطبية؛ لذا فالزوج W وY غير قطبي.', '["X تحتوي على مجموعة هيدروكسيل قطبية، وZ تحتوي على مجموعة كربوكسيل حمضية.","","W غير قطبية، لكن X تحتوي على مجموعة هيدروكسيل −OH قطبية.","Y غير قطبية، لكن Z تحتوي على مجموعة كربوكسيل −COOH فهي حمضية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-15T02:47:48.826Z"}'::jsonb),
('mcq', 5, 3, 'تنتهي سلسلة حمض الجلوتاميك بمجموعة كربوكسيل −COOH، ومجموعة الكربوكسيل حمضية؛ وتنتهي سلسلة اللايسين بمجموعة أمين −NH₂، ومجموعة الأمين قاعدية. لذا فسلسلة حمض الجلوتاميك حمضية وسلسلة اللايسين قاعدية.', '["كون المركب حمضًا أمينيًا لا يحدد صنف سلسلته الجانبية؛ فالتصنيف بحسب المجموعة الوظيفية في السلسلة، وسلسلة اللايسين فيها مجموعة أمين قاعدية.","هذا قلب للتصنيف؛ فمجموعة الكربوكسيل −COOH حمضية، ومجموعة الأمين −NH₂ قاعدية.","المجموعتان الطرفيتان −COOH و −NH₂ تجعلان السلسلتين لا تشبهان الألكانات، فالأولى حمضية والثانية قاعدية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-15T02:47:48.826Z"}'::jsonb),
('mcq', 6, 2, 'تحتوي السلسلة الجانبية على حلقة بنزين فهي أروماتية، وترتبط بالحلقة مجموعة هيدروكسيل −OH قطبية.', '["السلسلة تحتوي على حلقة بنزين أروماتية ومجموعة OH قطبية، فليست أليفاتية ولا ألكانية.","مجموعة OH مرتبطة بالحلقة مباشرة ولا توجد مجموعة C=O معها، فهي ليست مجموعة كربوكسيل.","","لا توجد في السلسلة الجانبية مجموعة أمين؛ مجموعة الأمين الوحيدة هي المرتبطة بالكربون المركزي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-15T02:47:48.827Z"}'::jsonb),
('mcq', 7, 0, 'السلسلة الجانبية لفينيل الألنين −CH₂− مرتبطة بحلقة بنزين، وحلقة البنزين أروماتية.', '["","السلسلة الجانبية للايسين سلسلة CH₂ تنتهي بمجموعة أمين، فهي قاعدية وليست أروماتية.","السلسلة الجانبية للسيرين −CH₂OH، فيها مجموعة هيدروكسيل قطبية ولا حلقة فيها.","السلسلة الجانبية للفالين −CH(CH₃)₂ ألكانية أليفاتية غير قطبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-11-15T02:47:48.827Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) غير قطبي: الفالين، لأن سلسلته الجانبية ألكانية من C وH فقط. قطبي: السيرين، لأن سلسلته الجانبية فيها مجموعة هيدروكسيل −OH قطبية.
(b) أروماتي: فينيل الألنين، لاحتواء سلسلته الجانبية على حلقة بنزين. أليفاتي: الفالين (أو اللايسين)، لأن سلسلته الجانبية سلسلة كربونية مفتوحة بلا حلقة أروماتية.
(c) حمضي: حمض الجلوتاميك، لاحتواء سلسلته الجانبية على مجموعة كربوكسيل −COOH. قاعدي: اللايسين، لاحتواء سلسلته الجانبية على مجموعة أمين −NH₂.
(d) السيستين (−CH₂SH).', '["(a) الفالين غير قطبي والسيرين قطبي مع التعليل","(b) فينيل الألنين أروماتي والفالين أو اللايسين أليفاتي","(c) حمض الجلوتاميك حمضي واللايسين قاعدي","(d) السيستين"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":1},{"element":"(d)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الاختيارات الأربعة صحيحة ومعللة"},{"level":"2–3 درجات","description":"اختياران أو ثلاثة صحيحة"},{"level":"1 درجة","description":"اختيار واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف السيرين غير قطبي لأن سلسلته الجانبية قصيرة","تصنيف اللايسين حمضيًا لأن اسمه حمض أميني","عدّ الفالين أروماتيًا لتفرعه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-15T02:47:48.827Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) التريبتوفان حمض أميني (وحدة بناء للبروتينات)؛ لأن ذرة الكربون المركزية ترتبط بأربع مجموعات: مجموعة أمين −NH₂، ومجموعة كربوكسيل −COOH، وذرة هيدروجين، وسلسلة جانبية R.
(b) سلسلته الجانبية أروماتية؛ لأنها تحتوي على حلقة بنزين (ملتحمة بحلقة خماسية).
