('mcq', 1, 'ما تصنيف كلٍّ من السكروز والسليلوز على الترتيب؟', null, null, '["سكر أحادي، سكر ثنائي","سكر ثنائي، سكر عديد التسكر","سكر ثنائي، سكر ثنائي","سكر أحادي، سكر عديد التسكر"]'::jsonb, 'تذكر', 'تصنيف', 'سهل', 'الكتاب ص 217 — السكريات الثنائية وعديدة التسكر'),
('mcq', 2, 'يمثل الشكل الآتي ثلاثة نماذج، يرمز كل شكل سداسي فيها إلى وحدة سكر أحادي. أيّ النماذج يمثل سكرًا عديد التسكر؟', null, '[{"src":"qimg/chem22/c6-l2-unit-counts.svg","alt":"ثلاثة نماذج، كل شكل سداسي يمثل وحدة سكر أحادي: (س) وحدة واحدة منفردة، (ص) وحدتان مرتبطتان معًا، (ع) سلسلة من أربع عشرة وحدة مرتبطة معًا."}]'::jsonb, '["النموذج (س)","النموذج (ص)","النموذجان (ص) و(ع)","النموذج (ع)"]'::jsonb, 'فهم', 'تفسير شكل', 'سهل', 'الكتاب ص 217 — السكريات عديدة التسكر (12 وحدة فأكثر)'),
('mcq', 3, 'ما التعريف الصحيح للسكريات عديدة التسكر؟', null, null, '["بوليمرات من السكريات البسيطة تحتوي على 12 وحدة بناء أساسية أو أكثر","سكريات ناتجة من اتحاد جزيئين من السكريات الأحادية","أبسط الكربوهيدرات تركيبًا وتُدعى السكريات البسيطة","بوليمرات من الأحماض الأمينية ترتبط بروابط ببتيدية"]'::jsonb, 'تذكر', 'تذكر تعريف', 'متوسط', 'الكتاب ص 217، 243 — السكريات عديدة التسكر'),
('mcq', 4, 'أيّ المجموعات الآتية تتكون من سكريات أحادية فقط؟', null, null, '["الجلوكوز، والسكروز، والفركتوز","الفركتوز، واللاكتوز، والجلاكتوز","الجلوكوز، والفركتوز، والرايبوز","النشا، والجلوكوز، والجلاكتوز"]'::jsonb, 'فهم', 'تصنيف', 'متوسط', 'الكتاب ص 217، 232 — السكريات الأحادية (س43)'),
('mcq', 5, 'عند التميّه الكامل لجزيء واحد من كربوهيدرات (X) نتج جزيء جلوكوز وجزيء جلاكتوز فقط. ما تصنيف (X)؟', null, null, '["سكر ثنائي؛ لأنه يتكون من وحدتين من السكريات الأحادية","سكر أحادي؛ لأن كلًّا من ناتجَي تميّهه سكر أحادي","سكر عديد التسكر؛ لأنه يتكون من نوعين مختلفين من الوحدات","سكر أحادي؛ لأن صيغته تحتوي على ست ذرات كربون فقط"]'::jsonb, 'تطبيق', 'تصنيف من بيانات', 'متوسط', 'الكتاب ص 217 — السكريات الثنائية'),
('mcq', 6, 'الصيغة الجزيئية لكل من الجلوكوز والفركتوز C₆H₁₂O₆، ويتحرر جزيء ماء واحد عند ارتباط سكرين أحاديين. لديك كربوهيدرات صيغته الجزيئية C₁₂H₂₂O₁₁. ما تصنيفه؟', null, null, '["سكر أحادي من وحدة واحدة","سكر عديد التسكر من 12 وحدة","ليس من الكربوهيدرات أصلًا","سكر ثنائي من وحدتين"]'::jsonb, 'تحليل', 'استنتاج من صيغة', 'صعب', 'الكتاب ص 217 — تكوين السكريات الثنائية بالتكثف'),
('mcq', 7, 'أيّ العبارات الآتية صحيحة في تصنيف الكربوهيدرات؟', null, null, '["تحتوي السكريات عديدة التسكر على نوعين مختلفين على الأقل من السكريات الأحادية","النشا والجلايكوجين والسليلوز سكريات عديدة التسكر مع أن كلًّا منها يتكون من الجلوكوز وحده","يُعد الفركتوز سكرًا ثنائيًّا لأنه يتكون من الجلوكوز والجلاكتوز","السكريات الثنائية بوليمرات لأنها تتكون من أكثر من وحدة سكر واحدة"]'::jsonb, 'فهم', 'تقويم عبارات', 'صعب', 'الكتاب ص 217–218 — أنواع الكربوهيدرات'),
('essay', 1, 'صنّف الكربوهيدرات الآتية إلى سكريات أحادية، أو ثنائية، أو عديدة التسكر: النشا، الجلوكوز، السكروز، الرايبوز، السليلوز، الجلايكوجين، الفركتوز، اللاكتوز.', null, null, null, 'فهم', 'تصنيف', 'سهل', 'الكتاب ص 232 — س43 تصنيف الكربوهيدرات'),
('essay', 2, 'قارن بين السكريات الأحادية والثنائية وعديدة التسكر من حيث: عدد وحدات البناء الأساسية في الجزيء، وطريقة تكوّن الجزيء، مع مثال واحد لكل نوع.', null, null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 217 — ماذا قرأت؟'),
('essay', 3, 'ثلاثة كربوهيدرات (X) و(Y) و(Z): عند التميّه الكامل لجزيء من (X) نتج جزيئا جلوكوز، ولجزيء من (Y) نتج نحو 3000 جزيء جلوكوز، أما (Z) فصيغته C₆H₁₂O₆ ولا يتميّه إلى سكر أبسط. صنّف كلًّا منها مع التعليل، ثم فسّر لماذا لا يكفي نوع الوحدات وحده للحكم على تصنيف الكربوهيدرات.', null, null, null, 'تحليل', 'تصنيف وتعليل', 'صعب', 'الكتاب ص 217، 243 — تعريفات أنواع السكريات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
