select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'السكروز يتكون من اتحاد سكرين أحاديين (جلوكوز وفركتوز) فهو سكر ثنائي، والسليلوز بوليمر من عدد كبير جدًّا من وحدات الجلوكوز (أكثر من 12 وحدة) فهو سكر عديد التسكر؛ فالترتيب: سكر ثنائي، سكر عديد التسكر.', '["السكروز ليس سكرًا أحاديًّا لأنه يتكون من وحدتين، والسليلوز ليس ثنائيًّا لأنه بوليمر من آلاف الوحدات.","","التصنيف الأول صحيح، لكن السليلوز بوليمر من عدد كبير من وحدات الجلوكوز وليس وحدتين فقط.","التصنيف الثاني صحيح، لكن السكروز يتكون من سكرين أحاديين مرتبطين فهو ثنائي لا أحادي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.828Z"}'::jsonb),
('mcq', 2, 3, 'السكريات عديدة التسكر بوليمرات من السكريات البسيطة تحتوي على 12 وحدة بناء أساسية أو أكثر، والنموذج (ع) سلسلة من 14 وحدة، فهو وحده عديد التسكر.', '["النموذج (س) وحدة واحدة منفردة، فهو سكر أحادي.","النموذج (ص) وحدتان مرتبطتان، فهو سكر ثنائي.","النموذج (ع) صحيح، لكن (ص) يحتوي على وحدتين فقط فهو سكر ثنائي وليس عديد التسكر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-15T02:47:48.828Z"}'::jsonb),
('mcq', 3, 0, 'السكريات عديدة التسكر (الكربوهيدرات المعقدة) بوليمرات تتكون من السكريات البسيطة وتحتوي على 12 وحدة بناء أساسية أو أكثر.', '["","هذا تعريف السكريات الثنائية، لا عديدة التسكر.","هذا تعريف السكريات الأحادية.","هذا وصف البروتينات (عديدات الببتيد)، لا الكربوهيدرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-15T02:47:48.828Z"}'::jsonb),
('mcq', 4, 2, 'الجلوكوز والفركتوز سكريات أحادية سداسية الكربون، والرايبوز سكر أحادي أيضًا؛ فالمجموعة كلها سكريات أحادية.', '["السكروز سكر ثنائي يتكون من الجلوكوز والفركتوز.","اللاكتوز سكر ثنائي يتكون من الجلوكوز والجلاكتوز.","","النشا سكر عديد التسكر يتكون من عدد كبير من وحدات الجلوكوز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.828Z"}'::jsonb),
('mcq', 5, 0, 'التميّه يفكك الرابطة بين الوحدات، وبما أن الناتج وحدتان فقط (جلوكوز وجلاكتوز) فإن (X) مكون من سكرين أحاديين مرتبطين، فهو سكر ثنائي.', '["","نواتج التميّه أحادية، لكن المركب نفسه يتكون من وحدتين مرتبطتين، فهو ثنائي لا أحادي.","التصنيف يعتمد على عدد الوحدات لا على تنوعها، وعديد التسكر يحتوي على 12 وحدة أو أكثر.","المركب المكون من وحدتين سداسيتي الكربون يحتوي على 12 ذرة كربون، وهو ثنائي لا أحادي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-15T02:47:48.828Z"}'::jsonb),
('mcq', 6, 3, 'مجموع صيغتي سكرين أحاديين C₁₂H₂₄O₁₂، وبطرح جزيء ماء H₂O ينتج C₁₂H₂₂O₁₁؛ إذن هذه الصيغة لسكرين أحاديين مرتبطين، أي سكر ثنائي من وحدتين.', '["السكر الأحادي سداسي الكربون صيغته C₆H₁₂O₆، أما C₁₂H₂₂O₁₁ فتساوي سكرين أحاديين ناقص جزيء ماء.","خلط بين 12 ذرة كربون و12 وحدة بناء؛ فعديد التسكر يحتوي على 12 وحدة سكر أو أكثر، لا 12 ذرة كربون.","ربما ظنًّا أنه لا يطابق الصيغة Cₙ(H₂O)ₙ تمامًا؛ لكن الصيغة تحتوي على 22 ذرة هيدروجين و11 ذرة أكسجين (بنسبة 2:1) وهي صيغة سكر ثنائي معروف هو السكروز؛ وعدم مطابقة Cₙ(H₂O)ₙ تمامًا لا ينفي أنه كربوهيدرات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-15T02:47:48.828Z"}'::jsonb),
('mcq', 7, 1, 'التصنيف يعتمد على عدد الوحدات؛ فالنشا والجلايكوجين والسليلوز بوليمرات من عدد كبير من وحدات الجلوكوز، فهي عديدة التسكر رغم أن وحداتها من نوع واحد.', '["النشا والسليلوز والجلايكوجين عديدة التسكر وتتكون كلها من وحدات الجلوكوز فقط.","","الفركتوز سكر أحادي، واللاكتوز هو الذي يتكون من الجلوكوز والجلاكتوز.","السكر الثنائي وحدتان فقط، أما البوليمر من السكريات فيحتوي على 12 وحدة أو أكثر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.829Z"}'::jsonb),
('essay', 1, null::int, null, null, 'السكريات الأحادية: الجلوكوز، والرايبوز، والفركتوز. السكريات الثنائية: السكروز (جلوكوز + فركتوز)، واللاكتوز (جلوكوز + جلاكتوز). السكريات عديدة التسكر: النشا، والسليلوز، والجلايكوجين (بوليمرات من وحدات الجلوكوز).', '["أحادية: الجلوكوز، الرايبوز، الفركتوز","ثنائية: السكروز، اللاكتوز","عديدة التسكر: النشا، السليلوز، الجلايكوجين"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف الجلوكوز أحاديًّا","marks":1},{"element":"تصنيف الرايبوز أحاديًّا","marks":1},{"element":"تصنيف الفركتوز أحاديًّا","marks":1},{"element":"تصنيف السكروز ثنائيًّا","marks":1},{"element":"تصنيف اللاكتوز ثنائيًّا","marks":1},{"element":"تصنيف النشا عديد التسكر","marks":1},{"element":"تصنيف السليلوز عديد التسكر","marks":1},{"element":"تصنيف الجلايكوجين عديد التسكر","marks":1}]'::jsonb, '[{"level":"8 درجات","description":"إجابة كاملة صحيحة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"6–7 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط"},{"level":"1–5 درجات","description":"إجابة جزئية تتضمن بعض العناصر الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف السكروز أو اللاكتوز سكرًا أحاديًّا لأنهما حلوا المذاق","تصنيف الجلايكوجين سكرًا ثنائيًّا لأنه يتكون من نوع واحد من الوحدات","عدّ الرايبوز سكرًا ثنائيًّا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (8 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.829Z"}'::jsonb),
('essay', 2, null::int, null, null, 'السكريات الأحادية أبسط الكربوهيدرات تركيبًا (السكريات البسيطة)، وتتكون من وحدة واحدة، مثل الجلوكوز. السكريات الثنائية تتكون من وحدتين، وتنتج من اتحاد سكرين أحاديين بتفاعل تكثف يُطلق جزيء ماء وتتكون رابطة إيثرية C–O–C، مثل السكروز. السكريات عديدة التسكر بوليمرات تحتوي على 12 وحدة بناء أساسية أو أكثر ترتبط بنوع الروابط نفسه الموجود في السكر الثنائي، مثل النشا أو الجلايكوجين أو السليلوز.', '["الأحادية: وحدة واحدة، أبسط الكربوهيدرات","الثنائية: وحدتان مرتبطتان بتكثف ورابطة C–O–C","عديدة التسكر: 12 وحدة أو أكثر بالروابط نفسها","مثال صحيح لكل نوع"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الأحادية (وحدة واحدة)","marks":1},{"element":"وصف الثنائية (وحدتان)","marks":1},{"element":"وصف عديدة التسكر (12 وحدة أو أكثر)","marks":1},{"element":"بيان أن الثنائية وعديدة التسكر تتكونان بالتكثف وتكوين الرابطة C–O–C","marks":1},{"element":"مثال على الأحادية","marks":1},{"element":"مثالان على الثنائية وعديدة التسكر","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"4–5 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط"},{"level":"1–3 درجات","description":"إجابة جزئية تتضمن بعض العناصر الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن عديد التسكر يحتوي على 12 ذرة كربون","عدّ الثنائي بوليمرًا","إغفال تحرر الماء في التكثف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-15T02:47:48.829Z"}'::jsonb),
('essay', 3, null::int, null, null, '(X) سكر ثنائي؛ لأنه يتكون من وحدتين (جلوكوز + جلوكوز). (Y) سكر عديد التسكر؛ لأنه بوليمر يحتوي على أكثر من 12 وحدة جلوكوز (نحو 3000 وحدة). (Z) سكر أحادي؛ لأنه أبسط الكربوهيدرات ولا يتجزأ إلى سكر أبسط. ونلاحظ أن (X) و(Y) يتكونان من النوع نفسه من الوحدات (الجلوكوز) ومع ذلك يختلف تصنيفهما؛ لأن التصنيف يعتمد على عدد وحدات السكريات الأحادية في الجزيء لا على نوعها.', '["X ثنائي (وحدتان)","Y عديد التسكر (أكثر من 12 وحدة)","Z أحادي (لا يتميه إلى أبسط)","التصنيف حسب عدد الوحدات لا نوعها"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف X مع التعليل","marks":2},{"element":"تصنيف Y مع التعليل","marks":2},{"element":"تصنيف Z مع التعليل","marks":1},{"element":"تفسير أن العدد لا النوع هو أساس التصنيف","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"4–5 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط"},{"level":"1–3 درجات","description":"إجابة جزئية تتضمن بعض العناصر الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف X عديد التسكر لأنه يتكون من الجلوكوز مثل Y","عدّ Y ثنائيًّا لأن وحداته من نوع واحد","الخلط بين عدد ذرات الكربون وعدد الوحدات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-15T02:47:48.829Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
