('mcq', 1, 'ما نوع التفاعل الذي ترتبط به السكريات الأحادية معًا لتكوين سكر ثنائي؟', null, null, '["تفاعل إضافة يُستهلك فيه جزيء ماء","تفاعل تصبن يحتاج إلى قاعدة قوية","تفاعل تكثف يُطلق جزيء ماء","تفاعل هدرجة تُضاف فيه ذرات الهيدروجين"]'::jsonb, 'تذكر', 'تذكر نوع تفاعل', 'سهل', 'الكتاب ص 217 — السكريات الثنائية (تفاعل التكثف)'),
('mcq', 2, 'ما اسم الرابطة التي تربط الحلقتين في السكر الثنائي الآتي؟', null, '[{"src":"qimg/chem22/c6-l2-maltose.svg","alt":"تركيب سكر ثنائي من حلقتين سداسيتين متماثلتين، كل منهما من خمس ذرات كربون وذرة أكسجين ومجموعة CH₂OH إلى أعلى. في الحلقة اليسرى: ذرة الكربون اليسرى تحمل HO إلى أسفل، والأمامية اليسرى OH إلى أعلى، والأمامية اليمنى OH إلى أسفل. في الحلقة اليمنى: الأمامية اليسرى OH إلى أعلى، والأمامية اليمنى OH إلى أسفل، واليمنى OH إلى أسفل. ترتبط ذرة الكربون اليمنى في الحلقة اليسرى بذرة أكسجين واحدة تتصل بذرة الكربون اليسرى في الحلقة اليمنى."}]'::jsonb, '["الرابطة الإيثرية C–O–C","الرابطة الببتيدية","رابطة الإستر –COO–","الرابطة الهيدروجينية"]'::jsonb, 'تذكر', 'تعرّف رابطة من شكل', 'سهل', 'الكتاب ص 217 — الرابطة الإيثرية C–O–C'),
('mcq', 3, 'يمثل المخطط الآتي اتحاد سكرين أحاديين. ما الذي يمثله الناتج المجهول؟', null, '[{"src":"qimg/chem22/c6-l2-sucrose-eq-q.svg","alt":"الصف العلوي: حلقة سداسية من خمس ذرات كربون وذرة أكسجين (CH₂OH إلى أعلى على الكربون الخلفي الأيسر، وOH وOH وHO على بقية ذرات الكربون) تحمل ذرة الكربون اليمنى فيها مجموعة OH أفقية، ثم إشارة +، ثم حلقة خماسية من أربع ذرات كربون وذرة أكسجين في أعلاها، ذرة الكربون اليسرى فيها تحمل مجموعة CH₂OH إلى أعلى ومجموعة HO أفقية متجهة نحو الحلقة السداسية، وذرة الكربون الأمامية اليسرى تحمل OH إلى أسفل، والأمامية اليمنى OH إلى أعلى، واليمنى CH₂OH إلى أسفل. سهم من الصف العلوي يتجه إلى أسفل. الصف السفلي: مربع متقطع بداخله علامة استفهام (ناتج مجهول)، ثم إشارة +، ثم H₂O."}]'::jsonb, '["سكر ثنائي ترتبط فيه الحلقتان برابطة C–C مباشرة","سكر ثنائي ترتبط فيه الحلقتان عبر ذرة أكسجين (C–O–C)","مخلوط من السكرين الأحاديين دون أي ارتباط بينهما","سكر عديد التسكر يحتوي على 12 وحدة أو أكثر"]'::jsonb, 'فهم', 'تفسير مخطط تفاعل', 'متوسط', 'الكتاب ص 217 — تكوين السكروز'),
('mcq', 4, 'في المخطط الآتي يتحد سكران أحاديان ويتحرر جزيء ماء. من أين تأتي ذرات جزيء الماء الناتج؟', null, '[{"src":"qimg/chem22/c6-l2-sucrose-eq-q.svg","alt":"الصف العلوي: حلقة سداسية من خمس ذرات كربون وذرة أكسجين (CH₂OH إلى أعلى على الكربون الخلفي الأيسر، وOH وOH وHO على بقية ذرات الكربون) تحمل ذرة الكربون اليمنى فيها مجموعة OH أفقية، ثم إشارة +، ثم حلقة خماسية من أربع ذرات كربون وذرة أكسجين في أعلاها، ذرة الكربون اليسرى فيها تحمل مجموعة CH₂OH إلى أعلى ومجموعة HO أفقية متجهة نحو الحلقة السداسية، وذرة الكربون الأمامية اليسرى تحمل OH إلى أسفل، والأمامية اليمنى OH إلى أعلى، واليمنى CH₂OH إلى أسفل. سهم من الصف العلوي يتجه إلى أسفل. الصف السفلي: مربع متقطع بداخله علامة استفهام (ناتج مجهول)، ثم إشارة +، ثم H₂O."}]'::jsonb, '["من مجموعتي OH كاملتين، واحدة من كل سكر","من ذرتي H من مجموعتي CH₂OH في السكرين","من ذرة أكسجين الحلقة في أحد السكرين وذرتي H من الآخر","من مجموعة OH في أحد السكرين وذرة H من مجموعة OH في السكر الآخر"]'::jsonb, 'فهم', 'تفسير مخطط تفاعل', 'متوسط', 'الكتاب ص 217 — تفاعل التكثف وتحرر الماء'),
('mcq', 5, 'ارتبطت 12 وحدة جلوكوز في سلسلة واحدة مستقيمة غير متفرعة بتفاعلات تكثف. كم جزيء ماء تحرر؟', null, null, '["12","6","11","24"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 217 — السكريات عديدة التسكر وتفاعل التكثف'),
('mcq', 6, 'يتكون السكر الثنائي المالتوز من وحدتي جلوكوز. إذا كانت الكتلة المولية للجلوكوز 180.16 g/mol وللماء 18.02 g/mol، فما الكتلة المولية للمالتوز؟', null, null, '["360.32 g/mol","342.30 g/mol","324.28 g/mol","378.34 g/mol"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 232 — س50 المالتوز'),
('mcq', 7, 'كيف ترتبط وحدات الجلوكوز معًا في جزيء الجلايكوجين؟', null, null, '["بالرابطة الإيثرية C–O–C نفسها التي في السكر الثنائي، بتكرار التكثف","بروابط ببتيدية تتكون بين مجموعات الأمين ومجموعات الكربوكسيل","بروابط هيدروجينية فقط بين الوحدات دون أي روابط تساهمية","بروابط إستر تتكون بين مجموعات OH ومجموعات الكربوكسيل"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 217 — السكريات عديدة التسكر'),
('essay', 1, 'يمثل المخطط الآتي تكوين سكر ثنائي من سكرين أحاديين. فسّر ما يحدث في هذا التفاعل بمقارنة المتفاعلات بالنواتج، مبينًا: اسم نوع التفاعل، والذرات التي تُفقد من كل سكر، والرابطة الجديدة التي تتكون، واسم السكر الثنائي الناتج إذا كان السكران الأحاديان هما الجلوكوز والفركتوز.', null, '[{"src":"qimg/chem22/c6-l2-sucrose-eq.svg","alt":"الصف العلوي: حلقة سداسية من خمس ذرات كربون وذرة أكسجين (CH₂OH إلى أعلى على الكربون الخلفي الأيسر، وOH وOH وHO على بقية ذرات الكربون) تحمل ذرة الكربون اليمنى فيها مجموعة OH أفقية، ثم إشارة +، ثم حلقة خماسية من أربع ذرات كربون وذرة أكسجين في أعلاها، ذرة الكربون اليسرى فيها تحمل مجموعة CH₂OH إلى أعلى ومجموعة HO أفقية متجهة نحو الحلقة السداسية، وذرة الكربون الأمامية اليسرى تحمل OH إلى أسفل، والأمامية اليمنى OH إلى أعلى، واليمنى CH₂OH إلى أسفل. سهم من الصف العلوي يتجه إلى أسفل. الصف السفلي: الحلقتان نفسهما مرتبطتان بذرة أكسجين واحدة بين ذرة الكربون اليمنى في الحلقة السداسية وذرة الكربون اليسرى في الحلقة الخماسية، وقد اختفت مجموعة OH الأفقية من الحلقة السداسية وذرة H من مجموعة HO الأفقية في الحلقة الخماسية، وبقيت مجموعة CH₂OH العلوية على ذرة الكربون اليسرى في الحلقة الخماسية، وبجانبهما إشارة + ثم H₂O."}]'::jsonb, null, 'فهم', 'تفسير مخطط', 'متوسط', 'الكتاب ص 217 — الشكل 6-10'),
('essay', 2, 'سكر عديد التسكر افتراضي يتكون من سلسلة مستقيمة واحدة من 15 وحدة جلوكوز. إذا كانت الكتلة المولية للجلوكوز 180.16 g/mol وللماء 18.02 g/mol: (أ) احسب عدد جزيئات الماء المتحررة عند تكوينه. (ب) احسب كتلته المولية. (ج) فسّر لماذا يُصنف عديد التسكر وليس سكرًا ثنائيًّا.', null, null, null, 'تطبيق', 'حساب بخطوات', 'صعب', 'الكتاب ص 217، 233 — السكريات عديدة التسكر (س56)'),
('essay', 3, 'قارن بين تكوّن السكر الثنائي من سكرين أحاديين وتكوّن ثنائي الببتيد من حمضين أمينيين، من حيث: نوع التفاعل، والجزيء الصغير المتحرر، ونوع الرابطة المتكونة.', null, null, null, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 211، 217 — التكثف في الأحماض الأمينية والسكريات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
