from (values
('mcq', 1, 2, 'ترتبط السكريات الأحادية معًا بتفاعل التكثف الذي يُطلق الماء، كما هو الحال في الأحماض الأمينية.', '["استهلاك الماء يحدث في التميّه (تفكيك السكر الثنائي)، لا في تكوينه.","التصبن تحلل الجليسريدات الثلاثية بقاعدة قوية، ولا علاقة له بربط السكريات.","","الهدرجة إضافة الهيدروجين إلى روابط ثنائية، ولا تربط سكرين معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-15T02:47:48.829Z"}'::jsonb),
('mcq', 2, 0, 'الحلقتان مرتبطتان بذرة أكسجين واحدة بين ذرتي كربون، وهذه هي الرابطة الإيثرية C–O–C التي تتكون عند اتحاد سكرين أحاديين.', '["","الرابطة الببتيدية (رابطة الأميد) تربط الأحماض الأمينية وتحتوي على النيتروجين، ولا نيتروجين في السكريات.","رابطة الإستر تحتوي على مجموعة كربونيل مجاورة للأكسجين، وهي تربط الأحماض الدهنية بالجليسرول.","الرابطة الهيدروجينية قوة تجاذب بين الجزيئات، أما الحلقتان هنا فمرتبطتان برابطة تساهمية عبر ذرة أكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-15T02:47:48.829Z"}'::jsonb),
('mcq', 3, 1, 'يتحد السكران الأحاديان بتفاعل تكثف؛ تخرج مجموعة OH من أحدهما وذرة H من الآخر مكونتين H₂O، وترتبط الحلقتان عبر ذرة الأكسجين المتبقية برابطة إيثرية C–O–C فيتكون سكر ثنائي.', '["لا ترتبط ذرتا الكربون مباشرة؛ فالأكسجين المتبقي من مجموعة OH يبقى جسرًا بين الحلقتين.","","تحرر جزيء الماء دليل على حدوث تفاعل تكثف وتكوّن رابطة جديدة بين السكرين.","اتحاد سكرين أحاديين فقط يعطي وحدتين، أي سكرًا ثنائيًّا لا عديد التسكر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.830Z"}'::jsonb),
('mcq', 4, 3, 'في التكثف تنفصل مجموعة OH كاملة من أحد السكرين وذرة H من مجموعة OH في السكر الآخر فتكوّنان H₂O، ويبقى أكسجين السكر الثاني رابطًا بين الحلقتين.', '["مجموعتا OH كاملتان تحتويان على ذرتي أكسجين، وجزيء الماء فيه ذرة أكسجين واحدة؛ ويبقى أحد الأكسجينين جسرًا.","مجموعتا CH₂OH لا تشاركان في التفاعل، وتبقيان في السكر الثنائي كما هما.","أكسجين الحلقة يبقى في مكانه ضمن الحلقة ولا يخرج في التكثف.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.830Z"}'::jsonb),
('mcq', 5, 2, 'كل رابطة إيثرية بين وحدتين متجاورتين تُطلق جزيء ماء واحدًا، وعدد الروابط في سلسلة من 12 وحدة = 12 − 1 = 11 رابطة، فيتحرر 11 جزيء ماء.', '["عدّ جزيء ماء لكل وحدة، مع أن الماء يتحرر لكل رابطة بين وحدتين، وعدد الروابط أقل من عدد الوحدات بواحد.","قسمة عدد الوحدات على 2 كأن الوحدات ترتبط أزواجًا منفصلة، مع أنها سلسلة واحدة متصلة.","","افتراض أن كل وحدة تُطلق جزيئي ماء (من طرفيها)، مع أن كل رابطة تُطلق جزيئًا واحدًا فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.830Z"}'::jsonb),
('mcq', 6, 1, 'يتكون المالتوز بتكثف جزيئي جلوكوز مع تحرر جزيء ماء: 2 × 180.16 − 18.02 = 342.30 g/mol.', '["جمع كتلتي الجلوكوز دون طرح كتلة جزيء الماء المتحرر في التكثف.","","طرح جزيئي ماء بدلًا من جزيء واحد، مع أن رابطة واحدة فقط تتكون بين الوحدتين.","إضافة كتلة الماء بدلًا من طرحها، كأن الماء يُستهلك في التكوين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-15T02:47:48.830Z"}'::jsonb),
('mcq', 7, 0, 'ترتبط الوحدات الأساسية في السكريات عديدة التسكر بنوع الروابط نفسه الذي يجمع سكرين أحاديين لتكوين سكر ثنائي، أي الرابطة الإيثرية الناتجة عن التكثف، ويتكرر ذلك بين كل وحدتين متجاورتين.', '["","الروابط الببتيدية تربط الأحماض الأمينية في البروتينات، ولا توجد مجموعات أمين في الجلوكوز.","الوحدات مرتبطة بروابط تساهمية إيثرية؛ والروابط الهيدروجينية وحدها لا تكوّن بوليمرًا.","لا توجد مجموعات كربوكسيل في الجلوكوز؛ وروابط الإستر تميز الليبيدات مثل الجليسريدات الثلاثية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-15T02:47:48.830Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التفاعل تفاعل تكثف؛ تنفصل مجموعة OH من أحد السكرين وذرة H من مجموعة OH في السكر الآخر فيتكون جزيء ماء H₂O يتحرر. ترتبط الحلقتان عبر ذرة الأكسجين المتبقية فتتكون الرابطة الإيثرية C–O–C. والسكر الثنائي الناتج من الجلوكوز والفركتوز هو السكروز (سكر المائدة).', '["نوع التفاعل: تكثف","فقد OH من سكر وH من الآخر وتكوين H₂O","تكون الرابطة الإيثرية C–O–C","الناتج السكروز"]'::jsonb, '[]'::jsonb, '[{"element":"تسمية التفاعل تكثفًا","marks":1},{"element":"تحديد الذرات المفقودة وتكوين الماء","marks":2},{"element":"تسمية الرابطة الإيثرية C–O–C","marks":1},{"element":"تسمية الناتج السكروز","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3–4 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط"},{"level":"1–2 درجة","description":"إجابة جزئية تتضمن بعض العناصر الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية التفاعل إضافة أو تميّهًا","القول إن الحلقتين ترتبطان برابطة C–C مباشرة","تسمية الناتج اللاكتوز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.830Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) كل رابطة بين وحدتين تُطلق جزيء ماء، وعدد الروابط في سلسلة من 15 وحدة = 15 − 1 = 14، فيتحرر 14 جزيء ماء. (ب) الكتلة المولية = 15 × 180.16 − 14 × 18.02 = 2702.40 − 252.28 = 2450.12 g/mol. (ج) لأنه بوليمر يحتوي على 15 وحدة بناء أساسية، والسكريات عديدة التسكر تحتوي على 12 وحدة أو أكثر، أما الثنائي فوحدتان فقط.', '["عدد جزيئات الماء = 14","الكتلة المولية = 2450.12 g/mol","التصنيف: 12 وحدة فأكثر"]'::jsonb, '["عدد الروابط = 15 − 1 = 14، فيتحرر 14 جزيء H₂O","كتلة الوحدات = 15 × 180.16 = 2702.40 g/mol","كتلة الماء المتحرر = 14 × 18.02 = 252.28 g/mol","الكتلة المولية = 2702.40 − 252.28 = 2450.12 g/mol"]'::jsonb, '[{"element":"عدد جزيئات الماء مع التعليل","marks":2},{"element":"حساب كتلة الوحدات وكتلة الماء","marks":2},{"element":"الكتلة المولية النهائية بوحدتها","marks":1},{"element":"تفسير التصنيف","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"4–5 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط"},{"level":"1–3 درجات","description":"إجابة جزئية تتضمن بعض العناصر الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ 15 جزيء ماء بدلًا من 14","عدم طرح كتلة الماء","تصنيفه ثنائيًّا لأنه يتكون من نوع واحد من الوحدات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-15T02:47:48.830Z"}'::jsonb),
('essay', 3, null::int, null, null, 'أوجه الشبه: كلاهما يتكون بتفاعل تكثف، وفي كليهما يتحرر جزيء ماء H₂O. أوجه الاختلاف: في السكر الثنائي تتكون الرابطة الإيثرية C–O–C بين مجموعتي هيدروكسيل في السكرين، أما في ثنائي الببتيد فتتكون الرابطة الببتيدية (رابطة الأميد) بين مجموعة الكربوكسيل في أحد الحمضين ومجموعة الأمين في الآخر.', '["كلاهما تكثف","كلاهما يُطلق ماء","السكر الثنائي: رابطة إيثرية C–O–C","ثنائي الببتيد: رابطة ببتيدية (أميد)"]'::jsonb, '[]'::jsonb, '[{"element":"نوع التفاعل في الحالتين","marks":1},{"element":"تحرر الماء في الحالتين","marks":1},{"element":"الرابطة في السكر الثنائي","marks":1},{"element":"الرابطة في ثنائي الببتيد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2–3 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط"},{"level":"1 درجة","description":"إجابة جزئية تتضمن بعض العناصر الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية الرابطة في السكر الثنائي ببتيدية","القول إن السكر الثنائي يتكون بالإضافة دون تحرر ماء","الخلط بين المجموعات الوظيفية المتفاعلة في الحالتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-15T02:47:48.830Z"}'::jsonb)
