('mcq', 2, 'ما الأسماء العلمية لكلٍّ من: سكر المائدة، وسكر الحليب، وسكر الفاكهة، على الترتيب؟', null, null, '["اللاكتوز، السكروز، الفركتوز","السكروز، اللاكتوز، الفركتوز","السكروز، الفركتوز، اللاكتوز","الجلوكوز، اللاكتوز، الفركتوز"]'::jsonb, 'تذكر', 'مصطلحات', 'سهل', 'الكتاب ص 217، 232 — س46 أسماء السكريات'),
('mcq', 3, 'أيّ العبارات الآتية تصف النشا وصفًا صحيحًا؟', null, null, '["جزيء يذوب بسهولة في الماء، ويخزن الطاقة في النبات","بوليمر غير متفرع يكوّن الجدران القاسية للخلايا النباتية","جزيء طري لا يذوب في الماء، تصنعه النباتات لتخزين الطاقة","سكر ثنائي يتكون من وحدتي جلوكوز، ويُستعمل في التحلية"]'::jsonb, 'فهم', 'وصف خاصية', 'متوسط', 'الكتاب ص 218 — النشا'),
('mcq', 4, 'يبين الشكل الآتي صورتين لسكر أحادي في محلول مائي. أيّ العبارات الآتية صحيحة عن العلاقة بين الصورتين؟', null, '[{"src":"qimg/chem22/c6-l2-glu-ring-open.svg","alt":"صورتان لسكر أحادي واحد بينهما سهم اتزان مزدوج (⇌). (س) صورة حلقية: حلقة سداسية مسطحة مرسومة منظورًا (أضلاعها الأمامية سميكة) تتكون من خمس ذرات كربون وذرة أكسجين واحدة في الركن الخلفي الأيمن. ذرة الكربون الخلفية اليسرى تحمل مجموعة CH₂OH إلى أعلى، وذرة الكربون اليمنى المجاورة لأكسجين الحلقة تحمل OH إلى أسفل، وذرة الكربون الأمامية اليمنى تحمل OH إلى أسفل، وذرة الكربون الأمامية اليسرى تحمل OH إلى أعلى، وذرة الكربون اليسرى تحمل HO إلى أسفل. (ص) صورة مفتوحة السلسلة: سلسلة رأسية من ست ذرات كربون: ذرة الكربون العليا ترتبط بذرة H يسارًا وبرابطة ثنائية مع ذرة O يمينًا (H–C=O)، ثم ذرة كربون عليها H يسارًا وOH يمينًا، ثم ذرة كربون عليها HO يسارًا وH يمينًا، ثم ذرتا كربون على كلٍّ منهما H يسارًا وOH يمينًا، وفي الأسفل مجموعة CH₂OH."}]'::jsonb, '["(س) و(ص) صورتان للسكر نفسه يتحول بينهما باستمرار وبسرعة، و(س) هي الأكثر استقرارًا","(ص) هي الصورة الأكثر استقرارًا والسائدة في المحلول؛ لأنها تحتوي على مجموعة الكربونيل","(س) و(ص) سكران مختلفان لا يتحول أحدهما إلى الآخر؛ لأن الكربونيل يوجد في (ص) فقط","تتحول (ص) كلها إلى (س) تحولًا نهائيًّا، فلا يبقى في المحلول إلا الصورة الحلقية"]'::jsonb, 'تحليل', 'تفسير شكل', 'متوسط', 'الكتاب ص 217 — الصورة الحلقية وتركيب السلسلة المفتوحة'),
('mcq', 5, 'أيّ الخواص الآتية يشترك فيها النشا والسليلوز؟', null, null, '["كلاهما يهضمه الإنسان","كلاهما يخزن الطاقة في النبات","كلاهما ذو تركيب كثير التفرع","كلاهما لا يذوب في الماء"]'::jsonb, 'فهم', 'مقارنة خواص', 'متوسط', 'الكتاب ص 218 — النشا والسليلوز'),
('mcq', 6, 'يحتاج عدّاء إلى مصدر للطاقة الفورية قبل سباق قصير. أيّ السكريات الآتية أنسب لهذا الغرض؟', null, null, '["الجلوكوز؛ لأنه مصدر رئيس للطاقة الفورية للجسم","السليلوز؛ لأنه أكثر الكربوهيدرات توافرًا في النباتات","النشا؛ لأن جزيئه أكبر فيعطي طاقة فورية أكبر","اللاكتوز؛ لأنه الكربوهيدرات الأهم في الحليب"]'::jsonb, 'تطبيق', 'تطبيق في موقف', 'متوسط', 'الكتاب ص 217 — الجلوكوز مصدر الطاقة الفورية'),
('mcq', 7, 'أيّ الأوصاف الآتية ينطبق على الفركتوز؟', null, null, '["سكر أحادي خماسي الكربون له تركيب ألدهيدي، ويوجد في الدم بتركيز عالٍ","سكر ثنائي يتكون من الجلوكوز والجلاكتوز، ويوجد في الحليب","سكر أحادي سداسي الكربون له تركيب كيتوني، ويوجد في معظم الفواكه","سكر أحادي سداسي الكربون له تركيب ألدهيدي، ويوجد في معظم الفواكه"]'::jsonb, 'فهم', 'وصف خواص', 'صعب', 'الكتاب ص 217 — الفركتوز سكر الفاكهة'),
('essay', 1, 'أعطِ الاسم العلمي لكلٍّ مما يأتي، واذكر معلومة واحدة تميز كلًّا منه: (أ) سكر الدم (ب) سكر المائدة (ج) سكر الفاكهة (د) سكر الحليب.', null, null, null, 'تذكر', 'مصطلحات ووصف', 'سهل', 'الكتاب ص 217، 232 — س46'),
('essay', 2, 'صف خواص النشا والسليلوز من حيث: الذوبان في الماء، والقوام أو الصلابة، ووظيفة كلٍّ منهما في النبات، ووحدة البناء المشتركة بينهما.', null, null, null, 'فهم', 'وصف', 'متوسط', 'الكتاب ص 218 — النشا والسليلوز'),
('essay', 3, 'صف سلوك السكريات الأحادية مثل الجلوكوز في المحلول المائي، مبينًا: الصورتين اللتين توجد عليهما، وأيهما أكثر استقرارًا، وأين توجد مجموعة الكربونيل، وماذا يحدث لها عند تكوين الحلقة.', null, null, null, 'فهم', 'وصف وتفسير', 'صعب', 'الكتاب ص 217 — السكريات الأحادية في المحلول المائي')
