from (values
('mcq', 1, 3, 'الجلوكوز سكر سداسي الكربون يوجد بتركيز عالٍ في الدم؛ لأنه يعمل مصدرًا رئيسًا للطاقة الفورية للجسم، ولذلك يُسمى سكر الدم.', '["السكر الموجود في معظم الفواكه هو الفركتوز (سكر الفاكهة)، والتسمية تعود إلى تركيز الجلوكوز العالي في الدم ودوره في الطاقة.","تخزين الطاقة في الكبد والعضلات وظيفة الجلايكوجين (عديد التسكر)، لا الجلوكوز الحر.","السكر المستعمل بشكل رئيس في التحلية هو السكروز (سكر المائدة).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-15T02:47:48.831Z"}'::jsonb),
('mcq', 2, 1, 'سكر المائدة هو السكروز (يُستعمل في التحلية)، وسكر الحليب هو اللاكتوز، وسكر الفاكهة هو الفركتوز الموجود في معظم الفواكه.', '["تبديل بين الاسمين الأولين؛ فاللاكتوز سكر الحليب والسكروز سكر المائدة.","","تبديل بين الاسمين الأخيرين؛ فالفركتوز سكر الفاكهة واللاكتوز سكر الحليب.","الجلوكوز يُسمى سكر الدم، أما سكر المائدة فهو السكروز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-15T02:47:48.831Z"}'::jsonb),
('mcq', 3, 2, 'النشا سكر عديد التسكر من وحدات الجلوكوز تصنعه النباتات، وهو جزيء طري لا يذوب في الماء ويُستعمل لتخزين الطاقة.', '["وظيفة تخزين الطاقة صحيحة، لكن النشا لا يذوب في الماء.","هذا وصف السليلوز؛ أما النشا فقد يكون متفرعًا أو غير متفرع ويخزن الطاقة.","","النشا سكر عديد التسكر من عدد كبير من وحدات الجلوكوز، والسكر المستعمل في التحلية هو السكروز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-15T02:47:48.831Z"}'::jsonb),
('mcq', 4, 0, '(س) صورة حلقية و(ص) سلسلة مفتوحة للسكر الأحادي نفسه (سهم الاتزان ⇌)؛ في المحلول المائي يغيّر السكر شكله بينهما باستمرار وبسرعة، والتراكيب الحلقية هي الأكثر استقرارًا والشكل السائد عند الاتزان.', '["","وجود مجموعة الكربونيل لا يجعل السلسلة المفتوحة أكثر استقرارًا؛ فالصورة الحلقية (س) هي السائدة.","صحيح أن الكربونيل يوجد في السلسلة المفتوحة فقط، لكن الصورتين للسكر نفسه وتتحولان إحداهما إلى الأخرى باستمرار؛ إذ تتحول مجموعة الكربونيل إلى هيدروكسيل عند تكوين الحلقة.","التحول بين الصورتين مستمر في الاتجاهين، فتبقى الصورتان موجودتين في المحلول وإن كانت الحلقية هي السائدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.831Z"}'::jsonb),
('mcq', 5, 3, 'النشا جزيء طري لا يذوب في الماء، والسليلوز بوليمر لا يذوب في الماء أيضًا؛ فعدم الذوبان في الماء خاصية مشتركة بينهما.', '["الإنسان يهضم النشا لكنه لا يستطيع هضم السليلوز.","النشا يخزن الطاقة، أما السليلوز فيكوّن الجدران القاسية للخلايا النباتية.","السليلوز غير متفرع، والنشا قد يكون متفرعًا أو غير متفرع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-15T02:47:48.831Z"}'::jsonb),
('mcq', 6, 0, 'الجلوكوز يعمل مصدرًا رئيسًا للطاقة الفورية للجسم، ولذلك يوجد بتركيز عالٍ في الدم؛ فهو الأنسب لحاجة فورية إلى الطاقة.', '["","الإنسان لا يهضم السليلوز، فهو يمر في الجهاز الهضمي دون أن يتغير كثيرًا ولا يمد الجسم بالطاقة.","النشا عديد التسكر يجب أن يُهضم أولًا إلى جلوكوز، والجلوكوز نفسه هو مصدر الطاقة الفورية.","أهمية اللاكتوز في الحليب لا تجعله مصدر الطاقة الفورية الرئيس؛ فهذا دور الجلوكوز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-15T02:47:48.831Z"}'::jsonb),
('mcq', 7, 2, 'الفركتوز يُعرف بسكر الفاكهة لأنه موجود في معظم الفواكه، وهو سكر أحادي يتكون من ست ذرات كربون وله تركيب كيتوني.', '["هذا الوصف خاطئ؛ فالفركتوز سداسي الكربون كيتوني، والسكر الموجود بتركيز عالٍ في الدم هو الجلوكوز.","هذا وصف اللاكتوز (سكر الحليب)، أما الفركتوز فسكر أحادي.","","الفركتوز سداسي الكربون ويوجد في الفواكه، لكن تركيبه كيتوني لا ألدهيدي؛ فالتركيب الألدهيدي للجلوكوز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.831Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) سكر الدم: الجلوكوز؛ يوجد بتركيز عالٍ في الدم لأنه مصدر رئيس للطاقة الفورية، وهو سكر أحادي سداسي الكربون ألدهيدي. (ب) سكر المائدة: السكروز؛ سكر ثنائي يُستعمل بشكل رئيس في التحلية ويتكون من الجلوكوز والفركتوز. (ج) سكر الفاكهة: الفركتوز؛ سكر أحادي سداسي الكربون كيتوني موجود في معظم الفواكه. (د) سكر الحليب: اللاكتوز؛ سكر ثنائي هو الكربوهيدرات الأهم في الحليب ويتكون من الجلوكوز والجلاكتوز.', '["الجلوكوز + معلومة صحيحة","السكروز + معلومة صحيحة","الفركتوز + معلومة صحيحة","اللاكتوز + معلومة صحيحة"]'::jsonb, '[]'::jsonb, '[{"element":"الجلوكوز","marks":1},{"element":"معلومة عن الجلوكوز","marks":1},{"element":"السكروز","marks":1},{"element":"معلومة عن السكروز","marks":1},{"element":"الفركتوز","marks":1},{"element":"معلومة عن الفركتوز","marks":1},{"element":"اللاكتوز","marks":1},{"element":"معلومة عن اللاكتوز","marks":1}]'::jsonb, '[{"level":"8 درجات","description":"إجابة كاملة صحيحة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"6–7 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط"},{"level":"1–5 درجات","description":"إجابة جزئية تتضمن بعض العناصر الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية سكر المائدة جلوكوزًا","الخلط بين اللاكتوز والفركتوز","وصف الفركتوز بأنه ألدهيدي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (8 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-15T02:47:48.831Z"}'::jsonb),
('essay', 2, null::int, null, null, 'كلاهما يتكون من وحدات الجلوكوز. النشا جزيء طري لا يذوب في الماء، ويُستعمل في النبات لتخزين الطاقة. السليلوز بوليمر لا يذوب في الماء، ويكوّن الجدران القاسية للخلايا النباتية مثل تلك الموجودة في الخشب، فهو مادة بنائية صلبة.', '["وحدة البناء: الجلوكوز لكليهما","النشا: طري، لا يذوب، يخزن الطاقة","السليلوز: لا يذوب، يكوّن الجدران القاسية للخلايا النباتية"]'::jsonb, '[]'::jsonb, '[{"element":"وحدة البناء المشتركة","marks":1},{"element":"النشا لا يذوب وطري","marks":1},{"element":"وظيفة النشا","marks":1},{"element":"السليلوز لا يذوب","marks":1},{"element":"وظيفة السليلوز وصلابته","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3–4 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط"},{"level":"1–2 درجة","description":"إجابة جزئية تتضمن بعض العناصر الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن النشا يذوب في الماء","عكس وظيفتي النشا والسليلوز","القول إن السليلوز يتكون من الفركتوز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-15T02:47:48.831Z"}'::jsonb),
('essay', 3, null::int, null, null, 'في المحلول المائي يوجد السكر الأحادي في صورتين: الصورة الحلقية وتركيب السلسلة المفتوحة، ويتحول بينهما باستمرار وبسرعة. التراكيب الحلقية هي الأكثر استقرارًا، وهي الشكل السائد في حالة الاتزان. توجد مجموعة الكربونيل (C=O) فقط في تركيب السلسلة المفتوحة، وعند تكوين الحلقة تتحول مجموعة الكربونيل إلى مجموعة هيدروكسيل.', '["صورتان: حلقية ومفتوحة السلسلة","تحول مستمر وسريع بينهما","الحلقية أكثر استقرارًا وسائدة","C=O في المفتوحة فقط","تتحول C=O إلى OH في الحلقة"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر الصورتين","marks":1},{"element":"التحول المستمر بينهما","marks":1},{"element":"الحلقية الأكثر استقرارًا","marks":1},{"element":"موقع مجموعة الكربونيل","marks":1},{"element":"تحول الكربونيل إلى هيدروكسيل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3–4 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط"},{"level":"1–2 درجة","description":"إجابة جزئية تتضمن بعض العناصر الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن السكر يوجد في صورة واحدة ثابتة","عدّ السلسلة المفتوحة الأكثر استقرارًا","القول إن الحلقة تحتوي على مجموعة كربونيل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-15T02:47:48.832Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
