insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C6-L2-O04'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالكربوهيدرات؟', null, null, '["مركبات تحتوي على عدة مجموعات من الهيدروكسيل (–OH) بالإضافة إلى مجموعة الكربونيل (C=O)","مركبات تحتوي على مجموعة أمين ومجموعة كربوكسيل مرتبطتين بذرة كربون واحدة","جزيئات حيوية كبيرة غير قطبية لا تذوب في الماء","بوليمرات تحتوي على النيتروجين وتخزن المعلومات الوراثية"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 218، 244 — تعريف الكربوهيدرات'),
('mcq', 2, 'يمثل الشكل الآتي التركيب الحلقي لسكر أحادي. كم مجموعة هيدروكسيل (–OH) في هذا التركيب؟', null, '[{"src":"qimg/chem22/c6-l2-fructose-ring.svg","alt":"تركيب حلقي لسكر أحادي: حلقة خماسية مسطحة مرسومة منظورًا (أضلاعها الأمامية سميكة) تتكون من أربع ذرات كربون وذرة أكسجين في أعلاها. ذرة الكربون اليمنى تحمل OH إلى أعلى ومجموعة CH₂OH إلى أسفل، وذرة الكربون الأمامية اليمنى تحمل OH إلى أعلى، وذرة الكربون الأمامية اليسرى تحمل OH إلى أسفل، وذرة الكربون اليسرى تحمل مجموعة CH₂OH إلى أعلى."}]'::jsonb, '["ثلاث مجموعات","أربع مجموعات","خمس مجموعات","ست مجموعات"]'::jsonb, 'فهم', 'تحديد مجموعات وظيفية من شكل', 'متوسط', 'الكتاب ص 217، 218 — المجموعات الوظيفية في الكربوهيدرات'),
('mcq', 3, 'كم عدد مجموعات الهيدروكسيل ومجموعات الكربونيل في التركيب الآتي؟', null, '[{"src":"qimg/chem22/c6-l2-glucose-open.svg","alt":"تركيب مفتوح السلسلة لسكر أحادي: سلسلة رأسية من ست ذرات كربون: ذرة الكربون العليا ترتبط بذرة H يسارًا وبرابطة ثنائية مع ذرة O يمينًا (H–C=O)، ثم ذرة كربون عليها H يسارًا وOH يمينًا، ثم ذرة كربون عليها HO يسارًا وH يمينًا، ثم ذرتا كربون على كلٍّ منهما H يسارًا وOH يمينًا، وفي الأسفل مجموعة CH₂OH."}]'::jsonb, '["أربع مجموعات هيدروكسيل ومجموعة كربونيل واحدة","ست مجموعات هيدروكسيل دون مجموعة كربونيل","خمس مجموعات هيدروكسيل ومجموعتا كربونيل","خمس مجموعات هيدروكسيل ومجموعة كربونيل واحدة"]'::jsonb, 'فهم', 'تحليل تركيب', 'متوسط', 'الكتاب ص 218 — المجموعات الوظيفية'),
('mcq', 4, 'اعتمادًا على تعريف الكربوهيدرات، أيّ المركبات الآتية يُعد من الكربوهيدرات؟', null, null, '["CH₃CH₂CH₂CH₂OH","HOCH₂CH(OH)CH(OH)CHO","HOCH₂CH₂CH₂CH₂OH","CH₃CH₂COCH₂CH₃"]'::jsonb, 'تطبيق', 'تطبيق تعريف', 'متوسط', 'الكتاب ص 244 — تعريف الكربوهيدرات'),
('mcq', 5, 'ما الصيغة العامة التي تُكتب بها صيغ كثير من الكربوهيدرات، ومنها الجلوكوز C₆H₁₂O₆؟', null, null, '["CₙH₂ₙ₊₂","Cₙ(H₂O)ₙ","CₙH₂ₙ","CₙH₂ₙ₋₂"]'::jsonb, 'تذكر', 'صيغة عامة', 'سهل', 'الكتاب ص 236 — اختبار مقنن س1'),
('mcq', 6, 'يمثل الشكل الآتي التركيب الحلقي لسكر أحادي. أيّ العبارات الآتية تصف صحيحًا مجموعات الهيدروكسيل والكربونيل فيه؟', null, '[{"src":"qimg/chem22/c6-l2-glucose-ring.svg","alt":"تركيب حلقي لسكر أحادي: حلقة سداسية مسطحة مرسومة منظورًا (أضلاعها الأمامية سميكة) تتكون من خمس ذرات كربون وذرة أكسجين واحدة في الركن الخلفي الأيمن. ذرة الكربون الخلفية اليسرى تحمل مجموعة CH₂OH إلى أعلى، وذرة الكربون اليمنى المجاورة لأكسجين الحلقة تحمل OH إلى أسفل، وذرة الكربون الأمامية اليمنى تحمل OH إلى أسفل، وذرة الكربون الأمامية اليسرى تحمل OH إلى أعلى، وذرة الكربون اليسرى تحمل HO إلى أسفل."}]'::jsonb, '["يحتوي على مجموعات هيدروكسيل ومجموعة كربونيل ظاهرة داخل الحلقة","يحتوي على مجموعة كربونيل واحدة فقط دون أي مجموعات هيدروكسيل","يحتوي على مجموعات هيدروكسيل فقط، ولا توجد فيه مجموعة كربونيل","يحتوي على مجموعات هيدروكسيل ومجموعة كربوكسيل على ذرة كربون طرفية"]'::jsonb, 'فهم', 'تحليل تركيب', 'صعب', 'الكتاب ص 217 — تحول الكربونيل إلى هيدروكسيل في التركيب الحلقي'),
('mcq', 7, 'يوحي اسم الكربوهيدرات (هيدرات الكربون) بأنها مركبات من الكربون والماء؛ فصيغة الجلوكوز مثلًا C₆H₁₂O₆ وصيغة الرايبوز C₅H₁₀O₅. ما التفسير الصحيح لهذه التسمية؟', null, null, '["لأنها تحتوي فعلًا على جزيئات ماء مرتبطة بذرات كربونها","لأنها جميعها تذوب في الماء بسهولة","لأنها تنتج في النبات من اتحاد الكربون مع الماء مباشرة","نسبة H إلى O في صيغها 2 : 1 كما في الماء، مع أنها لا تحتوي على جزيئات ماء"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 233، 236 — س55 والصيغة Cₙ(H₂O)ₙ'),
('essay', 1, 'عرّف الكربوهيدرات، ثم اكتب صيغتي المجموعتين الوظيفيتين المميزتين لها واسم كلٍّ منهما.', null, null, null, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 218، 244 — الكربوهيدرات'),
('essay', 2, 'يمثل الشكل الآتي التركيب المفتوح السلسلة لسكر أحادي. (أ) حدد المجموعات الوظيفية فيه واذكر عدد كل منها. (ب) اكتب صيغته الجزيئية، وبيّن أنها تطابق الصيغة العامة Cₙ(H₂O)ₙ. (ج) وضّح لماذا يُعد هذا المركب من الكربوهيدرات.', null, '[{"src":"qimg/chem22/c6-l2-glucose-open.svg","alt":"تركيب مفتوح السلسلة لسكر أحادي: سلسلة رأسية من ست ذرات كربون: ذرة الكربون العليا ترتبط بذرة H يسارًا وبرابطة ثنائية مع ذرة O يمينًا (H–C=O)، ثم ذرة كربون عليها H يسارًا وOH يمينًا، ثم ذرة كربون عليها HO يسارًا وH يمينًا، ثم ذرتا كربون على كلٍّ منهما H يسارًا وOH يمينًا، وفي الأسفل مجموعة CH₂OH."}]'::jsonb, null, 'فهم', 'تحليل تركيب', 'متوسط', 'الكتاب ص 218 — المجموعات الوظيفية في الكربوهيدرات'),
('essay', 3, 'حدد أيّ المركبات الآتية من الكربوهيدرات اعتمادًا على تعريفها، مع التعليل: (1) HOCH₂CH(OH)CHO (2) HOCH₂CH(OH)CH₂OH (3) HOCH₂COCH₂OH (4) CH₃COOH. ثم بيّن لماذا لا تكفي مطابقة الصيغة Cₙ(H₂O)ₙ وحدها للحكم على أن المركب كربوهيدرات.', null, null, null, 'تحليل', 'تطبيق تعريف وتعليل', 'صعب', 'الكتاب ص 236، 244 — تعريف الكربوهيدرات والصيغة العامة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
