('mcq', 1, 0, 'الكربوهيدرات مركبات تحتوي على عدة مجموعات من الهيدروكسيل (–OH) بالإضافة إلى مجموعة الكربونيل الوظيفية (C=O).', '["","هذا وصف الأحماض الأمينية، وحدات بناء البروتينات.","هذا وصف الليبيدات.","هذا وصف الأحماض النووية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-15T02:47:48.832Z"}'::jsonb),
('mcq', 2, 2, 'على ذرات كربون الحلقة ثلاث مجموعات OH، وفي كل من مجموعتي CH₂OH مجموعة OH أخرى؛ فالمجموع 3 + 2 = 5 مجموعات هيدروكسيل. وأكسجين الحلقة مرتبط بذرتي كربون ولا يحمل H، فليس مجموعة هيدروكسيل.', '["عدّ مجموعات OH المرتبطة مباشرة بذرات كربون الحلقة فقط، وإغفال مجموعتي OH في مجموعتي CH₂OH.","إغفال مجموعة OH في إحدى مجموعتي CH₂OH.","","عدّ أكسجين الحلقة مجموعة هيدروكسيل، مع أنه مرتبط بذرتي كربون ولا يحمل ذرة H."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-15T02:47:48.832Z"}'::jsonb),
('mcq', 3, 3, 'في التركيب أربع مجموعات OH على ذرات الكربون من الثانية إلى الخامسة، ومجموعة OH خامسة ضمن CH₂OH، ومجموعة C=O واحدة في الأعلى؛ أي 5 مجموعات هيدروكسيل ومجموعة كربونيل واحدة.', '["إغفال مجموعة OH الموجودة ضمن مجموعة CH₂OH في نهاية السلسلة.","عدّ ذرة أكسجين الكربونيل مجموعة هيدروكسيل، مع أنها مرتبطة برابطة ثنائية C=O ولا تحمل H.","يوجد في التركيب رابطة ثنائية C=O واحدة فقط في أعلى السلسلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-15T02:47:48.832Z"}'::jsonb),
('mcq', 4, 1, 'المركب HOCH₂CH(OH)CH(OH)CHO يحتوي على ثلاث مجموعات هيدروكسيل ومجموعة كربونيل (–CHO)، فينطبق عليه تعريف الكربوهيدرات.', '["يحتوي على مجموعة هيدروكسيل واحدة فقط ولا يحتوي على مجموعة كربونيل؛ فهو كحول.","","يحتوي على مجموعتي هيدروكسيل لكن لا يحتوي على مجموعة كربونيل.","يحتوي على مجموعة كربونيل لكن لا يحتوي على أي مجموعة هيدروكسيل؛ فهو كيتون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-15T02:47:48.832Z"}'::jsonb),
('mcq', 5, 1, 'الجلوكوز C₆H₁₂O₆ يمكن كتابته C₆(H₂O)₆، أي على الصورة العامة Cₙ(H₂O)ₙ حيث n = 6.', '["هذه الصيغة العامة للألكانات، ولا تحتوي على أكسجين.","","هذه الصيغة العامة للألكينات (أو الألكانات الحلقية)، ولا تحتوي على أكسجين.","هذه الصيغة العامة للألكاينات، ولا تحتوي على أكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.832Z"}'::jsonb),
('mcq', 6, 2, 'في التركيب الحلقي لا توجد رابطة C=O؛ فمجموعة الكربونيل توجد فقط في السلسلة المفتوحة، وفي التركيب الحلقي تتحول إلى مجموعة هيدروكسيل، فيظهر في الحلقة خمس مجموعات OH (منها واحدة في CH₂OH).', '["لا توجد رابطة ثنائية C=O في الحلقة؛ فأكسجين الحلقة مرتبط بذرتي كربون برابطتين أحاديتين.","التركيب يُظهر عدة مجموعات OH، ولا يحتوي على C=O.","","لا توجد مجموعة –COOH في التركيب؛ فلا ترتبط ذرة كربون بـ C=O وOH معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-15T02:47:48.832Z"}'::jsonb),
('mcq', 7, 3, 'في صيغ كثير من الكربوهيدرات تكون نسبة ذرات الهيدروجين إلى ذرات الأكسجين 2 : 1 كما في الماء (C₆H₁₂O₆ تبدو C₆(H₂O)₆)، فبدت كأنها «كربون + ماء»؛ لكن ذرات الهيدروجين والأكسجين فيها موجودة في مجموعات هيدروكسيل وكربونيل مرتبطة بذرات الكربون، لا على هيئة جزيئات ماء.', '["لا توجد جزيئات H₂O داخل جزيء الكربوهيدرات؛ فذراتها موزعة في مجموعات OH وC=O.","ليست كلها ذائبة؛ فالنشا والسليلوز لا يذوبان في الماء، والتسمية مرتبطة بالصيغة لا بالذوبان.","التسمية جاءت من شكل الصيغة الجزيئية، لا من تفاعل مباشر بين الكربون والماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.832Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الكربوهيدرات مركبات تحتوي على عدة مجموعات من الهيدروكسيل (–OH) بالإضافة إلى مجموعة الكربونيل الوظيفية (C=O). المجموعتان: مجموعة الهيدروكسيل –OH، ومجموعة الكربونيل C=O.', '["التعريف: عدة مجموعات OH ومجموعة C=O","–OH الهيدروكسيل","C=O الكربونيل"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"صيغة مجموعة الهيدروكسيل واسمها","marks":1},{"element":"صيغة مجموعة الكربونيل واسمها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2–3 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط"},{"level":"1 درجة","description":"إجابة جزئية تتضمن بعض العناصر الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الكربونيل والكربوكسيل","تعريف الكربوهيدرات بأنها مركبات من الكربون والماء","ذكر مجموعة هيدروكسيل واحدة فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-15T02:47:48.833Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) يحتوي على خمس مجموعات هيدروكسيل (–OH): أربع على ذرات الكربون الوسطى وواحدة ضمن CH₂OH، ومجموعة كربونيل واحدة (C=O) في أعلى السلسلة. (ب) عدد الذرات: C = 6، H = 12، O = 6، فالصيغة C₆H₁₂O₆ = C₆(H₂O)₆ حيث n = 6. (ج) لأنه يحتوي على عدة مجموعات هيدروكسيل بالإضافة إلى مجموعة الكربونيل، وهذا تعريف الكربوهيدرات.', '["5 مجموعات OH","مجموعة C=O واحدة","C₆H₁₂O₆ = C₆(H₂O)₆","تطبيق التعريف"]'::jsonb, '["عدّ ذرات الكربون: 6","عدّ ذرات الهيدروجين: 12 (منها 5 في مجموعات OH)","عدّ ذرات الأكسجين: 6 (5 في OH وواحدة في C=O)","C₆H₁₂O₆ = C₆(H₂O)₆، n = 6"]'::jsonb, '[{"element":"عدد مجموعات OH","marks":1},{"element":"تحديد مجموعة C=O","marks":1},{"element":"الصيغة الجزيئية","marks":1},{"element":"المطابقة مع Cₙ(H₂O)ₙ","marks":1},{"element":"التعليل بالتعريف","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3–4 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط"},{"level":"1–2 درجة","description":"إجابة جزئية تتضمن بعض العناصر الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال OH في CH₂OH","عدّ أكسجين الكربونيل ضمن مجموعات OH","كتابة الصيغة C₆H₁₀O₆"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-15T02:47:48.833Z"}'::jsonb),
('essay', 3, null::int, null, null, '(1) كربوهيدرات: فيه مجموعتا OH ومجموعة كربونيل (–CHO). (2) ليس كربوهيدرات: فيه ثلاث مجموعات OH ولا توجد مجموعة كربونيل. (3) كربوهيدرات: فيه مجموعتا OH ومجموعة كربونيل (C=O بين ذرتي كربون). (4) ليس كربوهيدرات: فيه مجموعة كربوكسيل –COOH وليست فيه عدة مجموعات هيدروكسيل. ومع أن صيغة (4) الجزيئية C₂H₄O₂ يمكن كتابتها C₂(H₂O)₂ فإنه ليس كربوهيدرات؛ لذا فالحكم يكون بالمجموعات الوظيفية (عدة OH مع C=O) لا بالصيغة الجزيئية وحدها.', '["(1) كربوهيدرات","(2) ليس كربوهيدرات لغياب C=O","(3) كربوهيدرات","(4) ليس كربوهيدرات (حمض كربوكسيلي)","C₂H₄O₂ = C₂(H₂O)₂ مثال على قصور الصيغة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على (1) مع التعليل","marks":1},{"element":"الحكم على (2) مع التعليل","marks":1},{"element":"الحكم على (3) مع التعليل","marks":1},{"element":"الحكم على (4) مع التعليل","marks":1},{"element":"تفسير قصور الصيغة العامة بمثال","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"4–5 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط"},{"level":"1–3 درجات","description":"إجابة جزئية تتضمن بعض العناصر الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ (2) كربوهيدرات لاحتوائه على عدة مجموعات OH","عدّ (4) كربوهيدرات لأن صيغته تطابق Cₙ(H₂O)ₙ","عدم التعرف على مجموعة الكربونيل في (3) لأنها في وسط السلسلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-15T02:47:48.833Z"}'::jsonb)
