('mcq', 1, 'ما نوع العلاقة بين الجلوكوز والجلاكتوز، وبين الجلوكوز والفركتوز، على الترتيب؟', null, null, '["متشكلان بنائيان، متشكلان هندسيان","متشكلان هندسيان، متشكلان هندسيان","متشكلان هندسيان، متشكلان بنائيان","متشكلان بنائيان، متشكلان بنائيان"]'::jsonb, 'تذكر', 'تحديد نوع التشكل', 'سهل', 'الكتاب ص 217 — الجلاكتوز والفركتوز'),
('mcq', 2, 'يمثل الشكل الآتي التراكيب الحلقية لثلاثة سكريات أحادية. أيّ التراكيب يمثل الفركتوز، وما الذي يميزه؟', null, '[{"src":"qimg/chem22/c6-l2-three-rings.svg","alt":"ثلاثة تراكيب حلقية لسكريات أحادية متجاورة. (أ): حلقة سداسية مسطحة مرسومة منظورًا (أضلاعها الأمامية سميكة) تتكون من خمس ذرات كربون وذرة أكسجين واحدة في الركن الخلفي الأيمن. ذرة الكربون الخلفية اليسرى تحمل مجموعة CH₂OH إلى أعلى، وذرة الكربون اليمنى المجاورة لأكسجين الحلقة تحمل OH إلى أسفل، وذرة الكربون الأمامية اليمنى تحمل OH إلى أسفل، وذرة الكربون الأمامية اليسرى تحمل OH إلى أعلى، وذرة الكربون اليسرى تحمل HO إلى أسفل. (ب): حلقة خماسية تتكون من أربع ذرات كربون وذرة أكسجين في أعلاها. ذرة الكربون اليمنى تحمل OH إلى أعلى ومجموعة CH₂OH إلى أسفل، وذرة الكربون الأمامية اليمنى تحمل OH إلى أعلى، وذرة الكربون الأمامية اليسرى تحمل OH إلى أسفل، وذرة الكربون اليسرى تحمل CH₂OH إلى أعلى. (ج): حلقة سداسية مماثلة تمامًا من خمس ذرات كربون وذرة أكسجين، وفيها المجموعات نفسها في المواقع نفسها، إلا أن مجموعة HO على ذرة الكربون اليسرى متجهة إلى أعلى بدلًا من أسفل مقارنة بالتركيب (أ)."}]'::jsonb, '["(أ)؛ لأن حلقته سداسية من خمس ذرات كربون وذرة أكسجين","(ج)؛ لأن مجموعة OH على ذرة الكربون اليسرى متجهة إلى أعلى","(ب)؛ لأنه يحتوي على عدد أقل من ذرات الكربون","(ب)؛ لأن حلقته خماسية من أربع ذرات كربون وذرة أكسجين"]'::jsonb, 'فهم', 'تفسير شكل', 'سهل', 'الكتاب ص 217 — الشكل 6-10'),
('mcq', 3, 'يبين الشكل الآتي التركيبين الحلقيين لسكرين أحاديين. كيف يختلف (س) عن (ص)؟', null, '[{"src":"qimg/chem22/c6-l2-glu-gal-rings.svg","alt":"تركيبان حلقيان لسكرين أحاديين. (س): حلقة سداسية مسطحة مرسومة منظورًا (أضلاعها الأمامية سميكة) تتكون من خمس ذرات كربون وذرة أكسجين واحدة في الركن الخلفي الأيمن. ذرة الكربون الخلفية اليسرى تحمل مجموعة CH₂OH إلى أعلى، وذرة الكربون اليمنى المجاورة لأكسجين الحلقة تحمل OH إلى أسفل، وذرة الكربون الأمامية اليمنى تحمل OH إلى أسفل، وذرة الكربون الأمامية اليسرى تحمل OH إلى أعلى، وذرة الكربون اليسرى تحمل HO إلى أسفل. (ص): حلقة سداسية مماثلة تمامًا من خمس ذرات كربون وذرة أكسجين، وفيها المجموعات نفسها في المواقع نفسها، إلا أن مجموعة HO على ذرة الكربون اليسرى متجهة إلى أعلى بدلًا من أسفل مقارنة بالتركيب (س)."}]'::jsonb, '["يختلفان فقط في اتجاه H ومجموعة OH حول ذرة كربون واحدة، فهما متشكلان هندسيان","يختلفان في عدد ذرات الكربون، فصيغتاهما الجزيئيتان مختلفتان","أحدهما ألدهيدي والآخر كيتوني، فهما متشكلان بنائيان","يختلفان في حجم الحلقة، فهما متشكلان بنائيان"]'::jsonb, 'تحليل', 'مقارنة تراكيب', 'متوسط', 'الكتاب ص 217 — الجلاكتوز متشكل هندسي للجلوكوز'),
('mcq', 4, 'يمثل الشكل الآتي التراكيب المفتوحة السلسلة لثلاثة سكريات أحادية. أيّ العبارات الآتية تصف صحيحًا العلاقة بين (أ) و(ج)؟', null, '[{"src":"qimg/chem22/c6-l2-open-three.svg","alt":"ثلاثة تراكيب مفتوحة السلسلة لسكريات أحادية. (أ): سلسلة رأسية من ست ذرات كربون: ذرة الكربون العليا ترتبط بذرة H يسارًا وبرابطة ثنائية مع ذرة O يمينًا (H–C=O)، ثم ذرة كربون عليها H يسارًا وOH يمينًا، ثم ذرة كربون عليها HO يسارًا وH يمينًا، ثم ذرتا كربون على كلٍّ منهما H يسارًا وOH يمينًا، وفي الأسفل مجموعة CH₂OH. (ب): سلسلة رأسية مماثلة من ست ذرات كربون أعلاها H–C=O، ثم ذرة كربون عليها H يسارًا وOH يمينًا، ثم ذرتا كربون على كلٍّ منهما HO يسارًا وH يمينًا، ثم ذرة كربون عليها H يسارًا وOH يمينًا، وفي الأسفل CH₂OH. (ج): سلسلة رأسية من ست ذرات كربون: في الأعلى مجموعة CH₂OH، تليها ذرة كربون مرتبطة برابطة ثنائية مع ذرة O يمينًا (C=O) دون ذرة H، ثم ذرة كربون عليها HO يسارًا وH يمينًا، ثم ذرتا كربون على كلٍّ منهما H يسارًا وOH يمينًا، وفي الأسفل CH₂OH."}]'::jsonb, '["(أ) ألدهيدي و(ج) كيتوني، فهما متشكلان هندسيان","(أ) ألدهيدي و(ج) كيتوني، ولهما الصيغة الجزيئية نفسها، فهما متشكلان بنائيان","(أ) كيتوني و(ج) ألدهيدي، فهما متشكلان بنائيان","(أ) ألدهيدي و(ج) كيتوني، ويختلفان في الصيغة الجزيئية"]'::jsonb, 'تحليل', 'مقارنة تراكيب', 'صعب', 'الكتاب ص 217 — الجلوكوز ألدهيدي والفركتوز كيتوني'),
('mcq', 5, 'ما الكتلة المولية لكلٍّ من الجلوكوز والفركتوز؟ (C = 12.01، H = 1.008، O = 16.00)', null, null, '["مختلفتان: 180.16 g/mol للجلوكوز و150.13 g/mol للفركتوز","مختلفتان: 180.16 g/mol للجلوكوز و178.14 g/mol للفركتوز","متساويتان: 162.14 g/mol لكلٍّ منهما","متساويتان: 180.16 g/mol لكلٍّ منهما"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 232 — س54'),
('mcq', 6, 'يمثل الشكل الآتي التراكيب المفتوحة السلسلة لثلاثة سكريات أحادية. فيمَ يختلف التركيب (أ) عن التركيب (ب)؟', null, '[{"src":"qimg/chem22/c6-l2-open-three.svg","alt":"ثلاثة تراكيب مفتوحة السلسلة لسكريات أحادية. (أ): سلسلة رأسية من ست ذرات كربون: ذرة الكربون العليا ترتبط بذرة H يسارًا وبرابطة ثنائية مع ذرة O يمينًا (H–C=O)، ثم ذرة كربون عليها H يسارًا وOH يمينًا، ثم ذرة كربون عليها HO يسارًا وH يمينًا، ثم ذرتا كربون على كلٍّ منهما H يسارًا وOH يمينًا، وفي الأسفل مجموعة CH₂OH. (ب): سلسلة رأسية مماثلة من ست ذرات كربون أعلاها H–C=O، ثم ذرة كربون عليها H يسارًا وOH يمينًا، ثم ذرتا كربون على كلٍّ منهما HO يسارًا وH يمينًا، ثم ذرة كربون عليها H يسارًا وOH يمينًا، وفي الأسفل CH₂OH. (ج): سلسلة رأسية من ست ذرات كربون: في الأعلى مجموعة CH₂OH، تليها ذرة كربون مرتبطة برابطة ثنائية مع ذرة O يمينًا (C=O) دون ذرة H، ثم ذرة كربون عليها HO يسارًا وH يمينًا، ثم ذرتا كربون على كلٍّ منهما H يسارًا وOH يمينًا، وفي الأسفل CH₂OH."}]'::jsonb, '["في اتجاه H ومجموعة OH حول ذرة الكربون الرابعة من الأعلى فقط","في موقع مجموعة الكربونيل في السلسلة","في اتجاه H ومجموعة OH حول ذرتي الكربون الثالثة والرابعة","في عدد مجموعات الهيدروكسيل في السلسلة"]'::jsonb, 'تحليل', 'مقارنة تراكيب', 'صعب', 'الكتاب ص 217 — الجلاكتوز والجلوكوز'),
('mcq', 7, 'أيّ العبارات الآتية صحيحة عن الجلوكوز والجلاكتوز والفركتوز؟', null, null, '["كلها سكريات أحادية لها تركيب ألدهيدي","الجلاكتوز يحتوي على ذرة كربون أكثر من الجلوكوز","كلها سكريات أحادية سداسية الكربون صيغتها الجزيئية C₆H₁₂O₆","الجلوكوز والفركتوز متشكلان هندسيان لأن لهما التركيب نفسه"]'::jsonb, 'فهم', 'تقويم عبارات', 'سهل', 'الكتاب ص 217 — السكريات الأحادية'),
('essay', 1, 'قارن بين الجلوكوز والفركتوز من حيث: الصيغة الجزيئية، والكتلة المولية (C = 12.01، H = 1.008، O = 16.00)، ونوع مجموعة الكربونيل، ونوع التشكل بينهما.', null, null, null, 'تحليل', 'مقارنة مع حساب', 'متوسط', 'الكتاب ص 217، 232 — س54'),
('essay', 2, 'يمثل الشكل الآتي التراكيب المفتوحة السلسلة لثلاثة سكريات أحادية (أ) و(ب) و(ج). (أ) صنّف كل تركيب إلى ألدهيدي أو كيتوني مع التعليل. (ب) حدد زوج التراكيب الذي يمثل متشكلين هندسيين، وزوجًا يمثل متشكلين بنائيين، مع التعليل. (ج) سمِّ السكر الذي يمثله كل تركيب.', null, '[{"src":"qimg/chem22/c6-l2-open-three.svg","alt":"ثلاثة تراكيب مفتوحة السلسلة لسكريات أحادية. (أ): سلسلة رأسية من ست ذرات كربون: ذرة الكربون العليا ترتبط بذرة H يسارًا وبرابطة ثنائية مع ذرة O يمينًا (H–C=O)، ثم ذرة كربون عليها H يسارًا وOH يمينًا، ثم ذرة كربون عليها HO يسارًا وH يمينًا، ثم ذرتا كربون على كلٍّ منهما H يسارًا وOH يمينًا، وفي الأسفل مجموعة CH₂OH. (ب): سلسلة رأسية مماثلة من ست ذرات كربون أعلاها H–C=O، ثم ذرة كربون عليها H يسارًا وOH يمينًا، ثم ذرتا كربون على كلٍّ منهما HO يسارًا وH يمينًا، ثم ذرة كربون عليها H يسارًا وOH يمينًا، وفي الأسفل CH₂OH. (ج): سلسلة رأسية من ست ذرات كربون: في الأعلى مجموعة CH₂OH، تليها ذرة كربون مرتبطة برابطة ثنائية مع ذرة O يمينًا (C=O) دون ذرة H، ثم ذرة كربون عليها HO يسارًا وH يمينًا، ثم ذرتا كربون على كلٍّ منهما H يسارًا وOH يمينًا، وفي الأسفل CH₂OH."}]'::jsonb, null, 'تحليل', 'تحليل تراكيب', 'صعب', 'الكتاب ص 217 — الجلوكوز والجلاكتوز والفركتوز'),
('essay', 3, 'اكتب بالصيغة البنائية المكثفة جزء السلسلة الذي يحتوي على مجموعة الكربونيل في كلٍّ من الجلوكوز والفركتوز (في صورة السلسلة المفتوحة)، ثم بيّن أوجه الشبه والاختلاف بين مجموعتي الكربونيل فيهما.', null, null, null, 'تحليل', 'مقارنة تراكيب', 'متوسط', 'الكتاب ص 217، 234 — س80')
