from (values
('mcq', 1, 2, 'الجلاكتوز يختلف عن الجلوكوز فقط في اتجاه ذرة H ومجموعة OH في الفراغ حول إحدى ذرات الكربون، فهما متشكلان هندسيان؛ أما الفركتوز فله تركيب كيتوني مختلف في ترتيب الذرات، فهو متشكل بنائي للجلوكوز.', '["عكس العلاقتين؛ فالجلوكوز والجلاكتوز يختلفان في الترتيب الفراغي فقط (هندسي)، والفركتوز يختلف في ترتيب الذرات (بنائي).","العلاقة الأولى صحيحة، لكن الفركتوز كيتوني والجلوكوز ألدهيدي، فالاختلاف في البناء لا في الترتيب الفراغي فقط.","","العلاقة الثانية صحيحة، لكن الجلاكتوز له ترتيب الذرات نفسه ويختلف فقط في الاتجاه الفراغي حول ذرة كربون واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-15T02:47:48.833Z"}'::jsonb),
('mcq', 2, 3, 'التركيبان (أ) و(ج) حلقتان سداسيتان (الجلوكوز والجلاكتوز)، أما (ب) فحلقة خماسية من أربع ذرات كربون وذرة أكسجين تحمل مجموعتي CH₂OH، وهو الفركتوز.', '["الحلقة السداسية هنا للجلوكوز، والفركتوز يظهر بحلقة خماسية.","هذا الاختلاف الفراغي يميز الجلاكتوز عن الجلوكوز، لا الفركتوز.","الاختيار (ب) صحيح لكن التعليل خاطئ؛ ففي (ب) ست ذرات كربون (أربع في الحلقة واثنتان في مجموعتي CH₂OH) مثل الآخرين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-15T02:47:48.833Z"}'::jsonb),
('mcq', 3, 0, 'الحلقتان متماثلتان في عدد الذرات وترتيبها، والفرق الوحيد اتجاه مجموعة OH على ذرة الكربون اليسرى (إلى أسفل في (س) وإلى أعلى في (ص))؛ فهما متشكلان هندسيان (الجلوكوز والجلاكتوز).', '["","كلا التركيبين فيه ست ذرات كربون، وصيغتهما الجزيئية واحدة C₆H₁₂O₆.","هذا وصف العلاقة بين الجلوكوز والفركتوز، أما هنا فالحلقتان سداسيتان وتختلفان في الاتجاه الفراغي فقط.","الحلقتان كلتاهما سداسية من خمس ذرات كربون وذرة أكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-15T02:47:48.833Z"}'::jsonb),
('mcq', 4, 1, 'في (أ) مجموعة الكربونيل في طرف السلسلة مرتبطة بذرة H (ألدهيد)، وفي (ج) مجموعة الكربونيل على ذرة الكربون الثانية مرتبطة بذرتي كربون (كيتون)؛ وكلاهما C₆H₁₂O₆، فهما متشكلان بنائيان (الجلوكوز والفركتوز).', '["التصنيف ألدهيدي/كيتوني صحيح، لكن اختلاف موقع مجموعة الكربونيل اختلاف في ترتيب الذرات، فهما بنائيان لا هندسيان.","","عكس التصنيف؛ فالكربونيل في (أ) طرفي مرتبط بـ H (ألدهيد)، وفي (ج) بين ذرتي كربون (كيتون).","عدد الذرات في التركيبين متساوٍ: C₆H₁₂O₆، فصيغتهما الجزيئية واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-15T02:47:48.834Z"}'::jsonb),
('mcq', 5, 3, 'الجلوكوز والفركتوز متشكلان لهما الصيغة الجزيئية نفسها C₆H₁₂O₆، فالكتلة المولية لكل منهما = 6(12.01) + 12(1.008) + 6(16.00) = 180.16 g/mol.', '["حساب الفركتوز على أنه C₅H₁₀O₅ بسبب حلقته الخماسية، مع أنه يحتوي على ست ذرات كربون.","افتراض أن التركيب الكيتوني ينقص ذرتي هيدروجين (C₆H₁₀O₆)، مع أن المتشكلات لها الصيغة الجزيئية نفسها.","طرح كتلة جزيء ماء كأنهما وحدتان داخل بوليمر (C₆H₁₀O₅)، مع أن السؤال عن السكرين الأحاديين الحرين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-15T02:47:48.834Z"}'::jsonb),
('mcq', 6, 0, 'عند مقارنة الصفوف: ذرات الكربون الأولى والثانية والثالثة والخامسة متطابقة في (أ) و(ب)، أما ذرة الكربون الرابعة فتحمل OH يمينًا في (أ) ويسارًا في (ب)؛ فالفرق في الاتجاه الفراغي حول ذرة كربون واحدة.', '["","مجموعة الكربونيل في كلا التركيبين في أعلى السلسلة (H–C=O)، فكلاهما ألدهيدي.","ذرة الكربون الثالثة متطابقة في التركيبين (HO يسارًا وH يمينًا)، والاختلاف في الرابعة فقط.","في كلا التركيبين خمس مجموعات OH؛ والاختلاف في اتجاه إحداها فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-15T02:47:48.834Z"}'::jsonb),
('mcq', 7, 2, 'الجلوكوز والجلاكتوز والفركتوز سكريات أحادية، كل منها مكون من ست ذرات كربون، وهي متشكلات لها الصيغة الجزيئية نفسها C₆H₁₂O₆.', '["الجلوكوز والجلاكتوز ألدهيديان، أما الفركتوز فله تركيب كيتوني.","الجلاكتوز متشكل للجلوكوز، فله العدد نفسه من الذرات (C₆H₁₂O₆).","","الفركتوز متشكل بنائي للجلوكوز؛ إذ يختلف ترتيب الذرات (كيتوني مقابل ألدهيدي)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-15T02:47:48.834Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الصيغة الجزيئية لكليهما C₆H₁₂O₆. الكتلة المولية لكليهما = 6(12.01) + 12(1.008) + 6(16.00) = 72.06 + 12.096 + 96.00 = 180.16 g/mol. الجلوكوز له تركيب ألدهيدي (مجموعة الكربونيل في طرف السلسلة مرتبطة بـ H)، والفركتوز له تركيب كيتوني (مجموعة الكربونيل مرتبطة بذرتي كربون). وبما أن لهما الصيغة الجزيئية نفسها وترتيب الذرات مختلف فهما متشكلان بنائيان.', '["C₆H₁₂O₆ لكليهما","180.16 g/mol لكليهما","الجلوكوز ألدهيدي والفركتوز كيتوني","متشكلان بنائيان"]'::jsonb, '["كتلة C = 6 × 12.01 = 72.06","كتلة H = 12 × 1.008 = 12.096","كتلة O = 6 × 16.00 = 96.00","المجموع = 180.16 g/mol"]'::jsonb, '[{"element":"الصيغة الجزيئية","marks":1},{"element":"حساب الكتلة المولية","marks":2},{"element":"نوع الكربونيل في كل منهما","marks":2},{"element":"نوع التشكل","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"4–5 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط"},{"level":"1–3 درجات","description":"إجابة جزئية تتضمن بعض العناصر الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إعطاء الفركتوز كتلة مولية مختلفة","عكس الألدهيدي والكيتوني","تسمية العلاقة تشكلًا هندسيًّا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-15T02:47:48.834Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) (أ) و(ب) ألدهيديان لأن مجموعة الكربونيل في طرف السلسلة مرتبطة بذرة H (H–C=O)؛ و(ج) كيتوني لأن مجموعة الكربونيل على ذرة الكربون الثانية مرتبطة بذرتي كربون. (ب) (أ) و(ب) متشكلان هندسيان: لهما ترتيب الذرات نفسه ويختلفان فقط في اتجاه H وOH حول ذرة الكربون الرابعة. و(أ) و(ج) متشكلان بنائيان: لهما الصيغة C₆H₁₂O₆ نفسها لكن ترتيب الذرات مختلف (ألدهيد مقابل كيتون). (ج) (أ) الجلوكوز، (ب) الجلاكتوز، (ج) الفركتوز.', '["(أ) و(ب) ألدهيديان، (ج) كيتوني","(أ) و(ب) هندسيان مع التعليل","(أ) و(ج) أو (ب) و(ج) بنائيان مع التعليل","الأسماء: جلوكوز، جلاكتوز، فركتوز"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف التراكيب الثلاثة مع التعليل","marks":2},{"element":"الزوج الهندسي مع التعليل","marks":2},{"element":"الزوج البنائي مع التعليل","marks":2},{"element":"تسمية التراكيب","marks":1}]'::jsonb, '[{"level":"7 درجات","description":"إجابة كاملة صحيحة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"5–6 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط"},{"level":"1–4 درجات","description":"إجابة جزئية تتضمن بعض العناصر الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ (ج) ألدهيديًّا لوجود C=O فيه","عدّ (أ) و(ب) متشكلين بنائيين","تسمية (ب) فركتوزًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (7 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-15T02:47:48.834Z"}'::jsonb),
('essay', 3, null::int, null, null, 'في الجلوكوز تقع مجموعة الكربونيل في طرف السلسلة على ذرة الكربون الأولى: –CH(OH)–CHO، أي H–C=O (ألدهيد). وفي الفركتوز تقع على ذرة الكربون الثانية: HOCH₂–CO–CH(OH)–، أي C=O مرتبطة بذرتي كربون (كيتون). أوجه الشبه: كلتاهما مجموعة كربونيل C=O في سكر أحادي سداسي الكربون صيغته C₆H₁₂O₆، وكلتاهما تتحول إلى مجموعة هيدروكسيل عند تكوين الحلقة. أوجه الاختلاف: موقعها (طرفي في الجلوكوز وداخلي في الفركتوز) وما ترتبط به (ذرة H وذرة كربون في الجلوكوز، وذرتا كربون في الفركتوز)، ولهذا الجلوكوز ألدهيدي والفركتوز كيتوني.', '["الجلوكوز: –CHO في الطرف","الفركتوز: –CO– على الكربون الثاني","شبه: كلتاهما C=O وتتحولان إلى OH في الحلقة","اختلاف: الموقع وما ترتبط به (ألدهيد/كيتون)"]'::jsonb, '[]'::jsonb, '[{"element":"صيغة جزء الجلوكوز","marks":1},{"element":"صيغة جزء الفركتوز","marks":1},{"element":"أوجه الشبه","marks":1},{"element":"أوجه الاختلاف","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3–4 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط"},{"level":"1–2 درجة","description":"إجابة جزئية تتضمن بعض العناصر الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الكربونيل في الفركتوز في طرف السلسلة","الخلط بين الكربونيل والكربوكسيل","إغفال ذرة H في مجموعة الألدهيد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-15T02:47:48.834Z"}'::jsonb)
