('mcq', 6, 'يتكون كلٌّ من الجلايكوجين والنشا من وحدات الجلوكوز. فيمَ يتشابه الجلايكوجين والنشا أيضًا؟', null, null, '["كلاهما تصنعه النباتات ويوجد في الحبوب","كلاهما يختزن الطاقة، ويستطيع الإنسان هضمه","كلاهما يكوّن الجدران القاسية للخلايا","كلاهما يذوب في الماء بسهولة"]'::jsonb, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 217–218 — الجلايكوجين والنشا'),
('mcq', 7, 'ينصح أخصائي التغذية بتناول الخضراوات والحبوب الغنية بالسليلوز الذي يُسمى «ألياف غذائية». لماذا يُسمى السليلوز بهذا الاسم؟', null, null, '["لأنه يتحلل بسرعة إلى جلوكوز يمد الجسم بالطاقة","لأنه يُخزن في العضلات على هيئة ألياف","لأنه يذوب في الماء مكونًا أليافًا","لأنه يمر في الجهاز الهضمي دون أن يتغير كثيرًا"]'::jsonb, 'تطبيق', 'تطبيق في موقف', 'متوسط', 'الكتاب ص 218 — الألياف الغذائية'),
('essay', 1, 'قارن بين النشا والسليلوز من حيث: التركيب الجزيئي (التفرع)، ووظيفة كلٍّ منهما في النبات، ثم وضّح أهمية التركيب الجزيئي لكلٍّ منهما بالنسبة لوظيفته.', null, null, null, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 218، 232 — س47 وس48'),
('essay', 2, 'أكمل مقارنة بين النشا والجلايكوجين والسليلوز في الجوانب الآتية: المخلوق أو العضو الذي يوجد فيه، ووظيفته، وهل يستطيع الإنسان هضمه.', null, null, null, 'تحليل', 'مقارنة في جدول', 'متوسط', 'الكتاب ص 217–218 — الشكلان 6-11 و6-12'),
('essay', 3, 'عند التميّه الكامل لكلٍّ من السليلوز والجلايكوجين والنشا ينتج سكر أحادي واحد فقط. فسّر ذلك، وسمِّ هذا السكر الأحادي، ثم وضّح لماذا ينتج الإنسان هذا السكر من هضم النشا لكنه لا ينتجه من السليلوز في جهازه الهضمي.', null, null, null, 'تحليل', 'تفسير', 'صعب', 'الكتاب ص 218، 232 — س51')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
