select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'النشا والسليلوز والجلايكوجين جميعها سكريات عديدة التسكر تتكون من وحدات الجلوكوز.', '["الفركتوز سكر الفاكهة، ويدخل في تركيب السكروز، لا في هذه السكريات عديدة التسكر.","","الجلاكتوز يدخل مع الجلوكوز في تركيب اللاكتوز، لا في النشا أو السليلوز أو الجلايكوجين.","السكروز سكر ثنائي وليس سكرًا أحاديًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-15T02:47:48.835Z"}'::jsonb),
('mcq', 2, 0, 'للسليلوز تركيب غير متفرع يشبه السياج ذا السلاسل المتقاطعة، وهذا ما يمثله النموذج (أ)، أما (ب) فتركيب كثير التفرع.', '["","السليلوز غير متفرع؛ أما التركيب المتفرع فيوجد في الجلايكوجين وفي النشا المتفرع.","الاختيار (أ) صحيح لكن التعليل خاطئ؛ فالسليلوز يتكون من وحدات الجلوكوز.","السليلوز لا يخزن الطاقة بل يكوّن الجدران القاسية للخلايا النباتية، وهو غير متفرع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-15T02:47:48.835Z"}'::jsonb),
('mcq', 3, 2, 'الجلايكوجين سكر عديد التسكر من وحدات الجلوكوز يختزن الطاقة، ويوجد غالبًا في الكبد وعضلات الإنسان والحيوانات.', '["هذه وظيفة السليلوز في النبات.","الجلوكوز هو الموجود بتركيز عالٍ في الدم ومصدر الطاقة الفورية.","","النشا هو الذي تصنعه النباتات لتخزين الطاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-15T02:47:48.835Z"}'::jsonb),
('mcq', 4, 3, 'يختلف السليلوز عن النشا في اتجاهات الروابط التي تربط الوحدات الأساسية في الفراغ، ولذلك لا تستطيع إنزيمات الهضم أن تستوعب السليلوز في مواقعها النشطة.', '["السليلوز يتكون من وحدات الجلوكوز مثل النشا تمامًا.","السليلوز لا يذوب في الماء، وسبب عدم هضمه هو اتجاه الروابط.","السليلوز بوليمر عديد التسكر من عدد كبير من وحدات الجلوكوز، وليس سكرًا ثنائيًّا، ولا يمتصه الجسم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-15T02:47:48.835Z"}'::jsonb),
('mcq', 5, 0, 'السليلوز يكوّن الجدران القاسية للخلايا النباتية، والإنسان لا يستطيع هضمه؛ فهذا الصف صحيح بأجزائه الثلاثة.', '["","قابلية الهضم صحيحة، لكن وظيفة النشا تخزين الطاقة في النبات لا تكوين الجدران.","الجلايكوجين يخزن الطاقة في الكبد والعضلات عند الإنسان والحيوانات، والإنسان يستطيع هضمه.","السليلوز لا يخزن الطاقة بل يكوّن الجدران الخلوية، والإنسان لا يهضمه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-15T02:47:48.835Z"}'::jsonb),
('mcq', 6, 1, 'النشا تصنعه النباتات لتخزين الطاقة، والجلايكوجين يختزن الطاقة في الكبد والعضلات؛ والإنسان يستطيع هضم الجلايكوجين والنشا، بخلاف السليلوز. فهما متشابهان في الوظيفة (تخزين الطاقة) وفي قابلية الهضم.', '["النشا تصنعه النباتات، أما الجلايكوجين فيوجد غالبًا في الكبد وعضلات الإنسان والحيوانات.","","تكوين الجدران القاسية للخلايا النباتية وظيفة السليلوز، أما الجلايكوجين والنشا فيختزنان الطاقة.","النشا جزيء طري لا يذوب في الماء، فالعبارة لا تصح عليهما معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-15T02:47:48.835Z"}'::jsonb),
('mcq', 7, 3, 'السليلوز الذي في الفواكه والخضراوات والحبوب يُسمى أليافًا غذائية؛ لأنه يمر في الجهاز الهضمي دون أن يتغير كثيرًا، إذ لا يستطيع الإنسان هضمه.', '["الإنسان لا يهضم السليلوز، فلا يتحلل في جهازه الهضمي إلى جلوكوز.","الذي يُخزن في العضلات هو الجلايكوجين، لا السليلوز.","السليلوز لا يذوب في الماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-15T02:47:48.835Z"}'::jsonb),
('essay', 1, null::int, null, null, 'كلاهما يتكون من وحدات الجلوكوز. النشا له تركيب متفرع أو غير متفرع، وهو جزيء طري لا يذوب في الماء، ويُستعمل في النبات لتخزين الطاقة. السليلوز له تركيب غير متفرع يشبه السياج ذا السلاسل المتقاطعة، ولا يذوب في الماء، ويكوّن الجدران القاسية للخلايا النباتية مثل الخشب. أهمية التركيب: اتجاه الروابط بين الوحدات في الفراغ مختلف؛ فتركيب السليلوز المستقيم ذو السلاسل المتقاطعة يعطيه الصلابة المناسبة لبناء الجدران الخلوية، أما تركيب النشا الطري فيجعله مخزنًا للطاقة يمكن تحليله إلى جلوكوز عند الحاجة.', '["كلاهما من الجلوكوز","النشا متفرع أو غير متفرع، طري، يخزن الطاقة","السليلوز غير متفرع كالسياج المتقاطع، يكوّن الجدران القاسية","اختلاف اتجاه الروابط يحدد الخواص والوظيفة"]'::jsonb, '[]'::jsonb, '[{"element":"التركيب الجزيئي للنشا","marks":1},{"element":"التركيب الجزيئي للسليلوز","marks":1},{"element":"وظيفة النشا","marks":1},{"element":"وظيفة السليلوز","marks":1},{"element":"ربط التركيب بالوظيفة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"4–5 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط"},{"level":"1–3 درجات","description":"إجابة جزئية تتضمن بعض العناصر الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس وظيفتي النشا والسليلوز","القول إن السليلوز متفرع","إرجاع الاختلاف إلى نوع الوحدات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-15T02:47:48.835Z"}'::jsonb),
('essay', 2, null::int, null, null, 'النشا: تصنعه النباتات (يوجد في الحبوب وغيرها)، وظيفته تخزين الطاقة في النبات، ويهضمه الإنسان. الجلايكوجين: يوجد غالبًا في الكبد وعضلات الإنسان والحيوانات وفي بعض المخلوقات المجهرية، وظيفته تخزين الطاقة، ويهضمه الإنسان. السليلوز: تصنعه النباتات ويوجد في الجدران الخلوية والخشب، وظيفته تكوين الجدران القاسية للخلايا النباتية، ولا يهضمه الإنسان.', '["النشا: نبات، تخزين طاقة، يُهضم","الجلايكوجين: كبد وعضلات، تخزين طاقة، يُهضم","السليلوز: جدران خلايا نباتية، دعم بنائي، لا يُهضم"]'::jsonb, '[]'::jsonb, '[{"element":"مكان وجود كل منها (3 × 1)","marks":3},{"element":"وظيفة كل منها (3 × 1)","marks":3},{"element":"قابلية الهضم للثلاثة","marks":3}]'::jsonb, '[{"level":"9 درجات","description":"إجابة كاملة صحيحة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"7–8 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط"},{"level":"1–6 درجات","description":"إجابة جزئية تتضمن بعض العناصر الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الجلايكوجين يوجد في النبات","القول إن الإنسان لا يهضم الجلايكوجين","عدّ السليلوز مخزنًا للطاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (9 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-15T02:47:48.835Z"}'::jsonb),
('essay', 3, null::int, null, null, 'لأن هذه السكريات عديدة التسكر الثلاثة بوليمرات تتكون كلها من نوع واحد من الوحدات الأساسية هو الجلوكوز، فتفكيك الروابط بين الوحدات بالتميّه لا يعطي إلا الجلوكوز. والإنسان يهضم النشا إلى جلوكوز لأن إنزيمات الهضم تستوعب النشا في مواقعها النشطة، أما السليلوز فالروابط بين وحداته تتجه في الفراغ اتجاهًا مختلفًا، فلا تستوعبه المواقع النشطة لإنزيمات الهضم، فيمر في الجهاز الهضمي دون أن يتغير كثيرًا (ألياف غذائية).', '["الثلاثة بوليمرات من الجلوكوز فقط","الناتج: الجلوكوز","النشا يُهضم لأن الإنزيمات تستوعبه","السليلوز لا يُهضم لاختلاف اتجاه الروابط وعدم ملاءمته للموقع النشط"]'::jsonb, '[]'::jsonb, '[{"element":"التفسير: وحدات من نوع واحد","marks":2},{"element":"تسمية الجلوكوز","marks":1},{"element":"هضم النشا","marks":1},{"element":"عدم هضم السليلوز مع السبب","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"4–5 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط"},{"level":"1–3 درجات","description":"إجابة جزئية تتضمن بعض العناصر الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الناتج سكروز","إرجاع عدم هضم السليلوز إلى نوع الوحدات","القول إن السليلوز يذوب في الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-15T02:47:48.836Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
