('mcq', 1, 'مِمّ يتكون جزيء السكروز؟', null, null, '["جزيئين من الجلوكوز","جزيء جلوكوز وجزيء جلاكتوز","جزيء فركتوز وجزيء جلاكتوز","جزيء جلوكوز وجزيء فركتوز"]'::jsonb, 'تذكر', 'تذكر مكونات', 'سهل', 'الكتاب ص 217، 236 — السكروز (اختبار مقنن س7)'),
('mcq', 2, 'ما السكران الأحاديان اللذان يتحدان لتكوين اللاكتوز (سكر الحليب)؟', null, null, '["الجلوكوز والفركتوز","الفركتوز والجلاكتوز","الجلوكوز والجلاكتوز","الجلوكوز والجلوكوز"]'::jsonb, 'تذكر', 'تذكر مكونات', 'سهل', 'الكتاب ص 217 — اللاكتوز'),
('mcq', 3, 'يتحد سكران أحاديان صيغة كلٍّ منهما C₆H₁₂O₆ لتكوين سكر ثنائي. أيّ المعادلات الآتية تمثل هذا التفاعل تمثيلًا صحيحًا موزونًا؟', null, null, '["C₆H₁₂O₆ + C₆H₁₂O₆ → C₁₂H₂₄O₁₂","C₆H₁₂O₆ + C₆H₁₂O₆ → C₁₂H₂₂O₁₁ + H₂O","C₆H₁₂O₆ + C₆H₁₂O₆ + H₂O → C₁₂H₂₂O₁₁","C₆H₁₂O₆ + C₆H₁₂O₆ → C₁₂H₂₀O₁₀ + 2H₂O"]'::jsonb, 'تطبيق', 'كتابة معادلة', 'متوسط', 'الكتاب ص 217، 234 — معادلة تكوين السكر الثنائي (س83، س84)'),
('mcq', 4, 'يمثل الشكل الآتي تركيب سكر ثنائي. ما السكران الأحاديان المكونان له؟', null, '[{"src":"qimg/chem22/c6-l2-lactose.svg","alt":"تركيب سكر ثنائي من حلقتين سداسيتين، كل منهما من خمس ذرات كربون وذرة أكسجين ومجموعة CH₂OH إلى أعلى. في الحلقة اليسرى: ذرة الكربون اليسرى تحمل HO إلى أعلى، والأمامية اليسرى OH إلى أعلى، والأمامية اليمنى OH إلى أسفل. في الحلقة اليمنى: ذرة الكربون الأمامية اليسرى تحمل OH إلى أعلى، والأمامية اليمنى OH إلى أسفل، واليمنى OH إلى أسفل. ترتبط ذرة الكربون اليمنى في الحلقة اليسرى بذرة أكسجين واحدة فوق مستوى الحلقتين تتصل بذرة الكربون اليسرى في الحلقة اليمنى (C–O–C)."}]'::jsonb, '["جلاكتوز (الحلقة اليسرى) وجلوكوز (الحلقة اليمنى)","جلوكوز (الحلقة اليسرى) وجلوكوز (الحلقة اليمنى)","جلوكوز (الحلقة اليسرى) وفركتوز (الحلقة اليمنى)","جلاكتوز (الحلقة اليسرى) وفركتوز (الحلقة اليمنى)"]'::jsonb, 'تحليل', 'تفسير شكل', 'صعب', 'الكتاب ص 217 — اللاكتوز'),
('mcq', 5, 'ما عدد مولات الماء اللازمة للتميّه الكامل لـ 2 mol من اللاكتوز، وعدد مولات السكريات الأحادية الناتجة؟', null, null, '["1 mol ماء، و2 mol سكريات أحادية","2 mol ماء، و2 mol سكريات أحادية","2 mol ماء، و4 mol سكريات أحادية","4 mol ماء، و4 mol سكريات أحادية"]'::jsonb, 'تطبيق', 'حساب مولات', 'متوسط', 'الكتاب ص 234 — س83 تميّه اللاكتوز'),
('mcq', 6, 'أيّ العبارات الآتية صحيحة عند المقارنة بين السكروز واللاكتوز؟', null, null, '["يتكونان من السكرين الأحاديين نفسيهما، ويختلفان في نوع الرابطة بينهما","لهما الصيغة الجزيئية نفسها، ويختلفان في أحد السكرين الأحاديين المكوّنين لهما","يختلفان في الصيغة الجزيئية؛ لأن أحدهما يتكون من ثلاثة سكريات أحادية","السكروز سكر ثنائي، أما اللاكتوز فسكر أحادي يوجد في الحليب"]'::jsonb, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 217 — السكروز واللاكتوز'),
('mcq', 7, 'تفاعلت 90.08 g من الجلوكوز تفاعلًا تامًّا لتكوين السكروز، وكل 1 mol من الجلوكوز يعطي 1 mol من السكروز. ما كتلة السكروز الناتجة؟ (الكتل المولية: الجلوكوز 180.16 g/mol، السكروز 342.30 g/mol، الماء 18.02 g/mol)', null, null, '["171.15 g","180.16 g","342.30 g","162.14 g"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 234 — س84 تكوين السكروز'),
('essay', 1, 'اكتب معادلة كيميائية موزونة لتكوين السكروز من الجلوكوز والفركتوز باستعمال الصيغ الجزيئية، ثم سمِّ نوع التفاعل ونوع الرابطة التي تتكون، وبيّن كيف تحققت من وزن المعادلة.', null, null, null, 'تطبيق', 'كتابة معادلة', 'متوسط', 'الكتاب ص 234 — س84'),
('essay', 2, 'اكتب معادلة كيميائية موزونة تمثل تميّه اللاكتوز، وسمِّ نواتجها، ثم احسب كتلة الماء اللازمة لتميّه 34.23 g من اللاكتوز تميّهًا تامًّا، وكتلة الجلوكوز الناتجة. (الكتل المولية: اللاكتوز 342.30 g/mol، الماء 18.02 g/mol، الجلوكوز 180.16 g/mol)', null, null, null, 'تطبيق', 'معادلة وحساب', 'صعب', 'الكتاب ص 234 — س83'),
('essay', 3, 'يمثل الشكل الآتي تركيب سكر ثنائي. (أ) حدد السكرين الأحاديين المكونين له مع التعليل من التركيب، وسمِّ هذا السكر الثنائي. (ب) اكتب معادلة تكوينه بالصيغ الجزيئية. (ج) قارن مكوناته بمكونات اللاكتوز.', null, '[{"src":"qimg/chem22/c6-l2-sucrose.svg","alt":"تركيب سكر ثنائي من حلقتين: الحلقة اليسرى سداسية من خمس ذرات كربون وذرة أكسجين، ذرة الكربون الخلفية اليسرى فيها تحمل CH₂OH إلى أعلى، والأمامية اليسرى OH إلى أعلى، والأمامية اليمنى OH إلى أسفل، واليسرى HO إلى أسفل. ترتبط ذرة الكربون اليمنى في هذه الحلقة بذرة أكسجين واحدة، وترتبط ذرة الأكسجين هذه بذرة الكربون اليسرى في الحلقة اليمنى (C–O–C). الحلقة اليمنى: حلقة خماسية من أربع ذرات كربون وذرة أكسجين في أعلاها، ذرة الكربون اليسرى فيها تحمل CH₂OH إلى أعلى، وذرة الكربون الأمامية اليسرى تحمل OH إلى أسفل، والأمامية اليمنى تحمل OH إلى أعلى، واليمنى تحمل CH₂OH إلى أسفل."}]'::jsonb, null, 'تطبيق', 'تحليل شكل وكتابة معادلة', 'متوسط', 'الكتاب ص 217 — الشكل 6-10')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
