from (values
('mcq', 1, 3, 'يتكون السكروز (سكر المائدة) من اتحاد الجلوكوز مع الفركتوز بتفاعل تكثف.', '["اتحاد جزيئي جلوكوز يعطي المالتوز لا السكروز.","اتحاد الجلوكوز والجلاكتوز يعطي اللاكتوز (سكر الحليب).","السكروز يحتوي على وحدة جلوكوز، ولا يدخل الجلاكتوز في تركيبه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-15T02:47:48.836Z"}'::jsonb),
('mcq', 2, 2, 'يتكون اللاكتوز عندما يتحد الجلوكوز والجلاكتوز.', '["اتحاد الجلوكوز والفركتوز يعطي السكروز.","اللاكتوز يحتوي على الجلوكوز، ولا يدخل الفركتوز في تركيبه.","","اتحاد وحدتي جلوكوز يعطي المالتوز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-15T02:47:48.836Z"}'::jsonb),
('mcq', 3, 1, 'يتكون السكر الثنائي بتفاعل تكثف تتكون فيه رابطة واحدة بين السكرين ويتحرر جزيء ماء واحد: C₁₂H₂₄O₁₂ − H₂O = C₁₂H₂₂O₁₁. والمعادلة موزونة: C: 12 = 12، H: 24 = 22 + 2، O: 12 = 11 + 1.', '["أُهمل جزيء الماء المتحرر؛ فالسكر الثنائي ليس مجموع صيغتي السكرين بل ينقص عنهما H₂O.","","الماء ناتج من التكثف لا متفاعل، والمعادلة بهذه الصورة غير موزونة (H: 26 مقابل 22، O: 13 مقابل 11).","المعادلة موزونة عدديًّا، لكنها تفترض تحرر جزيئي ماء، مع أن ارتباط سكرين أحاديين يكوّن رابطة واحدة ويُطلق جزيء ماء واحدًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-15T02:47:48.836Z"}'::jsonb),
('mcq', 4, 0, 'الحلقتان سداسيتان، فالسكران من الجلوكوز والجلاكتوز لا الفركتوز؛ والحلقة اليسرى تختلف عن الجلوكوز في اتجاه OH على ذرة الكربون اليسرى (إلى أعلى)، فهي جلاكتوز، واليمنى جلوكوز؛ وهذا السكر الثنائي هو اللاكتوز.', '["","الحلقتان ليستا متماثلتين؛ فمجموعة OH على ذرة الكربون اليسرى في الحلقة اليسرى متجهة إلى أعلى، وهذا يميز الجلاكتوز عن الجلوكوز.","الفركتوز يظهر بحلقة خماسية، أما الحلقتان هنا فسداسيتان؛ والحلقة اليسرى جلاكتوز لا جلوكوز.","الحلقة اليسرى جلاكتوز فعلًا، لكن الحلقة اليمنى سداسية فهي جلوكوز؛ فالفركتوز يظهر بحلقة خماسية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-15T02:47:48.836Z"}'::jsonb),
('mcq', 5, 2, 'التميّه عكس التكثف: C₁₂H₂₂O₁₁ + H₂O → C₆H₁₂O₆ + C₆H₁₂O₆ (جلوكوز وجلاكتوز)؛ فكل 1 mol لاكتوز يحتاج إلى 1 mol ماء ويعطي 2 mol سكريات أحادية، و2 mol لاكتوز تحتاج إلى 2 mol ماء وتعطي 4 mol سكريات أحادية.', '["هذه كميات 1 mol من اللاكتوز؛ والمطلوب 2 mol فتتضاعف الكميات.","كمية الماء صحيحة، لكن كل جزيء لاكتوز يعطي سكرين أحاديين، فـ 2 mol تعطي 4 mol.","","يلزم جزيء ماء واحد لكل رابطة، وفي جزيء اللاكتوز رابطة واحدة، فيلزم 2 mol ماء فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-15T02:47:48.836Z"}'::jsonb),
('mcq', 6, 1, 'السكروز = جلوكوز + فركتوز، واللاكتوز = جلوكوز + جلاكتوز؛ فكلاهما سكر ثنائي من سكرين أحاديين صيغة كلٍّ منهما C₆H₁₂O₆ مع تحرر جزيء ماء، فصيغة كلٍّ منهما C₁₂H₂₂O₁₁، ويختلفان في السكر الأحادي الثاني (الفركتوز مقابل الجلاكتوز). إذن لهما الصيغة الجزيئية نفسها، ويختلفان في أحد السكرين الأحاديين المكوّنين لهما.', '["يختلفان في أحد السكرين الأحاديين، وكلاهما يرتبط بالرابطة الإيثرية C–O–C الناتجة عن التكثف.","","كلاهما سكر ثنائي من وحدتين، وصيغة كلٍّ منهما C₁₂H₂₂O₁₁.","اللاكتوز (سكر الحليب) سكر ثنائي يتكون من سكرين أحاديين، لا سكر أحادي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-15T02:47:48.836Z"}'::jsonb),
('mcq', 7, 0, 'عدد مولات الجلوكوز = 90.08 ÷ 180.16 = 0.5000 mol، والنسبة المولية جلوكوز : سكروز = 1 : 1، فكتلة السكروز = 0.5000 × 342.30 = 171.15 g.', '["","مضاعفة كتلة الجلوكوز (2 × 90.08) لأن السكروز من وحدتين، دون مراعاة تحرر الماء ولا استعمال الكتل المولية.","افتراض أن المتفاعل 1 mol من الجلوكوز، مع أن 90.08 g تساوي 0.5000 mol فقط.","مضاعفة كتلة الجلوكوز ثم طرح 1 mol كامل من الماء (18.02 g)، مع أن الماء المتحرر 0.5000 mol فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-15T02:47:48.836Z"}'::jsonb),
('essay', 1, null::int, null, null, 'C₆H₁₂O₆ (جلوكوز) + C₆H₁₂O₆ (فركتوز) → C₁₂H₂₂O₁₁ (سكروز) + H₂O. نوع التفاعل: تكثف، ونوع الرابطة: الرابطة الإيثرية C–O–C. التحقق: C: 6 + 6 = 12 = 12؛ H: 12 + 12 = 24 = 22 + 2؛ O: 6 + 6 = 12 = 11 + 1.', '["المعادلة الموزونة","تكثف","رابطة إيثرية C–O–C","عدّ الذرات في الطرفين"]'::jsonb, '["المتفاعلات: 2 × C₆H₁₂O₆ = C₁₂H₂₄O₁₂","طرح H₂O: C₁₂H₂₂O₁₁","التحقق من C وH وO في الطرفين"]'::jsonb, '[{"element":"الصيغ الصحيحة للمتفاعلات والنواتج","marks":2},{"element":"نوع التفاعل","marks":1},{"element":"نوع الرابطة","marks":1},{"element":"التحقق من الوزن","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3–4 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط"},{"level":"1–2 درجة","description":"إجابة جزئية تتضمن بعض العناصر الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال الماء الناتج","وضع الماء في جهة المتفاعلات","كتابة اللاكتوز أو الجلاكتوز بدل الفركتوز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-15T02:47:48.837Z"}'::jsonb),
('essay', 2, null::int, null, null, 'C₁₂H₂₂O₁₁ (لاكتوز) + H₂O → C₆H₁₂O₆ (جلوكوز) + C₆H₁₂O₆ (جلاكتوز). عدد مولات اللاكتوز = 34.23 ÷ 342.30 = 0.1000 mol، والنسبة لاكتوز : ماء = 1 : 1، فكتلة الماء = 0.1000 × 18.02 = 1.802 g. وكتلة الجلوكوز الناتجة = 0.1000 × 180.16 = 18.02 g.', '["معادلة التميّه الموزونة","النواتج: جلوكوز وجلاكتوز","0.1000 mol لاكتوز","كتلة الماء 1.802 g","كتلة الجلوكوز 18.02 g"]'::jsonb, '["n(لاكتوز) = 34.23 ÷ 342.30 = 0.1000 mol","n(H₂O) = n(لاكتوز) = 0.1000 mol","m(H₂O) = 0.1000 × 18.02 = 1.802 g","m(جلوكوز) = 0.1000 × 180.16 = 18.02 g"]'::jsonb, '[{"element":"المعادلة الموزونة","marks":2},{"element":"تسمية النواتج","marks":1},{"element":"حساب عدد المولات","marks":1},{"element":"كتلة الماء","marks":1},{"element":"كتلة الجلوكوز","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"4–5 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط"},{"level":"1–3 درجات","description":"إجابة جزئية تتضمن بعض العناصر الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الفركتوز ناتجًا بدل الجلاكتوز","وضع الماء في جهة النواتج","استعمال الكتلة المولية للجلوكوز لحساب مولات اللاكتوز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-15T02:47:48.837Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الحلقة اليسرى سداسية (خمس ذرات كربون وذرة أكسجين) فهي جلوكوز، والحلقة اليمنى خماسية (أربع ذرات كربون وذرة أكسجين) تحمل مجموعتي CH₂OH فهي فركتوز؛ والحلقتان مرتبطتان برابطة إيثرية C–O–C؛ فهذا السكر الثنائي هو السكروز. (ب) C₆H₁₂O₆ + C₆H₁₂O₆ → C₁₂H₂₂O₁₁ + H₂O. (ج) يشترك السكروز واللاكتوز في احتواء كل منهما على وحدة جلوكوز، ويختلفان في الوحدة الثانية: الفركتوز في السكروز والجلاكتوز في اللاكتوز، ولكليهما الصيغة C₁₂H₂₂O₁₁.', '["جلوكوز (حلقة سداسية) وفركتوز (حلقة خماسية)","الاسم: السكروز","المعادلة الموزونة","المقارنة: جلوكوز مشترك، فركتوز مقابل جلاكتوز"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الجلوكوز مع التعليل","marks":1},{"element":"تحديد الفركتوز مع التعليل","marks":1},{"element":"تسمية السكروز","marks":1},{"element":"معادلة التكوين","marks":2},{"element":"المقارنة باللاكتوز","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"4–5 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط"},{"level":"1–3 درجات","description":"إجابة جزئية تتضمن بعض العناصر الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية الحلقة الخماسية جلاكتوزًا","تسمية الناتج لاكتوزًا","إغفال الماء في المعادلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-15T02:47:48.837Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
