from (values
('mcq', 1, 'ما التعريف الصحيح لليبيدات؟', null, null, '["جزيئات حيوية كبيرة غير قطبية لا تذوب في الماء","بوليمرات حيوية من أحماض أمينية ترتبط بروابط ببتيدية","مركبات تحتوي على مجموعات هيدروكسيل متعددة ومجموعة كربونيل","بوليمرات من نيوكليوتيدات تخزن المعلومات الوراثية"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 219 — ما الليبيد؟'),
('mcq', 2, 'لماذا لا تذوب الليبيدات في الماء؟', null, null, '["لأنها جزيئات قطبية تكوّن روابط هيدروجينية قوية فيما بينها","لأنها بوليمرات ضخمة من وحدات بناء متكررة","لأنها جزيئات غير قطبية، والماء مذيب قطبي","لأنها مركبات أيونية تتكون من أيونات موجبة وسالبة"]'::jsonb, 'فهم', 'تفسير خاصية', 'سهل', 'الكتاب ص 219 — ما الليبيد؟'),
('mcq', 3, 'بمَ تختلف الليبيدات عن البروتينات والكربوهيدرات من حيث التركيب؟', null, null, '["تتكون من وحدات بناء متكررة من الجلوكوز","ليست بوليمرات ذات وحدات بناء أساسية متكررة","ترتبط وحداتها بروابط ببتيدية بين أحماض أمينية","تتكون جميعها من سلاسل نيوكليوتيدات طويلة"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 219 — ما الليبيد؟'),
('mcq', 4, 'يمثل الشكل الآتي التركيب الأساسي لمجموعة من المركبات العضوية الحيوية. إلى أي مجموعة من المركبات الحيوية تنتمي هذه المركبات؟', null, '[{"src":"qimg/chem22/c6-l3a-steroid.svg","alt":"صيغة هيكلية لأربع حلقات كربونية ملتحمة: ثلاث حلقات سداسية متجاورة (حلقتان في الصف السفلي، وحلقة ثالثة أعلى يمين الحلقة الوسطى) وحلقة خماسية ملتحمة بالحلقة السداسية العليا من جهة اليمين. كل رأس في الحلقات يمثل ذرة كربون، ولا توجد على الحلقات أي ذرات أو مجموعات مكتوبة."}]'::jsonb, '["الكربوهيدرات","البروتينات","الأحماض النووية","الليبيدات"]'::jsonb, 'فهم', 'تصنيف من الشكل', 'متوسط', 'الكتاب ص 223 — الستيرويدات'),
('mcq', 5, 'ما الصفة المشتركة بين الشمع المستعمل في تلميع السيارات، والدهن الذي يقطر من اللحم عند شيّه، وفيتامين (د)؟', null, null, '["كلها بروتينات تتكون من أحماض أمينية","كلها سكريات عديدة التسكر","كلها ليبيدات غير قابلة للذوبان في الماء","كلها بوليمرات ذات وحدات بناء متكررة"]'::jsonb, 'تذكر', 'تعرف أمثلة', 'سهل', 'الكتاب ص 219 — الربط مع الحياة'),
('mcq', 6, 'رجّ طالب كمية من زيت الزيتون مع الماء في أنبوب اختبار ثم تركه مدة. ما الذي يتوقع أن يشاهده؟ ولماذا؟', null, null, '["ينفصل الزيت في طبقة مستقلة؛ لأنه ليبيد غير قطبي","يذوب الزيت تمامًا؛ لأنه يكوّن روابط هيدروجينية مع الماء","يذوب الزيت تمامًا؛ لأنه بوليمر من وحدات متكررة","ينفصل الزيت في طبقة مستقلة؛ لأنه مركب أيوني"]'::jsonb, 'تطبيق', 'تنبؤ وتفسير', 'متوسط', 'الكتاب ص 219، 220 — الليبيدات والزيوت'),
('mcq', 7, 'أي العبارات الآتية صحيحة فيما يتعلق بالليبيدات؟', null, null, '["تحتوي كلها على سلاسل أحماض دهنية طويلة","تشمل الأحماض الدهنية والجليسريدات الثلاثية والشموع والستيرويدات","تذوب في الماء لاحتوائها على مجموعات قطبية كثيرة","تتكون من وحدات جلوكوز ترتبط بروابط متكررة"]'::jsonb, 'تحليل', 'تقييم عبارات', 'صعب', 'الكتاب ص 219–223 — أنواع الليبيدات'),
('essay', 1, 'عرّف الليبيدات، ثم وضّح كيف تختلف عن البروتينات والكربوهيدرات من حيث التركيب.', null, null, null, 'تذكر', 'تعريف ومقارنة', 'متوسط', 'الكتاب ص 219 — ما الليبيد؟'),
('essay', 2, 'يمثل الشكل الآتي التركيب الأساسي لمجموعة من المركبات الحيوية، ولا يحتوي هذا التركيب على أي سلسلة حمض دهني. هل تُصنَّف هذه المركبات ضمن الليبيدات؟ فسّر إجابتك مستعينًا بتعريف الليبيدات، ثم سمِّ هذه المجموعة واذكر مثالين عليها.', null, '[{"src":"qimg/chem22/c6-l3a-steroid.svg","alt":"صيغة هيكلية لأربع حلقات كربونية ملتحمة: ثلاث حلقات سداسية متجاورة (حلقتان في الصف السفلي، وحلقة ثالثة أعلى يمين الحلقة الوسطى) وحلقة خماسية ملتحمة بالحلقة السداسية العليا من جهة اليمين. كل رأس في الحلقات يمثل ذرة كربون، ولا توجد على الحلقات أي ذرات أو مجموعات مكتوبة."}]'::jsonb, null, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 223 — الستيرويدات (س62 ص 233)'),
('essay', 3, 'صنّف المواد الآتية إلى ليبيدات وغير ليبيدات، مع تبرير تصنيفك: زيت الزيتون، شمع العسل، الكولسترول، النشا، الإنسولين، حمض الستيريك.', null, null, null, 'تطبيق', 'تصنيف وتبرير', 'صعب', 'الكتاب ص 219–223 — الليبيدات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
