('mcq', 1, 0, 'الليبيدات جزيئات حيوية كبيرة غير قطبية؛ ولأنها غير قطبية فهي غير قابلة للذوبان في الماء.', '["","هذا تعريف البروتينات، وهي بوليمرات من أحماض أمينية، أما الليبيدات فليست بوليمرات ذات وحدات متكررة.","هذا وصف الكربوهيدرات التي تحتوي على مجموعات –OH متعددة ومجموعة C=O.","هذا وصف الأحماض النووية التي تتكون من نيوكليوتيدات وتخزن المعلومات الوراثية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-15T02:47:48.837Z"}'::jsonb),
('mcq', 2, 2, 'الليبيدات جزيئات غير قطبية، والماء قطبي، والمواد غير القطبية لا تذوب في المذيبات القطبية؛ لذا فالليبيدات غير قابلة للذوبان في الماء.', '["الليبيدات غير قطبية وليست قطبية، والجزيئات القطبية تميل إلى الذوبان في الماء لا العكس.","الليبيدات ليست بوليمرات ذات وحدات بناء متكررة، وسبب عدم ذوبانها هو عدم قطبيتها.","","الليبيدات جزيئات تساهمية غير قطبية وليست مركبات أيونية، والمركبات الأيونية كثيرًا ما تذوب في الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-15T02:47:48.837Z"}'::jsonb),
('mcq', 3, 1, 'تختلف الليبيدات عن البروتينات والكربوهيدرات في أنها ليست بوليمرات ذات وحدات بناء أساسية متكررة، في حين تتكون البروتينات من أحماض أمينية متكررة، والكربوهيدرات المعقدة من سكريات أحادية متكررة.', '["الوحدات المتكررة من الجلوكوز تميز عديدات التسكر مثل النشا والسليلوز، وهي كربوهيدرات لا ليبيدات.","","الروابط الببتيدية بين الأحماض الأمينية تميز البروتينات لا الليبيدات.","النيوكليوتيدات وحدات بناء الأحماض النووية، ولا علاقة لها بتركيب الليبيدات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-11-15T02:47:48.838Z"}'::jsonb),
('mcq', 4, 3, 'الشكل هو التركيب الأساسي للستيرويدات المكوّن من أربع حلقات ملتحمة، والستيرويدات ليبيدات تحتوي تراكيبها على حلقات متعددة، وهي غير قطبية لا تذوب في الماء.', '["الكربوهيدرات تحتوي على مجموعات هيدروكسيل متعددة ومجموعة كربونيل، أما الحلقات المرسومة فلا تحمل أي ذرة أكسجين.","البروتينات بوليمرات من أحماض أمينية ترتبط بروابط ببتيدية، ولا يظهر في الشكل أي نيتروجين أو رابطة ببتيدية.","الأحماض النووية بوليمرات من نيوكليوتيدات فيها مجموعة فوسفات وسكر وقاعدة نيتروجينية، ولا يظهر شيء من ذلك في الشكل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-15T02:47:48.838Z"}'::jsonb),
('mcq', 5, 2, 'الشمع والدهن وفيتامين (د) كلها ليبيدات؛ أي جزيئات حيوية غير قطبية لا تذوب في الماء.', '["هذه المواد ليست بروتينات؛ فلا تتكون من أحماض أمينية مرتبطة بروابط ببتيدية.","السكريات عديدة التسكر كالنشا والسليلوز كربوهيدرات، وهذه المواد ليست منها.","","الليبيدات ليست بوليمرات ذات وحدات بناء متكررة، وهذا ما يميزها عن البروتينات والكربوهيدرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-15T02:47:48.838Z"}'::jsonb),
('mcq', 6, 0, 'زيت الزيتون جليسريد ثلاثي، أي ليبيد غير قطبي، فلا يذوب في الماء القطبي، وينفصل عنه في طبقة مستقلة.', '["","الزيت غير قطبي فلا يكوّن روابط هيدروجينية تكفي لإذابته في الماء، ولذا لا يذوب.","الزيت ليس بوليمرًا ذا وحدات متكررة، ثم إنه لا يذوب في الماء أصلًا.","الملاحظة صحيحة لكن التعليل خطأ؛ فالزيت ليس مركبًا أيونيًّا، وسبب عدم ذوبانه أنه غير قطبي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-15T02:47:48.838Z"}'::jsonb),
('mcq', 7, 1, 'الليبيدات مجموعة واسعة من الجزيئات غير القطبية تشمل الأحماض الدهنية، والجليسريدات الثلاثية، والليبيدات الفوسفورية، والشموع، والستيرويدات.', '["لا تحتوي الليبيدات كلها على سلاسل أحماض دهنية؛ فالستيرويدات تتكون من حلقات متعددة ولا تحتوي على سلاسل أحماض دهنية.","","الليبيدات غير قطبية ولا تذوب في الماء.","الوحدات المتكررة من الجلوكوز تميز عديدات التسكر، والليبيدات ليست بوليمرات ذات وحدات متكررة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-15T02:47:48.839Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الليبيدات جزيئات حيوية كبيرة غير قطبية، ولأنها غير قطبية فهي لا تذوب في الماء. وتختلف عن البروتينات والكربوهيدرات في أنها ليست بوليمرات ذات وحدات بناء أساسية متكررة؛ فالبروتينات بوليمرات من أحماض أمينية، والكربوهيدرات المعقدة بوليمرات من سكريات أحادية.', '["تعريف الليبيدات: جزيئات حيوية كبيرة غير قطبية","لا تذوب في الماء لأنها غير قطبية","ليست بوليمرات ذات وحدات بناء أساسية متكررة بخلاف البروتينات والكربوهيدرات"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الليبيدات: جزيئات حيوية كبيرة غير قطبية","marks":2},{"element":"لا تذوب في الماء لأنها غير قطبية","marks":1},{"element":"ليست بوليمرات ذات وحدات بناء أساسية متكررة بخلاف البروتينات والكربوهيدرات","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: تعريف الليبيدات: جزيئات حيوية كبيرة غير قطبية؛ لا تذوب في الماء لأنها غير قطبية؛ ليست بوليمرات ذات وحدات بناء أساسية متكررة بخلاف البروتينات والكربوهيدرات"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف الليبيدات بأنها مركبات قطبية تذوب في الماء","وصف الليبيدات بأنها بوليمرات من وحدات متكررة كالبروتينات","الاقتصار على ذكر أمثلة (الزيوت والدهون) بدل التعريف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-11-15T02:47:48.839Z"}'::jsonb),
('essay', 2, null::int, null, null, 'نعم، تُصنَّف ضمن الليبيدات؛ لأن تصنيف المركب ليبيدًا يعتمد على خواصه لا على احتوائه على أحماض دهنية؛ فالليبيدات جزيئات حيوية كبيرة غير قطبية لا تذوب في الماء. والتركيب المرسوم يتكون من أربع حلقات من ذرات الكربون والهيدروجين، فهو غير قطبي، ولذلك لا تذوب هذه المركبات في الماء، فينطبق عليها تعريف الليبيدات. وهذه المجموعة هي الستيرويدات، ومن أمثلتها: الكولسترول، وفيتامين (د)، والهرمونات الجنسية، والبوفوتوكسين.', '["الحكم: تُصنَّف ضمن الليبيدات؛ فأساس التصنيف أن الليبيدات غير قطبية لا تذوب في الماء، وليس شرطًا أن تحتوي على أحماض دهنية","التركيب حلقات من ذرات الكربون والهيدروجين فهو غير قطبي","هذه المركبات لا تذوب في الماء فينطبق عليها التعريف","تسمية المجموعة (الستيرويدات) ومثالان صحيحان عليها (الكولسترول، فيتامين د، الهرمونات الجنسية، البوفوتوكسين)"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم: تُصنَّف ضمن الليبيدات؛ فأساس التصنيف أن الليبيدات غير قطبية لا تذوب في الماء، وليس شرطًا أن تحتوي على أحماض دهنية","marks":2},{"element":"التركيب حلقات من ذرات الكربون والهيدروجين فهو غير قطبي","marks":1},{"element":"هذه المركبات لا تذوب في الماء فينطبق عليها التعريف","marks":1},{"element":"تسمية المجموعة (الستيرويدات) ومثالان صحيحان عليها (الكولسترول، فيتامين د، الهرمونات الجنسية، البوفوتوكسين)","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: الحكم: تُصنَّف ضمن الليبيدات؛ فأساس التصنيف أن الليبيدات غير قطبية لا تذوب في الماء، وليس شرطًا أن تحتوي على أحماض دهنية؛ التركيب حلقات من ذرات الكربون والهيدروجين فهو غير قطبي؛ هذه المركبات لا تذوب في الماء فينطبق عليها التعريف؛ تسمية المجموعة (الستيرويدات) ومثالان صحيحان عليها (الكولسترول، فيتامين د، الهرمونات الجنسية، البوفوتوكسين)"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاعتقاد أن كل ليبيد يجب أن يحتوي على أحماض دهنية فيُستبعد التركيب من الليبيدات","تعليل التصنيف بأن هذه المركبات بوليمرات","ذكر الجليسريدات الثلاثية أو الشموع أمثلةً على هذه المجموعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-15T02:47:48.839Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الليبيدات: زيت الزيتون (جليسريد ثلاثي)، وشمع العسل (شمع)، والكولسترول (ستيرويد)، وحمض الستيريك (حمض دهني)؛ لأنها كلها جزيئات غير قطبية لا تذوب في الماء، وليست بوليمرات ذات وحدات متكررة. أما غير الليبيدات: فالنشا كربوهيدرات، وهو بوليمر من وحدات جلوكوز متكررة، والإنسولين بروتين يتكون من أحماض أمينية مرتبطة بروابط ببتيدية.', '["تصنيف زيت الزيتون وشمع العسل ضمن الليبيدات","تصنيف الكولسترول وحمض الستيريك ضمن الليبيدات","النشا ليس ليبيدًا: كربوهيدرات من وحدات جلوكوز متكررة","الإنسولين ليس ليبيدًا: بروتين من أحماض أمينية","التبرير: الليبيدات غير قطبية لا تذوب في الماء وليست بوليمرات ذات وحدات متكررة"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف زيت الزيتون وشمع العسل ضمن الليبيدات","marks":1},{"element":"تصنيف الكولسترول وحمض الستيريك ضمن الليبيدات","marks":1},{"element":"النشا ليس ليبيدًا: كربوهيدرات من وحدات جلوكوز متكررة","marks":1},{"element":"الإنسولين ليس ليبيدًا: بروتين من أحماض أمينية","marks":1},{"element":"التبرير: الليبيدات غير قطبية لا تذوب في الماء وليست بوليمرات ذات وحدات متكررة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: تصنيف زيت الزيتون وشمع العسل ضمن الليبيدات؛ تصنيف الكولسترول وحمض الستيريك ضمن الليبيدات؛ النشا ليس ليبيدًا: كربوهيدرات من وحدات جلوكوز متكررة؛ الإنسولين ليس ليبيدًا: بروتين من أحماض أمينية؛ التبرير: الليبيدات غير قطبية لا تذوب في الماء وليست بوليمرات ذات وحدات متكررة"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف الكولسترول خارج الليبيدات لأنه لا يحتوي على أحماض دهنية","تصنيف النشا ضمن الليبيدات لأنه لا يذوب في الماء البارد","التصنيف دون تبرير مبني على التعريف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-15T02:47:48.839Z"}'::jsonb)
