('mcq', 1, 'ما الوظيفتان الرئيستان لليبيدات في المخلوقات الحية؟', null, null, '["تسريع التفاعلات الكيميائية ونقل الأكسجين","تخزين المعلومات الوراثية ونقلها","تخزين الطاقة بشكل فعّال وتكوين الأغشية الخلوية","الدعم البنائي للأنسجة وتقلصات العضلات"]'::jsonb, 'تذكر', 'تذكر وظائف', 'سهل', 'الكتاب ص 219 — ما الليبيد؟'),
('mcq', 2, 'يمثل الشكل الآتي ترتيب نوع من الليبيدات في جزء من غشاء خلوي. ما الوظيفة الرئيسة لهذا التركيب؟', null, '[{"src":"qimg/chem22/c6-l3a-bilayer.svg","alt":"رسم تخطيطي لطبقتين متقابلتين من الجزيئات، كُتب فوقهما «خارج الخلية» وتحتهما «داخل الخلية». الطبقة العليا صف من الدوائر يتدلى من كل دائرة خطان متعرجان نحو الأسفل، والطبقة السفلى صف مماثل من الدوائر يمتد من كل دائرة خطان متعرجان نحو الأعلى، فتلتقي الخطوط المتعرجة في وسط الغشاء، وتتجه الدوائر نحو الخارج من الجهتين: نحو خارج الخلية ونحو داخلها. لا توجد على الرسم تسميات أخرى."}]'::jsonb, '["حاجز ينظم دخول المواد إلى الخلية وخروجها منها","مخزن للطاقة الفائضة في الخلايا الدهنية","طبقة تمنع فقد الماء من سطوح أوراق النبات","هرمون ينظم عمليات الأيض داخل الخلية"]'::jsonb, 'فهم', 'ربط التركيب بالوظيفة', 'متوسط', 'الكتاب ص 222 — الليبيدات الفوسفورية'),
('mcq', 3, 'أين تُخزِّن المخلوقات الحية الطاقة الفائضة عندما تتوافر بكثرة، وفي أي صورة؟', null, null, '["في الكبد على هيئة أحماض أمينية","في أغشية الخلايا على هيئة ليبيدات فوسفورية","في الجلد على هيئة شموع","في الخلايا الدهنية على هيئة جليسريدات ثلاثية"]'::jsonb, 'تذكر', 'تذكر وظيفة', 'سهل', 'الكتاب ص 221 — تخزين الطاقة (س61 ص 233)'),
('mcq', 4, 'تمثل الصيغة الآتية التركيب العام لنوع من الليبيدات يغطي أوراق كثير من النباتات. ما وظيفته للنبات؟', null, '[{"src":"qimg/chem22/c6-l3a-wax.svg","alt":"صيغة عامة مكتوبة في سطر واحد: المجموعة CH₃(CH₂)ₓ مرتبطة بذرة كربون C، وترتبط ذرة الكربون هذه من أعلى بذرة أكسجين O برابطة ثنائية، ومن اليمين بذرة أكسجين O برابطة أحادية، وترتبط ذرة الأكسجين الأخيرة بالمجموعة (CH₂)ᵧCH₃؛ أي CH₃(CH₂)ₓ–C(=O)–O–(CH₂)ᵧCH₃، حيث x وy أعداد مختلفة من مجموعات CH₂."}]'::jsonb, '["يخزن الطاقة على هيئة جليسريد ثلاثي","يحمي الأوراق من الجفاف بمنع فقد الماء","ينظم عمليات الأيض بوصفه هرمونًا","يكوّن الطبقة الثنائية لأغشية الخلايا"]'::jsonb, 'فهم', 'ربط التركيب بالوظيفة', 'متوسط', 'الكتاب ص 222 — الشموع'),
('mcq', 5, 'يمثل الشكل الآتي التركيب الأساسي لمجموعة من المركبات الحيوية. أي الوظائف الآتية يؤديها بعض أفراد هذه المجموعة؟', null, '[{"src":"qimg/chem22/c6-l3a-steroid.svg","alt":"صيغة هيكلية لأربع حلقات كربونية ملتحمة: ثلاث حلقات سداسية متجاورة (حلقتان في الصف السفلي، وحلقة ثالثة أعلى يمين الحلقة الوسطى) وحلقة خماسية ملتحمة بالحلقة السداسية العليا من جهة اليمين. كل رأس في الحلقات يمثل ذرة كربون، ولا توجد على الحلقات أي ذرات أو مجموعات مكتوبة."}]'::jsonb, '["تنظيم عمليات الأيض بوصفها هرمونات جنسية","تخزين الطاقة الفائضة في الخلايا الدهنية","تكوين الشمع الذي يغطي أوراق النبات","تكوين أملاح الكربوكسيلات في صناعة الصابون"]'::jsonb, 'فهم', 'ربط التركيب بالوظيفة', 'متوسط', 'الكتاب ص 223 — الستيرويدات'),
('mcq', 6, 'أي الأزواج الآتية يربط الليبيد بوظيفته ربطًا صحيحًا؟', null, null, '["الشموع: تكوين الطبقة الثنائية للأغشية الخلوية","الجليسريدات الثلاثية: تنظيم الأيض بوصفها هرمونات","الستيرويدات: حماية أوراق النبات من الجفاف","الكولسترول: مكوّن بنائي مهم للأغشية الخلوية"]'::jsonb, 'فهم', 'مطابقة', 'متوسط', 'الكتاب ص 222، 223 — الشموع والستيرويدات'),
('mcq', 7, 'يحتوي سم بعض الأفاعي على إنزيم يحلل الليبيدات الفوسفورية بتفكيك إحدى روابط الإستر فيها. لماذا يؤدي دخول هذا السم إلى الدم إلى تمزق كريات الدم الحمراء؟', null, null, '["لأنه يحلل الجليسريدات الثلاثية المخزنة فتفقد الخلايا طاقتها","لأنه يحوّل الكولسترول إلى هرمونات تنظم الأيض","لأن تحلل الليبيدات الفوسفورية يُتلف الأغشية التي تكوّنها","لأنه يكوّن طبقة شمعية تمنع دخول الماء إلى الخلايا"]'::jsonb, 'تحليل', 'تفسير ظاهرة', 'صعب', 'الكتاب ص 222 — الربط مع علم الأحياء'),
('essay', 1, 'اذكر وظيفة مهمة لكل من الليبيدات الآتية: (أ) الجليسريدات الثلاثية (ب) الليبيدات الفوسفورية (ج) الشموع (د) الستيرويدات.', null, null, null, 'تذكر', 'تذكر وظائف', 'سهل', 'الكتاب ص 219–223 (س14 ص 223)'),
('essay', 2, 'من وظائف الليبيدات في المخلوقات الحية تخزين الطاقة والدفاع. (أ) صف كيف تستعمل الخلايا الدهنية الجليسريدات الثلاثية في تخزين الطاقة عند توافرها بكثرة وفي الحصول عليها عند نقصها. (ب) يفرز العلجوم البحري مادة البوفوتوكسين. ما نوع الليبيد الذي تنتمي إليه هذه المادة؟ وما وظيفتها للعلجوم؟', null, null, null, 'فهم', 'وصف وظائف', 'متوسط', 'الكتاب ص 221، 223 — تخزين الطاقة والستيرويدات'),
('essay', 3, 'تقترح بعض الأنظمة الغذائية خفض كمية الليبيدات في الغذاء خفضًا شديدًا. هل حذف الليبيدات من الغذاء حذفًا كاملًا فكرة جيدة؟ قوّم هذا الاقتراح مستندًا إلى وظائف الليبيدات في المخلوقات الحية، علمًا بأن الجرام الواحد من الدهون يعطي أكثر من ضعف الطاقة التي يعطيها الجرام الواحد من الكربوهيدرات أو البروتينات.', null, null, null, 'تقويم', 'تقويم اقتراح', 'صعب', 'الكتاب ص 208، 219–223 (س86 ص 234)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
