from (values
('mcq', 1, 2, 'تؤدي الليبيدات وظيفتين رئيستين في المخلوقات الحية: تخزين الطاقة بشكل فعّال، وتكوين معظم تراكيب الأغشية الخلوية.', '["تسريع التفاعلات وظيفة الإنزيمات، ونقل الأكسجين وظيفة الهيموجلوبين، وكلاهما بروتين.","تخزين المعلومات الوراثية ونقلها وظيفة الأحماض النووية.","","الدعم البنائي وتقلصات العضلات من وظائف البروتينات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-15T02:47:48.839Z"}'::jsonb),
('mcq', 2, 0, 'الشكل طبقة ثنائية من الليبيدات الفوسفورية: الرؤوس القطبية إلى الخارج والذيول غير القطبية إلى الداخل، وهذا التركيب يعمل حاجزًا، فتستطيع الخلية تنظيم المواد التي تدخل خلال الغشاء وتخرج منه.', '["","تخزين الطاقة الفائضة وظيفة الجليسريدات الثلاثية في الخلايا الدهنية، لا الطبقة الثنائية للغشاء.","منع فقد الماء من الأوراق وظيفة الشموع التي تغطي سطوح الأوراق.","الهرمونات التي تنظم الأيض ستيرويدات، والشكل غشاء لا هرمون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-15T02:47:48.839Z"}'::jsonb),
('mcq', 3, 3, 'عندما تتوافر الطاقة بكثرة تخزّن الخلايا الدهنية الطاقة الفائضة في الأحماض الدهنية على هيئة جليسريدات ثلاثية، وتحللها عند الحاجة إلى الطاقة.', '["الأحماض الأمينية وحدات بناء البروتينات، وليست صورة لتخزين الطاقة الفائضة.","الليبيدات الفوسفورية تكوّن أغشية الخلايا، ولا تُستعمل مخزنًا للطاقة.","الشموع تحمي السطوح من فقد الماء كما في أوراق النبات، ولا تُخزَّن فيها الطاقة الفائضة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-15T02:47:48.840Z"}'::jsonb),
('mcq', 4, 1, 'الصيغة صيغة الشمع (حمض دهني متحد مع كحول طويل السلسلة)، والنباتات تنتج الشمع الذي يغطي أوراقها ويحميها من الجفاف بمنع فقدان الماء.', '["الشمع ليس جليسريدًا ثلاثيًّا؛ فهو حمض دهني واحد متحد مع كحول طويل السلسلة، وليست وظيفته تخزين الطاقة للنبات.","","الهرمونات المنظمة للأيض ستيرويدات ذات حلقات متعددة، والصيغة المعطاة ليست كذلك.","الطبقة الثنائية للأغشية تتكون من الليبيدات الفوسفورية لا من الشموع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-15T02:47:48.840Z"}'::jsonb),
('mcq', 5, 0, 'الشكل تركيب الستيرويد ذو الحلقات الأربع، وبعض الهرمونات ومنها كثير من الهرمونات الجنسية ستيرويدات تنظم عمليات الأيض.', '["","تخزين الطاقة وظيفة الجليسريدات الثلاثية، وهي أحماض دهنية مرتبطة بالجليسرول لا حلقات ملتحمة.","الشمع حمض دهني متحد مع كحول طويل السلسلة، وليس ستيرويدًا.","أملاح الكربوكسيلات (الصابون) تنتج من تصبن الجليسريدات الثلاثية، لا من الستيرويدات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-15T02:47:48.840Z"}'::jsonb),
('mcq', 6, 3, 'الكولسترول ستيرويد، وهو مكوّن بنائي مهم للأغشية الخلوية.', '["الطبقة الثنائية للأغشية تكوّنها الليبيدات الفوسفورية، أما الشموع فتحمي أوراق النبات من الجفاف.","الجليسريدات الثلاثية تخزن الطاقة، والهرمونات المنظمة للأيض ستيرويدات.","حماية الأوراق من الجفاف وظيفة الشموع، أما الستيرويدات فمنها الهرمونات والكولسترول وفيتامين (د).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-15T02:47:48.840Z"}'::jsonb),
('mcq', 7, 2, 'الليبيدات الفوسفورية هي التي تكوّن أغشية الخلايا، فإذا حللها الإنزيم بتفكيك رابطة الإستر فإن ناتج التحلل يذيب أغشية كريات الدم الحمراء فتتمزق.', '["الإنزيم المذكور يحلل الليبيدات الفوسفورية لا الجليسريدات الثلاثية المخزنة، وفقدان الطاقة لا يفسر تمزق الغشاء.","الإنزيم لا يؤثر في الكولسترول، ولا يفسر تحويل الكولسترول تمزق الخلايا.","","الإنزيم يحلل الليبيدات ولا يكوّن شموعًا، والشمع يرتبط بحماية أوراق النبات لا بأغشية الخلايا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-15T02:47:48.840Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) الجليسريدات الثلاثية: تخزين الطاقة الفائضة في الخلايا الدهنية. (ب) الليبيدات الفوسفورية: تكوين الطبقة الثنائية للأغشية الخلوية التي تنظم دخول المواد وخروجها. (ج) الشموع: تغطية أوراق النبات وحمايتها من الجفاف بمنع فقد الماء. (د) الستيرويدات: تنظيم عمليات الأيض (الهرمونات الجنسية)، والكولسترول مكوّن للأغشية، وفيتامين (د) يؤدي دورًا في تكوين العظام.', '["الجليسريدات الثلاثية: تخزين الطاقة","الليبيدات الفوسفورية: تكوين الأغشية الخلوية","الشموع: حماية أوراق النبات من فقد الماء","الستيرويدات: هرمونات تنظم الأيض أو مكونات للأغشية (الكولسترول) أو تكوين العظام (فيتامين د)"]'::jsonb, '[]'::jsonb, '[{"element":"الجليسريدات الثلاثية: تخزين الطاقة","marks":1},{"element":"الليبيدات الفوسفورية: تكوين الأغشية الخلوية","marks":1},{"element":"الشموع: حماية أوراق النبات من فقد الماء","marks":1},{"element":"الستيرويدات: هرمونات تنظم الأيض أو مكونات للأغشية (الكولسترول) أو تكوين العظام (فيتامين د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: الجليسريدات الثلاثية: تخزين الطاقة؛ الليبيدات الفوسفورية: تكوين الأغشية الخلوية؛ الشموع: حماية أوراق النبات من فقد الماء؛ الستيرويدات: هرمونات تنظم الأيض أو مكونات للأغشية (الكولسترول) أو تكوين العظام (فيتامين د)"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة تكوين الأغشية إلى الشموع بدل الليبيدات الفوسفورية","نسبة تخزين الطاقة إلى الستيرويدات","ذكر وظيفة عامة لليبيدات دون ربطها بالنوع المطلوب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-15T02:47:48.840Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) عندما تتوافر الطاقة بكثرة تخزّن الخلايا الدهنية الطاقة الفائضة في الأحماض الدهنية على هيئة جليسريدات ثلاثية. وعندما تقل الطاقة تحلل الخلايا الجليسريدات الثلاثية بالإنزيمات، فتنطلق الطاقة التي استُعملت في تكوينها. (ب) البوفوتوكسين ستيرويد، يفرزه العلجوم البحري من نتوءات صغيرة على ظهره ومن غدد خلف عينيه مباشرة، ويستعمله آليةً دفاعية؛ فهو سم مهيج للإنسان وقاتل لبعض الحيوانات الصغيرة.', '["الخلايا الدهنية تخزّن الطاقة الفائضة على هيئة جليسريدات ثلاثية عند توافر الطاقة بكثرة","عند نقص الطاقة تحلل الخلايا الجليسريدات الثلاثية بالإنزيمات فتنطلق الطاقة التي استُعملت في تكوينها","البوفوتوكسين ستيرويد (من الليبيدات)","وظيفته: سم يفرزه العلجوم البحري من غدد خلف عينيه ونتوءات على ظهره آليةً دفاعية"]'::jsonb, '[]'::jsonb, '[{"element":"الخلايا الدهنية تخزّن الطاقة الفائضة على هيئة جليسريدات ثلاثية عند توافر الطاقة بكثرة","marks":1},{"element":"عند نقص الطاقة تحلل الخلايا الجليسريدات الثلاثية بالإنزيمات فتنطلق الطاقة التي استُعملت في تكوينها","marks":1},{"element":"البوفوتوكسين ستيرويد (من الليبيدات)","marks":1},{"element":"وظيفته: سم يفرزه العلجوم البحري من غدد خلف عينيه ونتوءات على ظهره آليةً دفاعية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: الخلايا الدهنية تخزّن الطاقة الفائضة على هيئة جليسريدات ثلاثية عند توافر الطاقة بكثرة؛ عند نقص الطاقة تحلل الخلايا الجليسريدات الثلاثية بالإنزيمات فتنطلق الطاقة التي استُعملت في تكوينها؛ البوفوتوكسين ستيرويد (من الليبيدات)؛ وظيفته: سم يفرزه العلجوم البحري من غدد خلف عينيه ونتوءات على ظهره آليةً دفاعية"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الطاقة تُخزَّن على هيئة ليبيدات فوسفورية أو شموع","إغفال تحلل الجليسريدات الثلاثية بالإنزيمات عند نقص الطاقة","تصنيف البوفوتوكسين بروتينًا أو شمعًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-15T02:47:48.840Z"}'::jsonb),
('essay', 3, null::int, null, null, 'حذف الليبيدات كليًّا ليس فكرة جيدة؛ لأن الليبيدات تؤدي وظائف أساسية: (1) تخزين الطاقة بشكل فعّال، فالجرام الواحد من الدهون يعطي أكثر من ضعف الطاقة التي تعطيها الكمية نفسها من الكربوهيدرات والبروتينات. (2) تكوين الأغشية الخلوية؛ فالليبيدات الفوسفورية تكوّن الطبقة الثنائية، والكولسترول مكوّن بنائي مهم للأغشية. (3) تنظيم العمليات الخلوية؛ فبعض الهرمونات ستيرويدات، وفيتامين (د) ستيرويد يؤدي دورًا في تكوين العظام. لذلك فالأفضل الاعتدال في كمية الليبيدات لا حذفها.', '["الحكم: حذفها كليًّا غير مناسب","تخزين الطاقة بكفاءة (الدهون تعطي أكثر من ضعف طاقة الكتلة نفسها من الكربوهيدرات والبروتينات)","تكوين الأغشية الخلوية (الليبيدات الفوسفورية والكولسترول)","تنظيم العمليات الخلوية (الهرمونات الستيرويدية، فيتامين د وتكوين العظام)","الاستنتاج: الاعتدال في الكمية بدل الحذف الكامل"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم: حذفها كليًّا غير مناسب","marks":1},{"element":"تخزين الطاقة بكفاءة (الدهون تعطي أكثر من ضعف طاقة الكتلة نفسها من الكربوهيدرات والبروتينات)","marks":1},{"element":"تكوين الأغشية الخلوية (الليبيدات الفوسفورية والكولسترول)","marks":1},{"element":"تنظيم العمليات الخلوية (الهرمونات الستيرويدية، فيتامين د وتكوين العظام)","marks":1},{"element":"الاستنتاج: الاعتدال في الكمية بدل الحذف الكامل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: الحكم: حذفها كليًّا غير مناسب؛ تخزين الطاقة بكفاءة (الدهون تعطي أكثر من ضعف طاقة الكتلة نفسها من الكربوهيدرات والبروتينات)؛ تكوين الأغشية الخلوية (الليبيدات الفوسفورية والكولسترول)؛ تنظيم العمليات الخلوية (الهرمونات الستيرويدية، فيتامين د وتكوين العظام)؛ الاستنتاج: الاعتدال في الكمية بدل الحذف الكامل"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم دون الاستناد إلى وظائف الليبيدات","الاعتقاد أن وظيفة الليبيدات الوحيدة تخزين الطاقة","الادعاء أن الكربوهيدرات تعطي طاقة أكبر من الدهون للكتلة نفسها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-15T02:47:48.840Z"}'::jsonb)
